window.JPG=window.JPG||{};JPG.N2=[{"id":"g2_027","t":"～にて","ko":"~에서, ~로 (で의 격식체)","cat":"조사","conn":[{"w":"명사 (장소)","f":"本館 + にて"},{"w":"명사 (수단·방법)","f":"メール + にて"},{"w":"명사 (시점)","f":"本日 + にて (종료)"}],"rule":["1. 조사 で가 들어갈 자리의 で를 にて로 바꾼다(本館で → 本館にて).","2. 장소(~에서), 수단·방법(~로), 끝나는 시점(本日にて終了)을 나타낸다.","3. 앞의 명사는 그대로이고, 활용은 없다."],"why":"오늘날의 조사 で는 고어 にて가 줄어서 생긴 말이다. 그래서 にて는 で와 같은 자리에 쓰이며 예스럽고 딱딱한 느낌을 준다.","nu":"안내 방송, 공지, 업무 문서, 편지처럼 격식 있는 글과 말에서 쓴다. 일상 회화에서 で 대신 쓰면 어색하다.","cmp":[{"g":"～で","d":"で는 모든 문체에 쓰는 일반 조사다. にて는 같은 뜻을 격식체·문어체로 나타낸다."}],"ex":[{"jp":"受付[うけつけ]は一階[いっかい]ロビーにて行[おこな]います。","ko":"접수는 1층 로비에서 합니다."},{"jp":"結果[けっか]はメールにてお知[し]らせします。","ko":"결과는 메일로 알려 드립니다."},{"jp":"今月[こんげつ]のセールは本日[ほんじつ]にて終了[しゅうりょう]いたします。","ko":"이번 달 세일은 오늘로 종료합니다."}],"dr":[{"t":"make","q":"会議室で行います → ～にて","a":"会議室にて行います","hint":"で를 にて로 바꾼다"},{"t":"make","q":"書面で連絡します → ～にて","a":"書面にて連絡します","hint":"수단의 で도 にて로"},{"t":"fill","q":"詳[くわ]しいことは、ホームページ（　）ご確認[かくにん]ください。","a":"にて","opts":["にて","につき","をはじめ","のことだから"]}],"src":["https://bunpro.jp/grammar_points/にて"],"vf":1,"u":1,"g":1,"gp":"gg_N2_00"},{"id":"g2_094","t":"～とか","ko":"~라든가, ~라던데","cat":"조사","conn":[{"w":"명사","f":"りんご + とか + みかん + とか"},{"w":"동사 사전형","f":"見る + とか、行く + とか + する"},{"w":"い형용사","f":"高い + とか、安い + とか"},{"w":"문말(전문) 보통형","f":"結婚する + とか"},{"w":"문말(전문) 명사·な형용사","f":"雨だ + とか"}],"rule":["1. 예로 들 말(명사)을 정한다. 명사 → りんご.","2. 그 뒤에 とか를 붙인다(りんごとか).","3. 다음 예를 이어 같은 방식으로 붙인다(りんごとかみかんとか). 동사는 사전형에 붙이고 끝에 する를 쓴다(見るとか行くとかする).","4. 문장 끝에서 보통형 + とか로 쓰면 '~라고 하던데'라는 불확실한 전문이 된다(명사·な형용사는 だ + とか)."],"why":"","nu":"예를 몇 가지 들어 나열할 때 쓰는 회화체다. 마지막 とか는 생략할 수 있고, 하나만 들어 말을 부드럽게 하기도 한다(お茶とか、どう?). 문장 끝의 전문 용법은 들은 내용이 확실하지 않다는 느낌으로, ～そうだ보다 막연하다. 동사 나열에서 끝의 する를 빠뜨리는 실수에 주의.","cmp":[{"g":"～や","d":"명사만 나열하고 회화·글 모두 쓰는 중립적인 말이다. ～とか는 회화적이며 동사·형용사도 나열할 수 있다."},{"g":"～たり～たりする","d":"동사를 나열하는 기본형이다. ～とか～とかする는 더 회화적이다."}],"ex":[{"jp":"休[やす]みの日[ひ]は、映画[えいが]を見[み]るとか、買[か]い物[もの]に行[い]くとかしています。","ko":"쉬는 날에는 영화를 본다든가 쇼핑을 간다든가 합니다."},{"jp":"コンビニでパンとか飲[の]み物[もの]とかを買[か]ってきた。","ko":"편의점에서 빵이라든가 음료라든가를 사 왔다."},{"jp":"田中[たなか]さん、来月[らいげつ]結婚[けっこん]するとか。","ko":"다나카 씨, 다음 달에 결혼한다던데."}],"dr":[{"t":"make","q":"パン / ケーキ → ～とか～とか","a":"パンとかケーキとか","hint":"명사마다 とか를 붙인다"},{"t":"make","q":"明日は雨だ(전문) → ～とか","a":"明日は雨だとか","hint":"명사는 だ를 남기고 + とか"},{"t":"fill","q":"部屋[へや]を掃除[そうじ]する（　）、洗濯[せんたく]する（　）して、週末[しゅうまつ]を過[す]ごした。","a":"とか","opts":["とか","ほど","さえ","ので"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%8B"],"vf":1,"u":1,"g":1,"gp":"gg_N2_00"},{"id":"g2_107","t":"～において","ko":"~에서, ~에 있어서","cat":"조사","conn":[{"w":"명사(장소)","f":"会議室 + において"},{"w":"명사(시대·시간)","f":"現代 + において"},{"w":"명사(분야)","f":"研究 + において"},{"w":"명사 수식","f":"日本 + における + 問題"}],"rule":["1. 장소·시간·분야를 나타내는 명사 뒤에 において를 붙인다. 会議室 → 会議室において.","2. 뒤의 명사를 꾸밀 때는 における로 바꾼다. 日本における問題.","3. 대비·강조할 때는 においては, においても처럼 조사를 더 붙인다."],"why":"","nu":"조사 で(동작이 일어나는 장소·시간)를 딱딱하게 바꾼 문어적 표현으로, 공식 문서·뉴스·논문·연설에서 쓴다. 행사·회의·시험이 열리는 장소, 시대, 분야에 쓰며, 사물이나 사람이 '있는' 장소(×東京において家がある)에는 쓰지 않는다. 일상 회화에서 쓰면 지나치게 딱딱하게 들린다.","cmp":[{"g":"で","d":"일상적인 장소·수단의 조사. において는 장소·시간·분야에만 쓰고 수단(×バスにおいて)에는 쓰지 않는다."},{"g":"～にとって","d":"'~의 입장에서 보면'이라는 평가의 기준을 나타낸다. において는 일이 일어나는 장(場)을 나타낸다."}],"ex":[{"jp":"会議[かいぎ]は本社[ほんしゃ]の会議室[かいぎしつ]において行[おこな]われます。","ko":"회의는 본사 회의실에서 열립니다."},{"jp":"現代[げんだい]において、インターネットは欠[か]かせないものだ。","ko":"현대에 있어서 인터넷은 빠뜨릴 수 없는 것이다."},{"jp":"彼[かれ]は医学[いがく]の分野[ぶんや]において大[おお]きな業績[ぎょうせき]を残[のこ]した。","ko":"그는 의학 분야에서 큰 업적을 남겼다."}],"dr":[{"t":"make","q":"東京 → ～において","a":"東京において","hint":"명사 뒤에 그대로 において"},{"t":"make","q":"日本 + 問題 → ～における","a":"日本における問題","hint":"명사를 꾸밀 때는 における"},{"t":"fill","q":"入学式[にゅうがくしき]は大[だい]ホール（　）行[おこな]われる。","a":"において","opts":["において","にとって","について","によって"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AB%E3%81%8A%E3%81%84%E3%81%A6-%E3%81%AB%E3%81%8A%E3%81%91%E3%82%8B?deck_id=14","https://www.mlcjapanese.co.jp/n2_04_28.html"],"vf":1,"u":1,"g":1,"gp":"gg_N2_00"},{"id":"g2_044","t":"～かける","ko":"~하다 말다, ~하다가 말다","cat":"활용","conn":[{"w":"동사 ます형 어간","f":"食べ + かける"},{"w":"명사 수식","f":"食べ + かけの + りんご"},{"w":"동사(する)","f":"し + かける"}],"rule":["1. 동사를 ます형 어간으로 바꾼다(2그룹 食べる: 어미 る를 뺀다 → 食べ).","2. 그 뒤에 かける를 붙인다(食べかける).","3. 명사를 꾸밀 때는 かけ + の를 쓴다(食べかけのりんご).","4. かける는 2그룹 동사처럼 활용한다(食べかけた, 食べかけて)."],"why":"","nu":"동작을 시작했지만 도중에 그만두었거나 아직 끝나지 않은 상태를 나타낸다(読みかけの本). 死ぬ・忘れる 같은 순간적인 변화 동사에 붙으면 '거의 ~할 뻔하다·~하려 하다'라는 뜻이 된다(死にかけた). 話しかける(말을 걸다)·呼びかける(호소하다)처럼 '상대에게 ~하다'라는 다른 뜻의 복합동사와 구별해야 한다.","cmp":[{"g":"～始める","d":"동작의 시작만 말한다. かける는 시작했지만 끝나지 않았다는 점에 초점이 있다."},{"g":"～途中","d":"'~하는 도중'이라는 명사 표현으로, 그만두었다는 느낌은 없다."}],"ex":[{"jp":"食[た]べかけのりんごがテーブルの上[うえ]にある。","ko":"먹다 만 사과가 테이블 위에 있다."},{"jp":"読[よ]みかけた本[ほん]を、電車[でんしゃ]に忘[わす]れてきた。","ko":"읽다 만 책을 전철에 두고 왔다."},{"jp":"何[なに]か言[い]いかけて、彼女[かのじょ]は黙[だま]ってしまった。","ko":"뭔가 말하려다 그녀는 입을 다물어 버렸다."}],"dr":[{"t":"make","q":"書く → ～かけの手紙","a":"書きかけの手紙","hint":"1그룹 く → き + かけの"},{"t":"make","q":"飲む → ～かけた","a":"飲みかけた","hint":"1그룹 む → み + かけた"},{"t":"fill","q":"作[つく]り（　）料理[りょうり]をそのままにして、出[で]かけた。","a":"かけの","opts":["かけの","がちな","あげくの","ながらの"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%8B%E3%81%91"],"vf":1,"u":1,"g":1,"gp":"gg_N2_00"},{"id":"g2_077","t":"～っぱなし","ko":"~한 채로 둠, 계속 ~함","cat":"활용","conn":[{"w":"동사 ます형(1그룹)","f":"出し + っぱなし"},{"w":"동사 ます형(2그룹)","f":"開け + っぱなし"},{"w":"동사 ます형(1그룹)","f":"立ち + っぱなし"}],"rule":["1. 1그룹 동사 出す는 어미 す를 し로 바꿔 ます형 出し를 만든다.","2. ます형 뒤에 っぱなし를 붙인다(出しっぱなし).","3. 문장에서는 出しっぱなしにする / 出しっぱなしだ / 出しっぱなしの水처럼 명사처럼 쓴다."],"why":"","nu":"① 해야 할 마무리를 하지 않고 그대로 내버려 둠(電気をつけっぱなし, 水を出しっぱなし)으로, 비난하는 느낌이 있다. ② 같은 상태가 계속됨(一日中立ちっぱなし, 負けっぱなし). 회화에서 자주 쓴다.","cmp":[{"g":"～たまま","d":"たまま는 '~한 채로'라는 중립적 상태 표현이다. っぱなし는 그대로 방치했다는 부정적 평가가 들어간다."}],"ex":[{"jp":"水[みず]を出[だ]しっぱなしにしないでください。","ko":"물을 틀어 놓은 채로 두지 마세요."},{"jp":"窓[まど]を開[あ]けっぱなしで出[で]かけてしまった。","ko":"창문을 열어 둔 채로 나가 버렸다."},{"jp":"今日[きょう]は一日中[いちにちじゅう]立[た]ちっぱなしで、足[あし]が痛[いた]い。","ko":"오늘은 하루 종일 서 있어서 다리가 아프다."}],"dr":[{"t":"make","q":"つける → ～っぱなし","a":"つけっぱなし","hint":"2그룹은 る를 뗀 ます형 + っぱなし"},{"t":"make","q":"置く → ～っぱなし","a":"置きっぱなし","hint":"く를 き로 바꾼 ます형 + っぱなし"},{"t":"fill","q":"テレビをつけ（　）で寝[ね]てしまった。","a":"っぱなし","opts":["っぱなし","っこない","つつある","だらけ"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/%E3%81%A3%E3%81%B1%E3%81%AA%E3%81%97-ppanashi-meaning/"],"vf":1,"u":1,"g":1,"gp":"gg_N2_00"},{"id":"g2_180","t":"～切る","ko":"끝까지 다 ~하다, 완전히 ~하다","cat":"활용","conn":[{"w":"동사 ます형","f":"食べ + 切る"},{"w":"동사 ます형(1그룹)","f":"使い + 切る"}],"rule":["1. 동사를 ます형으로 만든다. 食べる는 る를 떼어 食べ가 된다.","2. ます형 뒤에 切る를 붙인다(食べ切る).","3. 1그룹 동사는 어미 う단을 い단으로 바꾼다(使う → 使い切る).","4. 切る 자체는 1그룹 동사로 활용한다(食べ切った, 食べ切れない)."],"why":"","nu":"남김없이 끝까지 하거나, 상태가 완전히 그렇게 되었음을 나타낸다(疲れ切る, 澄み切る). 가능형 ～切れる / ～切れない는 '다 ~할 수 있다 / 다 ~할 수 없다'로 자주 쓴다(食べ切れない). 시작과 끝이 있는 동작에 붙으며, 終わる처럼 이미 끝을 뜻하는 동사에는 붙이지 않는다.","cmp":[{"g":"～終わる","d":"동작이 끝났다는 사실만 말한다. ～切る는 남김없이, 끝까지 해냈다는 점을 강조한다."}],"ex":[{"jp":"こんなにたくさん、一人[ひとり]では食[た]べ切[き]れない。","ko":"이렇게 많이는 혼자서 다 못 먹는다."},{"jp":"一か月[いっかげつ]で給料[きゅうりょう]を全部[ぜんぶ]使[つか]い切[き]ってしまった。","ko":"한 달 만에 월급을 전부 다 써 버렸다."},{"jp":"マラソンで42キロを走[はし]り切[き]った。","ko":"마라톤에서 42킬로미터를 끝까지 달렸다."}],"dr":[{"t":"make","q":"読む → ～切る","a":"読み切る","hint":"む를 み로 바꾼 ます형 + 切る"},{"t":"make","q":"疲れる → ～切っている","a":"疲れ切っている","hint":"る를 뗀 ます형 + 切っている"},{"t":"fill","q":"この本[ほん]は一日[いちにち]で読[よ]み（　）。","a":"切った","opts":["切った","次第","気味","向け"]}],"src":["https://bunpro.jp/ja/grammar_points/%E5%88%87%E3%82%8B"],"vf":1,"u":1,"g":1,"gp":"gg_N2_00"},{"id":"g2_062","t":"～ことになっている","ko":"~하게 되어 있다, ~하기로 되어 있다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"脱ぐ + ことになっている"},{"w":"동사 ない형","f":"外出しない + ことになっている"}],"rule":["1. 동사를 사전형 또는 ない형으로 둔다(脱ぐ, 外出しない).","2. 형식명사 こと와 조사 に를 붙인다(脱ぐことに).","3. なる의 ている형 なっている를 붙인다(脱ぐことになっている)."],"why":"","nu":"규칙·관습·법, 또는 이미 정해진 예정을 나타낸다. 말하는 사람이 아니라 조직·사회·다른 사람이 정한 것이라는 느낌이 있다. 정중하게는 ことになっています.","cmp":[{"g":"～ことにしている","d":"말하는 사람이 스스로 정해 지키는 습관을 나타낸다. ことになっている는 외부에서 정해진 규칙·예정이다."}],"ex":[{"jp":"日本[にほん]の家[いえ]では、玄関[げんかん]で靴[くつ]を脱[ぬ]ぐことになっている。","ko":"일본 집에서는 현관에서 신발을 벗게 되어 있다."},{"jp":"この寮[りょう]では、夜[よる]十時[じゅうじ]以降[いこう]は外出[がいしゅつ]しないことになっている。","ko":"이 기숙사에서는 밤 10시 이후에는 외출하지 않기로 되어 있다."},{"jp":"来週[らいしゅう]の会議[かいぎ]では、私[わたし]が発表[はっぴょう]することになっている。","ko":"다음 주 회의에서는 내가 발표하기로 되어 있다."}],"dr":[{"t":"make","q":"提出する → ～ことになっている","a":"提出することになっている","hint":"사전형 + ことに + なっている"},{"t":"make","q":"たばこを吸う(부정) → ～ことになっている","a":"たばこを吸わないことになっている","hint":"ない형(吸わない) + ことになっている"},{"t":"fill","q":"この会社[かいしゃ]では、休[やす]むときは前[まえ]の日[ひ]に連絡[れんらく]する（　）。","a":"ことになっている","opts":["ことになっている","ところだった","ばかりだ","ものか"]}],"src":["https://nihongokyoshi-net.com/2018/11/28/jlptn3-grammar-kotoninatteiru/"],"vf":1,"u":2,"g":1,"gp":"gg_N2_00"},{"id":"g2_065","t":"～ずにはいられない","ko":"~하지 않고는 못 배기다, 저절로 ~하게 된다","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"笑わ + ずにはいられない"},{"w":"2그룹 동사","f":"信じ + ずにはいられない"},{"w":"する","f":"心配せ + ずにはいられない"}],"rule":["1. 동사를 ない형으로 바꾸고 ない를 뺀다. 笑う → 笑わ(어미 う를 わ로).","2. 부정의 ず를 붙인다(笑わず).","3. には와 いられない를 붙인다(笑わずにはいられない).","4. する는 せず로 바꾼다(心配せずにはいられない)."],"why":"부정의 ず(~하지 않고)에 に・は와 いる의 가능 부정 いられない(있을 수 없다)가 붙어 '~하지 않고는 있을 수 없다'는 뜻이 된다.","nu":"감정이나 충동 때문에 의지와 상관없이 저절로 그렇게 하게 된다는 뜻이다. 주로 말하는 사람 자신에 대해 쓰고, 제3자에 쓸 때는 ようだ・らしい 등을 붙인다. 문어적이며 회화에서는 ～ないではいられない도 쓴다. する를 しず로 만드는 실수에 주의한다.","cmp":[{"g":"～ざるを得ない","d":"외부 사정 때문에 마지못해 하는 것이다. ずにはいられない는 내 감정이 저절로 그렇게 만든다."}],"ex":[{"jp":"あの映画[えいが]のラストシーンは、泣[な]かずにはいられなかった。","ko":"그 영화의 마지막 장면은 울지 않고는 못 배겼다."},{"jp":"彼[かれ]の話[はなし]がおかしくて、笑[わら]わずにはいられない。","ko":"그의 이야기가 우스워서 웃지 않을 수가 없다."},{"jp":"娘[むすめ]の帰[かえ]りが遅[おそ]いと、心配[しんぱい]せずにはいられない。","ko":"딸이 늦게 들어오면 걱정하지 않을 수가 없다."}],"dr":[{"t":"make","q":"言う → ～ずにはいられない","a":"言わずにはいられない","hint":"う를 わ로 바꾸고 ずにはいられない"},{"t":"make","q":"感動する → ～ずにはいられない","a":"感動せずにはいられない","hint":"する → せ + ずにはいられない"},{"t":"fill","q":"困[こま]っている人[ひと]を見[み]ると、つい助[たす]け（　）。","a":"ずにはいられない","opts":["ずにはいられない","ずにすむ","てはいけない","たがらない"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9A%E3%81%AB%E3%81%AF%E3%81%84%E3%82%89%E3%82%8C%E3%81%AA%E3%81%84","https://jlptsensei.com/learn-japanese-grammar/%E3%81%9A%E3%81%AB%E3%81%AF%E3%81%84%E3%82%89%E3%82%8C%E3%81%AA%E3%81%84-zu-ni-wa-irarenai-meaning/"],"vf":1,"u":2,"g":1,"gp":"gg_N2_00"},{"id":"g2_070","t":"～だけましだ","ko":"~인 것만도 다행이다, 그나마 낫다","cat":"문말표현","conn":[{"w":"동사 보통형(た형)","f":"済んだ + だけましだ"},{"w":"동사 보통형(사전형)","f":"ある + だけましだ"},{"w":"い형용사","f":"近い + だけましだ"},{"w":"な형용사","f":"静かな + だけましだ"}],"rule":["1. 1그룹 동사 済む는 어미 む를 ん으로 바꾸고 だ를 붙여 た형 済んだ를 만든다.","2. 그 뒤에 だけましだ를 붙인다(済んだだけましだ).","3. い형용사는 그대로(近いだけましだ), な형용사는 な를 넣어(静かなだけましだ) 붙인다."],"why":"","nu":"상황이 좋지는 않지만 더 나쁜 경우보다는 낫다고 스스로 위로하거나 남을 달랠 때 쓴다. 앞에 けど·が로 불만을 먼저 말하고, まだ와 함께 쓰는 일이 많다(まだ～だけましだ). 회화에서 자주 쓴다.","cmp":[{"g":"～だけあって","d":"だけあって는 '~인 만큼 역시 훌륭하다'는 칭찬이고, だけましだ는 '나쁘지만 그나마 낫다'는 위안이다."}],"ex":[{"jp":"事故[じこ]にあったが、軽[かる]いけがで済[す]んだだけましだ。","ko":"사고를 당했지만 가벼운 부상으로 끝난 것만도 다행이다."},{"jp":"給料[きゅうりょう]は安[やす]いけど、仕事[しごと]があるだけましだ。","ko":"월급은 적지만 일이 있는 것만도 낫다."},{"jp":"この部屋[へや]は狭[せま]いが、駅[えき]に近[ちか]いだけましだ。","ko":"이 방은 좁지만 역에서 가까운 것만도 낫다."}],"dr":[{"t":"make","q":"けががない(과거) → ～だけましだ","a":"けががなかっただけましだ","hint":"ない를 なかった로 바꾸고 + だけましだ"},{"t":"make","q":"静かだ → ～だけましだ","a":"静かなだけましだ","hint":"な형용사는 だ를 な로 바꾸고 + だけましだ"},{"t":"fill","q":"雨[あめ]に降[ふ]られたが、傘[かさ]を持[も]っていた（　）。","a":"だけましだ","opts":["だけましだ","わけがない","どころではない","ものか"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/だけましだ-dake-mashi-da-meaning/"],"vf":1,"u":2,"g":1,"gp":"gg_N2_00"},{"id":"g2_087","t":"～ではないか","ko":"~가 아닌가, ~지 않은가 / ~하자","cat":"문말표현","conn":[{"w":"동사 보통형","f":"言った + ではないか"},{"w":"い형용사","f":"おいしい + ではないか"},{"w":"な형용사 어간","f":"きれい + ではないか"},{"w":"명사","f":"田中さん + ではないか"},{"w":"동사 의지형","f":"頑張ろう + ではないか"}],"rule":["1. 동사는 보통형에 그대로 붙인다. 言う → 言った(う를 った로 바꾼 과거형).","2. 그 뒤에 ではないか를 붙인다(言ったではないか).","3. い형용사는 그대로(おいしいではないか), な형용사와 명사는 だ 없이 바로(きれいではないか, 田中さんではないか) 붙인다.","4. 동사 의지형에 붙이면 '함께 ~하자'는 호소가 된다(頑張ろうではないか)."],"why":"","nu":"질문이 아니라 말하는 사람의 놀람·발견, 상대에게 사실을 들이대며 확인·비난하는 기분을 나타낸다. 끝을 내려서 말하며, 한국어 부정 의문 '~가 아닌가요?'처럼 묻는 뜻으로 오해하기 쉽다. ではないか는 딱딱하고 연설·글에 많고, 회화에서는 じゃないか(남성적), じゃない를 쓴다. 의지형 + ではないか는 연설 등에서 청중에게 호소할 때 쓴다.","cmp":[{"g":"～ではないだろうか","d":"'~가 아닐까'라는 조심스러운 추측·의견 제시다. ～ではないか는 확신을 가지고 강하게 주장하거나 놀람을 나타낸다."}],"ex":[{"jp":"約束[やくそく]の時間[じかん]はとっくに過[す]ぎているではないか。","ko":"약속 시간은 이미 한참 지났지 않은가."},{"jp":"この店[みせ]のラーメン、なかなかおいしいではないか。","ko":"이 가게 라멘, 꽤 맛있지 않은가."},{"jp":"みんなで力[ちから]を合[あ]わせて頑張[がんば]ろうではないか。","ko":"모두 힘을 합쳐 열심히 해 보자."}],"dr":[{"t":"make","q":"言う(과거) → ～ではないか","a":"言ったではないか","hint":"う를 った로 바꾼 과거형 + ではないか"},{"t":"make","q":"始める(의지형) → ～ではないか","a":"始めようではないか","hint":"2그룹: る를 よう로 바꾼 의지형 + ではないか"},{"t":"fill","q":"最後[さいご]まであきらめずに戦[たたか]おう（　）。","a":"ではないか","opts":["ではないか","にすぎない","わけがない","ものか"]}],"src":["https://bunpro.jp/grammar_points/%E3%82%88%E3%81%86%E3%81%A7%E3%81%AF%E3%81%AA%E3%81%84%E3%81%8B"],"vf":1,"u":2,"g":1,"gp":"gg_N2_00"},{"id":"g2_090","t":"～て当然だ","ko":"~하는 것이 당연하다","cat":"문말표현","conn":[{"w":"동사 て형","f":"怒る → 怒って + 当然だ"},{"w":"동사 ない형","f":"合格しない → 合格しなくて + 当然だ"},{"w":"い형용사","f":"高い → 高くて + 当然だ"},{"w":"な형용사","f":"有名だ → 有名で + 当然だ"}],"rule":["1. 동사를 て형으로 만든다. 怒る → 怒って(る를 って로).","2. 그 뒤에 当然だ를 붙인다(怒って当然だ).","3. い형용사는 い를 くて로(高くて当然だ), な형용사는 だ를 で로(有名で当然だ) 바꾸어 붙인다."],"why":"","nu":"앞에 나온 사정을 생각하면 그런 결과·반응이 나오는 것이 마땅하다는 판단이다. 보통 앞에 ～から・～のだから・～たら 같은 이유나 조건이 온다. 정중하게는 ～て当然です. 남의 반응을 이해하고 편드는 느낌으로도 쓴다.","cmp":[{"g":"～て当たり前だ","d":"뜻은 거의 같고 조금 더 회화적이다."},{"g":"～のも無理はない","d":"'~하는 것도 무리가 아니다'로, 그럴 수밖에 없다고 이해하며 감싸 주는 느낌이 더 강하다."}],"ex":[{"jp":"あんなひどいことを言[い]われたら、怒[おこ]って当然[とうぜん]だ。","ko":"그런 심한 말을 들으면 화내는 게 당연하다."},{"jp":"毎日[まいにち]練習[れんしゅう]しているのだから、上手[じょうず]になって当然[とうぜん]だ。","ko":"매일 연습하고 있으니 잘하게 되는 게 당연하다."},{"jp":"駅[えき]の前[まえ]のマンションだから、家賃[やちん]が高[たか]くて当然[とうぜん]だ。","ko":"역 앞 아파트니까 집세가 비싼 게 당연하다."}],"dr":[{"t":"make","q":"疲れる → ～て当然だ","a":"疲れて当然だ","hint":"2그룹: る를 떼고 て + 当然だ"},{"t":"make","q":"高い → ～て当然だ","a":"高くて当然だ","hint":"い형용사: い를 くて로 바꾸고 当然だ"},{"t":"fill","q":"三日[みっか]も寝[ね]ていないのだから、疲[つか]れて（　）。","a":"当然だ","opts":["当然だ","おく","以来だ","あげる"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A6%E5%BD%93%E7%84%B6%E3%81%A0"],"vf":1,"u":2,"g":1,"gp":"gg_N2_00"},{"id":"g2_091","t":"～というものだ","ko":"(그것이 바로) ~라는 것이다, ~인 법이다","cat":"문말표현","conn":[{"w":"동사 보통형","f":"眠れる + というものだ"},{"w":"い형용사","f":"もったいない + というものだ"},{"w":"な형용사 어간","f":"無理 + というものだ"},{"w":"명사","f":"親 + というものだ"}],"rule":["1. な형용사는 끝의 だ를 뗀 어간을 쓴다. 無理だ → 無理.","2. 그 뒤에 というものだ를 붙인다(無理というものだ).","3. 명사도 だ 없이 바로 붙이고(親というものだ), 동사·い형용사는 보통형에 그대로 붙인다."],"why":"","nu":"어떤 일에 대해 '본래 그런 것이다, 그렇게 말하는 것이 당연하다'고 말하는 사람이 확신을 가지고 판단할 때 쓴다. それは無理というものだ처럼 상대의 생각을 부정하거나 비판할 때 자주 쓰이며, これで安心して眠れるというものだ처럼 '이제야 ~할 수 있게 되었다'는 감회에도 쓴다. 딱딱하고 글에 가까운 표현이다.","cmp":[{"g":"～というものではない","d":"'반드시 ~한 것은 아니다'라는 부분 부정이다(高ければいいというものではない). ～というものだ는 그렇다고 단정한다."},{"g":"～ものだ","d":"사물의 일반적인 성질·경향을 말한다(人は変わるものだ). ～というものだ는 눈앞의 구체적인 일에 대해 말하는 사람의 판단을 강하게 내세운다."}],"ex":[{"jp":"一日[いちにち]で全部[ぜんぶ]覚[おぼ]えるなんて、無理[むり]というものだ。","ko":"하루 만에 전부 외우다니, 그건 무리라는 것이다."},{"jp":"約束[やくそく]の時間[じかん]に一時間[いちじかん]も遅[おく]れるのは、失礼[しつれい]というものだ。","ko":"약속 시간에 한 시간이나 늦는 것은 실례라는 것이다."},{"jp":"試験[しけん]が終[お]わった。これでやっとゆっくり眠[ねむ]れるというものだ。","ko":"시험이 끝났다. 이제야 비로소 푹 잘 수 있겠다."}],"dr":[{"t":"make","q":"わがままだ → ～というものだ","a":"わがままというものだ","hint":"な형용사: だ를 떼고 というものだ"},{"t":"make","q":"安心できる → ～というものだ","a":"安心できるというものだ","hint":"동사는 보통형 그대로 + というものだ"},{"t":"fill","q":"一人[ひとり]で十人分[じゅうにんぶん]の仕事[しごと]をするのは無理[むり]（　）。","a":"というものだ","opts":["というものだ","とともに","ばかりか","どころか"]}],"src":["https://bunpro.jp/grammar_points/420"],"vf":1,"u":3,"g":1,"gp":"gg_N2_00"},{"id":"g2_092","t":"どうにか～ないものか","ko":"어떻게든 ~할 수 없을까","cat":"문말표현","conn":[{"w":"동사 가능형의 ない형","f":"乗れる → 乗れない + ものか"},{"w":"동사 ない형(무의지 동사)","f":"間に合う → 間に合わない + ものか"},{"w":"정중·완곡","f":"会えない + ものだろうか"}],"rule":["1. 동사를 가능형으로 만든다. 乗る → 乗れる(1그룹은 う단을 え단으로 바꾸고 る).","2. 가능형의 る를 ない로 바꾼다(乗れない).","3. 그 뒤에 ものか를 붙이고, 앞에 どうにか를 둔다(どうにか乗れないものか)."],"why":"","nu":"실현이 어려운 일을 '어떻게든 이루어졌으면' 하고 강하게 바라는 마음을 나타낸다. 앞에 どうにか・何とか・どうにかして가 자주 오고, 동사는 주로 가능형이나 間に合う 같은 무의지 동사의 ない형이다. ものだろうか로 하면 부드러워진다. 사전형에 붙는 반어의 ものか(行くものか = 절대 안 간다)와 헷갈리기 쉬우니, ない + ものか는 '바람'이라고 기억한다.","cmp":[{"g":"동사 사전형 + ものか","d":"行くものか처럼 '결코 ~하지 않겠다'는 강한 부정(반어)이다. ～ないものか는 '~할 수 없을까'라는 바람이다."}],"ex":[{"jp":"どうにかこの問題[もんだい]を解決[かいけつ]できないものか。","ko":"어떻게든 이 문제를 해결할 수 없을까."},{"jp":"どうにか終電[しゅうでん]に間[ま]に合[あ]わないものか。","ko":"어떻게든 막차 시간에 맞출 수 없을까."},{"jp":"何[なん]とかして、もう少[すこ]し安[やす]く買[か]えないものだろうか。","ko":"어떻게 좀 더 싸게 살 수 없을까."}],"dr":[{"t":"make","q":"会う → どうにか～ないものか","a":"どうにか会えないものか","hint":"う를 え로 바꾼 가능형 会える → る를 ない로 + ものか"},{"t":"make","q":"休む → どうにか～ないものか","a":"どうにか休めないものか","hint":"む를 め로 바꾼 가능형 休める → る를 ない로 + ものか"},{"t":"fill","q":"どうにかして、この痛[いた]みを止[と]められない（　）。","a":"ものか","opts":["ものか","ばかりか","どころか","くせに"]}],"src":["https://mainichi-nonbiri.com/grammar/n1-naimonoka/"],"vf":1,"u":3,"g":1,"gp":"gg_N2_01"},{"id":"g2_103","t":"～ないこともない","ko":"~하지 않는 것도 아니다, ~못 할 것도 없다","cat":"문말표현","conn":[{"w":"동사 ない형","f":"食べない + こともない"},{"w":"동사 ない형(1그룹)","f":"行かない + こともない"},{"w":"い형용사","f":"高くない + こともない"},{"w":"な형용사","f":"好きじゃない + こともない"},{"w":"명사","f":"無理じゃない + こともない"}],"rule":["1. 2그룹 동사는 어미 る를 떼고 ない를 붙여 ない형을 만든다. 食べる → 食べない.","2. 1그룹 동사는 어미 う단을 あ단으로 바꾸고 ない를 붙인다. 行く → 行かない.","3. 그 ない형 뒤에 こともない를 붙인다. 食べない → 食べないこともない.","4. い형용사는 い를 くない로(高くない), な형용사·명사는 じゃない로 바꾼 뒤 こともない를 붙인다."],"why":"","nu":"부정을 두 번 겹쳐 '완전히 그런 것은 아니다 → 어느 정도는 그렇다/할 수는 있다'는 소극적인 긍정을 나타낸다. 적극적으로 하겠다는 뜻이 아니라 마지못해 인정하는 느낌이 있어, 뒤에 けど・が로 조건이나 망설임을 잇는 경우가 많다. 회화에서는 ～ないことはない도 거의 같은 뜻으로 쓴다. 한국어 '~하지 않을 수 없다(반드시 한다)'와 혼동하기 쉬운데 뜻이 전혀 다르다.","cmp":[{"g":"～ないことはない","d":"뜻은 거의 같다. は가 들어가 '전혀 ~하지 않는 것은 아니다'라는 대비가 조금 더 분명하다."},{"g":"～ないではいられない","d":"감정을 억누를 수 없어 '저절로 ~하게 된다'는 강한 긍정이다. ないこともない는 약한 긍정이다."}],"ex":[{"jp":"辛[から]い料理[りょうり]は苦手[にがて]だが、食[た]べられないこともない。","ko":"매운 요리는 잘 못 먹지만 못 먹을 것도 없다."},{"jp":"駅[えき]まで歩[ある]けないこともないけど、バスで行[い]こう。","ko":"역까지 못 걸어갈 것도 없지만 버스로 가자."},{"jp":"この服[ふく]は少[すこ]し派手[はで]だけど、似合[にあ]わないこともない。","ko":"이 옷은 조금 화려하지만 안 어울리는 것도 아니다."}],"dr":[{"t":"make","q":"行く → ～ないこともない","a":"行かないこともない","hint":"く를 か로 바꾸고 ない + こともない"},{"t":"make","q":"分かる → ～ないこともない","a":"分からないこともない","hint":"る를 ら로 바꾸고 ない + こともない"},{"t":"fill","q":"お酒[さけ]は飲[の]ま（　）が、あまり好[す]きではない。","a":"ないこともない","opts":["ないこともない","ないではいられない","ないわけにはいかない","ずにはいられない"]}],"src":["https://nihongokyoshi-net.com/2019/05/17/jlptn2-grammar-naikotowanai","https://bunpro.jp/grammar_points/310"],"vf":1,"u":3,"g":1,"gp":"gg_N2_01"},{"id":"g2_104","t":"～ないではいられない","ko":"~하지 않고는 못 배기다, 저절로 ~하게 된다","cat":"문말표현","conn":[{"w":"동사 ない형(1그룹)","f":"泣かない + ではいられない"},{"w":"동사 ない형(2그룹)","f":"食べない + ではいられない"},{"w":"する","f":"心配しない + ではいられない"},{"w":"来る","f":"来ない + ではいられない"}],"rule":["1. 1그룹 동사는 어미 う단을 あ단으로 바꾸고 ない를 붙인다. 泣く → 泣かない.","2. 2그룹 동사는 る를 떼고 ない를 붙인다. 食べる → 食べない. する는 しない, 来る는 来ない가 된다.","3. ない형 뒤에 ではいられない를 붙인다. 泣かない → 泣かないではいられない."],"why":"ない + で(~하지 않고) + は + いられない(있을 수 없다, いる의 가능형 부정)로 이루어져 '~하지 않은 채로는 있을 수 없다'는 뜻이 된다.","nu":"감정이나 생리적인 충동 때문에 참으려 해도 저절로 그렇게 행동하게 된다는 뜻이다. 주어는 보통 말하는 사람 자신이며, 제3자가 주어일 때는 ～ないではいられないようだ・らしい처럼 추측 표현을 붙인다. 의지로 정한 일(규칙상 해야 하는 일)에는 쓰지 않는데, 그럴 때는 ～ないわけにはいかない를 쓴다. 회화에서는 ～ないじゃいられない라고도 한다.","cmp":[{"g":"～ずにはいられない","d":"뜻은 같고 더 문어적이다. ない 대신 ず를 쓰며 する는 せずにはいられない가 된다."},{"g":"～ないわけにはいかない","d":"사회적 사정이나 의무 때문에 '안 할 수 없다'는 뜻이다. ないではいられない는 감정에서 나오는 충동이다."}],"ex":[{"jp":"あの映画[えいが]の最後[さいご]は、泣[な]かないではいられなかった。","ko":"그 영화의 마지막 장면에서는 울지 않을 수 없었다."},{"jp":"彼[かれ]の話[はなし]がおもしろくて、笑[わら]わないではいられない。","ko":"그의 이야기가 재미있어서 웃지 않고는 못 배기겠다."},{"jp":"子[こ]どもの帰[かえ]りが遅[おそ]いと、心配[しんぱい]しないではいられない。","ko":"아이가 늦게 오면 걱정하지 않을 수가 없다."}],"dr":[{"t":"make","q":"笑う → ～ないではいられない","a":"笑わないではいられない","hint":"う를 わ로 바꾸고 ない + ではいられない"},{"t":"make","q":"言う → ～ないではいられない","a":"言わないではいられない","hint":"う를 わ로 바꾸고 ない + ではいられない"},{"t":"fill","q":"かわいい子犬[こいぬ]を見[み]ると、なで（　）。","a":"ないではいられない","opts":["ないではいられない","ないこともない","てはいけない","なくてもいい"]}],"src":["https://bunpro.jp/grammar_points/418"],"vf":1,"u":3,"g":1,"gp":"gg_N2_01"},{"id":"g2_134","t":"～のももっともだ","ko":"~하는 것도 당연하다, ~할 만도 하다","cat":"문말표현","conn":[{"w":"동사 보통형","f":"怒る + のももっともだ"},{"w":"い형용사","f":"痛い + のももっともだ"},{"w":"な형용사","f":"心配な + のももっともだ"},{"w":"명사","f":"病気な + のももっともだ"}],"rule":["1. 동사・い형용사는 보통형 그대로 뒤에 の를 붙여 명사화한다(怒るの).","2. な형용사와 명사는 な를 넣어 の를 붙인다(心配なの, 病気なの).","3. 그 뒤에 も(~도)와 もっともだ(당연하다)를 붙인다(怒るのももっともだ)."],"why":"もっとも(尤も, 지당함)에 だ가 붙은 もっともだ가 '이치에 맞다, 당연하다'는 뜻이며, の로 앞 내용을 명사로 만들고 も를 더한 것이다.","nu":"상대나 제3자의 감정・반응에 대해 '사정을 생각하면 그럴 만하다'고 이해를 나타낸다. 앞이나 뒤에 이유가 함께 나오는 일이 많다. 말하는 사람 자신의 행동에는 잘 쓰지 않는다. 같은 뜻의 회화 표현으로 ～のも無理はない, ～のも当然だ가 있다.","cmp":[{"g":"～のも無理はない","d":"뜻이 거의 같다. 無理はない는 '그럴 수밖에 없다'는 동정의 느낌이 조금 더 강하다."}],"ex":[{"jp":"大事[だいじ]なケーキを食[た]べられたんだから、彼女[かのじょ]が怒[おこ]るのももっともだ。","ko":"소중한 케이크를 먹혀 버렸으니 그녀가 화내는 것도 당연하다."},{"jp":"三日[みっか]も寝[ね]ていないなら、眠[ねむ]いのももっともだ。","ko":"사흘이나 못 잤다면 졸린 것도 당연하다."},{"jp":"初[はじ]めての海外旅行[かいがいりょこう]だから、心配[しんぱい]なのももっともだ。","ko":"첫 해외여행이니 걱정되는 것도 당연하다."}],"dr":[{"t":"make","q":"緊張する → ～のももっともだ","a":"緊張するのももっともだ","hint":"동사 보통형 + の + も + もっともだ"},{"t":"make","q":"不安だ → ～のももっともだ","a":"不安なのももっともだ","hint":"な형용사는 だ를 な로 바꾸고 の + も + もっともだ"},{"t":"fill","q":"あんなに練習[れんしゅう]したのだから、彼[かれ]が優勝[ゆうしょう]した（　）。","a":"のももっともだ","opts":["のももっともだ","に過ぎない","ばかりか","ねばならない"]}],"src":["https://bunpro.jp/grammar_points/684"],"vf":1,"u":3,"g":1,"gp":"gg_N2_01"},{"id":"g2_138","t":"～ばかりだ","ko":"~하기만 한다, 점점 ~해질 뿐이다","cat":"문말표현","conn":[{"w":"동사 사전형(변화 동사)","f":"増える + ばかりだ"},{"w":"동사 사전형","f":"悪くなる + ばかりだ"}],"rule":["1. 활용 없이 동사 사전형을 그대로 쓴다(増える).","2. 그 뒤에 ばかり를 붙인다(増えるばかり).","3. 끝에 だ를 붙인다(増えるばかりだ). 명사를 꾸밀 때는 ばかりの + 명사."],"why":"","nu":"변화가 한 방향으로만 계속 진행된다는 뜻이며 대개 나쁜 방향(悪くなる・増える・減る・ひどくなる)에 쓴다. 앞에는 변화를 나타내는 동사의 사전형만 온다. た형 + ばかりだ(막 ~했다), て형 + ばかりいる(~하기만 한다)와는 뜻이 다르니 형태를 꼭 구별해야 한다.","cmp":[{"g":"～一方だ","d":"一方だ도 한 방향으로의 계속된 변화를 나타내며 좋은 쪽・나쁜 쪽 모두 비교적 중립적으로 쓴다. ばかりだ는 나쁜 쪽에 치우친다."},{"g":"～てばかりいる","d":"てばかりいる는 '같은 행동만 반복한다'는 뜻으로 변화가 아니라 행동의 반복을 비난한다(遊んでばかりいる)."}],"ex":[{"jp":"町[まち]のごみは増[ふ]えるばかりだ。","ko":"마을의 쓰레기는 늘어나기만 한다."},{"jp":"薬[くすり]を飲[の]んでも、痛[いた]みはひどくなるばかりだった。","ko":"약을 먹어도 통증은 심해지기만 했다."},{"jp":"この村[むら]の人口[じんこう]は減[へ]るばかりだ。","ko":"이 마을의 인구는 줄어들기만 한다."}],"dr":[{"t":"make","q":"悪くなる → ～ばかりだ","a":"悪くなるばかりだ","hint":"동사 사전형 + ばかりだ"},{"t":"make","q":"減る → ～ばかりだ","a":"減るばかりだ","hint":"동사 사전형 + ばかりだ"},{"t":"fill","q":"話[はな]し合[あ]いをしないので、二人[ふたり]の関係[かんけい]は悪[わる]くなる（　）。","a":"ばかりだ","opts":["ばかりだ","ばかりか","に過ぎない","に限り"]}],"src":["https://nihongokyoshi-net.com/2019/05/03/jlptn2-grammar-bakarida/","https://bunpro.jp/grammar_points/%E3%81%B0%E3%81%8B%E3%82%8A%E3%81%A0"],"vf":1,"u":4,"g":1,"gp":"gg_N2_01"},{"id":"g2_150","t":"～ものか","ko":"~할까 보냐, 절대 ~하지 않겠다","cat":"문말표현","conn":[{"w":"동사 보통형","f":"負ける + ものか"},{"w":"い형용사","f":"おいしい + ものか"},{"w":"な형용사","f":"簡単な + ものか"},{"w":"명사","f":"天才な + ものか"}],"rule":["1. 동사는 사전형(보통형)을 그대로 둔다(負ける).","2. 그 뒤에 ものか를 붙인다(負けるものか).","3. な형용사와 명사는 な를 넣어 붙인다(簡単なものか)."],"why":"","nu":"반어 표현으로 '절대 ~하지 않는다/절대 ~가 아니다'라는 강한 부정·거부를 나타낸다. 회화체이며, 더 허물없게는 もんか, 정중하게는 ものですか(もんですか)를 쓴다. 감정이 강하게 들어가므로 윗사람 앞에서는 피하는 것이 좋다. 문말을 내려서 말한다.","cmp":[{"g":"～まい","d":"まい도 부정 의지를 나타내지만 문어적이고 담담하다. ものか는 회화체로 감정이 실린 강한 거부다."}],"ex":[{"jp":"あんな店[みせ]、二度[にど]と行[い]くものか。","ko":"저런 가게, 두 번 다시 갈까 보냐."},{"jp":"こんな難[むずか]しい問題[もんだい]が簡単[かんたん]なものか。","ko":"이렇게 어려운 문제가 쉬울 리가 있나."},{"jp":"絶対[ぜったい]に負[ま]けるものか。","ko":"절대로 질까 보냐."}],"dr":[{"t":"make","q":"諦める → ～ものか","a":"諦めるものか","hint":"사전형 + ものか"},{"t":"make","q":"静かだ → ～ものか","a":"静かなものか","hint":"な형용사는 な + ものか"},{"t":"fill","q":"あんな人[ひと]の言[い]うことなんか、信[しん]じる（　）。","a":"ものか","opts":["ものか","ものだ","ものの","ものなら"]}],"src":["https://bunpro.jp/grammar_points/503"],"vf":1,"u":4,"g":1,"gp":"gg_N2_01"},{"id":"g2_151","t":"～ものがある","ko":"~한 데가 있다, 정말 ~하다고 느껴진다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"心を打つ + ものがある"},{"w":"い형용사","f":"つらい + ものがある"},{"w":"な형용사","f":"見事な + ものがある"}],"rule":["1. い형용사는 그대로 둔다(つらい).","2. 그 뒤에 ものがある를 붙인다(つらいものがある).","3. 동사는 사전형에(心を打つものがある), な형용사는 な를 넣어(見事なものがある) 붙인다."],"why":"","nu":"어떤 대상에서 화자가 강하게 느끼는 인상·감동을 '그런 무언가가 있다'고 표현한다. 객관적 사실이 아니라 화자의 느낌이므로 감정·평가를 나타내는 말과 함께 쓴다. 약간 딱딱한 표현이다. 사물이 실제로 '있다'는 뜻으로 오해하지 않도록 주의.","cmp":[{"g":"～ところがある","d":"ところがある는 사람·사물의 일부 성질(子供っぽいところがある)을 말하고, ものがある는 화자가 받은 강한 느낌을 말한다."}],"ex":[{"jp":"彼[かれ]の歌[うた]には人[ひと]の心[こころ]を打[う]つものがある。","ko":"그의 노래에는 사람의 마음을 울리는 무언가가 있다."},{"jp":"毎日[まいにち]同[おな]じ作業[さぎょう]を続[つづ]けるのは、つらいものがある。","ko":"매일 같은 작업을 계속하는 것은 정말 힘든 데가 있다."},{"jp":"この子[こ]の絵[え]の才能[さいのう]には見事[みごと]なものがある。","ko":"이 아이의 그림 재능은 정말 훌륭하다."}],"dr":[{"t":"make","q":"寂しい → ～ものがある","a":"寂しいものがある","hint":"い형용사 + ものがある"},{"t":"make","q":"見事だ → ～ものがある","a":"見事なものがある","hint":"な형용사는 な + ものがある"},{"t":"fill","q":"この映画[えいが]には考[かんが]えさせられる（　）。","a":"ものがある","opts":["ものがある","ことがある","わけがない","ほかない"]}],"src":["https://nihongokyoshi-net.com/2019/06/05/jlptn2-grammar-monogaaru/"],"vf":1,"u":4,"g":1,"gp":"gg_N2_01"},{"id":"g2_152","t":"～ものだ","ko":"~하는 법이다 / ~하곤 했다 / 참 ~하구나","cat":"문말표현","conn":[{"w":"동사 사전형 (본성·충고)","f":"変わる + ものだ"},{"w":"동사 た형 (회상)","f":"遊んだ + ものだ"},{"w":"い형용사 (감탄)","f":"早い + ものだ"},{"w":"な형용사 (감탄)","f":"不思議な + ものだ"}],"rule":["1. 회상의 뜻일 때는 동사를 た형으로 만든다. ぶ로 끝나는 1그룹 동사는 ぶ를 んだ로 바꾼다(遊ぶ → 遊んだ).","2. 그 뒤에 ものだ를 붙인다(遊んだものだ).","3. 본성·충고의 뜻일 때는 사전형에, な형용사는 な를 넣어 붙인다."],"why":"","nu":"뜻이 여러 가지다. ① 본성·일반적 경향: 人は変わるものだ(사람은 변하는 법이다). ② 충고·상식: 年上の人には敬語を使うものだ. ③ 과거의 습관 회상: 子供のころよく遊んだものだ(た형). ④ 감탄: 時間がたつのは早いものだ. 회화에서는 もんだ가 된다. 한 번 있었던 일에는 회상 용법을 쓰지 않는다.","cmp":[{"g":"～べきだ","d":"충고의 뜻에서 べきだ는 화자 개인의 판단이고, ものだ는 사회 상식상 당연하다는 느낌이다."}],"ex":[{"jp":"子供[こども]のころは、毎日[まいにち]暗[くら]くなるまで外[そと]で遊[あそ]んだものだ。","ko":"어릴 적에는 매일 어두워질 때까지 밖에서 놀곤 했다."},{"jp":"時間[じかん]がたつのは本当[ほんとう]に早[はや]いものだ。","ko":"시간이 흐르는 건 정말 빠르구나."},{"jp":"人[ひと]の気持[きも]ちは変[か]わるものだ。","ko":"사람의 마음은 변하는 법이다."}],"dr":[{"t":"make","q":"読む → ～ものだ (회상)","a":"読んだものだ","hint":"む를 んだ로 바꾼 た형 + ものだ"},{"t":"make","q":"不思議だ → ～ものだ","a":"不思議なものだ","hint":"な형용사는 な + ものだ"},{"t":"fill","q":"学生[がくせい]のころは、よく徹夜[てつや]で勉強[べんきょう]した（　）。","a":"ものだ","opts":["ものだ","ものか","ものの","ものなら"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201206.html"],"vf":1,"u":4,"g":1,"gp":"gg_N2_01"},{"id":"g2_174","t":"～一方だ","ko":"~하기만 하다, 점점 ~해지기만 한다","cat":"문말표현","conn":[{"w":"동사 사전형(변화 동사)","f":"増える + 一方だ"},{"w":"동사 사전형(～くなる)","f":"悪くなる + 一方だ"},{"w":"する동사","f":"悪化する + 一方だ"}],"rule":["1. 변화를 나타내는 동사를 사전형 그대로 둔다. 増える.","2. 그 뒤에 一方だ를 붙인다. 増える一方だ.","3. 과거면 一方だった, 명사를 꾸밀 때는 一方の를 쓴다."],"why":"","nu":"어떤 변화가 한 방향으로만 계속 진행된다는 뜻으로, 나쁜 변화에 많이 쓰지만(増える・減る・悪くなる) 좋은 변화에도 쓸 수 있다(給料が上がる一方だ). 변화가 없는 동사(食べる・ある 등)에는 쓰지 않는다.","cmp":[{"g":"～ばかりだ","d":"동사 사전형 + ばかりだ도 '점점 ~해지기만 한다'는 뜻이지만 나쁜 변화에만 쓴다. ～一方だ는 좋은 변화에도 쓸 수 있다."},{"g":"～一方(で)","d":"문장 중간에서 '~하는 한편'이라는 대비를 나타낸다. ～一方だ는 문말에서 한 방향의 변화를 나타낸다."}],"ex":[{"jp":"最近[さいきん]、仕事[しごと]が増[ふ]える一方[いっぽう]だ。","ko":"요즘 일이 늘어나기만 한다."},{"jp":"雨[あめ]は強[つよ]くなる一方[いっぽう]だ。","ko":"비는 점점 세지기만 한다."},{"jp":"祖父[そふ]の病気[びょうき]は悪[わる]くなる一方[いっぽう]だった。","ko":"할아버지의 병은 나빠지기만 했다."}],"dr":[{"t":"make","q":"減る → ～一方だ","a":"減る一方だ","hint":"사전형 그대로 + 一方だ"},{"t":"make","q":"寒くなる → ～一方だ","a":"寒くなる一方だ","hint":"사전형 그대로 + 一方だ"},{"t":"fill","q":"この町[まち]の人口[じんこう]は減[へ]る（　）。","a":"一方だ","opts":["一方だ","わけがない","も同然だ","ようがない"]}],"src":["https://nihongokyoshi-net.com/2019/05/06/jlptn3-grammar-ippooda/","https://bunpro.jp/grammar_points/%E4%B8%80%E6%96%B9%E3%81%A0"],"vf":1,"u":4,"g":1,"gp":"gg_N2_01"},{"id":"g2_188","t":"～次第です","ko":"~한 것입니다, ~하게 된 사정입니다 (경위 설명)","cat":"문말표현","conn":[{"w":"동사 た형","f":"連絡した + 次第です"},{"w":"동사 사전형","f":"お願いする + 次第です"},{"w":"문장 + という","f":"…という + 次第です"}],"rule":["1. 동사를 た형으로 바꾼다. 連絡する는 する를 した로 바꾼다(連絡した).","2. 그 뒤에 次第です를 붙인다(連絡した次第です).","3. 앞에서 이유·경위를 설명한 다음, 그 결과 한 행동을 이 형태로 맺는다."],"why":"","nu":"'이러이러해서 ~한 것입니다'처럼 어떤 행동에 이르게 된 사정·경위를 정중하게 설명하는 격식 있는 문말 표현이다. 비즈니스 메일·사과·부탁 문장에 많다. 일상 회화에서는 ～んです, ～わけです가 자연스럽다. 명사 + 次第です(結果次第です)는 '~에 달려 있습니다'라는 다른 뜻이다.","cmp":[{"g":"～わけです","d":"이유를 설명하는 일반적인 표현. ～次第です는 더 격식 있고 자신이 한 행동의 경위를 공손히 말할 때 쓴다."},{"g":"명사 + 次第です","d":"'~에 달려 있습니다'라는 뜻(すべてはお客様次第です)으로 경위 설명이 아니다."}],"ex":[{"jp":"急[きゅう]に予定[よてい]が変[か]わったので、ご連絡[れんらく]した次第[しだい]です。","ko":"갑자기 일정이 바뀌어서 연락드린 것입니다."},{"jp":"このたび、新[あたら]しい担当者[たんとうしゃ]が決[き]まりましたので、ご挨拶[あいさつ]に伺[うかが]った次第[しだい]です。","ko":"이번에 새 담당자가 정해져서 인사차 찾아뵌 것입니다."},{"jp":"私[わたし]一人[ひとり]では難[むずか]しいので、皆様[みなさま]にご協力[きょうりょく]をお願[ねが]いする次第[しだい]です。","ko":"저 혼자서는 어렵기 때문에 여러분께 협조를 부탁드리는 바입니다."}],"dr":[{"t":"make","q":"お知らせする(과거) → ～次第です","a":"お知らせした次第です","hint":"する를 した로 바꾼 た형 + 次第です"},{"t":"make","q":"お詫びする → ～次第です","a":"お詫びする次第です","hint":"동사 사전형 + 次第です"},{"t":"fill","q":"資料[しりょう]に間違[まちが]いがありましたので、もう一度[いちど]お送[おく]りした（　）。","a":"次第です","opts":["次第です","恐れがあります","限りです","向けです"]}],"src":["https://bunpro.jp/grammar_points/865"],"vf":1,"u":5,"g":1,"gp":"gg_N2_01"},{"id":"g2_033","t":"～をめぐる","ko":"~을 둘러싼","cat":"명사화·수식","conn":[{"w":"명사","f":"土地 + をめぐる + 争い"}],"rule":["1. 화제가 되는 명사(명사1) 뒤에 조사 を를 붙인다.","2. 그 뒤에 동사 めぐる를 사전형(연체형) 그대로 붙인다.","3. 바로 뒤에 争い・問題・議論처럼 다툼·논의를 뜻하는 명사(명사2)를 놓아 꾸민다(土地をめぐる争い)."],"why":"동사 めぐる(巡る, 둘레를 돌다)가 사전형으로 뒤의 명사를 꾸미는 형태다.","nu":"뉴스 제목·기사처럼 딱딱한 글에서 많이 쓴다. 명사2에는 争い・対立・議論・問題・うわさ처럼 여러 사람이 얽힌 다툼·논의를 나타내는 말이 온다. 문장을 이어 갈 때는 をめぐって를 쓴다.","cmp":[{"g":"～をめぐって","d":"같은 뜻이지만 뒤의 동사·문장에 이어진다. をめぐる는 바로 뒤 명사를 꾸민다."},{"g":"～に関する","d":"단순히 '~에 관한'이라는 뜻으로 다툼이 없어도 쓴다(日本に関する本)."}],"ex":[{"jp":"土地[とち]をめぐる争[あらそ]いは、なかなか終[お]わらない。","ko":"땅을 둘러싼 다툼은 좀처럼 끝나지 않는다."},{"jp":"環境問題[かんきょうもんだい]をめぐる国際会議[こくさいかいぎ]が開[ひら]かれた。","ko":"환경 문제를 둘러싼 국제회의가 열렸다."},{"jp":"彼[かれ]の結婚[けっこん]をめぐるうわさが広[ひろ]がっている。","ko":"그의 결혼을 둘러싼 소문이 퍼지고 있다."}],"dr":[{"t":"make","q":"遺産 / 争い → ～をめぐる","a":"遺産をめぐる争い","hint":"명사1 + を + めぐる + 명사2"},{"t":"make","q":"ダム建設をめぐって議論 → 명사 수식으로","a":"ダム建設をめぐる議論","hint":"めぐって를 사전형 めぐる로 바꿔 명사를 꾸민다"},{"t":"fill","q":"新[あたら]しい法律[ほうりつ]（　）議論[ぎろん]が続[つづ]いている。","a":"をめぐる","opts":["をめぐる","にかけて","につれて","のわりに"]}],"src":["https://bunpro.jp/grammar_points/690"],"vf":1,"u":5,"g":1,"gp":"gg_N2_01"},{"id":"g2_182","t":"～向け","ko":"~용, ~을 대상으로 한","cat":"명사화·수식","conn":[{"w":"명사 + 向けの + 명사","f":"子ども向けの + 本"},{"w":"명사 + 向けに + 동사","f":"初心者向けに + 作る"},{"w":"명사 + 向けだ","f":"若者向けだ"}],"rule":["1. 대상이 되는 사람·집단을 나타내는 명사를 놓는다(子ども).","2. 그 뒤에 向け를 붙인다(子ども向け).","3. 명사를 꾸밀 때는 の를 넣고(子ども向けの本), 동사를 꾸밀 때는 に를 넣는다(子ども向けに作る)."],"why":"向ける(향하게 하다)의 ます형 向け가 명사처럼 쓰인 것이다.","nu":"처음부터 그 사람들을 대상으로 만들었거나 계획했다는 뜻이다. 대상이 아닌 사람에게 '알맞다, 어울린다'라는 판단만 말할 때는 ～向き를 쓴다. 상품·서비스·방송 설명에 자주 쓴다.","cmp":[{"g":"～向き","d":"원래 의도와 관계없이 그 사람에게 '알맞다'는 뜻(この本は子ども向きだ = 아이에게 알맞다). ～向け는 '아이를 대상으로 만들었다'는 뜻."}],"ex":[{"jp":"これは子[こ]ども向[む]けの本[ほん]です。","ko":"이것은 어린이용 책입니다."},{"jp":"このアプリは初心者[しょしんしゃ]向[む]けに作[つく]られている。","ko":"이 앱은 초보자를 대상으로 만들어졌다."},{"jp":"外国人[がいこくじん]向[む]けの日本語[にほんご]教室[きょうしつ]に通[かよ]っている。","ko":"외국인 대상의 일본어 교실에 다니고 있다."}],"dr":[{"t":"make","q":"女性 + 向け + 雑誌","a":"女性向けの雑誌","hint":"명사를 꾸밀 때는 向け + の"},{"t":"make","q":"留学生 + 向け + 説明する","a":"留学生向けに説明する","hint":"동사를 꾸밀 때는 向け + に"},{"t":"fill","q":"この番組[ばんぐみ]は高齢者[こうれいしゃ]（　）に作[つく]られた。","a":"向け","opts":["向け","気味","次第","以来"]}],"src":["https://bunpro.jp/grammar_points/向け"],"vf":1,"u":5,"g":1,"gp":"gg_N2_01"},{"id":"g2_048","t":"～かねる","ko":"~하기 어렵다, ~할 수 없다 (정중한 거절)","cat":"가능·의무·허가","conn":[{"w":"동사 ます형 어간","f":"答え + かねる"},{"w":"동사(する)","f":"し + かねる"}],"rule":["1. 동사를 ます형 어간으로 바꾼다(2그룹 答える: 어미 る를 뺀다 → 答え).","2. 그 뒤에 かねる를 붙인다(答えかねる).","3. 정중하게 말할 때는 かねます로 끝낸다(答えかねます)."],"why":"","nu":"능력이 없어서가 아니라 입장·사정·마음 때문에 '그렇게 하기 어렵다'는 뜻이다. 가게·회사 직원이 손님에게 부드럽게 거절할 때 わかりかねます・お答えしかねます처럼 자주 쓴다. 신체적 능력이 없다는 뜻으로는 쓰지 않는다(×泳ぎかねる → 泳げない). 부정형 かねない는 '~할지도 모른다'로 뜻이 전혀 다르므로 주의한다.","cmp":[{"g":"～かねない","d":"나쁜 일이 일어날 가능성. 형태는 비슷하지만 뜻이 다르다."},{"g":"～できません","d":"직접적인 거절. かねます는 같은 내용을 더 부드럽고 정중하게 말한다."}],"ex":[{"jp":"その質問[しつもん]には、お答[こた]えしかねます。","ko":"그 질문에는 답변드리기 어렵습니다."},{"jp":"担当者[たんとうしゃ]が不在[ふざい]なので、私[わたし]には分[わ]かりかねます。","ko":"담당자가 자리에 없어서 저로서는 알기 어렵습니다."},{"jp":"彼[かれ]の意見[いけん]には、賛成[さんせい]しかねる。","ko":"그의 의견에는 찬성하기 어렵다."}],"dr":[{"t":"make","q":"決める → ～かねます","a":"決めかねます","hint":"2그룹: る를 빼고 かねます"},{"t":"make","q":"引き受ける → ～かねます","a":"引き受けかねます","hint":"ます형 어간 引き受け + かねます"},{"t":"fill","q":"申[もう]し訳[わけ]ございませんが、そのご要望[ようぼう]にはお応[こた]えし（　）。","a":"かねます","opts":["かねます","かねません","がちです","かけます"]}],"src":["https://nihongokyoshi-net.com/2018/07/23/jlptn2-grammar-kaneru/"],"vf":1,"u":5,"g":1,"gp":"gg_N2_02"},{"id":"g2_064","t":"～ざるを得ない","ko":"~하지 않을 수 없다, 어쩔 수 없이 ~하다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사","f":"行か + ざるを得ない"},{"w":"2그룹 동사","f":"認め + ざるを得ない"},{"w":"する","f":"せ + ざるを得ない"},{"w":"来る","f":"来(こ) + ざるを得ない"}],"rule":["1. 동사를 ない형으로 바꾸고 ない를 뺀다. 行く → 行か(어미 く를 か로).","2. 그 뒤에 ざるを得ない를 붙인다(行かざるを得ない).","3. 2그룹은 る를 빼고 붙인다(認めざるを得ない).","4. する는 せ, 来る는 こ로 바꾼다(中止せざるを得ない)."],"why":"","nu":"하고 싶지 않지만 상황상 다른 선택지가 없어 한다는 뜻이다. 딱딱한 문어체이며 회화에서는 ～しかない, ～なければならない가 더 흔하다. する를 しざる로 만드는 실수에 주의한다.","cmp":[{"g":"～ずにはいられない","d":"감정이 저절로 솟아 참을 수 없다는 뜻이다. ざるを得ない는 외부 사정 때문에 마지못해 한다는 뜻이다."}],"ex":[{"jp":"社長[しゃちょう]の命令[めいれい]なので、従[したが]わざるを得ない。","ko":"사장의 명령이니 따르지 않을 수 없다."},{"jp":"台風[たいふう]が来[く]るので、旅行[りょこう]は中止[ちゅうし]せざるを得ない。","ko":"태풍이 오기 때문에 여행은 취소할 수밖에 없다."},{"jp":"証拠[しょうこ]がこれだけあれば、彼[かれ]が犯人[はんにん]だと認[みと]めざるを得ない。","ko":"증거가 이만큼 있으면 그가 범인이라고 인정하지 않을 수 없다."}],"dr":[{"t":"make","q":"諦める → ～ざるを得ない","a":"諦めざるを得ない","hint":"る를 빼고 ざるを得ない"},{"t":"make","q":"残業する → ～ざるを得ない","a":"残業せざるを得ない","hint":"する → せ + ざるを得ない"},{"t":"fill","q":"電車[でんしゃ]が止[と]まったので、タクシーで行[い]か（　）。","a":"ざるを得なかった","opts":["ざるを得なかった","ないでほしかった","ずにはいられなかった","ないことはなかった"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ざるを得ない-zaru-o-enai-meaning/"],"vf":1,"u":5,"g":1,"gp":"gg_N2_02"},{"id":"g2_079","t":"～ていられない","ko":"(더 이상) ~하고 있을 수 없다","cat":"가능·의무·허가","conn":[{"w":"동사 て형(1그룹)","f":"待って + いられない"},{"w":"동사 て형(2그룹)","f":"見て + いられない"},{"w":"동사 て형(する)","f":"のんびりして + いられない"}],"rule":["1. 1그룹 동사 待つ는 어미 つ를 촉음 っ로 바꾸고 て를 붙여 て형 待って를 만든다.","2. て형 뒤에 いられない를 붙인다(待っていられない).","3. 강조할 때는 は를 넣어 待ってはいられない로 쓴다."],"why":"いられない는 いる의 가능형 いられる의 부정형으로, '~하고 있는 상태로 있을 수 없다'는 뜻이 된다.","nu":"시간이 없거나 급하거나 참기 어려운 사정 때문에 그 상태를 더 이상 계속할 수 없다, 또는 그럴 여유가 없다는 말하는 사람의 마음을 나타낸다. のんびり·ゆっくり와 함께 ～てはいられない 꼴로 자주 쓴다.","cmp":[{"g":"～どころではない","d":"どころではない는 '~할 형편이 아니다'로 명사(勉強どころではない)에도 붙는다. ていられない는 동사 て형에만 붙어 그 상태를 계속할 수 없음을 말한다."}],"ex":[{"jp":"寒[さむ]くて、もう外[そと]で待[ま]っていられない。","ko":"추워서 더 이상 밖에서 기다릴 수 없다."},{"jp":"試験[しけん]は明日[あした]だから、のんびり遊[あそ]んではいられない。","ko":"시험이 내일이라서 느긋하게 놀고 있을 수는 없다."},{"jp":"困[こま]っている人[ひと]を見[み]て、黙[だま]って見[み]ていられなかった。","ko":"곤란해하는 사람을 보고 잠자코 보고만 있을 수 없었다."}],"dr":[{"t":"make","q":"座る → ～ていられない","a":"座っていられない","hint":"る를 って로 바꾼 て형 + いられない"},{"t":"make","q":"寝る → ～ていられない","a":"寝ていられない","hint":"2그룹은 る를 떼고 て + いられない"},{"t":"fill","q":"時間[じかん]がないから、ゆっくり食[た]べて（　）。","a":"いられない","opts":["いられない","あげる","くれる","みせる"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%A6%E3%81%AF%E3%81%84%E3%82%89%E3%82%8C%E3%81%AA%E3%81%84"],"vf":1,"u":6,"g":1,"gp":"gg_N2_02"},{"id":"g2_086","t":"～てばかりはいられない","ko":"~만 하고 있을 수는 없다","cat":"가능·의무·허가","conn":[{"w":"동사 て형","f":"泣く → 泣いて + ばかりはいられない"},{"w":"동사 て형(ん음편)","f":"遊ぶ → 遊んで + ばかりはいられない"},{"w":"명사 + ばかり + 동사 て형","f":"好きな仕事ばかり + してはいられない"}],"rule":["1. 동사를 て형으로 만든다. 泣く → 泣いて(く를 いて로).","2. 뒤에 '~만'을 뜻하는 ばかり를 붙인다(泣いてばかり).","3. 대비의 조사 は와, いる의 가능형 いられる를 부정한 いられない를 붙인다(泣いてばかりはいられない).","4. 명사를 강조할 때는 명사 뒤에 ばかり를 두고 동사 て형 + はいられない를 쓴다(好きな仕事ばかりしてはいられない)."],"why":"동사 て형 + ばかり(~만) + は(대비) + いられない(いる의 가능형 부정, '있을 수 없다')로 이루어져, '~만 하고 있는 상태로 계속 있을 수는 없다'는 뜻이 된다.","nu":"상황이 그 행동만 계속하도록 내버려 두지 않으니 다른 일을 해야 한다는, 스스로 마음을 다잡는 느낌이 있다. 泣く・落ち込む・遊ぶ・頼る 등 오래 계속되는 행동과 잘 어울린다. は 대신 も를 쓴 ～てばかりもいられない도 자주 쓴다. 한국어 '~만'에 끌려 ばかり를 동사 앞에 두는(×ばかり泣いて) 실수에 주의.","cmp":[{"g":"～てはいられない","d":"ばかり가 없으면 '(지금) ~하고 있을 여유가 없다'는 뜻으로, 그 행동 자체를 할 수 없다는 말이다. ～てばかりは는 그 행동'만' 계속할 수는 없다는 뜻이다."}],"ex":[{"jp":"いつまでも泣[な]いてばかりはいられない。明日[あした]からまた頑張[がんば]ろう。","ko":"언제까지나 울고만 있을 수는 없다. 내일부터 다시 힘내자."},{"jp":"親[おや]に頼[たよ]ってばかりはいられないので、アルバイトを始[はじ]めた。","ko":"부모님께 기대기만 할 수는 없어서 아르바이트를 시작했다."},{"jp":"試験[しけん]が近[ちか]いから、遊[あそ]んでばかりはいられない。","ko":"시험이 가까우니 놀고만 있을 수는 없다."}],"dr":[{"t":"make","q":"休む → ～てばかりはいられない","a":"休んでばかりはいられない","hint":"む를 んで로 바꾼 て형 + ばかりはいられない"},{"t":"make","q":"笑う → ～てばかりはいられない","a":"笑ってばかりはいられない","hint":"う를 って로 바꾼 て형 + ばかりはいられない"},{"t":"fill","q":"失敗[しっぱい]したけれど、落[お]ち込[こ]んで（　）はいられない。","a":"ばかり","opts":["ばかり","だけに","からこそ","ほど"]}],"src":["https://www.gyanmirai.com/jlpt/jlpt-n2/grammar-study/tebakarihairarenai"],"vf":1,"u":6,"g":1,"gp":"gg_N2_02"},{"id":"g2_088","t":"～てはならない","ko":"~해서는 안 된다","cat":"가능·의무·허가","conn":[{"w":"동사 て형(1그룹)","f":"吸う → 吸って + はならない"},{"w":"동사 て형(2그룹)","f":"忘れる → 忘れて + はならない"},{"w":"する","f":"する → して + はならない"},{"w":"명사","f":"差別 + があってはならない"}],"rule":["1. 동사를 て형으로 만든다. 吸う → 吸って(う를 って로).","2. 그 뒤에 조사 は를 붙인다(吸っては).","3. 마지막에 ならない를 붙인다(吸ってはならない)."],"why":"동사 て형 + は + ならない(なる의 부정)로 이루어져 '~해서는 안 된다'는 금지를 나타낸다. 같은 구조의 ～てはいけない와 짝을 이룬다.","nu":"규칙·법·도덕처럼 일반적으로 해서는 안 되는 일을 말하는 딱딱한 표현이다. 글, 게시문, 연설에 많다. 일상 회화에서 특정 상대에게 금지할 때는 ～てはいけない(회화체 ～ちゃだめ)가 자연스럽다. 'あってはならない(있어서는 안 된다)'는 관용적으로 자주 쓰인다.","cmp":[{"g":"～てはいけない","d":"뜻은 같지만 회화에서 널리 쓴다. ～てはならない는 더 딱딱하고, 사회 규범이나 원칙을 말할 때 어울린다."}],"ex":[{"jp":"図書館[としょかん]の中[なか]で大[おお]きな声[こえ]で話[はな]してはならない。","ko":"도서관 안에서 큰 소리로 이야기해서는 안 된다."},{"jp":"戦争[せんそう]の悲[かな]しさを忘[わす]れてはならない。","ko":"전쟁의 슬픔을 잊어서는 안 된다."},{"jp":"人[ひと]の物[もの]を勝手[かって]に使[つか]ってはならない。","ko":"남의 물건을 마음대로 써서는 안 된다."}],"dr":[{"t":"make","q":"入る → ～てはならない","a":"入ってはならない","hint":"入る는 1그룹: る를 って로 바꾸고 はならない"},{"t":"make","q":"見る → ～てはならない","a":"見てはならない","hint":"2그룹: る를 떼고 て + はならない"},{"t":"fill","q":"博物館[はくぶつかん]の規則[きそく]により、展示品[てんじひん]に触[さわ]って（　）。","a":"はならない","opts":["はならない","ばかりいる","しまう","あげる"]}],"src":["https://bunpro.jp/grammar_points/516"],"vf":1,"u":6,"g":1,"gp":"gg_N2_02"},{"id":"g2_132","t":"～ねばならない","ko":"~해야 한다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사","f":"行く → 行か + ねばならない"},{"w":"2그룹 동사","f":"食べる → 食べ + ねばならない"},{"w":"する(불규칙)","f":"する → せ + ねばならない"},{"w":"来る(불규칙)","f":"来る → 来(こ) + ねばならない"}],"rule":["1. 동사를 ない형으로 만든다. 1그룹은 어미 う단을 あ단으로 바꾼다(行く → 行か).","2. ない를 붙이는 대신 ねば를 붙인다(行かねば).","3. 그 뒤에 ならない를 붙인다(行かねばならない).","4. 2그룹은 る를 떼고(食べねばならない), する는 せねばならない, 来る는 来(こ)ねばならない가 된다."],"why":"ね는 옛 부정 조동사 ず의 ね형에 ば가 붙은 것으로, '~하지 않으면 안 된다'는 なければならない와 같은 짜임이다. する가 せねば가 되는 것도 せず와 같은 이유다.","nu":"なければならない의 문어・격식 표현이다. 연설・글・결의를 말할 때 쓰며 일상 회화에서는 딱딱하게 들린다. する는 しねば가 아니라 せねば가 되는 점에 주의. 문장 끝에서 ならない를 생략한 ～ねば만으로도 결의를 나타낸다.","cmp":[{"g":"～なければならない","d":"뜻은 같지만 なければならない는 일반적인 표현이고 ねばならない는 문어적・격식적이다."}],"ex":[{"jp":"六時[ろくじ]までに駅[えき]に行[い]かねばならない。","ko":"6시까지 역에 가야 한다."},{"jp":"この問題[もんだい]は、みんなで考[かんが]えねばならない。","ko":"이 문제는 모두 함께 생각해야 한다."},{"jp":"試験[しけん]に合格[ごうかく]するために、もっと努力[どりょく]せねばならない。","ko":"시험에 합격하기 위해 더 노력해야 한다."}],"dr":[{"t":"make","q":"急ぐ → ～ねばならない","a":"急がねばならない","hint":"ぐ를 が로 바꾼 ない형 + ねばならない"},{"t":"make","q":"説明する → ～ねばならない","a":"説明せねばならない","hint":"する는 せ + ねばならない"},{"t":"fill","q":"約束[やくそく]は守[まも]ら（　）ならない。","a":"ねば","opts":["ねば","ずに","ないで","ぬように"]}],"src":["https://bunpro.jp/grammar_points/548"],"vf":1,"u":6,"g":1,"gp":"gg_N2_02"},{"id":"g2_145","t":"～べきではない","ko":"~해서는 안 된다, ~하지 말아야 한다","cat":"가능·의무·허가","conn":[{"w":"동사 사전형","f":"言う + べきではない"},{"w":"する 동사","f":"する + べきではない / すべきではない"},{"w":"명사·な형용사","f":"子供である + べきではない"}],"rule":["1. 동사를 사전형 그대로 둔다(言う).","2. 그 뒤에 べき를 붙인다(言うべき).","3. 끝에 ではない를 붙여 부정한다(言うべきではない).","4. する는 するべき 외에 る를 뺀 すべき(すべきではない)도 쓴다."],"why":"べき는 문어 조동사 べし의 연체형으로, 그 부정을 ではない로 나타낸 것이다.","nu":"도덕·상식에 비추어 그 행동은 하면 안 된다는 화자의 판단이나 충고를 나타낸다. 상대에게 직접 쓰면 강하게 들린다. べきではない(~해야 하는 것이 아니다)로 부정하며, ~ないべきだ라고 하지 않는 점에 주의. 법·규칙으로 금지된 것에는 てはいけない가 자연스럽다.","cmp":[{"g":"～てはいけない","d":"てはいけない는 규칙·허가의 금지이고, べきではない는 화자의 가치 판단에 따른 '하지 않는 편이 옳다'는 충고다."}],"ex":[{"jp":"人[ひと]の悪口[わるぐち]を言[い]うべきではない。","ko":"남의 험담을 해서는 안 된다."},{"jp":"約束[やくそく]の時間[じかん]に遅[おく]れるべきではない。","ko":"약속 시간에 늦어서는 안 된다."},{"jp":"よく知[し]らないことで人[ひと]を判断[はんだん]すべきではない。","ko":"잘 모르는 일로 사람을 판단해서는 안 된다."}],"dr":[{"t":"make","q":"捨てる → ～べきではない","a":"捨てるべきではない","hint":"사전형 + べきではない"},{"t":"make","q":"無理をする → ～べきではない (す형)","a":"無理をすべきではない","hint":"する의 る를 빼고 す + べきではない"},{"t":"fill","q":"子供[こども]の前[まえ]でたばこを吸[す]う（　）。","a":"べきではない","opts":["べきではない","わけがない","ものがある","ことになる"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%B9%E3%81%8D%E3%81%A7%E3%81%AF%E3%81%AA%E3%81%84?deck_id=99"],"vf":1,"u":6,"g":1,"gp":"gg_N2_02"},{"id":"g2_154","t":"～ものではない","ko":"~하는 게 아니다, ~해서는 안 된다 (상식)","cat":"가능·의무·허가","conn":[{"w":"동사 사전형","f":"残す + ものではない"}],"rule":["1. 동사를 사전형으로 둔다(残す).","2. 그 뒤에 ものではない를 붙인다(残すものではない)."],"why":"","nu":"사회 상식·도덕으로 볼 때 그런 행동은 하는 것이 아니라고 타이르는 표현이다. 주로 윗사람이 아랫사람에게 쓴다. 회화에서는 もんじゃない가 된다. '~인 것이 아니다'라는 단순 부정(これは私のものではない: 이것은 내 물건이 아니다)과 혼동하지 않도록 주의.","cmp":[{"g":"～べきではない","d":"べきではない는 화자 개인의 판단에 따른 충고이고, ものではない는 '세상 상식상 그렇게 하지 않는 법'이라는 타이름이다."}],"ex":[{"jp":"食[た]べ物[もの]を残[のこ]すものではない。","ko":"음식을 남기는 게 아니다."},{"jp":"人[ひと]の悪口[わるぐち]を言[い]うものではありません。","ko":"남의 험담을 하는 게 아닙니다."},{"jp":"夜遅[よるおそ]く人[ひと]の家[いえ]に電話[でんわ]するものではない。","ko":"밤늦게 남의 집에 전화하는 게 아니다."}],"dr":[{"t":"make","q":"笑う → ～ものではない","a":"笑うものではない","hint":"사전형 + ものではない"},{"t":"make","q":"嘘をつく → ～ものではない","a":"嘘をつくものではない","hint":"사전형 + ものではない"},{"t":"fill","q":"お年寄[としよ]りにそんな失礼[しつれい]なことを言[い]う（　）。","a":"ものではない","opts":["ものではない","ものがある","ものだから","ものの"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201206.html"],"vf":1,"u":7,"g":1,"gp":"gg_N2_02"},{"id":"g2_160","t":"～ようがない","ko":"~할 방법이 없다, ~할 수가 없다","cat":"가능·의무·허가","conn":[{"w":"동사 ます형","f":"直し + ようがない"},{"w":"する동사","f":"連絡し + ようがない"},{"w":"명사 + の + し","f":"連絡のし + ようがない"}],"rule":["1. 1그룹 동사는 어미 う단을 い단으로 바꿔 ます형을 만든다. 直す → 直し.","2. 2그룹 동사는 る를 뺀다. 食べる → 食べ. する → し, 来る → 来.","3. ます형 뒤에 ようがない를 붙인다. 直しようがない."],"why":"よう(様, 방법·방식) + が + ない로 '하는 방법이 없다'는 구성이다.","nu":"능력이 부족해서가 아니라 수단·방법이 없어서 할 수 없다는 뜻이다. 회화에서 자주 쓰는 'しょうがない(어쩔 수 없다)'는 'しようがない'에서 온 말이다. 강조할 때는 ～ようもない를 쓴다.","cmp":[{"g":"～ことができない","d":"단순한 불가능을 말한다. ～ようがない는 '방법·수단이 전혀 없다'는 점을 강조한다."}],"ex":[{"jp":"ここまで壊[こわ]れたら、もう直[なお]しようがない。","ko":"이렇게까지 망가지면 이제 고칠 방법이 없다."},{"jp":"電話番号[でんわばんごう]を知[し]らないので、連絡[れんらく]しようがない。","ko":"전화번호를 몰라서 연락할 방법이 없다."},{"jp":"何[なに]も言[い]ってくれないから、助[たす]けようがない。","ko":"아무 말도 해 주지 않으니 도와줄 방법이 없다."}],"dr":[{"t":"make","q":"説明する → ～ようがない","a":"説明しようがない","hint":"する의 ます형 し + ようがない"},{"t":"make","q":"探す → ～ようがない","a":"探しようがない","hint":"す를 し로 바꾼 ます형 + ようがない"},{"t":"fill","q":"住所[じゅうしょ]がわからないので、手紙[てがみ]の送[おく]り（　）。","a":"ようがない","opts":["ようがない","わけだ","ことになる","ばかりだ"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%88%E3%81%86%E3%81%8C%E3%81%AA%E3%81%84%E3%83%BB%E3%82%88%E3%81%86%E3%82%82%E3%81%AA%E3%81%84"],"vf":1,"u":7,"g":1,"gp":"gg_N2_02"},{"id":"g2_161","t":"～よりほかない","ko":"~할 수밖에 없다","cat":"가능·의무·허가","conn":[{"w":"동사 사전형","f":"歩く + よりほかない"},{"w":"동사 사전형(する)","f":"我慢する + よりほかない"}],"rule":["1. 동사는 사전형 그대로 둔다. 歩く.","2. 그 뒤에 より를 붙이고, 이어서 ほかない를 붙인다. 歩くよりほかない.","3. よりほかはない, よりほかに方法がない처럼 は나 방법을 넣어 말하기도 한다."],"why":"より(~보다) + ほか(他, 다른 것) + ない로 '그것 말고 다른 것이 없다'는 구성이다.","nu":"다른 방법이 없어서 그것을 택할 수밖에 없다는 체념·결심의 표현이다. 다소 딱딱한 표현이며 회화에서는 ～しかない가 더 흔하다. 동사 ない형이 아니라 사전형에 붙는다는 점에 주의.","cmp":[{"g":"～しかない","d":"뜻은 거의 같지만 회화에서 훨씬 많이 쓴다. ～よりほかない는 글이나 격식 있는 말투."}],"ex":[{"jp":"バスが来[こ]ないので、駅[えき]まで歩[ある]くよりほかない。","ko":"버스가 오지 않으니 역까지 걸어갈 수밖에 없다."},{"jp":"だれも手伝[てつだ]ってくれないなら、自分[じぶん]でやるよりほかない。","ko":"아무도 도와주지 않는다면 스스로 할 수밖에 없다."},{"jp":"薬[くすり]がないので、今夜[こんや]は我慢[がまん]するよりほかない。","ko":"약이 없으니 오늘 밤은 참을 수밖에 없다."}],"dr":[{"t":"make","q":"待つ → ～よりほかない","a":"待つよりほかない","hint":"사전형 그대로 + よりほかない"},{"t":"make","q":"あきらめる → ～よりほかない","a":"あきらめるよりほかない","hint":"사전형 그대로 + よりほかない"},{"t":"fill","q":"終電[しゅうでん]に乗[の]り遅[おく]れたから、タクシーで帰[かえ]る（　）。","a":"よりほかない","opts":["よりほかない","わけがない","も同然だ","ようがない"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%88%E3%82%8A%E3%81%BB%E3%81%8B%E3%81%AA%E3%81%84"],"vf":1,"u":7,"g":1,"gp":"gg_N2_02"},{"id":"g2_165","t":"～わけにはいかない","ko":"~할 수는 없다","cat":"가능·의무·허가","conn":[{"w":"동사 사전형","f":"飲む + わけにはいかない"},{"w":"동사 ない형","f":"行かない + わけにはいかない"}],"rule":["1. 동사는 사전형 그대로 둔다. 飲む.","2. 그 뒤에 わけには를 붙이고 いかない를 붙인다. 飲むわけにはいかない.","3. ない형에 붙이면 '하지 않을 수 없다(해야 한다)'가 된다. 行かない → 行かないわけにはいかない."],"why":"","nu":"능력이 없어서가 아니라 상식·도덕·사회적 책임·사정 때문에 그렇게 할 수 없다는 뜻이다. 능력상의 불가능(飲めない)과 구별해야 한다. 주로 말하는 사람 자신의 행동에 쓴다. 회화에서는 わけにはいかない를 わけにいかない라고도 한다.","cmp":[{"g":"～ことができない","d":"능력이나 상황상 불가능하다는 일반적인 말. ～わけにはいかない는 '해도 되는 상황이 아니다'라는 사회적·도덕적 이유를 담는다."}],"ex":[{"jp":"車[くるま]で来[き]たので、お酒[さけ]を飲[の]むわけにはいかない。","ko":"차를 가지고 왔기 때문에 술을 마실 수는 없다."},{"jp":"明日[あした]は試験[しけん]だから、今日[きょう]は遊[あそ]ぶわけにはいかない。","ko":"내일은 시험이라서 오늘은 놀 수 없다."},{"jp":"先生[せんせい]に頼[たの]まれたら、手伝[てつだ]わないわけにはいかない。","ko":"선생님께 부탁받으면 돕지 않을 수 없다."}],"dr":[{"t":"make","q":"休む → ～わけにはいかない","a":"休むわけにはいかない","hint":"사전형 그대로 + わけにはいかない"},{"t":"make","q":"行く(하지 않을 수 없다) → ～わけにはいかない","a":"行かないわけにはいかない","hint":"ない형 行かない + わけにはいかない"},{"t":"fill","q":"大切[たいせつ]な会議[かいぎ]があるので、遅[おく]れる（　）。","a":"わけにはいかない","opts":["わけにはいかない","わけだ","やら","も同然だ"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%8F%E3%81%91%E3%81%AB%E3%81%AF%E3%81%84%E3%81%8B%E3%81%AA%E3%81%84"],"vf":1,"u":7,"g":1,"gp":"gg_N2_02"},{"id":"g2_007","t":"A。すると B。","ko":"그러자, 그랬더니","cat":"시간·순서","conn":[{"w":"문장 + 문장","f":"ボタンを押した。 + すると + ドアが開いた。"},{"w":"상대의 말 + 추론","f":"(相手の話) + すると + ～ということですか"}],"rule":["1. 먼저 어떤 행동이나 일 A를 말한다(ボタンを押した。).","2. 다음 문장 맨 앞에 すると를 놓는다.","3. 그 뒤에 A 직후에 일어난 일이나 알게 된 사실 B를 말한다(ドアが開いた). B는 보통 과거형이다."],"why":"","nu":"B에는 A 다음에 저절로 일어난 일이나 발견한 일이 오며, 말하는 이가 의지로 하는 행동·명령·권유는 오지 않는다. 이야기나 글에서 일의 흐름을 전할 때 자주 쓴다. 상대의 말을 받아 '그렇다면'이라는 뜻으로 결론을 추측할 때도 쓴다(すると、明日は休みですか).","cmp":[{"g":"そして","d":"そして는 단순히 일을 순서대로 나열하며 자기 의지의 행동도 이어 말할 수 있다. すると는 A를 계기로 뒤따라 일어난 결과·발견을 말한다."}],"ex":[{"jp":"ボタンを押[お]した。すると、ドアが開[あ]いた。","ko":"버튼을 눌렀다. 그러자 문이 열렸다."},{"jp":"窓[まど]を開[あ]けた。すると、冷[つめ]たい風[かぜ]が入[はい]ってきた。","ko":"창문을 열었다. 그러자 찬 바람이 들어왔다."},{"jp":"薬[くすり]を飲[の]んで寝[ね]た。すると、熱[ねつ]が下[さ]がった。","ko":"약을 먹고 잤다. 그랬더니 열이 내렸다."}],"dr":[{"t":"make","q":"ボタンを押した。/ ドアが開いた。→ すると로 연결","a":"ボタンを押した。すると、ドアが開いた。","hint":"뒤따라 일어난 일 앞에 すると"},{"t":"make","q":"窓を開けた。/ 風が入ってきた。→ すると로 연결","a":"窓を開けた。すると、風が入ってきた。","hint":"결과 문장 앞에 すると"},{"t":"fill","q":"箱[はこ]を開[あ]けた。（　）、中[なか]から猫[ねこ]が出[で]てきた。","a":"すると","opts":["すると","それでも","あるいは","すなわち"]}],"src":["https://bunpro.jp/grammar_points/すると"],"vf":1,"u":7,"g":1,"gp":"gg_N2_02"},{"id":"g2_038","t":"～あげく","ko":"~한 끝에 (결국)","cat":"시간·순서","conn":[{"w":"동사 た형","f":"迷った + あげく"},{"w":"명사","f":"けんかの + あげく"}],"rule":["1. 동사를 た형으로 바꾼다(1그룹 迷う: 어미 う → った, 迷った).","2. 그 뒤에 あげく를 붙인다(迷ったあげく).","3. 명사는 の를 넣어 연결한다(けんかのあげく).","4. 뒤에는 오랜 과정 끝에 나온 결과를 쓴다(迷ったあげく、買わなかった)."],"why":"","nu":"오랫동안 고민하거나 고생한 끝에 결국 좋지 않은 결과, 또는 아쉬운 결론에 이르렀을 때 쓴다. 좋은 결과에는 잘 쓰지 않는다(좋은 결과라면 ～た結果 / ～た末に). 뒤에는 이미 일어난 일을 쓰며, 명령·의지 표현은 오지 않는다. 강조할 때는 あげくの果てに라고도 한다.","cmp":[{"g":"～末(に)","d":"'~한 끝에'로 뜻이 비슷하지만 결과가 좋든 나쁘든 쓰며 더 문어적이다. あげく는 불만·실망의 느낌이 강하다."},{"g":"～た結果","d":"원인과 결과를 객관적으로 잇는 표현이다."}],"ex":[{"jp":"一時間[いちじかん]も迷[まよ]ったあげく、何[なに]も買[か]わなかった。","ko":"한 시간이나 고민한 끝에 아무것도 사지 않았다."},{"jp":"さんざん待[ま]たされたあげく、会議[かいぎ]は中止[ちゅうし]になった。","ko":"실컷 기다린 끝에 회의는 취소되었다."},{"jp":"二人[ふたり]は長[なが]いけんかのあげく、別[わか]れてしまった。","ko":"두 사람은 오랜 싸움 끝에 헤어지고 말았다."}],"dr":[{"t":"make","q":"悩む → ～あげく","a":"悩んだあげく","hint":"1그룹 む → んだ + あげく"},{"t":"make","q":"相談 → ～あげく","a":"相談のあげく","hint":"명사 + の + あげく"},{"t":"fill","q":"さんざん悩[なや]んだ（　）、留学[りゅうがく]をあきらめた。","a":"あげく","opts":["あげく","うちに","ついでに","とたん"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%82%E3%81%92%E3%81%8F"],"vf":1,"u":7,"g":1,"gp":"gg_N2_03"},{"id":"g2_040","t":"～うちに","ko":"~하는 동안에, ~하기 전에","cat":"시간·순서","conn":[{"w":"동사 ない형","f":"冷めない + うちに"},{"w":"동사 ている형","f":"寝ている + うちに"},{"w":"い형용사","f":"若い + うちに"},{"w":"な형용사","f":"元気な + うちに"},{"w":"명사","f":"今の + うちに"}],"rule":["1. 동사를 ない형으로 바꾼다(2그룹 冷める: る를 빼고 ない → 冷めない).","2. 그 뒤에 うちに를 붙인다(冷めないうちに).","3. い형용사는 그대로, な형용사는 な, 명사는 の를 넣어 연결한다(若いうちに, 元気なうちに, 今のうちに)."],"why":"","nu":"두 가지 쓰임이 있다. ① 상태가 바뀌기 전에 미리 하다(若いうちに・冷めないうちに): 뒤에 의지·권유 표현이 자주 온다. ② 어떤 일을 하는 동안 모르는 사이에 변화가 생기다(話しているうちに、夜になった). ①은 한국어 '~하기 전에'로 옮기는 편이 자연스러운 경우가 많지만, '~ないうちに'를 '~하지 않는 동안'으로 직역하면 어색하다.","cmp":[{"g":"～前に","d":"단순히 시간 순서를 말한다. うちに는 '그 상태가 계속되는 동안, 바뀌기 전에'라는 느낌이 있다."},{"g":"～間に","d":"정해진 기간 안을 객관적으로 말한다. うちに는 상태가 바뀌기 전이라는 의식이 들어 있다."}],"ex":[{"jp":"スープが冷[さ]めないうちに、どうぞ召[め]し上[あ]がってください。","ko":"수프가 식기 전에 어서 드세요."},{"jp":"若[わか]いうちに、いろいろな国[くに]へ行[い]ってみたい。","ko":"젊을 때 여러 나라에 가 보고 싶다."},{"jp":"音楽[おんがく]を聞[き]いているうちに、眠[ねむ]ってしまった。","ko":"음악을 듣는 동안 잠들어 버렸다."}],"dr":[{"t":"make","q":"暗くなる → ～ないうちに","a":"暗くならないうちに","hint":"1그룹 る → ら + ない + うちに"},{"t":"make","q":"元気 → ～うちに","a":"元気なうちに","hint":"な형용사 + な + うちに"},{"t":"fill","q":"雨[あめ]が降[ふ]らない（　）、早[はや]く帰[かえ]りましょう。","a":"うちに","opts":["うちに","あまり","あげく","くせに"]}],"src":["https://www.mlcjapanese.co.jp/n2_04_06.html"],"vf":1,"u":8,"g":1,"gp":"gg_N2_03"},{"id":"g2_046","t":"～か～ないかのうちに","ko":"~하자마자, ~할까 말까 할 때","cat":"시간·순서","conn":[{"w":"동사 사전형 + ない형","f":"着く + か + 着かない + かのうちに"},{"w":"동사 た형 + ない형","f":"座った + か + 座らない + かのうちに"}],"rule":["1. 동사 사전형(또는 た형) 뒤에 か를 붙인다(着くか).","2. 같은 동사의 ない형을 이어 쓴다(1그룹 着く: く → か + ない, 着かない).","3. 마지막에 かのうちに를 붙인다(着くか着かないかのうちに)."],"why":"","nu":"앞의 동작이 끝났는지 아닌지 모를 만큼 거의 동시에 다음 일이 일어났다는 뜻이다. 뒤에는 이미 일어난 사실을 과거형으로 쓰며, 의지·명령·권유 표현은 올 수 없다. 같은 동사를 두 번 쓰는 점에 주의한다.","cmp":[{"g":"～たとたん(に)","d":"앞 동작이 끝난 직후 뜻밖의 일이 일어남. か～ないかのうちに는 앞 동작이 끝나기 전인지 후인지 모를 만큼 동시라는 느낌이 더 강하다."},{"g":"～や否や","d":"뜻이 비슷한 문어적 표현."}],"ex":[{"jp":"駅[えき]に着[つ]くか着[つ]かないかのうちに、雨[あめ]が降[ふ]り出[だ]した。","ko":"역에 도착하자마자 비가 내리기 시작했다."},{"jp":"ベルが鳴[な]るか鳴[な]らないかのうちに、学生[がくせい]たちは教室[きょうしつ]を出[で]た。","ko":"종이 울리자마자 학생들은 교실을 나갔다."},{"jp":"席[せき]に座[すわ]ったか座[すわ]らないかのうちに、電話[でんわ]がかかってきた。","ko":"자리에 앉자마자 전화가 걸려 왔다."}],"dr":[{"t":"make","q":"寝る → ～か～ないかのうちに","a":"寝るか寝ないかのうちに","hint":"사전형 + か + ない형 + かのうちに"},{"t":"make","q":"始まる → ～か～ないかのうちに","a":"始まるか始まらないかのうちに","hint":"1그룹 る → ら + ない"},{"t":"fill","q":"家[いえ]を出[で]るか出[で]ない（　）、雪[ゆき]が降[ふ]ってきた。","a":"かのうちに","opts":["かのうちに","ことには","あまり","かいもなく"]}],"src":["https://nihongokyoshi-net.com/2019/05/23/jlptn2-grammar-ka-naikanouchini/"],"vf":1,"u":8,"g":1,"gp":"gg_N2_03"},{"id":"g2_055","t":"～から～にかけて","ko":"~부터 ~에 걸쳐","cat":"시간·순서","conn":[{"w":"명사(장소)","f":"九州 + から + 関東 + にかけて"},{"w":"명사(시간)","f":"今夜 + から + 明日の朝 + にかけて"}],"rule":["1. 시작점이 되는 명사 뒤에 から를 붙인다(九州から).","2. 끝 쪽이 되는 명사 뒤에 にかけて를 붙인다(関東にかけて).","3. 활용하는 부분은 없다. 명사를 꾸밀 때는 にかけての를 쓴다(九州から関東にかけての地域)."],"why":"","nu":"시간·장소의 대략적인 범위 전체에 어떤 일이 일어나거나 퍼져 있음을 나타낸다. 일기예보나 뉴스에서 자주 쓴다. 한 번으로 끝나는 일에는 쓰지 않고, 그 범위 동안 이어지는 일에 쓴다. 시작과 끝을 분명히 말하고 싶을 때는 ～から～まで를 쓴다.","cmp":[{"g":"～から～まで","d":"시작과 끝이 분명한 구간을 말한다. から～にかけて는 경계가 흐릿한 대략적인 범위를 말한다."}],"ex":[{"jp":"今夜[こんや]から明日[あした]の朝[あさ]にかけて、雪[ゆき]が降[ふ]るでしょう。","ko":"오늘 밤부터 내일 아침에 걸쳐 눈이 내리겠습니다."},{"jp":"九州[きゅうしゅう]から関東[かんとう]にかけて、強[つよ]い風[かぜ]が吹[ふ]いている。","ko":"규슈에서 간토에 걸쳐 강한 바람이 불고 있다."},{"jp":"三月[さんがつ]から四月[しがつ]にかけて、桜[さくら]が咲[さ]く。","ko":"3월부터 4월에 걸쳐 벚꽃이 핀다."}],"dr":[{"t":"make","q":"夏 / 秋 → ～から～にかけて","a":"夏から秋にかけて","hint":"명사1 + から + 명사2 + にかけて"},{"t":"make","q":"北海道 / 東北 → ～から～にかけて","a":"北海道から東北にかけて","hint":"시작 쪽에 から, 끝 쪽에 にかけて"},{"t":"fill","q":"昨日[きのう]の夜[よる]から今朝[けさ]（　）、大雨[おおあめ]が降[ふ]った。","a":"にかけて","opts":["にかけて","において","に対して","によって"]}],"src":["https://nihongokyoshi-net.com/2018/04/22/jlptn3-grammar-kara-nikakete/"],"vf":1,"u":8,"g":1,"gp":"gg_N2_03"},{"id":"g2_067","t":"～たかと思ったら","ko":"~했나 싶더니 (곧바로)","cat":"시간·순서","conn":[{"w":"동사 た형(1그룹)","f":"降った + かと思ったら"},{"w":"동사 た형(2그룹)","f":"晴れた + かと思ったら"},{"w":"동사 た형(불규칙)","f":"来た + かと思ったら"}],"rule":["1. 1그룹 동사 降る는 어미 る를 촉음 っ로 바꾸고 た를 붙여 た형 降った를 만든다.","2. た형 뒤에 かと思ったら를 붙인다(降ったかと思ったら).","3. 2그룹은 る를 떼고 た(晴れた), 来る는 来た가 된다."],"why":"か(~인가) + と思ったら(~라고 생각했더니)로 이루어져 '~했나 생각했더니'라는 뜻이 된다.","nu":"앞의 일이 일어나자마자 곧바로 뒤의 일이 이어질 때, 지켜본 사람이 놀라움을 담아 묘사한다. 뒤에는 앞과 대조적인 변화가 오는 경우가 많다. 말하는 사람 자신의 행동에는 쓰지 않고, 뒤에 의지·명령·희망 표현은 오지 않는다.","cmp":[{"g":"～たとたん","d":"たとたん은 앞 동작 직후 뜻밖의 일이 일어남을 말하며 자기 행동(立ち上がったとたん)에도 쓴다. たかと思ったら는 남이나 사물의 변화를 지켜보며 쓴다."}],"ex":[{"jp":"赤[あか]ちゃんは泣[な]いたかと思[おも]ったら、もう笑[わら]っている。","ko":"아기는 울었나 싶더니 벌써 웃고 있다."},{"jp":"空[そら]が暗[くら]くなったかと思[おも]ったら、急[きゅう]に雨[あめ]が降[ふ]ってきた。","ko":"하늘이 어두워졌나 싶더니 갑자기 비가 내리기 시작했다."},{"jp":"弟[おとうと]は家[いえ]に帰[かえ]って来[き]たかと思[おも]ったら、すぐ遊[あそ]びに出[で]かけた。","ko":"남동생은 집에 왔나 싶더니 바로 놀러 나갔다."}],"dr":[{"t":"make","q":"泣く → ～たかと思ったら","a":"泣いたかと思ったら","hint":"く를 いた로 바꾼 た형 + かと思ったら"},{"t":"make","q":"来る → ～たかと思ったら","a":"来たかと思ったら","hint":"来る는 불규칙으로 来た + かと思ったら"},{"t":"fill","q":"雨[あめ]が止[や]んだ（　）、また降[ふ]り出[だ]した。","a":"かと思ったら","opts":["かと思ったら","からには","ばかりに","くせに"]}],"src":["https://bunpro.jp/grammar_points/426"],"vf":1,"u":8,"g":1,"gp":"gg_N2_03"},{"id":"g2_068","t":"～たきり","ko":"~한 채로 (그 뒤로 계속 ~않다)","cat":"시간·순서","conn":[{"w":"동사 た형(1그룹)","f":"会った + きり"},{"w":"동사 た형(2그룹)","f":"出かけた + きり"},{"w":"동사 た형(예외 行く)","f":"行った + きり"}],"rule":["1. 行く는 예외로 어미 く를 っ로 바꾸고 た를 붙여 行った가 된다.","2. た형 뒤에 きり를 붙인다(行ったきり).","3. 뒤에는 그 뒤로 예상한 일이 일어나지 않는 상태(帰ってこない, 連絡がない 등)가 온다."],"why":"","nu":"어떤 일을 한 것을 마지막으로 그 뒤 변화가 없음을 나타내며, 뒤에는 주로 부정 표현이 온다. 회화에서는 行ったっきり처럼 っきり로 말하는 일이 많다. 寝たきり(몸져누운 상태)처럼 굳어진 말도 있다.","cmp":[{"g":"～て以来","d":"て以来는 그 뒤 계속 이어지는 상태나 습관을 넓게 말한다. たきり는 그 뒤 기대한 일이 일어나지 않았다는 데에 초점이 있다."}],"ex":[{"jp":"兄[あに]は朝[あさ]出[で]かけたきり、まだ帰[かえ]ってこない。","ko":"형은 아침에 나간 채로 아직 돌아오지 않는다."},{"jp":"彼[かれ]とは卒業式[そつぎょうしき]で会[あ]ったきり、一度[いちど]も会[あ]っていない。","ko":"그와는 졸업식에서 만난 뒤로 한 번도 만나지 않았다."},{"jp":"祖母[そぼ]は去年[きょねん]から寝[ね]たきりだ。","ko":"할머니는 작년부터 몸져누워 계신다."}],"dr":[{"t":"make","q":"会う → ～たきり","a":"会ったきり","hint":"う를 った로 바꾼 た형 + きり"},{"t":"make","q":"出る → ～たきり","a":"出たきり","hint":"2그룹은 る를 떼고 た + きり"},{"t":"fill","q":"父[ちち]は若[わか]いころ一度[いちど]韓国[かんこく]へ行[い]った（　）、それから一度[いちど]も行[い]っていない。","a":"きり","opts":["きり","とたん","うちに","ついでに"]}],"src":["https://www.mlcjapanese.co.jp/n3_004.html"],"vf":1,"u":8,"g":1,"gp":"gg_N2_03"},{"id":"g2_072","t":"～たとたん","ko":"~하자마자, ~한 순간","cat":"시간·순서","conn":[{"w":"동사 た형(2그룹)","f":"開けた + とたん"},{"w":"동사 た형(1그룹)","f":"着いた + とたん"},{"w":"동사 た형(불규칙)","f":"来た + とたん"}],"rule":["1. 2그룹 동사 開ける는 어미 る를 た로 바꿔 開けた가 된다.","2. た형 뒤에 とたん(또는 とたんに)을 붙인다(開けたとたん).","3. 뒤에는 그 순간 일어난 뜻밖의 일을 과거형으로 쓴다."],"why":"とたん은 한자로 途端이라 쓰며 '바로 그 순간'을 뜻하는 명사다.","nu":"앞 동작이 끝난 바로 그 순간 예상하지 못한 일이 일어났음을 나타낸다. 뒤에 의지·명령·권유는 올 수 없다(×着いたとたん、電話してください). 말하는 사람 자신의 행동에도 쓸 수 있다.","cmp":[{"g":"～たかと思ったら","d":"たかと思ったら는 남이나 사물의 대조적인 변화를 지켜보며 말하고 자기 행동에는 쓰지 않는다. たとたん은 자기 행동에도 쓴다."}],"ex":[{"jp":"ドアを開[あ]けたとたん、猫[ねこ]が外[そと]に飛[と]び出[だ]した。","ko":"문을 연 순간 고양이가 밖으로 뛰쳐나갔다."},{"jp":"立[た]ち上[あ]がったとたん、頭[あたま]が痛[いた]くなった。","ko":"일어서자마자 머리가 아파졌다."},{"jp":"家[いえ]に着[つ]いたとたんに、雨[あめ]が降[ふ]り出[だ]した。","ko":"집에 도착하자마자 비가 내리기 시작했다."}],"dr":[{"t":"make","q":"着く → ～たとたん","a":"着いたとたん","hint":"く를 いた로 바꾼 た형 + とたん"},{"t":"make","q":"飲む → ～たとたん","a":"飲んだとたん","hint":"む를 んだ로 바꾼 た형 + とたん"},{"t":"fill","q":"電気[でんき]を消[け]した（　）、子[こ]どもが泣[な]き出[だ]した。","a":"とたん","opts":["とたん","からには","ついでに","うえは"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/たとたん-ta-totan-meaning"],"vf":1,"u":9,"g":1,"gp":"gg_N2_03"},{"id":"g2_076","t":"～つつある","ko":"~하고 있다, 점점 ~되어 가고 있다","cat":"시간·순서","conn":[{"w":"동사 ます형(2그룹)","f":"増え + つつある"},{"w":"동사 ます형(1그룹)","f":"変わり + つつある"},{"w":"동사 ます형(する)","f":"回復し + つつある"}],"rule":["1. 2그룹 동사 増える는 어미 る를 떼어 ます형 増え를 만든다.","2. ます형 뒤에 つつある를 붙인다(増えつつある).","3. 1그룹은 う단을 い단으로(変わる → 変わりつつある), する는 しつつある가 된다."],"why":"","nu":"변화가 한 방향으로 조금씩 진행 중임을 나타내는 문어적 표현으로, 뉴스·보고서에서 많이 쓴다. 増える·減る·変わる·進む·広がる처럼 변화를 나타내는 동사와 쓰며, 食べる·読む처럼 단순한 동작 동사에는 쓰지 않는다.","cmp":[{"g":"～ている","d":"ている는 동작의 진행이나 결과 상태 모두에 쓰는 일반 표현이다. 変わっている는 '이미 변해 있다'로도 읽히지만 変わりつつある는 '지금 변해 가는 중'만 뜻한다."}],"ex":[{"jp":"この町[まち]の人口[じんこう]は少[すこ]しずつ増[ふ]えつつある。","ko":"이 마을의 인구는 조금씩 늘고 있다."},{"jp":"人々[ひとびと]の考[かんが]え方[かた]は変[か]わりつつある。","ko":"사람들의 사고방식은 변해 가고 있다."},{"jp":"父[ちち]の病気[びょうき]は回復[かいふく]しつつある。","ko":"아버지의 병은 회복되어 가고 있다."}],"dr":[{"t":"make","q":"減る → ～つつある","a":"減りつつある","hint":"る를 り로 바꾼 ます형 + つつある"},{"t":"make","q":"広がる → ～つつある","a":"広がりつつある","hint":"る를 り로 바꾼 ます형 + つつある"},{"t":"fill","q":"地球[ちきゅう]の気温[きおん]は年々[ねんねん]上[あ]がり（　）。","a":"つつある","opts":["つつある","っこない","っぱなしだ","っぽい"]}],"src":["https://nihongokyoshi-net.com/2018/03/28/jlptn2-grammar-tsutsuaru/"],"vf":1,"u":9,"g":1,"gp":"gg_N2_03"},{"id":"g2_095","t":"～ところだ","ko":"막 ~하려는 참이다 / ~하는 중이다 / 막 ~했다","cat":"시간·순서","conn":[{"w":"동사 사전형(직전)","f":"食べる + ところだ"},{"w":"동사 ている형(진행 중)","f":"食べている + ところだ"},{"w":"동사 た형(직후)","f":"食べた + ところだ"}],"rule":["1. 동사 사전형에 ところ를 붙이면 막 시작하려는 장면이다(食べるところ).","2. る를 ている로 바꾸면 그 동작이 진행 중인 장면이다(食べているところ).","3. る를 た로 바꾸면 막 끝난 직후의 장면이다(食べたところ)."],"why":"","nu":"ところ는 여기서 장소가 아니라 동작의 '국면·장면'을 뜻한다. 앞에 붙는 동사의 형태로 직전·진행 중·직후를 구별한다. たところ는 실제로 막 끝난 시점에만 쓰고, たばかり는 말하는 사람이 짧게 느끼면 시간이 꽤 지나도 쓸 수 있다. ～ところだった(하마터면 ~할 뻔했다)는 다른 표현이다.","cmp":[{"g":"～たばかり","d":"'~한 지 얼마 안 됨'으로 심리적인 짧음이다(先月来たばかり). ～たところ는 바로 직후의 장면에만 쓴다."}],"ex":[{"jp":"今[いま]から出[で]かけるところです。","ko":"지금 막 나가려던 참입니다."},{"jp":"今[いま]、晩[ばん]ご飯[はん]を作[つく]っているところだ。","ko":"지금 저녁밥을 만들고 있는 중이다."},{"jp":"たった今[いま]、駅[えき]に着[つ]いたところです。","ko":"방금 막 역에 도착했습니다."}],"dr":[{"t":"make","q":"寝る → ～ところだ(직전)","a":"寝るところだ","hint":"사전형 그대로 + ところだ"},{"t":"make","q":"読む → ～ところだ(진행 중)","a":"読んでいるところだ","hint":"む를 んで로 바꾼 ている형 + ところだ"},{"t":"fill","q":"今[いま]ちょうど家[いえ]を出[で]た（　）です。","a":"ところ","opts":["ところ","ほど","ために","わりに"]}],"src":["https://langoal.com/jlpt/explain-grammar-tokoroda.html"],"vf":1,"u":9,"g":1,"gp":"gg_N2_03"},{"id":"g2_100","t":"～とともに","ko":"~와 함께, ~함과 동시에, ~에 따라","cat":"시간·순서","conn":[{"w":"명사(함께)","f":"家族 + とともに"},{"w":"동사 사전형(동시·변화)","f":"年をとる + とともに"},{"w":"명사(변화)","f":"成長 + とともに"},{"w":"명사·な형용사(겸함)","f":"医者である + とともに"}],"rule":["1. 동사는 사전형을 그대로 쓴다(とる).","2. 그 뒤에 とともに를 붙인다(とるとともに).","3. 목적어를 넣어 문장을 만든다(年をとるとともに). 명사에는 바로 붙인다(家族とともに, 成長とともに)."],"why":"","nu":"뜻이 셋이다. ① 명사 + とともに: '~와 함께'(家族とともに). ② 동사 사전형·변화를 나타내는 명사 + とともに: 한쪽이 변하면 다른 쪽도 함께 변한다(年をとるとともに). ③ である + とともに: '~인 동시에 ~이기도 하다'. 딱딱한 문어체라 회화에서는 ～と一緒に, ～につれて를 많이 쓴다.","cmp":[{"g":"～につれて","d":"점차 변해 가는 연동 변화에만 쓴다. ～とともに는 변화 외에 '함께', '동시에'의 뜻도 있다."}],"ex":[{"jp":"家族[かぞく]とともに、新[あたら]しい年[とし]を迎[むか]えた。","ko":"가족과 함께 새해를 맞았다."},{"jp":"年[とし]をとるとともに、体力[たいりょく]が落[お]ちてきた。","ko":"나이를 먹음에 따라 체력이 떨어졌다."},{"jp":"彼[かれ]は医者[いしゃ]であるとともに、作家[さっか]でもある。","ko":"그는 의사인 동시에 작가이기도 하다."}],"dr":[{"t":"make","q":"時代 → ～とともに","a":"時代とともに","hint":"명사에 바로 とともに"},{"t":"make","q":"進む → ～とともに","a":"進むとともに","hint":"사전형 그대로 + とともに"},{"t":"fill","q":"子供[こども]の成長[せいちょう]（　）、家[いえ]が狭[せま]く感[かん]じるようになった。","a":"とともに","opts":["とともに","にしては","どころか","とおりに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E5%85%B1%E3%81%AB"],"vf":1,"u":9,"g":1,"gp":"gg_N2_03"},{"id":"g2_105","t":"～ながら","ko":"~하면서 (동시 동작) / ~이면서도 (역접)","cat":"시간·순서","conn":[{"w":"동사 ます형(1그룹)","f":"歌い + ながら"},{"w":"동사 ます형(2그룹)","f":"見 + ながら"},{"w":"する·来る","f":"し + ながら / 来 + ながら"},{"w":"역접: 동사 ます형·ている","f":"知ってい + ながら"},{"w":"역접: い형용사·명사","f":"狭い + ながら / 子ども + ながら"}],"rule":["1. 1그룹 동사는 어미 う단을 い단으로 바꿔 ます형을 만든다. 歌う → 歌います.","2. ます를 떼고 그 자리에 ながら를 붙인다. 歌います → 歌いながら.","3. 2그룹 동사는 る를 떼고 ながら를 붙인다(見る → 見ながら). する는 しながら, 来る는 来ながら.","4. 역접 용법에서는 ～ていながら(知っていながら), い형용사 사전형 + ながら(狭いながら), 명사 + ながら(子どもながら)처럼도 쓴다."],"why":"","nu":"동시 동작의 ながら는 한 사람이 두 동작을 동시에 할 때 쓰며, 주된 동작은 뒤 문장에 온다(テレビを見ながらご飯を食べる는 '밥 먹기'가 중심). 두 동작의 주어는 같아야 한다. N2에서 중요한 것은 역접 용법으로, '~이면서도, ~인데도'라는 뜻이다(知っていながら教えてくれなかった). 이 경우 앞에는 상태를 나타내는 말이 오고 말하는 사람의 비난·의외의 느낌이 담기기 쉽다. 残念ながら・失礼ながら 같은 관용 표현도 역접 용법이다.","cmp":[{"g":"～つつ","d":"동시 동작과 역접 두 용법이 같지만 더 문어적이다."},{"g":"～のに","d":"역접이지만 ながら보다 회화적이고 불만의 감정이 더 직접적이다. 주어가 달라도 쓸 수 있다."}],"ex":[{"jp":"母[はは]は歌[うた]を歌[うた]いながら料理[りょうり]を作[つく]っていた。","ko":"어머니는 노래를 부르면서 요리를 하고 있었다."},{"jp":"音楽[おんがく]を聞[き]きながら勉強[べんきょう]するのが好[す]きだ。","ko":"음악을 들으면서 공부하는 것을 좋아한다."},{"jp":"彼[かれ]は本当[ほんとう]のことを知[し]っていながら、何[なに]も言[い]わなかった。","ko":"그는 사실을 알면서도 아무 말도 하지 않았다."}],"dr":[{"t":"make","q":"歩く → ～ながら","a":"歩きながら","hint":"く를 き로 바꾼 ます형에서 ます를 떼고 ながら"},{"t":"make","q":"食べる → ～ながら","a":"食べながら","hint":"る를 떼고 ながら"},{"t":"fill","q":"コーヒーを飲[の]み（　）、新聞[しんぶん]を読[よ]む。","a":"ながら","opts":["ながら","たら","ために","ように"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%81%8C%E3%82%89","https://bunpro.jp/ja/grammar_points/569"],"vf":1,"u":9,"g":1,"gp":"gg_N2_03"},{"id":"g2_106","t":"～にあたり","ko":"~에 즈음하여, ~할 때에","cat":"시간·순서","conn":[{"w":"명사","f":"開店 + にあたり"},{"w":"동사 사전형","f":"留学する + にあたり"}],"rule":["1. 명사 뒤에 그대로 にあたり를 붙인다. 開店 → 開店にあたり.","2. 동사는 사전형 뒤에 붙인다. 留学する → 留学するにあたり.","3. て형 にあたって, 명사 수식형 にあたっての도 같은 뜻으로 쓴다."],"why":"","nu":"개업·입학·결혼·졸업처럼 특별하고 중요한 일을 앞두고 있거나 시작할 때, 그에 맞춰 무엇을 한다는 뜻이다. 인사말·공지·연설 같은 격식 있는 장면에서 쓰는 딱딱한 표현이다. 일상의 사소한 일(×ご飯を食べるにあたり)에는 쓰지 않는다. 뒤에는 준비·인사·결의 같은 내용이 오는 경우가 많다.","cmp":[{"g":"～に際して","d":"뜻과 격식 정도가 비슷하다. にあたり는 중요한 일을 앞두고 준비하거나 마음가짐을 밝히는 느낌이 조금 더 강하다."},{"g":"～とき","d":"일반적인 '~할 때'로 장면 제한이 없다. にあたり는 특별한 일에만 쓴다."}],"ex":[{"jp":"新[あたら]しい店[みせ]の開店[かいてん]にあたり、ご挨拶[あいさつ]申[もう]し上[あ]げます。","ko":"새 가게 개업에 즈음하여 인사 말씀 올립니다."},{"jp":"留学[りゅうがく]するにあたり、必要[ひつよう]な書類[しょるい]をそろえた。","ko":"유학하는 것에 즈음하여 필요한 서류를 갖췄다."},{"jp":"入学[にゅうがく]にあたって、注意[ちゅうい]していただきたいことがあります。","ko":"입학에 즈음하여 주의해 주셨으면 하는 것이 있습니다."}],"dr":[{"t":"make","q":"卒業 → ～にあたり","a":"卒業にあたり","hint":"명사 뒤에 그대로 にあたり"},{"t":"make","q":"引っ越す → ～にあたり","a":"引っ越すにあたり","hint":"동사 사전형 + にあたり"},{"t":"fill","q":"会社[かいしゃ]の設立[せつりつ]（　）、多[おお]くの方[かた]にお世話[せわ]になりました。","a":"にあたり","opts":["にあたり","にかかわらず","にしたがって","にかけては"]}],"src":["https://nihongokyoshi-net.com/2019/05/21/jlptn2-grammar-niatari","https://bunpro.jp/grammar_points/522"],"vf":1,"u":10,"g":1,"gp":"gg_N2_03"},{"id":"g2_119","t":"～にわたって","ko":"~에 걸쳐 (기간·범위 전체)","cat":"시간·순서","conn":[{"w":"명사(기간)","f":"三日間 + にわたって"},{"w":"명사(범위·장소)","f":"全国 + にわたって"},{"w":"명사(횟수·분야)","f":"十回 + にわたって"},{"w":"명사 수식","f":"長年 + にわたる + 研究"}],"rule":["1. 기간·범위를 나타내는 명사 뒤에 그대로 にわたって를 붙인다. 三日間 → 三日間にわたって.","2. 문어에서는 にわたり, 명사를 꾸밀 때는 にわたる(長年にわたる研究)를 쓴다."],"why":"わたる(渡る・亘る, 걸치다·미치다)의 て형 わたって에 조사 に가 붙은 것으로, '~ 전체에 걸쳐서'라는 뜻이 된다.","nu":"어떤 일이 짧지 않은 기간이나 넓은 범위 전체에 걸쳐 계속되거나 퍼져 있음을 나타낸다. 그래서 앞에는 三日間・10年・全国・広い範囲처럼 길거나 넓은 말이 오며, 짧은 시점(×3時にわたって)에는 쓰지 않는다. 뉴스·보고서 같은 딱딱한 문장에서 많이 쓴다.","cmp":[{"g":"～を通じて","d":"'~ 내내'라는 뜻으로 一年を通じて처럼 쓰며, '~을 통해서(수단)'의 뜻도 있다."},{"g":"～から～まで","d":"시작과 끝을 그냥 나타낸다. にわたって는 그 전체에 걸쳐 있다는 점을 강조한다."}],"ex":[{"jp":"祭[まつ]りは三日間[みっかかん]にわたって行[おこな]われた。","ko":"축제는 사흘에 걸쳐 열렸다."},{"jp":"台風[たいふう]の影響[えいきょう]は、全国[ぜんこく]にわたって広[ひろ]がった。","ko":"태풍의 영향은 전국에 걸쳐 퍼졌다."},{"jp":"彼[かれ]は長年[ながねん]にわたる研究[けんきゅう]の結果[けっか]を発表[はっぴょう]した。","ko":"그는 오랜 세월에 걸친 연구 결과를 발표했다."}],"dr":[{"t":"make","q":"一週間 → ～にわたって","a":"一週間にわたって","hint":"기간 명사 뒤에 그대로 にわたって"},{"t":"make","q":"十年 + 調査 → ～にわたる","a":"十年にわたる調査","hint":"명사를 꾸밀 때는 にわたる"},{"t":"fill","q":"工事[こうじ]は半年[はんとし]（　）続[つづ]く予定[よてい]だ。","a":"にわたって","opts":["にわたって","に先立ち","にほかならない","にしたら"]}],"src":["https://www.mlcjapanese.co.jp/n2_04_13.html","https://www.bunpro.jp/grammar_points/553"],"vf":1,"u":10,"g":1,"gp":"gg_N2_04"},{"id":"g2_120","t":"～に先立ち","ko":"~에 앞서","cat":"시간·순서","conn":[{"w":"명사","f":"試合 + に先立ち"},{"w":"동사 사전형","f":"出発する + に先立ち"},{"w":"명사 수식","f":"開会 + に先立つ + 式"}],"rule":["1. 명사 뒤에 그대로 に先立ち를 붙인다. 試合 → 試合に先立ち.","2. 동사는 사전형 뒤에 붙인다. 出発する → 出発するに先立ち.","3. て형 に先立って도 같은 뜻이며, 명사를 꾸밀 때는 に先立つ를 쓴다."],"why":"先立つ(さきだつ, 앞서다)의 연용형 先立ち에 조사 に가 붙은 것이다. て형으로 하면 に先立って가 된다.","nu":"중요한 행사나 일을 하기 전에, 그 준비나 앞선 절차로 무엇을 한다는 뜻이다. 행사·공식 일정·사업 같은 격식 있는 내용에 쓰며, 일상의 사소한 일(×寝るに先立ち歯を磨く)에는 어울리지 않는다. 그럴 때는 ～前に를 쓴다. 뉴스·공지·연설에서 자주 쓴다.","cmp":[{"g":"～前に","d":"일반적인 '~하기 전에'로 장면 제한이 없다. に先立ち는 격식 있는 행사·절차에 쓴다."},{"g":"～にあたり","d":"'~에 즈음하여'로 그 시기·기회에 맞춰 하는 일을 말한다. に先立ち는 '그보다 먼저'라는 순서를 강조한다."}],"ex":[{"jp":"試合[しあい]に先立[さきだ]ち、国旗[こっき]が掲揚[けいよう]された。","ko":"경기에 앞서 국기가 게양되었다."},{"jp":"工事[こうじ]を始[はじ]めるに先立[さきだ]ち、住民[じゅうみん]への説明会[せつめいかい]が開[ひら]かれた。","ko":"공사를 시작하기에 앞서 주민 설명회가 열렸다."},{"jp":"新商品[しんしょうひん]の発売[はつばい]に先立[さきだ]って、試食会[ししょくかい]を行[おこな]います。","ko":"신상품 발매에 앞서 시식회를 합니다."}],"dr":[{"t":"make","q":"開会 → ～に先立ち","a":"開会に先立ち","hint":"명사 뒤에 그대로 に先立ち"},{"t":"make","q":"出発する → ～に先立ち","a":"出発するに先立ち","hint":"동사 사전형 + に先立ち"},{"t":"fill","q":"会議[かいぎ]の開始[かいし]（　）、社長[しゃちょう]から挨拶[あいさつ]があった。","a":"に先立ち","opts":["に先立ち","にわたって","にもかかわらず","にほかならない"]}],"src":["https://bunpro.jp/grammar_points/605"],"vf":1,"u":10,"g":1,"gp":"gg_N2_04"},{"id":"g2_131","t":"～に際して","ko":"~에 즈음하여, ~할 때","cat":"시간·순서","conn":[{"w":"명사","f":"出発 + に際して"},{"w":"동사 사전형","f":"入学する + に際して"},{"w":"명사 수식","f":"開会 + に際しての + あいさつ"}],"rule":["1. 동사 際する의 어미 する를 し로 바꾼다.","2. し 뒤에 て를 붙여 際して를 만든다(する → して).","3. 명사 또는 동사 사전형 뒤에 に際して를 붙인다. 명사를 꾸밀 때는 に際しての + 명사."],"why":"","nu":"입학・졸업・출발・계약처럼 특별한 일을 시작하거나 맞이하는 때를 나타내는 딱딱한 격식 표현이다. 인사말・공지・안내문에 많이 쓴다. 일상적인 일(食事に際して처럼 매일 하는 일)에는 잘 쓰지 않고 とき를 쓴다. 딱딱한 문장에서는 に際し도 쓴다.","cmp":[{"g":"～にあたって","d":"にあたって도 거의 같은 뜻의 격식 표현이지만 '그 일을 앞두고 준비・각오한다'는 느낌이 더 강하다."}],"ex":[{"jp":"出発[しゅっぱつ]に際[さい]して、パスポートをもう一度[いちど]確認[かくにん]してください。","ko":"출발할 때 여권을 한 번 더 확인해 주세요."},{"jp":"卒業[そつぎょう]に際[さい]して、校長先生[こうちょうせんせい]がお話[はなし]をされた。","ko":"졸업에 즈음하여 교장 선생님이 말씀을 하셨다."},{"jp":"契約[けいやく]するに際[さい]して、注意[ちゅうい]すべき点[てん]を説明[せつめい]します。","ko":"계약할 때 주의해야 할 점을 설명하겠습니다."}],"dr":[{"t":"make","q":"入学 → ～に際して","a":"入学に際して","hint":"명사 + に + 際して(する → して)"},{"t":"make","q":"留学する → ～に際して","a":"留学するに際して","hint":"동사 사전형 그대로 + に際して"},{"t":"fill","q":"工事[こうじ]の開始[かいし]に（　）、近所[きんじょ]にあいさつをした。","a":"際して","opts":["際して","過ぎず","沿って","反して"]}],"src":["https://bunpro.jp/grammar_points/683"],"vf":1,"u":10,"g":1,"gp":"gg_N2_04"},{"id":"g2_175","t":"～上で","ko":"~한 후에, ~한 다음 (그것을 바탕으로)","cat":"시간·순서","conn":[{"w":"동사 た형","f":"確認した + 上で"},{"w":"명사 + の","f":"相談の + 上で"}],"rule":["1. 동사를 た형으로 바꾼다. する동사는 する를 した로 바꾼다(確認する → 確認した).","2. 그 뒤에 上で를 붙인다(確認した上で).","3. 명사는 の를 넣어 上で를 붙인다(相談の上で)."],"why":"","nu":"앞의 행동을 먼저 확실히 끝내고, 그 결과를 근거로 뒤의 행동(결정·판단·계약 등)을 한다는 뜻이다. 단순한 시간 순서(～てから)보다 '확인·검토를 거친 다음'이라는 의미가 강하며 격식 있는 말투에 많이 쓴다. 동사 ます형에 붙이지 않는다는 점에 주의(×確認し上で). 동사 사전형 + 上で는 '~하는 데 있어서'라는 다른 뜻이 된다(日本で生活する上で、日本語は大切だ).","cmp":[{"g":"～てから","d":"단순히 앞 일이 끝난 뒤 다음 일을 한다는 순서만 나타낸다. ～上で는 앞 일의 결과를 바탕으로 판단·결정한다는 뉘앙스가 있다."},{"g":"동사 사전형 + 上で","d":"'~하는 과정에서, ~하는 데 있어서'라는 뜻으로 시간 순서가 아니다."}],"ex":[{"jp":"内容[ないよう]をよく確認[かくにん]した上[うえ]で、サインしてください。","ko":"내용을 잘 확인한 후에 서명해 주세요."},{"jp":"家族[かぞく]と相談[そうだん]の上[うえ]、返事[へんじ]をします。","ko":"가족과 상의한 후에 답을 드리겠습니다."},{"jp":"実際[じっさい]に見[み]た上[うえ]で、買[か]うかどうか決[き]めます。","ko":"실제로 본 다음에 살지 말지 정하겠습니다."}],"dr":[{"t":"make","q":"話し合う → ～上で","a":"話し合った上で","hint":"う를 った로 바꾼 た형 + 上で"},{"t":"make","q":"検討 → ～上で","a":"検討の上で","hint":"명사는 の + 上で"},{"t":"fill","q":"よく考[かんが]えた（　）、決[き]めてください。","a":"上で","opts":["上で","うちに","最中に","とたんに"]}],"src":["https://nihongokyoshi-net.com/2019/05/26/jlptn2-grammar-uede-3/"],"vf":1,"u":10,"g":1,"gp":"gg_N2_04"},{"id":"g2_179","t":"～以来","ko":"~한 이래, ~한 뒤로 (줄곧)","cat":"시간·순서","conn":[{"w":"동사 て형","f":"来て + 以来"},{"w":"명사","f":"卒業 + 以来"}],"rule":["1. 동사를 て형으로 바꾼다. 来る(くる)는 来て(きて)가 된다.","2. て형 뒤에 以来를 붙인다(来て以来).","3. 명사는 바로 以来를 붙인다(卒業以来)."],"why":"","nu":"과거의 어느 시점부터 지금까지 같은 상태가 계속되고 있음을 나타낸다. 뒤에는 계속되는 상태(～ている, ～ない 등)가 오며, 한 번으로 끝난 일은 오지 않는다. 동사는 た형이 아니라 て형에 붙인다(×来た以来). 아주 가까운 과거(어제 이래)에는 잘 쓰지 않는다. 약간 딱딱한 표현이다.","cmp":[{"g":"～てから","d":"단순히 '~하고 나서'로 그 뒤의 한 번의 일도 말할 수 있다. ～以来는 그때부터 지금까지 계속되는 상태를 말한다."}],"ex":[{"jp":"日本[にほん]に来[き]て以来[いらい]、毎日[まいにち]日本語[にほんご]を勉強[べんきょう]している。","ko":"일본에 온 뒤로 매일 일본어를 공부하고 있다."},{"jp":"卒業[そつぎょう]以来[いらい]、彼[かれ]とは一度[いちど]も会[あ]っていない。","ko":"졸업 이래 그와는 한 번도 만나지 않았다."},{"jp":"この町[まち]に引[ひ]っ越[こ]して以来[いらい]、体[からだ]の調子[ちょうし]がいい。","ko":"이 동네로 이사 온 뒤로 몸 상태가 좋다."}],"dr":[{"t":"make","q":"入学する → ～以来","a":"入学して以来","hint":"する를 して로 바꾼 て형 + 以来"},{"t":"make","q":"会う → ～以来","a":"会って以来","hint":"う를 って로 바꾼 て형 + 以来"},{"t":"fill","q":"大学[だいがく]を卒業[そつぎょう]して（　）、ずっとこの会社[かいしゃ]で働[はたら]いている。","a":"以来","opts":["以来","以上","上に","末に"]}],"src":["https://nihongokyoshi-net.com/2018/03/27/jlptn2-grammar-irai/"],"vf":1,"u":11,"g":1,"gp":"gg_N2_04"},{"id":"g2_184","t":"～折には","ko":"~할 때에는, ~하는 기회에는 (격식)","cat":"시간·순서","conn":[{"w":"동사 사전형","f":"東京に来る + 折には"},{"w":"동사 た형","f":"お会いした + 折には"},{"w":"명사 + の","f":"お越しの + 折には"}],"rule":["1. 동사 사전형을 놓는다(東京に来る).","2. 그 뒤에 折には를 붙인다(東京に来る折には).","3. 명사는 の를 넣어 붙인다(お越しの折には)."],"why":"","nu":"'~할 기회가 있을 때에는'이라는 뜻의 격식 있는 표현으로, 편지·인사·비즈니스에서 쓴다. 자주 있는 일상적인 때나 좋지 않은 상황(병이 났을 때 등)에는 잘 쓰지 않는다. 뒤에는 ぜひ～てください, お～ください 같은 권유·부탁이 자주 온다. 일상 회화라면 ～時には가 자연스럽다.","cmp":[{"g":"～時には","d":"모든 상황에 쓰는 일반적인 '~할 때는'. ～折には는 좋은 기회를 가리키는 정중한 표현."},{"g":"～際に","d":"격식 있는 '~할 때'로 안내·주의사항에 많다. ～折には는 인사·초대처럼 상대에 대한 배려가 담긴다."}],"ex":[{"jp":"東京[とうきょう]に来[く]る折[おり]には、ぜひ連絡[れんらく]してください。","ko":"도쿄에 오실 때에는 꼭 연락해 주세요."},{"jp":"近[ちか]くにお越[こ]しの折[おり]には、お立[た]ち寄[よ]りください。","ko":"근처에 오시는 길에는 들러 주세요."},{"jp":"今度[こんど]お会[あ]いした折[おり]には、ゆっくりお話[はなし]を聞[き]かせてください。","ko":"다음에 뵐 때에는 천천히 이야기를 들려주세요."}],"dr":[{"t":"make","q":"京都に行く → ～折には","a":"京都に行く折には","hint":"동사 사전형 + 折には"},{"t":"make","q":"ご来店 → ～折には","a":"ご来店の折には","hint":"명사는 の + 折には"},{"t":"fill","q":"日本[にほん]へいらっしゃる（　）、ぜひ私[わたし]の家[いえ]に泊[と]まってください。","a":"折には","opts":["折には","末に","反面","上は"]}],"src":["https://bunpro.jp/grammar_points/849"],"vf":1,"u":11,"g":1,"gp":"gg_N2_04"},{"id":"g2_185","t":"～末(に)","ko":"~한 끝에","cat":"시간·순서","conn":[{"w":"동사 た형","f":"考えた + 末に"},{"w":"명사 + の","f":"話し合いの + 末に"}],"rule":["1. 동사를 た형으로 바꾼다. 考える는 る를 た로 바꾼다(考える → 考えた).","2. 그 뒤에 末(に)를 붙인다(考えた末に).","3. 명사는 の를 넣어 붙인다(議論の末に)."],"why":"末(すえ)는 '끝'이라는 뜻의 명사로, '~한 끝에'라는 의미가 된다.","nu":"오랜 시간 고민·노력·어려움을 거친 뒤 마지막에 어떤 결과에 이르렀음을 나타낸다. 뒤에는 결과(결정했다, 성공했다 등)가 과거형으로 오는 경우가 많다. に는 생략할 수 있고(考えた末、), 명사를 꾸밀 때는 末の를 쓴다(苦労した末の成功). 짧고 간단한 행동에는 쓰지 않는다. 다소 문어적이다.","cmp":[{"g":"～あげく","d":"오래 ~한 끝에 결국 나쁜 결과가 되었다는 뜻이 많다. ～末に는 좋은 결과·중립적인 결과에도 쓴다."}],"ex":[{"jp":"いろいろ考[かんが]えた末[すえ]に、会社[かいしゃ]を辞[や]めることにした。","ko":"여러모로 생각한 끝에 회사를 그만두기로 했다."},{"jp":"長[なが]い話[はな]し合[あ]いの末[すえ]、やっと結論[けつろん]が出[で]た。","ko":"긴 논의 끝에 겨우 결론이 났다."},{"jp":"何度[なんど]も失敗[しっぱい]した末[すえ]に、ついに成功[せいこう]した。","ko":"몇 번이나 실패한 끝에 마침내 성공했다."}],"dr":[{"t":"make","q":"迷う → ～末に","a":"迷った末に","hint":"う를 った로 바꾼 た형 + 末に"},{"t":"make","q":"努力 → ～末に","a":"努力の末に","hint":"명사는 の + 末に"},{"t":"fill","q":"三時間[さんじかん]悩[なや]んだ（　）、赤[あか]いかばんを買[か]った。","a":"末に","opts":["末に","以来","向けに","際に"]}],"src":["https://mainichi-nonbiri.com/grammar/n3-sue/"],"vf":1,"u":11,"g":1,"gp":"gg_N2_04"},{"id":"g2_186","t":"～次第","ko":"~하는 대로 (곧바로)","cat":"시간·순서","conn":[{"w":"동사 ます형","f":"着き + 次第"},{"w":"する동사 ます형","f":"到着し + 次第"}],"rule":["1. 동사를 ます형으로 만든다. 1그룹 동사 着く는 어미 く를 き로 바꾼다(着く → 着き).","2. ます형 뒤에 次第를 붙인다(着き次第).","3. する동사는 する를 し로 바꾼다(到着する → 到着し次第)."],"why":"","nu":"앞의 일이 실현되면 곧바로 뒤의 행동을 하겠다는 뜻이다. 뒤에는 의지·의뢰·예정(～ます, ～てください)이 오며, 이미 일어난 과거의 일에는 쓰지 않는다(×着き次第、電話した). 비즈니스에서 많이 쓰는 격식 있는 표현이다. 명사 + 次第는 '~에 달려 있다'라는 다른 용법이다(天気次第).","cmp":[{"g":"～たらすぐ","d":"같은 뜻의 일상 표현으로 과거의 일에도 쓸 수 있다. ～次第는 격식 있고 앞으로의 일에만 쓴다."},{"g":"～とたん(に)","d":"'~하자마자 (뜻밖에)'로 이미 일어난 일을 말한다. ～次第는 앞으로 할 의지적 행동."}],"ex":[{"jp":"駅[えき]に着[つ]き次第[しだい]、電話[でんわ]します。","ko":"역에 도착하는 대로 전화하겠습니다."},{"jp":"準備[じゅんび]ができ次第[しだい]、出発[しゅっぱつ]しましょう。","ko":"준비가 되는 대로 출발합시다."},{"jp":"結果[けっか]が分[わ]かり次第[しだい]、お知[し]らせください。","ko":"결과를 아는 대로 알려 주세요."}],"dr":[{"t":"make","q":"終わる → ～次第","a":"終わり次第","hint":"る를 り로 바꾼 ます형 + 次第"},{"t":"make","q":"決まる → ～次第","a":"決まり次第","hint":"る를 り로 바꾼 ます형 + 次第"},{"t":"fill","q":"会議[かいぎ]が終[お]わり（　）、そちらに向[む]かいます。","a":"次第","opts":["次第","末","反面","以上"]}],"src":["https://bunpro.jp/ja/grammar_points/%E6%AC%A1%E7%AC%AC"],"vf":1,"u":11,"g":1,"gp":"gg_N2_04"},{"id":"g2_191","t":"～際に","ko":"~할 때에, ~하는 경우에 (격식)","cat":"시간·순서","conn":[{"w":"동사 사전형","f":"出かける + 際に"},{"w":"동사 た형","f":"使った + 際に"},{"w":"명사 + の","f":"出発の + 際に"}],"rule":["1. 명사를 놓는다(出発).","2. 조사 の를 넣는다(出発の).","3. 그 뒤에 際に를 붙인다(出発の際に). 동사는 사전형이나 た형에 바로 붙인다(出かける際に)."],"why":"際(さい)는 '때, 경우'라는 뜻의 명사다.","nu":"～時に의 격식 있는 표현으로 안내문·공지·비즈니스 문장에 많이 쓴다. に는 생략할 수 있고(出発の際、), 際は(~할 때는)로도 쓴다. 일상 회화에서 쓰면 딱딱하게 들린다. 뒤에는 주의사항·부탁이 자주 온다.","cmp":[{"g":"～時に","d":"같은 뜻의 일반적인 표현. ～際に는 공식적인 장면에서 쓴다."},{"g":"～折には","d":"인사·초대 등에서 좋은 기회를 가리키는 정중한 표현. ～際に는 절차·주의사항에 많다."}],"ex":[{"jp":"出発[しゅっぱつ]の際[さい]に、パスポートを確認[かくにん]してください。","ko":"출발할 때 여권을 확인해 주세요."},{"jp":"お出[で]かけになる際[さい]には、鍵[かぎ]をフロントに預[あず]けてください。","ko":"외출하실 때에는 열쇠를 프런트에 맡겨 주세요."},{"jp":"この機械[きかい]を使[つか]った際[さい]は、必[かなら]ず電源[でんげん]を切[き]ってください。","ko":"이 기계를 사용했을 때는 반드시 전원을 꺼 주세요."}],"dr":[{"t":"make","q":"入場 → ～際に","a":"入場の際に","hint":"명사는 の + 際に"},{"t":"make","q":"帰国する → ～際に","a":"帰国する際に","hint":"동사 사전형 + 際に"},{"t":"fill","q":"ご利用[りよう]の（　）、こちらの書類[しょるい]にお名前[なまえ]をお書[か]きください。","a":"際に","opts":["際に","末に","反面","限り"]}],"src":["https://bunpro.jp/grammar_points/際に"],"vf":1,"u":11,"g":1,"gp":"gg_N2_04"},{"id":"g2_005","t":"A。したがって B。","ko":"따라서, 그러므로","cat":"원인·이유","conn":[{"w":"문장 + 문장","f":"本日は祝日です。 + したがって + 窓口は休みです。"},{"w":"문장 + 문장","f":"雨が少ない。 + したがって + 水が不足しやすい。"}],"rule":["1. 근거나 원인이 되는 사실 A를 말한다(本日は祝日です。).","2. 다음 문장 맨 앞에 したがって를 놓는다.","3. 그 뒤에 A에서 논리적으로 이끌어지는 결과·결론 B를 말한다(窓口は休みです)."],"why":"따르다는 뜻의 동사 従う의 て형 従って에서 온 접속사로, 한자로 従って라고도 쓴다.","nu":"논문·공문·뉴스 등 딱딱한 문어체에서 주로 쓰며 일상 회화에는 だから가 자연스럽다. B에는 객관적인 결과·결론이 오며, 권유·명령·부탁 같은 말하는 이의 의지 표현은 잘 오지 않는다(したがって、行きましょう는 부자연스럽다).","cmp":[{"g":"だから","d":"だから는 회화에서 쓰며 B에 의지·권유·명령도 올 수 있다. したがって는 문어적이고 논리적인 결론에 쓴다."}],"ex":[{"jp":"本日[ほんじつ]は祝日[しゅくじつ]です。したがって、窓口[まどぐち]は休[やす]みです。","ko":"오늘은 공휴일입니다. 따라서 창구는 쉽니다."},{"jp":"この地域[ちいき]は雨[あめ]が少[すく]ない。したがって、水[みず]が不足[ふそく]しやすい。","ko":"이 지역은 비가 적다. 그러므로 물이 부족해지기 쉽다."},{"jp":"この製品[せいひん]は他社[たしゃ]より安[やす]い。したがって、よく売[う]れている。","ko":"이 제품은 타사보다 싸다. 따라서 잘 팔리고 있다."}],"dr":[{"t":"make","q":"本日は祝日です。/ 休みです。→ したがって로 연결","a":"本日は祝日です。したがって、休みです。","hint":"결론 문장 앞에 したがって"},{"t":"make","q":"雨が少ない。/ 水が不足しやすい。→ したがって로 연결","a":"雨が少ない。したがって、水が不足しやすい。","hint":"결과 문장 앞에 したがって"},{"t":"fill","q":"応募者[おうぼしゃ]が少[すく]なかった。（　）、締[し]め切[き]りが延長[えんちょう]された。","a":"したがって","opts":["したがって","ところが","さて","あるいは"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%97%E3%81%9F%E3%81%8C%E3%81%A3%E3%81%A6"],"vf":1,"u":12,"g":1,"gp":"gg_N2_04"},{"id":"g2_009","t":"A。そこで B。","ko":"그래서(대책으로)","cat":"원인·이유","conn":[{"w":"문장 + 문장","f":"道がわからなかった。 + そこで + 近くの人に聞いた。"},{"w":"문장 + 문장","f":"太ってきた。 + そこで + 毎朝走ることにした。"}],"rule":["1. 해결해야 할 상황이나 문제 A를 말한다(道がわからなかった。).","2. 다음 문장 맨 앞에 そこで를 놓는다.","3. 그 뒤에 A에 대처하려고 일부러 한 행동 B를 말한다(近くの人に聞いた)."],"why":"","nu":"B에는 A라는 상황을 해결하기 위해 의도적으로 취한 행동·조치가 온다. 자연히 생긴 결과(雨が降った。そこで試合が中止になった)에는 어울리지 않고 それで를 쓴다. 회화와 글 모두에서 쓴다. '그 자리에서·그때'라는 장소·시점의 뜻으로도 쓰니 문맥으로 구별한다.","cmp":[{"g":"それで","d":"それで는 원인에 따른 자연스러운 결과에도 쓴다. そこで는 문제에 대처하기 위한 의도적인 행동에 쓴다."}],"ex":[{"jp":"道[みち]がわからなかった。そこで、近[ちか]くの人[ひと]に聞[き]いた。","ko":"길을 몰랐다. 그래서 근처 사람에게 물었다."},{"jp":"最近[さいきん]太[ふと]ってきた。そこで、毎朝[まいあさ]走[はし]ることにした。","ko":"요즘 살이 쪘다. 그래서 매일 아침 달리기로 했다."},{"jp":"駅前[えきまえ]に駐車場[ちゅうしゃじょう]がなかった。そこで、電車[でんしゃ]で行[い]くことにした。","ko":"역 앞에 주차장이 없었다. 그래서 전철로 가기로 했다."}],"dr":[{"t":"make","q":"道がわからなかった。/ 人に聞いた。→ そこで로 연결","a":"道がわからなかった。そこで、人に聞いた。","hint":"대처 행동 앞에 そこで"},{"t":"make","q":"太ってきた。/ 毎朝走ることにした。→ そこで로 연결","a":"太ってきた。そこで、毎朝走ることにした。","hint":"해결책 문장 앞에 そこで"},{"t":"fill","q":"英語[えいご]が全然[ぜんぜん]話[はな]せない。（　）、英会話[えいかいわ]教室[きょうしつ]に通[かよ]うことにした。","a":"そこで","opts":["そこで","それでも","すなわち","あるいは"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9D%E3%81%93%E3%81%A7"],"vf":1,"u":12,"g":1,"gp":"gg_N2_04"},{"id":"g2_011","t":"A。それで B。","ko":"그래서, 그 때문에","cat":"원인·이유","conn":[{"w":"문장 + 문장","f":"熱があった。 + それで + 学校を休んだ。"},{"w":"상대의 말 + 재촉","f":"(相手の話) + それで + どうしたの？"}],"rule":["1. 원인이나 이유가 되는 일 A를 말한다(熱があった。).","2. 다음 문장 맨 앞에 それで를 놓는다.","3. 그 뒤에 A 때문에 생긴 결과 B를 말한다(学校を休んだ)."],"why":"","nu":"회화에서 많이 쓴다. B에는 이미 일어난 결과나 사실이 오며, 명령·부탁·권유(それで、行きなさい 등)는 보통 오지 않는다. 상대의 이야기를 들으며 '그래서?'라고 다음을 재촉할 때도 쓴다(それで、どうなったの？).","cmp":[{"g":"だから","d":"だから는 B에 명령·권유·의지 표현도 올 수 있고 말하는 이의 주장이 강하다. それで는 사실로서 원인과 결과를 이어 말한다."}],"ex":[{"jp":"昨日[きのう]は熱[ねつ]があった。それで、学校[がっこう]を休[やす]んだ。","ko":"어제는 열이 있었다. 그래서 학교를 쉬었다."},{"jp":"電車[でんしゃ]が遅[おく]れた。それで、会議[かいぎ]に間[ま]に合[あ]わなかった。","ko":"전철이 늦었다. 그 때문에 회의에 늦었다."},{"jp":"「昨日[きのう]、駅[えき]で先生[せんせい]に会[あ]ったんだ。」「それで、どうしたの？」","ko":"\"어제 역에서 선생님을 만났어.\" \"그래서 어떻게 했어?\""}],"dr":[{"t":"make","q":"熱があった。/ 学校を休んだ。→ それで로 연결","a":"熱があった。それで、学校を休んだ。","hint":"결과 문장 앞에 それで"},{"t":"make","q":"電車が遅れた。/ 遅刻した。→ それで로 연결","a":"電車が遅れた。それで、遅刻した。","hint":"결과 문장 앞에 それで"},{"t":"fill","q":"部屋[へや]が寒[さむ]かった。（　）、暖房[だんぼう]をつけた。","a":"それで","opts":["それで","それでも","ところで","あるいは"]}],"src":["https://bunpro.jp/grammar_points/それで"],"vf":1,"u":12,"g":1,"gp":"gg_N2_04"},{"id":"g2_019","t":"だって","ko":"그치만, 왜냐면","cat":"원인·이유","conn":[{"w":"문장 A 다음 (문장 첫머리)","f":"なんで食べないの？ + だって + 辛いもん。"}],"rule":["1. 상대의 질문·비난·권유 A를 받는다.","2. 대답하는 문장 맨 앞에 だって를 놓는다.","3. B에는 자기 쪽의 이유·변명이 오고, 끝은 ～から / ～んだ / ～もん으로 맺는 경우가 많다(辛いもん)."],"why":"","nu":"친한 사이의 회화체로, 상대 말에 반발하거나 자기를 정당화하는 느낌이 강하다. 아이 같거나 응석 부리는 말투로 들릴 수 있어 윗사람·격식 있는 자리에서는 쓰지 않는다(그때는 というのは, 実は 등). 문장 첫머리의 だって는 '~도', '~래' 뜻의 だって(子どもだって分かる / 来ないんだって)와는 다른 말이다.","cmp":[{"g":"なぜなら","d":"なぜなら는 글이나 격식 있는 말에서 이유를 논리적으로 밝힌다. だって는 회화에서 변명·반론으로 쓴다."},{"g":"というのは","d":"というのは는 앞 말의 이유를 차분히 설명한다. 감정적인 반발의 느낌은 없다."}],"ex":[{"jp":"「どうして食[た]べないの？」「だって、辛[から]いんだもん。」","ko":"\"왜 안 먹어?\" \"그치만 맵단 말이야.\""},{"jp":"「また遅刻[ちこく]？」「だって、電車[でんしゃ]が止[と]まってたんだよ。」","ko":"\"또 지각이야?\" \"그치만 전철이 멈춰 있었단 말이야.\""},{"jp":"「宿題[しゅくだい]、まだやってないの？」「だって、時間[じかん]がなかったから。」","ko":"\"숙제 아직 안 했어?\" \"그치만 시간이 없었으니까.\""}],"dr":[{"t":"make","q":"「なんで行かないの？」→ だって + 雨が降っている + から","a":"だって、雨が降っているから。","hint":"문장 맨 앞에 だって, 끝은 から"},{"t":"make","q":"「どうして寝ないの？」→ だって + 眠くない + もん","a":"だって、眠くないもん。","hint":"보통형 + もん으로 맺는다"},{"t":"fill","q":"「どうしてそのケーキ、食[た]べないの？」「（　）、甘[あま]すぎるんだもん。」","a":"だって","opts":["だって","ただし","なお","ということは"]}],"src":["https://bunpro.jp/grammar_points/だって"],"vf":1,"u":12,"g":1,"gp":"gg_N2_05"},{"id":"g2_022","t":"というのは","ko":"왜냐하면, 그 이유는","cat":"원인·이유","conn":[{"w":"문장 A 다음 (문장 첫머리)","f":"今日は休む。+ というのは + 熱があるからだ。"}],"rule":["1. 앞 문장 A에서 결과·결정을 먼저 말한다.","2. 다음 문장 맨 앞에 というのは를 놓는다.","3. B에는 A의 이유를 쓰고, 끝을 ～からだ / ～のだ(～んです)로 맺는다(熱がある → 熱があるからだ)."],"why":"と(인용) + いう(말하다) + の(것) + は(주제). '(앞에서) 말한 것은'이라는 뜻에서 앞 말을 설명하는 접속사가 되었다.","nu":"앞에서 말한 일의 이유·사정을 덧붙여 설명할 때 쓴다. 회화·글 모두 쓰고 감정적인 반발의 느낌은 없다. B 끝을 からだ·のだ로 맺는 것이 자연스러우며, 빠뜨리면 어색해지기 쉽다. 'X라는 것은 ~이다'처럼 명사 뒤에서 뜻을 정의하는 ～というのは와는 쓰임이 다르다.","cmp":[{"g":"なぜなら","d":"なぜなら는 더 딱딱하고 논리적인 문어체 표현이다. というのは는 회화에서도 자연스럽다."},{"g":"だって","d":"だって는 친한 사이에서 쓰는 변명·반론이다."}],"ex":[{"jp":"今日[きょう]は会社[かいしゃ]を休[やす]みます。というのは、熱[ねつ]があるからです。","ko":"오늘은 회사를 쉽니다. 왜냐하면 열이 있기 때문입니다."},{"jp":"この店[みせ]はいつも混[こ]んでいる。というのは、安[やす]くておいしいからだ。","ko":"이 가게는 늘 붐빈다. 그 이유는 싸고 맛있기 때문이다."},{"jp":"旅行[りょこう]は来月[らいげつ]に延[の]ばしました。というのは、急[きゅう]に仕事[しごと]が入[はい]ったんです。","ko":"여행은 다음 달로 미뤘습니다. 왜냐하면 갑자기 일이 생겼거든요."}],"dr":[{"t":"make","q":"今日は早く帰ります。/ 子どもが病気だ → というのは","a":"今日は早く帰ります。というのは、子どもが病気だからです。","hint":"というのは + 이유 + からです"},{"t":"make","q":"彼は遅れた。/ 道が混んでいた → というのは","a":"彼は遅れた。というのは、道が混んでいたからだ。","hint":"이유 문장 끝을 からだ로"},{"t":"fill","q":"パーティーには行[い]けません。（　）、その日[ひ]は出張[しゅっちょう]があるんです。","a":"というのは","opts":["というのは","ということは","それなら","ちなみに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%84%E3%81%86%E3%81%AE%E3%81%AF"],"vf":1,"u":12,"g":1,"gp":"gg_N2_05"},{"id":"g2_026","t":"～につき","ko":"~이므로, ~때문에 (안내문)","cat":"원인·이유","conn":[{"w":"명사","f":"工事中 + につき"},{"w":"명사 (～中)","f":"準備中 + につき"}],"rule":["1. 명사 뒤에 につき를 바로 붙인다(の나 だ를 넣지 않는다: 工事中につき).","2. 뒤에는 그 이유로 생기는 결과·조치가 온다(通行止め, 休業します 등).","3. 활용하는 부분은 없고, 앞말은 명사 그대로 쓴다."],"why":"","nu":"게시물·안내문·공지 같은 딱딱한 글에서 쓰며, 일상 회화에는 거의 쓰지 않는다(회화에서는 ～なので). 工事中·改装中·準備中처럼 ～中이 붙은 명사와 자주 쓴다. 一人につき三枚(한 사람당 세 장)처럼 수량 뒤에서 '~당'의 뜻으로 쓰는 につき도 있으니 문맥으로 구별한다.","cmp":[{"g":"～のため","d":"のため도 이유를 나타내지만 회화·글에 두루 쓰고 명사 뒤에 の가 필요하다(工事のため). につき는 안내문용으로 더 딱딱하다."}],"ex":[{"jp":"この先[さき]、工事中[こうじちゅう]につき通行止[つうこうど]め。","ko":"이 앞은 공사 중이므로 통행금지."},{"jp":"本日[ほんじつ]は定休日[ていきゅうび]につき、お休[やす]みさせていただきます。","ko":"오늘은 정기 휴일이므로 쉽니다."},{"jp":"店内[てんない]改装中[かいそうちゅう]につき、しばらく休業[きゅうぎょう]いたします。","ko":"가게 안 개장 공사 중이므로 당분간 휴업합니다."}],"dr":[{"t":"make","q":"準備中 + 입장할 수 없습니다 → ～につき","a":"準備中につき、入れません。","hint":"명사 뒤에 바로 につき"},{"t":"make","q":"工事のため → ～につき","a":"工事中につき","hint":"の를 빼고 명사(～中)에 につき를 붙인다"},{"t":"fill","q":"清掃中[せいそうちゅう]（　）、このトイレはご使用[しよう]になれません。","a":"につき","opts":["につき","にとって","によって","に対して"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AB%E3%81%A4%E3%81%8D","https://jlptsensei.com/learn-japanese-grammar/につき-ni-tsuki-meaning"],"vf":1,"u":13,"g":1,"gp":"gg_N2_05"},{"id":"g2_028","t":"～のことだから","ko":"~이니까 (그 사람을 잘 알기에)","cat":"원인·이유","conn":[{"w":"명사 (주로 사람)","f":"田中さん + の + ことだから"},{"w":"수식어 + 명사","f":"いつも遅れる彼 + の + ことだから"}],"rule":["1. 명사(주로 사람) 뒤에 の를 붙이고 ことだから를 이어 붙인다(田中さん → 田中さんのことだから).","2. 뒤에는 그 사람의 성격·습관으로 미루어 한 말하는 사람의 판단·추측이 온다.","3. 문장 끝은 きっと～だろう / ～に違いない / ～はずだ처럼 추측으로 맺는 경우가 많다."],"why":"","nu":"말하는 사람과 듣는 사람이 모두 아는 인물·조직의 성격을 근거로 한다. 좋은 평가(まじめな彼のことだから)와 나쁜 평가(のんびり屋の彼女のことだから) 모두 쓸 수 있다. 처음 보는 사람이나 성격을 모르는 대상에는 쓰지 않는다. 회화·글 모두 쓴다.","cmp":[{"g":"～だから","d":"だから는 일반적인 이유다. のことだから는 그 대상의 평소 성질을 아는 것이 판단 근거라는 점을 드러낸다."}],"ex":[{"jp":"田中[たなか]さんのことだから、今日[きょう]もきっと遅[おく]れて来[く]るよ。","ko":"다나카 씨니까 오늘도 분명 늦게 올 거야."},{"jp":"まじめな彼[かれ]のことだから、約束[やくそく]は必[かなら]ず守[まも]るだろう。","ko":"성실한 그니까 약속은 반드시 지킬 것이다."},{"jp":"料理[りょうり]が好[す]きな母[はは]のことだから、たくさん作[つく]って待[ま]っているはずだ。","ko":"요리를 좋아하는 어머니니까 잔뜩 만들어서 기다리고 계실 것이다."}],"dr":[{"t":"make","q":"彼女 → ～のことだから","a":"彼女のことだから","hint":"명사 + の + ことだから"},{"t":"make","q":"頭のいい山田さん → ～のことだから + きっと合格する","a":"頭のいい山田さんのことだから、きっと合格する。","hint":"수식어가 붙은 명사에도 の + ことだから"},{"t":"fill","q":"心配性[しんぱいしょう]の母[はは]（　）、何度[なんど]も電話[でんわ]してくるだろう。","a":"のことだから","opts":["のことだから","にて","につき","をはじめ"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%93%E3%81%A8%E3%81%A0%E3%81%8B%E3%82%89"],"vf":1,"u":13,"g":1,"gp":"gg_N2_05"},{"id":"g2_039","t":"～あまり","ko":"너무 ~한 나머지","cat":"원인·이유","conn":[{"w":"명사","f":"緊張の + あまり"},{"w":"동사 사전형","f":"考える + あまり"},{"w":"동사 た형","f":"急いだ + あまり"},{"w":"な형용사","f":"慎重な + あまり"}],"rule":["1. 명사는 그대로 두고 뒤에 の를 붙인다(緊張の).","2. 그 뒤에 あまり를 붙인다(緊張のあまり).","3. 동사는 사전형이나 た형에 바로, な형용사는 な를 붙여 연결한다(考えるあまり, 慎重なあまり).","4. 뒤에는 정도가 지나쳐서 생긴 뜻밖의 결과를 쓴다(緊張のあまり、声が出なかった)."],"why":"","nu":"감정이나 상태가 지나치게 강해서 평소와 다른, 대개 좋지 않은 결과가 생겼을 때 쓴다. 心配・緊張・喜び・悲しみ・驚き 같은 감정 명사와 자주 쓴다. い형용사는 명사형 ～さ로 바꿔 うれしさのあまり처럼 쓰는 일이 많다. 뒤에는 말하는 사람의 의지·명령·권유가 오지 않는다. 부사 あまり(그다지)와 혼동하지 않는다.","cmp":[{"g":"～すぎて","d":"'너무 ~해서'라는 일상 표현. あまり는 문어적이고 감정의 정도가 지나쳐 뜻밖의 결과가 생겼다는 느낌이 강하다."}],"ex":[{"jp":"緊張[きんちょう]のあまり、声[こえ]が出[で]なかった。","ko":"너무 긴장한 나머지 목소리가 나오지 않았다."},{"jp":"母[はは]は心配[しんぱい]するあまり、夜[よる]も眠[ねむ]れなかった。","ko":"어머니는 너무 걱정한 나머지 밤에도 잠을 이루지 못했다."},{"jp":"彼女[かのじょ]はうれしさのあまり、泣[な]き出[だ]した。","ko":"그녀는 너무 기쁜 나머지 울기 시작했다."}],"dr":[{"t":"make","q":"驚き → ～あまり","a":"驚きのあまり","hint":"명사 + の + あまり"},{"t":"make","q":"急ぐ → た형 + あまり","a":"急いだあまり","hint":"1그룹 ぐ → いだ + あまり"},{"t":"fill","q":"悲[かな]しみの（　）、彼[かれ]は何[なに]も食[た]べられなくなった。","a":"あまり","opts":["あまり","うちに","かわりに","とおりに"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%82%E3%81%BE%E3%82%8A"],"vf":1,"u":13,"g":1,"gp":"gg_N2_05"},{"id":"g2_042","t":"～かいがあって","ko":"~한 보람이 있어서","cat":"원인·이유","conn":[{"w":"동사 た형","f":"練習した + かいがあって"},{"w":"명사","f":"努力の + かいがあって"}],"rule":["1. 동사를 た형으로 바꾼다(する동사 練習する: する → した, 練習した).","2. 그 뒤에 かいがあって를 붙인다(練習したかいがあって).","3. 명사는 の를 넣어 연결한다(努力のかいがあって).","4. 뒤에는 노력이 보상받은 좋은 결과를 쓴다."],"why":"かい(甲斐, 보람) + が + ある의 て형 あって로 이루어져 '~한 보람이 있어서'라는 뜻이 된다.","nu":"앞에 쓴 노력·고생이 헛되지 않고 바라던 좋은 결과로 이어졌을 때 쓴다. 뒤에는 이미 이루어진 결과(合格した, 勝てた 등)가 온다. 반대로 노력이 헛되었을 때는 ～かいもなく를 쓴다. 동사는 た형에 붙는다는 점에 주의한다.","cmp":[{"g":"～おかげで","d":"남의 도움이나 외부 원인 덕분일 때도 쓴다. かいがあって는 주로 자신이 들인 노력의 보람을 말한다."},{"g":"～かいもなく","d":"반대 뜻으로, 노력했지만 보람이 없었을 때."}],"ex":[{"jp":"毎日[まいにち]練習[れんしゅう]したかいがあって、試合[しあい]に勝[か]てた。","ko":"매일 연습한 보람이 있어서 시합에 이길 수 있었다."},{"jp":"努力[どりょく]のかいがあって、第一志望[だいいちしぼう]の大学[だいがく]に合格[ごうかく]した。","ko":"노력한 보람이 있어서 1지망 대학에 합격했다."},{"jp":"早[はや]く家[いえ]を出[で]たかいがあって、いい席[せき]に座[すわ]れた。","ko":"일찍 집을 나선 보람이 있어서 좋은 자리에 앉을 수 있었다."}],"dr":[{"t":"make","q":"待つ → ～かいがあって","a":"待ったかいがあって","hint":"1그룹 つ → った + かいがあって"},{"t":"make","q":"応援 → ～かいがあって","a":"応援のかいがあって","hint":"명사 + の + かいがあって"},{"t":"fill","q":"一年間[いちねんかん]がんばった（　）、日本語[にほんご]が話[はな]せるようになった。","a":"かいがあって","opts":["かいがあって","かいもなく","あまり","ことなく"]}],"src":["https://bunpro.jp/grammar_points/540"],"vf":1,"u":13,"g":1,"gp":"gg_N2_05"},{"id":"g2_051","t":"～からこそ","ko":"~이기 때문에야말로, 바로 ~이니까","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"失敗した + からこそ"},{"w":"い형용사","f":"苦しい + からこそ"},{"w":"な형용사","f":"好きだ + からこそ"},{"w":"명사","f":"家族だ + からこそ"}],"rule":["1. 동사·い형용사는 보통형 그대로 쓴다(失敗した, 苦しい).","2. な형용사·명사는 だ를 붙인다(好き → 好きだ).","3. 이유를 나타내는 から를 붙인다(好きだから).","4. 마지막에 강조의 こそ를 붙인다(好きだからこそ)."],"why":"이유의 접속조사 から에 '바로 그것'이라고 강조하는 조사 こそ가 붙은 형태다.","nu":"여러 이유 가운데 바로 그 이유라고 강하게 내세운다. 상대가 의외로 여길 만한 이유(좋아하니까 엄하게 한다 등)를 말할 때 잘 어울린다. 뒤에 のだ·のです가 자주 온다. 단순한 불평이나 핑계에는 잘 쓰지 않는다.","cmp":[{"g":"～から","d":"단순히 이유를 말한다. からこそ는 다른 이유가 아니라 바로 그 이유임을 강조한다."}],"ex":[{"jp":"失敗[しっぱい]したからこそ、成功[せいこう]の意味[いみ]がわかる。","ko":"실패했기 때문에야말로 성공의 의미를 안다."},{"jp":"あなたのことが好[す]きだからこそ、厳[きび]しく言[い]うんです。","ko":"당신을 좋아하니까 더욱 엄하게 말하는 거예요."},{"jp":"家族[かぞく]だからこそ、言[い]えないこともある。","ko":"가족이기 때문에 오히려 말할 수 없는 것도 있다."}],"dr":[{"t":"make","q":"大切だ → ～からこそ","a":"大切だからこそ","hint":"な형용사는 だ + から + こそ"},{"t":"make","q":"練習した → ～からこそ","a":"練習したからこそ","hint":"동사 보통형 + からこそ"},{"t":"fill","q":"毎日[まいにち]努力[どりょく]した（　）、合格[ごうかく]できたのだ。","a":"からこそ","opts":["からこそ","くせに","わりに","からといって"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201612.html"],"vf":1,"u":13,"g":1,"gp":"gg_N2_05"},{"id":"g2_056","t":"～からには","ko":"~한 이상은, ~하는 바에는","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"約束した + からには"},{"w":"동사 사전형","f":"出る + からには"},{"w":"명사","f":"学生である + からには"}],"rule":["1. 동사를 보통형으로 만든다. 約束する → 約束した(する를 した로).","2. 그 뒤에 からには를 붙인다(約束したからには).","3. 명사는 である를 넣고 からには를 붙인다(学生であるからには).","4. 뒤에는 의지·의무·희망·당연(つもりだ, なければならない, たい, べきだ)이 온다."],"why":"","nu":"'어떤 상황이 된 이상 당연히 끝까지 ~해야 한다'는 각오나 책임감을 나타낸다. 뒤에 단순한 사실 서술은 오지 않는다. 以上(は)와 뜻이 거의 같고, からには가 조금 더 회화적이다.","cmp":[{"g":"～以上(は)","d":"뜻은 거의 같으며 조금 더 딱딱하다. 둘 다 뒤에 의지·의무·판단이 온다."}],"ex":[{"jp":"約束[やくそく]したからには、必[かなら]ず守[まも]ります。","ko":"약속한 이상은 반드시 지키겠습니다."},{"jp":"試合[しあい]に出[で]るからには、勝[か]ちたい。","ko":"시합에 나가는 바에는 이기고 싶다."},{"jp":"学生[がくせい]であるからには、勉強[べんきょう]を第一[だいいち]にすべきだ。","ko":"학생인 이상은 공부를 최우선으로 해야 한다."}],"dr":[{"t":"make","q":"引き受ける(과거) → ～からには","a":"引き受けたからには","hint":"る를 빼고 た + からには"},{"t":"make","q":"日本に来る(과거) → ～からには","a":"日本に来たからには","hint":"来る → 来た + からには"},{"t":"fill","q":"やると決[き]めた（　）、最後[さいご]までがんばるつもりだ。","a":"からには","opts":["からには","くせに","わりに","ものの"]}],"src":["https://nihongokyoshi-net.com/2019/05/23/jlptn3-grammar-karaniwa/"],"vf":1,"u":13,"g":1,"gp":"gg_N2_05"},{"id":"g2_060","t":"～ことから","ko":"~라는 점에서, ~해서(근거·유래)","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"見える + ことから"},{"w":"い형용사","f":"多い + ことから"},{"w":"な형용사","f":"得意な + ことから"},{"w":"명사","f":"港町である + ことから"}],"rule":["1. 동사·い형용사는 보통형 그대로 쓴다(見える).","2. 형식명사 こと를 붙여 명사처럼 만든다(見えること).","3. 이유·근거의 から를 붙인다(見えることから).","4. な형용사는 な, 명사는 である를 넣고 ことから를 붙인다(得意なことから)."],"why":"형식명사 こと(~것)에 이유·기점의 から가 붙은 형태다.","nu":"어떤 사실을 근거로 판단하거나, 이름·명칭의 유래를 설명할 때 많이 쓴다(～と呼ばれる, ～と名付けられた). 문어적이며 설명문·뉴스에 어울린다. 명사에는 のことから가 아니라 であることから를 쓴다.","cmp":[{"g":"～から","d":"일반적인 이유를 말한다. ことから는 객관적인 사실을 근거나 유래로 제시하는 문어적 표현이다."}],"ex":[{"jp":"この町[まち]は富士山[ふじさん]がよく見[み]えることから、「富士見町[ふじみちょう]」と呼[よ]ばれている。","ko":"이 마을은 후지산이 잘 보여서 '후지미초'라고 불린다."},{"jp":"道[みち]がぬれていることから、夜中[よなか]に雨[あめ]が降[ふ]ったとわかる。","ko":"길이 젖어 있는 것으로 보아 한밤중에 비가 왔다는 것을 알 수 있다."},{"jp":"彼[かれ]は英語[えいご]が得意[とくい]なことから、通訳[つうやく]を頼[たの]まれた。","ko":"그는 영어를 잘해서 통역을 부탁받았다."}],"dr":[{"t":"make","q":"形が似ている → ～ことから","a":"形が似ていることから","hint":"동사 보통형 + こと + から"},{"t":"make","q":"有名だ → ～ことから","a":"有名なことから","hint":"な형용사는 な + ことから"},{"t":"fill","q":"この花[はな]は形[かたち]が星[ほし]に似[に]ている（　）、「星[ほし]の花[はな]」と呼[よ]ばれる。","a":"ことから","opts":["ことから","ことなく","ことに","ことだし"]}],"src":["https://mainichi-nonbiri.com/grammar/n2-kotokara/"],"vf":1,"u":14,"g":1,"gp":"gg_N2_05"},{"id":"g2_069","t":"～だけあって","ko":"~인 만큼 (역시)","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"練習した + だけあって"},{"w":"い형용사","f":"高い + だけあって"},{"w":"な형용사","f":"有名な + だけあって"},{"w":"명사","f":"プロ + だけあって"}],"rule":["1. な형용사는 끝의 だ를 な로 바꾼다(有名だ → 有名な).","2. 그 뒤에 だけあって를 붙인다(有名なだけあって).","3. 명사는 だ 없이 바로 붙이고(プロだけあって), 동사·い형용사는 보통형 그대로 붙인다."],"why":"","nu":"앞의 지위·노력·평판에 걸맞게 뒤의 결과가 좋다고 감탄하거나 칭찬할 때 쓴다. さすが와 함께 쓰는 일이 많다. 뒤에는 주로 긍정적 평가가 오지만, 安いだけあって、すぐ壊れた처럼 앞의 조건에서 당연히 예상되는 결과라면 좋지 않은 결과에도 쓴다.","cmp":[{"g":"～だけに","d":"だけに도 '~인 만큼'이지만 期待していただけに、がっかりした처럼 기대에 어긋난 결과에도 쓸 수 있다. だけあって는 앞에서 당연히 예상되는 대로의 결과(주로 칭찬)를 말한다."}],"ex":[{"jp":"このレストランは有名[ゆうめい]なだけあって、いつも客[きゃく]が多[おお]い。","ko":"이 레스토랑은 유명한 만큼 늘 손님이 많다."},{"jp":"毎日[まいにち]練習[れんしゅう]しただけあって、彼女[かのじょ]のピアノは本当[ほんとう]に上手[じょうず]だ。","ko":"매일 연습한 만큼 그녀의 피아노는 정말 훌륭하다."},{"jp":"さすがプロだけあって、写真[しゃしん]がとてもきれいだ。","ko":"역시 프로인 만큼 사진이 아주 예쁘다."}],"dr":[{"t":"make","q":"高い → ～だけあって","a":"高いだけあって","hint":"い형용사는 그대로 + だけあって"},{"t":"make","q":"有名だ → ～だけあって","a":"有名なだけあって","hint":"な형용사는 だ를 な로 바꾸고 + だけあって"},{"t":"fill","q":"10年[ねん]も日本[にほん]に住[す]んでいた（　）、彼[かれ]の日本語[にほんご]はとても自然[しぜん]だ。","a":"だけあって","opts":["だけあって","にもかかわらず","くせに","わりに"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/だけあって-dake-atte-meaning/"],"vf":1,"u":14,"g":1,"gp":"gg_N2_05"},{"id":"g2_118","t":"～により","ko":"~로 인해, ~에 의해, ~에 따라","cat":"원인·이유","conn":[{"w":"명사(원인)","f":"大雪 + により"},{"w":"명사(수단·방법)","f":"話し合い + により"},{"w":"명사(행위자·수동)","f":"警察 + により"},{"w":"동사 + こと","f":"運動する + こと + により"}],"rule":["1. 원인·수단·근거를 나타내는 명사 뒤에 그대로 により를 붙인다. 大雪 → 大雪により.","2. 동사는 こと를 붙여 명사로 만든 뒤 붙인다. 運動する → 運動することにより.","3. 명사를 꾸밀 때는 による(地震による被害), 회화나 일반 문장에서는 によって를 쓴다."],"why":"동사 よる(因る・依る, 말미암다·의거하다)의 연용형 より에 조사 に가 붙은 형태다. て형으로 하면 によって가 된다.","nu":"원인(大雪により運休), 수단·방법(話し合いにより解決), 수동문의 행위자(警察により逮捕された), 경우에 따른 차이(人により考え方が違う) 등을 나타낸다. によって의 딱딱한 형태로, 뉴스·안내 방송·공문서에서 많이 쓴다. 수동문의 행위자는 보통 に로 나타내지만, 만들어 낸 사람(発明·建設 등)이나 공적인 행위에서는 により・によって를 쓴다.","cmp":[{"g":"～によって","d":"뜻은 같고 일반적인 문장과 회화에서도 쓴다. により는 더 딱딱하다."},{"g":"～ため(に)","d":"원인을 나타내지만 명사 + のため처럼 연결하며, 목적의 뜻도 있다."}],"ex":[{"jp":"大雪[おおゆき]により、電車[でんしゃ]が止[と]まっています。","ko":"폭설로 인해 전철이 멈춰 있습니다."},{"jp":"話[はな]し合[あ]いにより、問題[もんだい]は解決[かいけつ]された。","ko":"논의에 의해 문제는 해결되었다."},{"jp":"毎日[まいにち]運動[うんどう]することにより、体[からだ]が丈夫[じょうぶ]になった。","ko":"매일 운동함으로써 몸이 튼튼해졌다."}],"dr":[{"t":"make","q":"台風 → ～により","a":"台風により","hint":"명사 뒤에 그대로 により"},{"t":"make","q":"地震 + 被害 → ～による","a":"地震による被害","hint":"명사를 꾸밀 때는 による"},{"t":"fill","q":"事故[じこ]（　）、道路[どうろ]が通行止[つうこうど]めになっています。","a":"により","opts":["により","にわたって","にかけては","にしたら"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AB%E3%82%88%E3%81%A3%E3%81%A6-%E3%81%AB%E3%82%88%E3%82%8B"],"vf":1,"u":14,"g":1,"gp":"gg_N2_05"},{"id":"g2_139","t":"～ばかりに","ko":"~한 탓에, ~한 것 때문에 (나쁜 결과)","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"寝坊した + ばかりに"},{"w":"い형용사","f":"安い + ばかりに"},{"w":"な형용사","f":"正直な / 正直である + ばかりに"},{"w":"명사","f":"外国人である + ばかりに"}],"rule":["1. 동사는 보통형(주로 た형)에 붙인다. 寝坊する → 寝坊した(する를 した로).","2. 그 뒤에 ばかりに를 붙인다(寝坊したばかりに).","3. い형용사는 그대로(安いばかりに), な형용사는 な 또는 である를 넣고(正直なばかりに), 명사는 である를 넣는다(外国人であるばかりに)."],"why":"","nu":"오직 그 하나의 원인 때문에 원치 않는 나쁜 결과가 생겼다는 후회·불만을 나타낸다. 뒤에는 이미 일어난 좋지 않은 결과가 오며, 의지·명령·권유는 오지 않는다. 좋은 결과에는 쓰지 않는다. 다만 '~たいばかりに(~하고 싶은 마음 하나로)'는 무리한 행동의 동기를 나타낸다. '~たばかり(막 ~했다)'와 혼동하지 않도록 주의.","cmp":[{"g":"～せいで","d":"せいで도 나쁜 결과의 원인을 나타내지만, ばかりに는 '그것 하나만 아니었으면' 하는 후회의 느낌이 더 강하고 문어적이다."}],"ex":[{"jp":"寝坊[ねぼう]したばかりに、大事[だいじ]な試験[しけん]を受[う]けられなかった。","ko":"늦잠을 잔 탓에 중요한 시험을 보지 못했다."},{"jp":"値段[ねだん]が安[やす]いばかりに、質[しつ]の悪[わる]い物[もの]を買[か]ってしまった。","ko":"가격이 싸다는 이유 하나로 질 나쁜 물건을 사 버렸다."},{"jp":"彼[かれ]は正直[しょうじき]なばかりに、損[そん]をすることが多[おお]い。","ko":"그는 정직한 탓에 손해를 보는 일이 많다."}],"dr":[{"t":"make","q":"忘れる → ～ばかりに","a":"忘れたばかりに","hint":"る를 た로 바꾼 た형 + ばかりに"},{"t":"make","q":"正直だ → ～ばかりに","a":"正直なばかりに","hint":"な형용사는 な + ばかりに"},{"t":"fill","q":"傘[かさ]を持[も]って行[い]かなかった（　）、びしょぬれになった。","a":"ばかりに","opts":["ばかりに","おかげで","ように","ために"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ばかりに-bakari-ni-meaning"],"vf":1,"u":14,"g":1,"gp":"gg_N2_05"},{"id":"g2_153","t":"～ものだから","ko":"~해서, ~하는 바람에 (이유·변명)","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"遅れた + ものだから"},{"w":"い형용사","f":"忙しい + ものだから"},{"w":"な형용사","f":"心配な + ものだから"},{"w":"명사","f":"子供な + ものだから"}],"rule":["1. 동사를 보통형(た형 등)으로 만든다. 遅れる → 遅れた(る를 た로).","2. 그 뒤에 ものだから를 붙인다(遅れたものだから).","3. な형용사와 명사는 な를 넣어 붙인다(心配なものだから)."],"why":"","nu":"개인적인 사정을 이유로 들어 변명하거나 사정을 설명할 때 쓴다. 회화에서는 もんだから가 된다. 뒤에 명령·의뢰·권유·의지 표현은 오지 않는다. 객관적인 이유를 말할 때는 ので・から가 자연스럽다.","cmp":[{"g":"～から","d":"から는 이유 일반에 쓰고 뒤에 명령·의지도 올 수 있지만, ものだから는 '어쩔 수 없었다'는 변명의 느낌이 있고 뒤에 명령·의지가 오지 않는다."}],"ex":[{"jp":"電車[でんしゃ]が遅[おく]れたものだから、会議[かいぎ]に間[ま]に合[あ]わなかった。","ko":"전철이 늦는 바람에 회의에 늦었다."},{"jp":"最近[さいきん]忙[いそが]しいものだから、なかなか連絡[れんらく]できなかった。","ko":"요즘 바빠서 좀처럼 연락하지 못했다."},{"jp":"一人[ひとり]で行[い]かせるのが心配[しんぱい]なものだから、駅[えき]まで送[おく]った。","ko":"혼자 보내기가 걱정돼서 역까지 바래다주었다."}],"dr":[{"t":"make","q":"寝坊する → ～ものだから","a":"寝坊したものだから","hint":"する를 した로 바꾼 た형 + ものだから"},{"t":"make","q":"心配だ → ～ものだから","a":"心配なものだから","hint":"な형용사는 な + ものだから"},{"t":"fill","q":"道[みち]が込[こ]んでいた（　）、遅[おく]れてしまいました。","a":"ものだから","opts":["ものだから","ものの","ものなら","ものか"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201209.html","https://bunpro.jp/ja/grammar_points/%E3%82%82%E3%81%AE%E3%81%A0%E3%81%8B%E3%82%89"],"vf":1,"u":14,"g":1,"gp":"gg_N2_06"},{"id":"g2_163","t":"～わけだ","ko":"~인 것이다, (그러니) ~한 게 당연하다","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"上手になる + わけだ"},{"w":"い형용사","f":"寒い + わけだ"},{"w":"な형용사","f":"上手な + わけだ"},{"w":"명사","f":"一人っ子である + わけだ"}],"rule":["1. 동사·い형용사는 보통형 그대로 둔다. 寒い.","2. 그 뒤에 わけだ를 붙인다. 寒いわけだ.","3. な형용사는 な를 넣고(上手なわけだ), 명사는 である를 넣는다(一人っ子であるわけだ).","4. 이유를 알고 납득할 때는 앞에 どうりで(어쩐지)를 자주 함께 쓴다. どうりで寒いわけだ."],"why":"","nu":"앞의 사실이나 이유로부터 당연히 그런 결론이 나온다는 것을 나타낸다. ① 이유를 알고 '그래서 그렇구나' 납득할 때(どうりで~わけだ), ② 앞 내용을 다른 말로 바꿔 정리할 때(つまり~わけだ) 쓴다. 단순한 이유 설명 'から'를 わけだ로 바꾸는 것은 부자연스럽다.","cmp":[{"g":"～はずだ","d":"근거로부터 '분명 ~일 것이다'라고 추측한다. ～わけだ는 이미 알게 된 사실에 대해 '그래서 그런 거구나' 하고 납득한다."}],"ex":[{"jp":"窓[まど]が開[あ]いている。どうりで寒[さむ]いわけだ。","ko":"창문이 열려 있네. 어쩐지 춥더라."},{"jp":"十年[じゅうねん]も日本[にほん]に住[す]んでいたなら、日本語[にほんご]が上手[じょうず]なわけだ。","ko":"10년이나 일본에 살았다면 일본어를 잘하는 게 당연하다."},{"jp":"一日[いちにち]に十[じゅう]ページ読[よ]めば、一か月[いっかげつ]で三百[さんびゃく]ページ読[よ]むわけだ。","ko":"하루에 10페이지 읽으면 한 달에 300페이지 읽는 셈이다."}],"dr":[{"t":"make","q":"疲れる(た형) → ～わけだ","a":"疲れたわけだ","hint":"る를 빼고 た를 붙인 보통형 + わけだ"},{"t":"make","q":"静かだ → ～わけだ","a":"静かなわけだ","hint":"な형용사는 だ를 な로 바꿔 + わけだ"},{"t":"fill","q":"昨日[きのう]三時間[さんじかん]しか寝[ね]ていないのか。どうりで眠[ねむ]そうな（　）。","a":"わけだ","opts":["わけだ","わけがない","わけにはいかない","ようがない"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%8F%E3%81%91%E3%81%A0"],"vf":1,"u":15,"g":1,"gp":"gg_N2_06"},{"id":"g2_166","t":"～をきっかけに","ko":"~을 계기로","cat":"원인·이유","conn":[{"w":"명사","f":"留学 + をきっかけに"},{"w":"동사 보통형 + の/こと","f":"入院したこと + をきっかけに"}],"rule":["1. 명사 뒤에 조사 を를 붙인다. 留学を.","2. 그 뒤에 きっかけに를 붙인다. 留学をきっかけに.","3. 동사는 の나 こと로 명사화해서 붙인다. 入院したことをきっかけに.","4. をきっかけにして, がきっかけで 형태로도 쓴다."],"why":"きっかけ(계기·실마리) + に의 구성이다.","nu":"어떤 일이 새로운 행동이나 변화가 시작되는 계기가 되었음을 나타낸다. 뒤에는 시작·변화를 나타내는 내용(~를 시작했다, ~하게 되었다)이 온다. 계기는 우연한 일, 작은 일이어도 된다.","cmp":[{"g":"～を契機に","d":"뜻은 같지만 한자어라 더 딱딱하고 글에서 많이 쓴다."}],"ex":[{"jp":"留学[りゅうがく]をきっかけに、料理[りょうり]を始[はじ]めた。","ko":"유학을 계기로 요리를 시작했다."},{"jp":"入院[にゅういん]したことをきっかけに、たばこをやめた。","ko":"입원한 것을 계기로 담배를 끊었다."},{"jp":"ある映画[えいが]がきっかけで、日本語[にほんご]の勉強[べんきょう]を始[はじ]めた。","ko":"어떤 영화가 계기가 되어 일본어 공부를 시작했다."}],"dr":[{"t":"make","q":"結婚 → ～をきっかけに","a":"結婚をきっかけに","hint":"명사 + を + きっかけに"},{"t":"make","q":"会社をやめた → ～をきっかけに","a":"会社をやめたことをきっかけに","hint":"동사는 こと로 명사화 + をきっかけに"},{"t":"fill","q":"一冊[いっさつ]の本[ほん]（　）、彼[かれ]は医者[いしゃ]になろうと決[き]めた。","a":"をきっかけに","opts":["をきっかけに","を問わず","をこめて","を頼りに"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/がきっかけで-ga-kikkake-de-をきっかけに-o-kikkake-ni-meaning"],"vf":1,"u":15,"g":1,"gp":"gg_N2_06"},{"id":"g2_177","t":"～上は","ko":"~한 이상은, ~하게 된 바에는","cat":"원인·이유","conn":[{"w":"동사 た형","f":"決めた + 上は"},{"w":"동사 사전형","f":"引き受ける + 上は"}],"rule":["1. 동사를 た형으로 바꾼다. 2그룹 동사 決める는 る를 た로 바꾼다(決める → 決めた).","2. 그 뒤에 上は를 붙인다(決めた上は).","3. 뒤에는 '끝까지 하겠다, 해야 한다' 같은 결의·의무·각오가 온다."],"why":"","nu":"어떤 상황이 된 이상 당연히 그에 맞는 행동을 해야 한다는 강한 결의나 의무를 나타낸다. 뒤에는 ～つもりだ, ～なければならない, ～べきだ, ～しかない 같은 표현이 온다. 딱딱한 문어체로, 회화에서는 ～からには, ～以上(は)를 더 많이 쓴다.","cmp":[{"g":"～からには","d":"뜻은 거의 같지만 ～からには가 회화에서 더 자연스럽다. ～上は는 더 딱딱하다."},{"g":"～以上(は)","d":"같은 뜻으로 쓰이며, 명사·형용사에도 である를 넣어 붙이기 쉽다."}],"ex":[{"jp":"やると決[き]めた上[うえ]は、最後[さいご]までがんばるつもりだ。","ko":"하기로 정한 이상은 끝까지 열심히 할 생각이다."},{"jp":"引[ひ]き受[う]けた上[うえ]は、責任[せきにん]を持[も]ってやらなければならない。","ko":"맡은 이상은 책임을 지고 해야 한다."},{"jp":"こうなった上[うえ]は、本当[ほんとう]のことを話[はな]すしかない。","ko":"이렇게 된 바에는 사실을 말할 수밖에 없다."}],"dr":[{"t":"make","q":"約束する → ～上は","a":"約束した上は","hint":"する를 した로 바꾼 た형 + 上は"},{"t":"make","q":"始める → ～上は","a":"始めた上は","hint":"る를 た로 바꾼 た형 + 上は"},{"t":"fill","q":"試合[しあい]に出[で]る（　）、絶対[ぜったい]に勝[か]ちたい。","a":"上は","opts":["上は","わりに","ついでに","うちに"]}],"src":["https://nihongokyoshi-net.com/2019/06/04/jlptn2-grammar-uewa/"],"vf":1,"u":15,"g":1,"gp":"gg_N2_06"},{"id":"g2_178","t":"～以上","ko":"~한 이상, ~인 이상 (당연히)","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"約束した + 以上"},{"w":"い형용사","f":"難しい + 以上"},{"w":"な형용사","f":"好きである + 以上"},{"w":"명사 + である","f":"学生である + 以上"}],"rule":["1. 동사를 보통형으로 만든다. 約束する는 する를 した로 바꾼다(約束した).","2. 그 뒤에 以上를 붙인다(約束した以上). 以上は라고도 한다.","3. 명사는 である를 넣어 붙인다(学生である以上). 명사 + の + 以上는 쓰지 않는다."],"why":"","nu":"'~라는 사실이 있는 이상, 당연히 ~해야 한다/~할 것이다'라는 판단을 나타낸다. 뒤에는 ～べきだ, ～なければならない, ～つもりだ, ～はずだ 같은 의무·결의·판단이 자주 온다. 수량의 '이상(3人以上)'과는 다른 용법이다. 명사에는 반드시 である를 쓴다.","cmp":[{"g":"～からには","d":"뜻이 거의 같고 회화적이다. ～以上는 조금 더 딱딱하고 논리적인 느낌이다."},{"g":"～上は","d":"같은 뜻이지만 더 문어적이고 주로 동사에 붙는다."}],"ex":[{"jp":"約束[やくそく]した以上[いじょう]、守[まも]らなければならない。","ko":"약속한 이상 지켜야 한다."},{"jp":"学生[がくせい]である以上[いじょう]、勉強[べんきょう]が一番[いちばん]大切[たいせつ]だ。","ko":"학생인 이상 공부가 가장 중요하다."},{"jp":"自分[じぶん]で決[き]めた以上[いじょう]、文句[もんく]は言[い]わない。","ko":"스스로 정한 이상 불평은 하지 않겠다."}],"dr":[{"t":"make","q":"選手だ → ～以上","a":"選手である以上","hint":"명사는 である + 以上"},{"t":"make","q":"引き受ける(과거) → ～以上","a":"引き受けた以上","hint":"る를 た로 바꾼 た형 + 以上"},{"t":"fill","q":"お金[かね]を払[はら]った（　）、最後[さいご]まで見[み]たい。","a":"以上","opts":["以上","以来","最中","次第"]}],"src":["https://bunpro.jp/ja/grammar_points/%E4%BB%A5%E4%B8%8A2","https://nihongokyoshi-net.com/2019/06/04/jlptn2-grammar-uewa/"],"vf":1,"u":15,"g":1,"gp":"gg_N2_06"},{"id":"g2_014","t":"それなら","ko":"그렇다면, 그러면","cat":"접속·조건","conn":[{"w":"문장 A 다음 (문장 첫머리)","f":"雨です。+ それなら + 傘を持とう。"}],"rule":["1. 상대의 말이나 앞에서 밝혀진 사정 A를 받는다.","2. 다음 문장 맨 앞에 それなら를 놓는다.","3. B에는 A를 전제로 한 말하는 사람의 판단·제안·의지·권유가 온다."],"why":"それ(그것) + なら(조건). 'A가 그렇다면'이라는 뜻을 한 단어로 만든 접속사다.","nu":"상대가 한 말을 받아 대답할 때 특히 많이 쓴다. B는 제안(～たらどう), 의지(～よう), 명령·의뢰도 자연스럽다. 회화에서는 それじゃ·じゃあ·だったら로 바꿔 말하는 경우가 많다. 이미 일어난 결과를 말할 때는 쓰지 않는다.","cmp":[{"g":"だから","d":"だから는 A가 원인이 되어 B가 된다는 인과를 말한다. それなら는 A라는 정보를 전제로 지금 판단·제안을 한다."}],"ex":[{"jp":"「明日[あした]は雨[あめ]らしいよ。」「それなら、傘[かさ]を持[も]って行[い]こう。」","ko":"\"내일은 비가 온대.\" \"그렇다면 우산을 가지고 가자.\""},{"jp":"「お腹[なか]がすいた。」「それなら、何[なに]か食[た]べに行[い]こうか。」","ko":"\"배고파.\" \"그러면 뭐 먹으러 갈까?\""},{"jp":"「この服[ふく]、ちょっと大[おお]きいんです。」「それなら、一[ひと]つ小[ちい]さいサイズはいかがですか。」","ko":"\"이 옷 좀 커요.\" \"그렇다면 한 사이즈 작은 것은 어떠세요?\""}],"dr":[{"t":"make","q":"「時間がない。」→ それなら + タクシーで行こう","a":"それなら、タクシーで行こう。","hint":"상대 말을 받아 문장 앞에 それなら"},{"t":"make","q":"「頭が痛い。」→ それなら + 早く寝たほうがいい","a":"それなら、早く寝たほうがいい。","hint":"그 사정을 전제로 한 조언을 뒤에 둔다"},{"t":"fill","q":"「明日[あした]は暇[ひま]だよ。」「（　）、一緒[いっしょ]に映画[えいが]を見[み]に行[い]かない？」","a":"それなら","opts":["それなら","それなのに","ところが","もっとも"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9D%E3%82%8C%E3%81%AA%E3%82%89"],"vf":1,"u":15,"g":1,"gp":"gg_N2_06"},{"id":"g2_037","t":"～ないことには～ない","ko":"~하지 않고서는 ~할 수 없다","cat":"접속·조건","conn":[{"w":"동사 ない형","f":"食べない + ことには"},{"w":"い형용사","f":"安くない + ことには"},{"w":"な형용사·명사","f":"元気でない + ことには"}],"rule":["1. 동사를 ない형으로 바꾼다(2그룹 食べる: る를 빼고 ない → 食べない).","2. 그 뒤에 ことには를 붙인다(食べないことには).","3. 뒤 문장은 分からない・できない처럼 부정이나 '실현되지 않음'을 나타내는 말로 끝낸다(食べないことには分からない)."],"why":"","nu":"'앞의 조건이 먼저 이루어져야 뒤의 일이 실현된다'는 뜻으로, 그 조건이 꼭 필요하다는 것을 강조한다. 뒤에는 부정형이나 困る・無理だ 같은 부정적 의미의 말이 온다. 회화와 글 모두에서 쓴다. 뒤 문장을 긍정으로 끝내는 실수에 주의한다(×行かないことには分かる).","cmp":[{"g":"～なければ～ない","d":"단순한 조건 표현. ないことには는 '그 조건 없이는 아무것도 시작되지 않는다'는 필수성을 더 강조한다."},{"g":"～てからでないと","d":"'~하고 나서가 아니면'으로 순서를 강조한다."}],"ex":[{"jp":"実際[じっさい]に食[た]べてみないことには、味[あじ]は分[わ]からない。","ko":"실제로 먹어 보지 않고서는 맛은 알 수 없다."},{"jp":"値段[ねだん]がもっと安[やす]くないことには、この商品[しょうひん]は売[う]れないだろう。","ko":"가격이 더 싸지 않고서는 이 상품은 팔리지 않을 것이다."},{"jp":"体[からだ]が丈夫[じょうぶ]でないことには、この仕事[しごと]は続[つづ]けられない。","ko":"몸이 튼튼하지 않고서는 이 일은 계속할 수 없다."}],"dr":[{"t":"make","q":"会う → ～ないことには","a":"会わないことには","hint":"1그룹: う → わ + ない, 그 뒤에 ことには"},{"t":"make","q":"見る → ～ないことには","a":"見ないことには","hint":"2그룹: る를 빼고 ない + ことには"},{"t":"fill","q":"本人[ほんにん]に聞[き]いてみない（　）、本当[ほんとう]のことは分[わ]からない。","a":"ことには","opts":["ことには","ものなら","くせに","うえで"]}],"src":["https://nihongokyoshi-net.com/2019/01/23/jlptn2-grammar-naikotowa-nai/"],"vf":1,"u":16,"g":1,"gp":"gg_N2_06"},{"id":"g2_063","t":"～さえ～ば","ko":"~만 ~하면","cat":"접속·조건","conn":[{"w":"명사","f":"薬 + さえ + 飲めば"},{"w":"동사 ます형","f":"練習し + さえすれば"},{"w":"동사 て형","f":"寝て + さえいれば"},{"w":"い형용사","f":"安く + さえあれば"},{"w":"な형용사","f":"健康で + さえあれば"}],"rule":["1. 명사 뒤의 조사(を・が)를 さえ로 바꾼다(薬を → 薬さえ).","2. 동사를 가정형으로 만든다. 飲む → 飲め(어미 む를 め로)에 ば를 붙인다(飲めば).","3. 동사 자체를 조건으로 할 때는 ます형 + さえすれば로 만든다(練習しさえすれば).","4. い형용사는 く + さえあれば, な형용사는 で + さえあれば로 만든다."],"why":"","nu":"'그 한 가지 조건만 갖춰지면 다른 것은 필요 없이 결과가 이루어진다'는 뜻이다. 회화와 글 모두에 쓴다. 명사에 붙을 때 を・が는 사라지지만 に・で 등은 남는다(駅にさえ着けば).","cmp":[{"g":"～ば","d":"단순한 조건이다. さえ～ば는 그 조건 하나만 있으면 충분하다는 최소 조건을 강조한다."}],"ex":[{"jp":"お金[かね]さえあれば、世界中[せかいじゅう]を旅行[りょこう]できるのに。","ko":"돈만 있으면 전 세계를 여행할 수 있을 텐데."},{"jp":"この薬[くすり]さえ飲[の]めば、すぐ治[なお]りますよ。","ko":"이 약만 먹으면 금방 나아요."},{"jp":"毎日[まいにち]練習[れんしゅう]しさえすれば、上手[じょうず]になる。","ko":"매일 연습하기만 하면 능숙해진다."}],"dr":[{"t":"make","q":"時間がある → ～さえ～ば","a":"時間さえあれば","hint":"が를 さえ로, ある → あれば"},{"t":"make","q":"謝る → ～さえすれば","a":"謝りさえすれば","hint":"ます형(謝り) + さえすれば"},{"t":"fill","q":"天気[てんき]（　）よければ、明日[あした]は山[やま]に登[のぼ]れる。","a":"さえ","opts":["さえ","しか","ほど","について"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/さえ～ば-sae-ba-meaning/"],"vf":1,"u":16,"g":1,"gp":"gg_N2_06"},{"id":"g2_071","t":"～たところ","ko":"~했더니 (결과)","cat":"접속·조건","conn":[{"w":"동사 た형(1그룹)","f":"聞いた + ところ"},{"w":"동사 た형(2그룹)","f":"調べた + ところ"},{"w":"동사 た형(する)","f":"電話した + ところ"}],"rule":["1. する는 불규칙으로 した가 된다(電話する → 電話した).","2. た형 뒤에 ところ를 붙인다(電話したところ).","3. 뒤에는 그 행동의 결과 알게 된 사실을 과거형으로 쓴다."],"why":"","nu":"어떤 행동을 했더니 그 결과 이러했다(이런 사실을 알게 되었다)는 보고에 쓴다. 뒤는 이미 일어난 사실이며 의지·명령은 오지 않는다. 다소 딱딱한 표현이라 보고나 글에 잘 쓴다. '막 ~했다'의 ～たところだ와 헷갈리지 않도록 주의.","cmp":[{"g":"～たら","d":"たら도 '~했더니'의 발견을 나타낼 수 있지만 회화적이다. たところ는 더 딱딱하고, 조건(~하면)의 뜻으로는 쓰지 않는다."},{"g":"～たところだ","d":"문말의 たところだ는 '막 ~했다'로 시점을 나타낸다. 문장 중간의 たところ는 결과를 이어 준다."}],"ex":[{"jp":"駅[えき]の人[ひと]に聞[き]いたところ、電車[でんしゃ]は30分[ぷん]遅[おく]れるそうだ。","ko":"역 직원에게 물었더니 전철이 30분 늦는다고 한다."},{"jp":"店[みせ]に電話[でんわ]したところ、今日[きょう]は休[やす]みだった。","ko":"가게에 전화했더니 오늘은 휴무였다."},{"jp":"薬[くすり]を飲[の]んだところ、熱[ねつ]が下[さ]がった。","ko":"약을 먹었더니 열이 내렸다."}],"dr":[{"t":"make","q":"調べる → ～たところ","a":"調べたところ","hint":"2그룹은 る를 떼고 た + ところ"},{"t":"make","q":"頼む → ～たところ","a":"頼んだところ","hint":"む를 んだ로 바꾼 た형 + ところ"},{"t":"fill","q":"先生[せんせい]に相談[そうだん]した（　）、いいアドバイスをもらえた。","a":"ところ","opts":["ところ","きり","あげく","ばかりに"]}],"src":[],"vf":0,"u":16,"g":1,"gp":"gg_N2_06"},{"id":"g2_081","t":"～てからでないと","ko":"~하고 나서가 아니면 (~할 수 없다)","cat":"접속·조건","conn":[{"w":"동사 て형(1그룹)","f":"洗って + からでないと"},{"w":"동사 て형(2그룹)","f":"調べて + からでないと"},{"w":"동사 て형(する)","f":"予約して + からでないと"}],"rule":["1. 1그룹 동사 洗う는 어미 う를 촉음 っ로 바꾸고 て를 붙여 て형 洗って를 만든다.","2. て형 뒤에 からでないと를 붙인다(洗ってからでないと).","3. 뒤에는 불가능·금지 표현(～できない, ～てはいけない)이 온다."],"why":"てから(~하고 나서) + でないと(~가 아니면)로 이루어져 '~하고 나서가 아니면'이라는 뜻이 된다.","nu":"앞의 일을 먼저 끝내야만 뒤의 일이 가능하다는 조건을 나타낸다. 뒤에는 '할 수 없다·하면 안 된다·모른다' 같은 부정적 표현이 온다. 더 딱딱하게는 ～てからでなければ라고 한다.","cmp":[{"g":"～てはじめて","d":"てはじめて는 '~하고 나서야 비로소 ~했다'로 실제로 일어난 일을 말하며 뒤가 긍정이다. てからでないと는 조건을 말하고 뒤가 부정이다."}],"ex":[{"jp":"手[て]を洗[あら]ってからでないと、おやつを食[た]べてはいけません。","ko":"손을 씻고 나서가 아니면 간식을 먹으면 안 됩니다."},{"jp":"店長[てんちょう]に聞[き]いてからでないと、お返事[へんじ]できません。","ko":"점장님께 여쭤본 뒤가 아니면 답을 드릴 수 없습니다."},{"jp":"実際[じっさい]に使[つか]ってみてからでないと、いいかどうか分[わ]からない。","ko":"실제로 써 보고 나서가 아니면 좋은지 어떤지 모른다."}],"dr":[{"t":"make","q":"予約する → ～てからでないと","a":"予約してからでないと","hint":"する는 して + からでないと"},{"t":"make","q":"調べる → ～てからでないと","a":"調べてからでないと","hint":"2그룹은 る를 떼고 て + からでないと"},{"t":"fill","q":"熱[ねつ]が下[さ]がって（　）、学校[がっこう]に行[い]ってはいけない。","a":"からでないと","opts":["からでないと","からには","ばかりで","こそ"]}],"src":["https://bunpro.jp/grammar_points/507"],"vf":1,"u":16,"g":1,"gp":"gg_N2_06"},{"id":"g2_098","t":"～としたら","ko":"~라고 한다면, 만약 ~라면","cat":"접속·조건","conn":[{"w":"동사 보통형","f":"当たった + としたら"},{"w":"い형용사","f":"高い + としたら"},{"w":"な형용사","f":"本当だ + としたら"},{"w":"명사","f":"病気だ + としたら"}],"rule":["1. 동사를 보통형으로 만든다. 과거라면 当たる → 当たった(る를 った로).","2. 그 뒤에 としたら를 붙인다(当たったとしたら).","3. な형용사와 명사는 だ를 남긴 채 붙인다(本当だとしたら, 病気だとしたら)."],"why":"","nu":"실제로 그런지 모르거나 실현 가능성이 낮은 일을 '그렇다고 가정하면'이라고 말할 때 쓴다. 앞에 もし가 자주 오고, 뒤에는 말하는 사람의 판단·의지·질문이 온다. 들은 정보를 일단 사실로 받아들여 '그렇다면'이라고 말할 때도 쓴다. としたら・とすれば・とすると는 뜻이 거의 같다.","cmp":[{"g":"～たら","d":"일반적인 조건으로 실제로 일어날 일에도 쓴다(駅に着いたら電話する). ～としたら는 '가정하면'이라는 가정의 느낌이 강하다."}],"ex":[{"jp":"もし宝[たから]くじが当[あ]たったとしたら、何[なに]を買[か]いますか。","ko":"만약 복권에 당첨된다면 무엇을 사겠습니까?"},{"jp":"その話[はなし]が本当[ほんとう]だとしたら、大変[たいへん]なことだ。","ko":"그 이야기가 사실이라면 큰일이다."},{"jp":"明日[あした]行[い]くとしたら、何時[なんじ]に出[で]ればいいですか。","ko":"내일 간다고 하면 몇 시에 나가면 됩니까?"}],"dr":[{"t":"make","q":"行く → ～としたら","a":"行くとしたら","hint":"사전형(보통형) 그대로 + としたら"},{"t":"make","q":"病気だ → ～としたら","a":"病気だとしたら","hint":"명사는 だ를 남기고 + としたら"},{"t":"fill","q":"もし生[う]まれ変[か]われる（　）、鳥[とり]になりたい。","a":"としたら","opts":["としたら","どころか","とおりに","ばかりか"]}],"src":["https://bunpro.jp/grammar_points/251"],"vf":1,"u":16,"g":1,"gp":"gg_N2_06"},{"id":"g2_108","t":"～にかかわらず","ko":"~에 관계없이, ~와 상관없이","cat":"접속·조건","conn":[{"w":"명사(차이·폭을 가진 말)","f":"天気 + にかかわらず"},{"w":"동사 사전형 + ない형","f":"行く行かない + にかかわらず"},{"w":"い형용사 대립","f":"多い少ない + にかかわらず"},{"w":"～かどうか","f":"できるかどうか + にかかわらず"}],"rule":["1. 天気・年齢・性別처럼 여러 경우를 포함하는 명사 뒤에 にかかわらず를 붙인다. 天気 → 天気にかかわらず.","2. 동사는 긍정과 부정을 나란히 놓고 붙인다. 行く + 行かない → 行く行かないにかかわらず.","3. い형용사도 반대말 둘을 나란히 놓는다(多い少ないにかかわらず). ～かどうかにかかわらず도 쓴다."],"why":"","nu":"앞의 조건이 어떤 경우든 뒤의 결과는 변하지 않는다는 뜻으로, 공지·안내문 같은 격식 있는 글에서 많이 쓴다. 앞에는 '맑음/비', '남/여'처럼 여러 경우를 포함하는 말이 와야 하며, 하나의 사실(×雨にかかわらず)에는 쓰지 않는다. 한자로는 ～に関わらず로 쓴다. '~인데도'라는 뜻의 ～にもかかわらず와 헷갈리지 않도록 주의한다.","cmp":[{"g":"～にもかかわらず","d":"'~인데도 불구하고'라는 역접이다. 앞에는 하나의 사실이 온다(雨にもかかわらず)."},{"g":"～に関係なく","d":"뜻은 거의 같고 조금 더 회화적이다."}],"ex":[{"jp":"試合[しあい]は天気[てんき]にかかわらず行[おこな]われます。","ko":"경기는 날씨에 관계없이 열립니다."},{"jp":"年齢[ねんれい]や経験[けいけん]にかかわらず、だれでも応募[おうぼ]できます。","ko":"나이나 경험에 관계없이 누구나 응모할 수 있습니다."},{"jp":"参加[さんか]するしないにかかわらず、メールで返事[へんじ]をください。","ko":"참가하든 안 하든 상관없이 메일로 답장 주세요."}],"dr":[{"t":"make","q":"性別 → ～にかかわらず","a":"性別にかかわらず","hint":"명사 뒤에 그대로 にかかわらず"},{"t":"make","q":"行く(긍정·부정) → ～にかかわらず","a":"行く行かないにかかわらず","hint":"사전형 + ない형을 나란히 놓고 にかかわらず"},{"t":"fill","q":"料金[りょうきん]は距離[きょり]の長[なが]さ（　）同[おな]じです。","a":"にかかわらず","opts":["にかかわらず","にもかかわらず","にあたり","において"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AB%E3%81%8B%E3%81%8B%E3%82%8F%E3%82%89%E3%81%9A"],"vf":1,"u":17,"g":1,"gp":"gg_N2_06"},{"id":"g2_110","t":"～にしたがって","ko":"~함에 따라 / ~에 따라(따라서)","cat":"접속·조건","conn":[{"w":"동사 사전형(변화)","f":"登る + にしたがって"},{"w":"명사(변화)","f":"経済の発展 + にしたがって"},{"w":"명사(지시·규칙)","f":"指示 + にしたがって"}],"rule":["1. 변화를 나타내는 동사의 사전형 뒤에 그대로 にしたがって를 붙인다. 登る → 登るにしたがって.","2. 변화를 뜻하는 명사나 지시·규칙을 뜻하는 명사 뒤에도 붙는다(指示にしたがって).","3. 딱딱한 문장에서는 にしたがい, 명사를 꾸밀 때는 にしたがった를 쓴다."],"why":"従う(したがう, 따르다)의 て형 従って에 조사 に가 붙은 것으로, '~에 따라서'라는 뜻이 그대로 드러난다.","nu":"두 가지 용법이 있다. 첫째는 한쪽이 변하면 다른 쪽도 그에 맞춰 변한다는 비례 변화(山を登るにしたがって寒くなる)로, 이때 앞뒤 모두 변화를 나타내는 말이 온다. 둘째는 규칙·지시·안내를 '따라서' 행동한다는 뜻(係員の指示にしたがって避難する)이다. 비례 변화 용법에서는 뒤에 한 번으로 끝나는 일이나 말하는 사람의 의지(명령 등)가 오기 어렵다.","cmp":[{"g":"～につれて","d":"비례 변화의 뜻은 같지만 자연스러운 변화에 주로 쓰며, '규칙을 따르다'라는 뜻은 없다."},{"g":"～とともに","d":"비례 변화 외에 '~와 함께, ~와 동시에'라는 뜻도 있다."}],"ex":[{"jp":"山[やま]を登[のぼ]るにしたがって、気温[きおん]が下[さ]がっていった。","ko":"산을 오름에 따라 기온이 내려갔다."},{"jp":"説明書[せつめいしょ]にしたがって、棚[たな]を組[く]み立[た]てた。","ko":"설명서에 따라 선반을 조립했다."},{"jp":"町[まち]の人口[じんこう]が増[ふ]えるにしたがって、店[みせ]も多[おお]くなった。","ko":"마을 인구가 늘어남에 따라 가게도 많아졌다."}],"dr":[{"t":"make","q":"年をとる → ～にしたがって","a":"年をとるにしたがって","hint":"동사 사전형 + にしたがって"},{"t":"make","q":"矢印 → ～にしたがって","a":"矢印にしたがって","hint":"명사 + にしたがって"},{"t":"fill","q":"係員[かかりいん]の指示[しじ]（　）、会場[かいじょう]から出[で]てください。","a":"にしたがって","opts":["にしたがって","にかけては","にしたら","にあたり"]}],"src":["https://www.mlcjapanese.co.jp/n2_04_32.html","https://bunpro.jp/grammar_points/581"],"vf":1,"u":17,"g":1,"gp":"gg_N2_07"},{"id":"g2_112","t":"～にしろ～にしろ","ko":"~하든 ~하든, ~이든 ~이든","cat":"접속·조건","conn":[{"w":"동사 보통형(긍정·부정)","f":"行く + にしろ + 行かない + にしろ"},{"w":"い형용사","f":"高い + にしろ + 安い + にしろ"},{"w":"명사","f":"肉 + にしろ + 魚 + にしろ"}],"rule":["1. 첫 번째 말(보통형) 뒤에 にしろ를 붙인다. 行く → 行くにしろ.","2. 대립하는 두 번째 말을 만들어 다시 にしろ를 붙인다. 行く의 く를 か로 바꾸고 ない → 行かないにしろ.","3. 둘을 이어 行くにしろ行かないにしろ가 되고, 뒤에 '어느 쪽이든 마찬가지'인 내용이 온다."],"why":"조사 に + する의 명령형 しろ로 이루어진 형태다. 문어에서는 같은 구조로 する의 명령형 せよ를 쓴 にせよ～にせよ가 된다.","nu":"두 가지 경우(대개 반대되는 것이나 같은 종류의 예)를 들고, 그중 어느 쪽이라도 뒤의 판단은 변하지 않는다는 뜻이다. 뒤에는 의뢰·의무·판단(~해 주세요, ~해야 한다) 같은 말하는 사람의 생각이 자주 온다. にしても～にしても보다 딱딱하고, にせよ～にせよ보다는 덜 딱딱하다.","cmp":[{"g":"～にせよ～にせよ","d":"뜻은 같고 더 문어적이다."},{"g":"～にかかわらず","d":"'~에 관계없이'로 공지문에 많이 쓰며, 天気にかかわらず처럼 명사 하나로도 쓸 수 있다."}],"ex":[{"jp":"行[い]くにしろ行[い]かないにしろ、明日[あした]までに連絡[れんらく]してください。","ko":"가든 안 가든 내일까지 연락해 주세요."},{"jp":"肉[にく]にしろ魚[さかな]にしろ、新[あたら]しいものを選[えら]んだほうがいい。","ko":"고기든 생선이든 신선한 것을 고르는 게 좋다."},{"jp":"高[たか]いにしろ安[やす]いにしろ、必要[ひつよう]なものは買[か]わなければならない。","ko":"비싸든 싸든 필요한 것은 사야 한다."}],"dr":[{"t":"make","q":"賛成する / 反対する → ～にしろ～にしろ","a":"賛成するにしろ反対するにしろ","hint":"각각 사전형 + にしろ"},{"t":"make","q":"買う(긍정·부정) → ～にしろ～にしろ","a":"買うにしろ買わないにしろ","hint":"う를 わ로 바꾼 ない형을 두 번째에"},{"t":"fill","q":"電車[でんしゃ]（　）バスにしろ、時間[じかん]はかかる。","a":"にしろ","opts":["にしろ","につれて","にあたり","にかけては"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AB%E3%81%97%E3%82%8D-%E3%81%AB%E3%81%97%E3%82%8D"],"vf":1,"u":17,"g":1,"gp":"gg_N2_07"},{"id":"g2_113","t":"～につけ～につけ","ko":"~하든 ~하든, ~일 때나 ~일 때나","cat":"접속·조건","conn":[{"w":"い형용사(반대말 쌍)","f":"いい + につけ + 悪い + につけ"},{"w":"동사 사전형(쌍)","f":"見る + につけ + 聞く + につけ"},{"w":"명사(쌍)","f":"雨 + につけ + 風 + につけ"}],"rule":["1. 첫 번째 말 뒤에 につけ를 붙인다. いい → いいにつけ.","2. 짝이 되는 두 번째 말 뒤에도 につけ를 붙인다. 悪い → 悪いにつけ.","3. 둘을 이어 いいにつけ悪いにつけ가 되고, 어느 경우에도 같은 일이 일어난다는 내용이 뒤에 온다."],"why":"","nu":"いい/悪い, うれしい/悲しい, 見る/聞く처럼 짝을 이루는 두 말을 들어 '어느 경우든 늘 ~하다'라고 말하는 표현이다. 아무 동사 두 개나 늘어놓는 것은 부자연스럽고, いいにつけ悪いにつけ・見るにつけ聞くにつけ 같은 굳어진 짝으로 쓰는 경우가 많다. 문어적이다. 하나만 쓰는 ～につけ(この写真を見るにつけ)는 '~할 때마다'라는 뜻이다.","cmp":[{"g":"～にしろ～にしろ","d":"'~든 ~든'이라는 뜻은 비슷하지만 짝의 종류에 제한이 적고, 뒤에 의뢰·의무도 자유롭게 온다."},{"g":"～につけ(단독)","d":"見るにつけ・聞くにつけ처럼 하나만 쓰면 '~할 때마다 (늘 어떤 감정이 든다)'라는 뜻이다."}],"ex":[{"jp":"いいにつけ悪[わる]いにつけ、彼[かれ]は何[なん]でも母[はは]に相談[そうだん]する。","ko":"좋은 일이든 나쁜 일이든 그는 무엇이든 어머니와 상의한다."},{"jp":"うれしいにつけ悲[かな]しいにつけ、音楽[おんがく]がそばにあった。","ko":"기쁠 때나 슬플 때나 음악이 곁에 있었다."},{"jp":"雨[あめ]につけ風[かぜ]につけ、祖母[そぼ]は毎朝[まいあさ]散歩[さんぽ]に出[で]かける。","ko":"비가 오나 바람이 부나 할머니는 매일 아침 산책을 나가신다."}],"dr":[{"t":"make","q":"うれしい / 悲しい → ～につけ～につけ","a":"うれしいにつけ悲しいにつけ","hint":"짝이 되는 두 말 뒤에 각각 につけ"},{"t":"make","q":"見る / 聞く → ～につけ～につけ","a":"見るにつけ聞くにつけ","hint":"사전형 + につけ를 두 번"},{"t":"fill","q":"いい（　）悪いにつけ、結果[けっか]は受[う]け入[い]れるしかない。","a":"につけ","opts":["につけ","につれて","にかけて","において"]}],"src":["https://bunpro.jp/grammar_points/551"],"vf":1,"u":17,"g":1,"gp":"gg_N2_07"},{"id":"g2_114","t":"～につれて","ko":"~함에 따라, ~할수록","cat":"접속·조건","conn":[{"w":"동사 사전형(변화)","f":"暗くなる + につれて"},{"w":"명사(변화)","f":"時代の変化 + につれて"},{"w":"い형용사 → くなる","f":"暗い → 暗くなる + につれて"}],"rule":["1. い형용사는 어미 い를 く로 바꾸고 なる를 붙여 변화를 나타내는 동사로 만든다. 暗い → 暗くなる.","2. 변화를 나타내는 동사의 사전형 뒤에 につれて를 붙인다. 暗くなる → 暗くなるにつれて.","3. 변화를 뜻하는 명사 뒤에도 붙는다(時間の経過につれて). 문어에서는 につれ라고도 한다."],"why":"連れる(つれる, 데리고 가다)의 て형 連れて에 조사 に가 붙은 것으로, 한쪽이 다른 쪽을 데리고 가듯 함께 변한다는 뜻이 된다.","nu":"한쪽이 조금씩 변하면 그에 따라 다른 쪽도 조금씩 변한다는 뜻이다. 앞뒤 모두 변화를 나타내는 말이어야 하며, 増える・上がる・なる・近づく 같은 동사가 자주 온다. 한 번으로 끝나는 일(×駅に着くにつれて)이나 말하는 사람의 의지·명령·의뢰는 뒤에 오지 않는다. 한국어 '~할수록'으로 옮기면 자연스러운 경우가 많다.","cmp":[{"g":"～にしたがって","d":"비례 변화의 뜻은 같지만 '규칙·지시를 따르다'라는 뜻도 있다."},{"g":"～ば～ほど","d":"'~하면 ~할수록'으로 회화에서 자주 쓰며, 앞에 같은 말을 반복한다(読めば読むほど)."}],"ex":[{"jp":"空[そら]が暗[くら]くなるにつれて、星[ほし]がたくさん見[み]えてきた。","ko":"하늘이 어두워짐에 따라 별이 많이 보이기 시작했다."},{"jp":"春[はる]が近[ちか]づくにつれて、暖[あたた]かくなってきた。","ko":"봄이 다가옴에 따라 따뜻해졌다."},{"jp":"時代[じだい]の変化[へんか]につれて、人々[ひとびと]の生活[せいかつ]も変[か]わった。","ko":"시대의 변화에 따라 사람들의 생활도 바뀌었다."}],"dr":[{"t":"make","q":"寒い → ～くなるにつれて","a":"寒くなるにつれて","hint":"い를 く로 바꾸고 なる + につれて"},{"t":"make","q":"年をとる → ～につれて","a":"年をとるにつれて","hint":"동사 사전형 + につれて"},{"t":"fill","q":"日本語[にほんご]が上手[じょうず]になる（　）、日本[にほん]の生活[せいかつ]が楽[たの]しくなった。","a":"につれて","opts":["につれて","にしたら","にかけては","にしろ"]}],"src":["https://www.mlcjapanese.co.jp/n2_04_32.html"],"vf":1,"u":17,"g":1,"gp":"gg_N2_07"},{"id":"g2_115","t":"～にともなって","ko":"~에 따라, ~와 함께","cat":"접속·조건","conn":[{"w":"명사(변화·사건)","f":"人口の増加 + にともなって"},{"w":"동사 사전형","f":"人口が増える + にともなって"},{"w":"명사 수식","f":"開発 + にともなう + 問題"}],"rule":["1. 변화나 사건을 나타내는 명사 뒤에 그대로 にともなって를 붙인다. 人口増加 → 人口増加にともなって.","2. 동사는 사전형 뒤에 붙인다. 増える → 増えるにともなって.","3. 문어에서는 にともない, 명사를 꾸밀 때는 にともなう를 쓴다(開発にともなう問題)."],"why":"伴う(ともなう, 동반하다·따르다)의 て형 伴って에 조사 に가 붙은 것으로, '~을 동반하여'라는 뜻이 된다.","nu":"한쪽의 변화나 사건이 일어나면 그에 따라 다른 변화도 함께 일어난다는 뜻이다. 뉴스·보고서·공지 같은 딱딱한 글에서 많이 쓰며, 개인적인 일상 이야기에는 잘 쓰지 않는다. 앞에는 증가·발전·이전처럼 사회적이고 비교적 규모가 큰 변화가 오는 경우가 많다. 한자로 ～に伴って라고도 쓴다.","cmp":[{"g":"～につれて","d":"점차적인 비례 변화에 쓰며 회화에서도 쓴다. にともなって는 더 딱딱하고 한 번의 사건(移転など)에도 쓸 수 있다."},{"g":"～とともに","d":"비례 변화 외에 '~와 함께(같이)'라는 동반의 뜻으로 사람에게도 쓴다."}],"ex":[{"jp":"人口[じんこう]の増加[ぞうか]にともなって、車[くるま]の数[かず]も増[ふ]えた。","ko":"인구 증가에 따라 자동차 수도 늘었다."},{"jp":"駅[えき]ができるにともなって、町[まち]の様子[ようす]が大[おお]きく変[か]わった。","ko":"역이 생기면서 마을 모습이 크게 바뀌었다."},{"jp":"会社[かいしゃ]の移転[いてん]にともない、電話番号[でんわばんごう]が変[か]わります。","ko":"회사 이전에 따라 전화번호가 바뀝니다."}],"dr":[{"t":"make","q":"経済の発展 → ～にともなって","a":"経済の発展にともなって","hint":"명사 뒤에 그대로 にともなって"},{"t":"make","q":"開発 + 問題 → ～にともなう","a":"開発にともなう問題","hint":"명사를 꾸밀 때는 にともなう"},{"t":"fill","q":"気温[きおん]の上昇[じょうしょう]（　）、海[うみ]の水位[すいい]も上[あ]がっている。","a":"にともなって","opts":["にともなって","にかけては","にしたら","に先立ち"]}],"src":["https://nihongokyoshi-net.com/2018/04/16/jlptn2-grammar-tomonatte/","https://bunpro.jp/grammar_points/600"],"vf":1,"u":18,"g":1,"gp":"gg_N2_07"},{"id":"g2_155","t":"～ものなら","ko":"~할 수 있다면 / ~하기라도 하면","cat":"접속·조건","conn":[{"w":"동사 가능형","f":"帰れる + ものなら"},{"w":"동사 의지형","f":"遅刻しよう + ものなら"}],"rule":["1. 동사를 가능형으로 만든다. 1그룹 帰る는 る를 れ로 바꾸고 る를 붙인다(帰る → 帰れる).","2. 그 뒤에 ものなら를 붙인다(帰れるものなら).","3. 의지형에 붙이면(遅刻しようものなら) '~하기라도 하면 큰일 난다'는 뜻이 된다."],"why":"","nu":"① 가능형 + ものなら: 실현이 어려운 일을 '만약 할 수 있다면'이라고 가정하며, 뒤에 ～たい・～てみろ 같은 희망·명령이 온다. ② 의지형 + ものなら: 그런 일을 하면 나쁜 결과가 생긴다고 경고한다. 회화에서는 もんなら가 된다. 쉽게 할 수 있는 일에는 쓰지 않는다.","cmp":[{"g":"～なら","d":"なら는 일반 조건이고, ものなら는 실현 가능성이 낮은 일을 가정하는 느낌이 있다."}],"ex":[{"jp":"帰[かえ]れるものなら、今[いま]すぐ国[くに]へ帰[かえ]りたい。","ko":"돌아갈 수 있다면 지금 당장 고향에 돌아가고 싶다."},{"jp":"やり直[なお]せるものなら、学生時代[がくせいじだい]に戻[もど]りたい。","ko":"다시 할 수 있다면 학생 시절로 돌아가고 싶다."},{"jp":"あの先生[せんせい]の授業[じゅぎょう]に遅刻[ちこく]しようものなら、ひどく叱[しか]られる。","ko":"그 선생님 수업에 지각이라도 하면 심하게 혼난다."}],"dr":[{"t":"make","q":"会う → ～ものなら (가능형)","a":"会えるものなら","hint":"う를 え로 바꾸고 る를 붙인 가능형 + ものなら"},{"t":"make","q":"言う → ～ものなら (의지형)","a":"言おうものなら","hint":"う를 おう로 바꾼 의지형 + ものなら"},{"t":"fill","q":"できる（　）、もう一度[いちど]あの日[ひ]に戻[もど]りたい。","a":"ものなら","opts":["ものなら","ものの","ものだから","ものか"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201209.html"],"vf":1,"u":18,"g":1,"gp":"gg_N2_07"},{"id":"g2_187","t":"～次第で","ko":"~에 따라서, ~여하에 따라","cat":"접속·조건","conn":[{"w":"명사 + 次第で","f":"天気 + 次第で"},{"w":"명사 + 次第だ","f":"あなた + 次第だ"},{"w":"명사 + 次第では","f":"結果 + 次第では"}],"rule":["1. 결과를 좌우하는 조건이 되는 명사를 놓는다(天気).","2. 그 뒤에 次第で를 붙인다(天気次第で).","3. 문장 끝에서는 次第だ / 次第です(天気次第だ), '경우에 따라서는'은 次第では가 된다."],"why":"","nu":"앞의 명사가 어떻게 되느냐에 따라 뒤의 일이 정해지거나 달라진다는 뜻이다. 뒤에는 '변한다, 정해진다, ~할 수도 있다' 같은 내용이 온다. 次第では는 '경우에 따라서는 (특별한 결과도)'라는 뜻이다. 동사 ます형 + 次第(~하는 대로 곧)와 혼동하지 않도록 주의.","cmp":[{"g":"～によって","d":"'~에 따라 각각 다르다'는 일반적인 표현. ～次第で는 그것 하나에 결과가 전적으로 달려 있다는 느낌이 강하다."},{"g":"동사 ます형 + 次第","d":"'~하는 대로 곧바로'라는 시간 표현으로 뜻이 전혀 다르다."}],"ex":[{"jp":"天気[てんき]次第[しだい]で、明日[あした]の予定[よてい]を決[き]めます。","ko":"날씨에 따라 내일 일정을 정하겠습니다."},{"jp":"成功[せいこう]するかどうかは、あなたの努力[どりょく]次第[しだい]だ。","ko":"성공할지 어떨지는 당신의 노력에 달려 있다."},{"jp":"検査[けんさ]の結果[けっか]次第[しだい]では、入院[にゅういん]することになる。","ko":"검사 결과에 따라서는 입원하게 된다."}],"dr":[{"t":"make","q":"値段 → ～次第で","a":"値段次第で","hint":"명사 + 次第で"},{"t":"make","q":"考え方 → ～次第だ","a":"考え方次第だ","hint":"문장 끝은 명사 + 次第だ"},{"t":"fill","q":"使[つか]い方[かた]（　）、この道具[どうぐ]はとても便利[べんり]になる。","a":"次第で","opts":["次第で","向けに","以来","末に"]}],"src":["https://bunpro.jp/grammar_points/%E6%AC%A1%E7%AC%AC%E3%81%A0-%E6%AC%A1%E7%AC%AC%E3%81%A7"],"vf":1,"u":18,"g":1,"gp":"gg_N2_07"},{"id":"g2_190","t":"～限り","ko":"~하는 한, ~하는 동안은","cat":"접속·조건","conn":[{"w":"동사 사전형","f":"ある + 限り"},{"w":"동사 ている형","f":"生きている + 限り"},{"w":"동사 ない형","f":"謝らない + 限り"},{"w":"な형용사","f":"元気な + 限り"},{"w":"명사 + である","f":"学生である + 限り"}],"rule":["1. 동사 生きる의 어미 る를 떼고 ている를 붙여 상태를 나타낸다(生きる → 生きている).","2. 그 뒤에 限り를 붙인다(生きている限り).","3. な형용사는 な(元気な限り), 명사는 である(学生である限り)를 넣는다.","4. ない형 + 限り는 '~하지 않는 한'이 된다(謝らない限り)."],"why":"限り(かぎり)는 限る(한정하다)의 명사형으로 '한계, 범위'라는 뜻이다.","nu":"앞의 상태가 계속되는 동안은 뒤의 일도 계속 성립한다는 조건을 나타낸다. ～ない限り는 '~하지 않으면 (계속) ~이다'라는 뜻으로 자주 쓴다. 私の知る限り(내가 아는 한)처럼 범위를 나타내기도 한다. 다소 딱딱한 표현이다. 명사 + の限り(力の限り)는 '~의 한계까지'라는 다른 뜻이다.","cmp":[{"g":"～うちは","d":"'~하는 동안에는'으로 회화적이다. ～限り는 조건의 의미가 더 강하다."},{"g":"～以上","d":"'~한 이상 당연히'라는 판단. ～限り는 '그 상태가 이어지는 동안'이라는 조건."}],"ex":[{"jp":"生[い]きている限[かぎ]り、この日[ひ]のことは忘[わす]れない。","ko":"살아 있는 한 이날을 잊지 않을 것이다."},{"jp":"雨[あめ]が降[ふ]らない限[かぎ]り、試合[しあい]は行[おこな]われます。","ko":"비가 오지 않는 한 시합은 열립니다."},{"jp":"体[からだ]が元気[げんき]な限[かぎ]り、働[はたら]き続[つづ]けたい。","ko":"몸이 건강한 한 계속 일하고 싶다."}],"dr":[{"t":"make","q":"練習しない → ～限り","a":"練習しない限り","hint":"ない형 + 限り = ~하지 않는 한"},{"t":"make","q":"住む → ～ている限り","a":"住んでいる限り","hint":"む를 んで로 바꾼 て형 + いる + 限り"},{"t":"fill","q":"私[わたし]が知[し]っている（　）、彼[かれ]はうそをつく人[ひと]ではない。","a":"限り","opts":["限り","末に","気味","向け"]}],"src":["https://mlcjapanese.co.jp/n2_04_18.html","https://bunpro.jp/grammar_points/限り"],"vf":1,"u":18,"g":1,"gp":"gg_N2_07"},{"id":"g2_010","t":"A。それが B。","ko":"그게 말이야(실은), 그런데 그게","cat":"역접","conn":[{"w":"상대의 질문 + 대답","f":"試験、どうだった？ + それが + 全然できなかったんだ。"},{"w":"예상 + 실제","f":"簡単だと思っていた。 + それが + 意外に難しかった。"}],"rule":["1. 상대의 질문이나 기대, 또는 자신의 예상 A가 먼저 나온다(試験、どうだった？).","2. 대답하는 문장 맨 앞에 それが를 놓는다.","3. 그 뒤에 A의 예상과 다른 실제 사정 B를 말한다. B는 んだ·のだ로 끝나는 경우가 많다(全然できなかったんだ)."],"why":"","nu":"회화에서 상대의 질문이나 기대와 다른 대답을 할 때 '그게 말이지…'처럼 예상과 다른 내용을 꺼낼 때 쓴다. 곤란한 소식에 많이 쓰지만 뜻밖의 좋은 소식에도 쓸 수 있다. 지시어 それ의 뜻(그것)과 혼동하기 쉬운데, 여기서는 문장 앞의 접속 표현으로 쓰여 뜻밖의 내용을 예고한다.","cmp":[{"g":"ところが","d":"ところが는 예상과 다른 결과를 이야기·글에서 서술할 때 널리 쓴다. それが는 주로 회화에서 상대의 질문·기대에 대답하며 쓴다."}],"ex":[{"jp":"「試験[しけん]、どうだった？」「それが、全然[ぜんぜん]できなかったんだ。」","ko":"\"시험 어땠어?\" \"그게 말이야, 전혀 못 봤어.\""},{"jp":"「彼女[かのじょ]、来[く]るって言[い]ってたよね。」「それが、急[きゅう]に来[こ]られなくなったんだって。」","ko":"\"그녀, 온다고 했었지?\" \"그게, 갑자기 못 오게 됐대.\""},{"jp":"簡単[かんたん]だと思[おも]っていた。それが、やってみると意外[いがい]に難[むずか]しかった。","ko":"쉽다고 생각했다. 그런데 그게 해 보니 의외로 어려웠다."}],"dr":[{"t":"make","q":"試験、どうだった？ / 全然できなかったんだ。→ それが로 대답","a":"それが、全然できなかったんだ。","hint":"뜻밖의 대답 앞에 それが"},{"t":"make","q":"簡単だと思っていた。/ 難しかった。→ それが로 연결","a":"簡単だと思っていた。それが、難しかった。","hint":"예상과 다른 사실 앞에 それが"},{"t":"fill","q":"「旅行[りょこう]、楽[たの]しかった？」「（　）、ずっと雨[あめ]だったんだ。」","a":"それが","opts":["それが","しかも","したがって","すなわち"]}],"src":["https://howtojapanese.substack.com/p/sorega"],"vf":1,"u":18,"g":1,"gp":"gg_N2_07"},{"id":"g2_012","t":"A。それでも B。","ko":"그래도, 그런데도","cat":"역접","conn":[{"w":"문장 + 문장","f":"雨が降っている。 + それでも + 散歩に行く。"},{"w":"문장 + 문장","f":"何度も失敗した。 + それでも + 諦めなかった。"}],"rule":["1. 어떤 상황이나 사실 A를 말한다(雨が降っている。).","2. 다음 문장 맨 앞에 それでも를 놓는다.","3. 그 뒤에 A로 보아 예상되는 것과 반대되는 행동·사실 B를 말한다(散歩に行く)."],"why":"","nu":"A라는 사정이 있는데도 B가 바뀌지 않는다는 강한 역접이다. 회화와 글 모두에서 쓰며, B에는 말하는 이의 의지나 바람(行きたい, 諦めない)도 자연스럽게 온다.","cmp":[{"g":"しかし","d":"しかし는 앞뒤 내용이 대립한다는 것만 나타낸다. それでも는 'A인데도 여전히 B'라는 뜻으로 A를 무릅쓰는 느낌이 강하다."}],"ex":[{"jp":"何度[なんど]も失敗[しっぱい]した。それでも、彼[かれ]は諦[あきら]めなかった。","ko":"몇 번이나 실패했다. 그래도 그는 포기하지 않았다."},{"jp":"雨[あめ]が強[つよ]くなってきた。それでも、試合[しあい]は続[つづ]けられた。","ko":"비가 거세졌다. 그런데도 시합은 계속되었다."},{"jp":"高[たか]いのはわかっている。それでも、この靴[くつ]が欲[ほ]しい。","ko":"비싼 건 알고 있다. 그래도 이 신발을 갖고 싶다."}],"dr":[{"t":"make","q":"雨が降っている。/ 散歩に行く。→ それでも로 연결","a":"雨が降っている。それでも、散歩に行く。","hint":"예상과 반대되는 행동 앞에 それでも"},{"t":"make","q":"何度も失敗した。/ 諦めなかった。→ それでも로 연결","a":"何度も失敗した。それでも、諦めなかった。","hint":"반대 결과 문장 앞에 それでも"},{"t":"fill","q":"医者[いしゃ]に止[と]められた。（　）、彼[かれ]はたばこをやめない。","a":"それでも","opts":["それでも","それで","そこで","しかも"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/それでも-sore-demo-meaning/"],"vf":1,"u":19,"g":1,"gp":"gg_N2_07"},{"id":"g2_013","t":"それなのに","ko":"그런데도, 그럼에도 불구하고","cat":"역접","conn":[{"w":"문장 A 다음 (문장 첫머리)","f":"早く寝た。+ それなのに + 眠い。"}],"rule":["1. 앞 문장 A를 。로 끝낸다.","2. 뒤 문장 B 맨 앞에 それなのに를 놓는다(뒤에 、를 찍는 경우가 많다).","3. B에는 A로부터 당연히 예상되는 것과 반대되는 결과가 온다."],"why":"それ(그것) + なのに(접속조사 のに의 접속사형). 앞 문장 전체를 それ로 받아 のに의 뜻을 문장 사이에서 쓰는 형태다.","nu":"예상과 다른 결과에 대한 의외·불만·실망이 담긴다. B에는 이미 일어난 사실이 오며, 명령·의뢰·의지 표현은 오지 않는다. 회화와 글 모두 쓴다. 감정이 없는 단순 대비라면 しかし·でも가 자연스럽다.","cmp":[{"g":"それでも","d":"それでも는 'A라도 굴하지 않고 B한다'처럼 의지적 행동도 올 수 있다. それなのに는 의외의 결과에 대한 불만·놀람에 쓴다."},{"g":"しかし","d":"しかし는 중립적인 역접으로 감정이 실리지 않는다."}],"ex":[{"jp":"昨日[きのう]は早[はや]く寝[ね]た。それなのに、まだ眠[ねむ]い。","ko":"어제는 일찍 잤다. 그런데도 아직 졸리다."},{"jp":"一生懸命[いっしょうけんめい]練習[れんしゅう]した。それなのに、試合[しあい]に負[ま]けてしまった。","ko":"열심히 연습했다. 그런데도 시합에 지고 말았다."},{"jp":"約束[やくそく]の時間[じかん]はもう過[す]ぎている。それなのに、彼[かれ]からは何[なん]の連絡[れんらく]もない。","ko":"약속 시간은 이미 지났다. 그런데도 그에게서는 아무 연락도 없다."}],"dr":[{"t":"make","q":"薬を飲んだ。/ 熱が下がらない。→ それなのに","a":"薬を飲んだ。それなのに、熱が下がらない。","hint":"B 문장 앞에 それなのに를 놓는다"},{"t":"make","q":"たくさん勉強した。/ 試験に落ちた。→ それなのに","a":"たくさん勉強した。それなのに、試験に落ちた。","hint":"예상과 반대인 결과 앞에 それなのに"},{"t":"fill","q":"何度[なんど]も説明[せつめい]した。（　）、彼[かれ]はまた同[おな]じ間違[まちが]いをした。","a":"それなのに","opts":["それなのに","それなら","だから","ちなみに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9D%E3%82%8C%E3%81%AA%E3%81%AE%E3%81%AB"],"vf":1,"u":19,"g":1,"gp":"gg_N2_07"},{"id":"g2_016","t":"だが","ko":"그러나, 하지만","cat":"역접","conn":[{"w":"문장 A 다음 (문장 첫머리)","f":"高い。+ だが + おいしい。"},{"w":"절 끝 (보통형 + が)","f":"高いが、おいしい。 / 静かだが、不便だ。"}],"rule":["1. 앞 문장 A를 。로 끝내고, 다음 문장 맨 앞에 だが를 놓는다.","2. B에는 A와 대립되는 내용이나 A에서 예상되는 것과 다른 내용이 온다.","3. 문장 안에서 이을 때는 だが를 쓰지 않고 앞말에 が를 붙인다(高いが / 静かだが)."],"why":"단정의 だ + 역접 접속조사 が가 문장 첫머리에서 접속사로 굳은 것이다.","nu":"だ체(보통체) 문장, 즉 논설문·소설·신문 같은 글에서 주로 쓴다. です·ます체 문장 안에서는 어울리지 않으며 그때는 ですが·しかし를 쓴다. 회화에서는 딱딱하게 들려서 でも·けど가 보통이다.","cmp":[{"g":"しかし","d":"しかし는 문체와 관계없이 글과 격식 있는 말에 두루 쓴다. だが는 だ체 문장에 어울린다."},{"g":"でも","d":"でも는 회화체 역접이다."}],"ex":[{"jp":"この店[みせ]は値段[ねだん]が高[たか]い。だが、味[あじ]は確[たし]かだ。","ko":"이 가게는 값이 비싸다. 하지만 맛은 확실하다."},{"jp":"計画[けいかく]は簡単[かんたん]そうに見[み]えた。だが、実際[じっさい]にやってみると大変[たいへん]だった。","ko":"계획은 간단해 보였다. 그러나 실제로 해 보니 힘들었다."},{"jp":"彼[かれ]は口[くち]は悪[わる]い。だが、本当[ほんとう]は優[やさ]しい人[ひと]だ。","ko":"그는 입은 험하다. 하지만 사실은 다정한 사람이다."}],"dr":[{"t":"make","q":"この部屋は狭い。/ 駅に近い。→ だが","a":"この部屋は狭い。だが、駅に近い。","hint":"B 문장 맨 앞에 だが"},{"t":"make","q":"この部屋は狭い。/ 駅に近い。→ 한 문장으로 (が)","a":"この部屋は狭いが、駅に近い。","hint":"문장 안에서는 앞말에 が를 붙인다"},{"t":"fill","q":"努力[どりょく]は続[つづ]けた。（　）、結果[けっか]は出[で]なかった。","a":"だが","opts":["だが","だから","それなら","ちなみに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A0%E3%81%8C%E3%83%BB%E3%81%A7%E3%81%99%E3%81%8C","https://www.seirei.ac.jp/media/20201224_4setsuzokugo.pdf"],"vf":1,"u":19,"g":1,"gp":"gg_N2_07"},{"id":"g2_017","t":"ただ","ko":"다만, 단지","cat":"역접","conn":[{"w":"문장 A 다음 (문장 첫머리)","f":"いい部屋だ。+ ただ + 駅から遠い。"}],"rule":["1. 앞 문장 A에서 주된 평가·내용을 먼저 말한다.","2. 다음 문장 맨 앞에 ただ를 놓는다(뒤에 、를 찍는 경우가 많다).","3. B에는 A를 크게 뒤집지 않는 작은 단서·아쉬운 점·보충이 온다."],"why":"","nu":"A를 대체로 인정하면서 한 가지만 덧붙일 때 쓰며, しかし보다 역접의 힘이 약하다. 회화·글 모두 쓴다. 부사 ただ(그저, 단지)와는 쓰임이 다르다: 접속사 ただ는 문장 첫머리에 온다. 규칙·조건을 정식으로 덧붙일 때는 ただし가 어울린다.","cmp":[{"g":"ただし","d":"ただし는 앞에서 말한 원칙에 조건·예외를 정식으로 붙인다(규칙·안내문). ただ는 개인적인 평가에 단서를 다는 경우가 많다."},{"g":"しかし","d":"しかし는 A와 대립되는 내용을 강하게 내세운다."}],"ex":[{"jp":"この部屋[へや]は広[ひろ]くて明[あか]るい。ただ、駅[えき]から少[すこ]し遠[とお]い。","ko":"이 방은 넓고 밝다. 다만 역에서 조금 멀다."},{"jp":"彼[かれ]の意見[いけん]には賛成[さんせい]です。ただ、時間[じかん]がかかりすぎると思[おも]います。","ko":"그의 의견에는 찬성합니다. 다만 시간이 너무 걸린다고 생각합니다."},{"jp":"旅行[りょこう]は楽[たの]しかった。ただ、天気[てんき]があまりよくなかった。","ko":"여행은 즐거웠다. 다만 날씨가 별로 좋지 않았다."}],"dr":[{"t":"make","q":"この料理はおいしい。/ 少し辛い。→ ただ","a":"この料理はおいしい。ただ、少し辛い。","hint":"아쉬운 점 문장 앞에 ただ"},{"t":"make","q":"仕事は楽しい。/ 給料が安い。→ ただ","a":"仕事は楽しい。ただ、給料が安い。","hint":"주된 평가 뒤, 단서 앞에 ただ"},{"t":"fill","q":"このパソコンは軽[かる]くて便利[べんり]だ。（　）、少[すこ]し高[たか]い。","a":"ただ","opts":["ただ","だから","それなら","すると"]}],"src":["https://www.lang.nagoya-u.ac.jp/nichigen/menu7_folder/symposium/pdf/5/12.pdf"],"vf":1,"u":19,"g":1,"gp":"gg_N2_08"},{"id":"g2_018","t":"ただし","ko":"단, 다만","cat":"역접","conn":[{"w":"문장 A 다음 (문장 첫머리)","f":"入場無料。+ ただし + 予約制です。"}],"rule":["1. 앞 문장 A에서 원칙·규칙을 말한다.","2. 다음 문장 맨 앞에 ただし를 놓는다(뒤에 、를 찍는 경우가 많다).","3. B에는 A에 붙는 조건·예외·주의 사항이 온다."],"why":"","nu":"안내문·규칙·계약 등 정보를 정확히 전하는 글과 격식 있는 말에서 많이 쓴다. B에는 조건(～こと, ～てください, ～場合は)이나 예외가 오는 것이 보통이다. 개인적인 감상에 아쉬운 점을 덧붙일 때는 ただ가 자연스럽다.","cmp":[{"g":"ただ","d":"ただ는 평가에 가벼운 단서·아쉬움을 붙인다. ただし는 원칙에 조건·예외를 붙인다."},{"g":"なお","d":"なお는 관련된 정보를 보충할 뿐 앞 내용을 제한하지 않는다."}],"ex":[{"jp":"入場[にゅうじょう]は無料[むりょう]です。ただし、予約[よやく]が必要[ひつよう]です。","ko":"입장은 무료입니다. 단, 예약이 필요합니다."},{"jp":"この部屋[へや]は自由[じゆう]に使[つか]ってもいいです。ただし、使[つか]った後[あと]は片付[かたづ]けてください。","ko":"이 방은 자유롭게 써도 됩니다. 단, 쓴 뒤에는 정리해 주세요."},{"jp":"毎週[まいしゅう]月曜日[げつようび]は休[やす]みです。ただし、祝日[しゅくじつ]の場合[ばあい]は営業[えいぎょう]します。","ko":"매주 월요일은 휴무입니다. 단, 공휴일인 경우에는 영업합니다."}],"dr":[{"t":"make","q":"写真を撮ってもいいです。/ フラッシュは使わないでください。→ ただし","a":"写真を撮ってもいいです。ただし、フラッシュは使わないでください。","hint":"조건 문장 앞에 ただし"},{"t":"make","q":"参加は自由です。/ 前日までに申し込んでください。→ ただし","a":"参加は自由です。ただし、前日までに申し込んでください。","hint":"원칙 뒤에 ただし + 조건"},{"t":"fill","q":"図書館[としょかん]の本[ほん]は二週間[にしゅうかん]借[か]りられます。（　）、辞書[じしょ]は借[か]りられません。","a":"ただし","opts":["ただし","だから","それなのに","要するに"]}],"src":["https://bunpro.jp/ja/vocabs/%E4%BD%86%E3%81%97"],"vf":1,"u":19,"g":1,"gp":"gg_N2_08"},{"id":"g2_024","t":"もっとも","ko":"하기는, 다만","cat":"역접","conn":[{"w":"문장 A 다음 (문장 첫머리)","f":"毎朝走る。+ もっとも + 雨の日は別だが。"}],"rule":["1. 앞 문장 A에서 주장·사실을 먼저 말한다.","2. 다음 문장 맨 앞에 もっとも를 놓는다(뒤에 、를 찍는 경우가 많다).","3. B에는 A를 일부 고치거나 예외를 덧붙이는 내용이 오고, 끝에 が / けど를 붙이는 경우가 많다(別だ → 別だが)."],"why":"","nu":"A를 대체로 유지하면서 '하기는 ~이긴 하지만'처럼 스스로 보충·수정할 때 쓴다. 회화·글 모두 쓰지만 약간 딱딱한 편이다. B 끝에 が·けど를 붙이면 자연스럽다. 부사 最も(가장)나 형용동사 もっともだ(지당하다)와는 다른 말이다.","cmp":[{"g":"ただし","d":"ただし는 규칙·안내에 조건을 다는 말이다. もっとも는 자기가 한 말에 예외·사정을 덧붙인다."},{"g":"ただ","d":"ただ는 아쉬운 점을 가볍게 덧붙인다. もっとも는 앞 말을 일부 고쳐 말하는 느낌이 있다."}],"ex":[{"jp":"毎朝[まいあさ]一時間[いちじかん]走[はし]っている。もっとも、雨[あめ]の日[ひ]は休[やす]むけど。","ko":"매일 아침 한 시간 달리고 있다. 하기는 비 오는 날은 쉬지만."},{"jp":"この仕事[しごと]は来週[らいしゅう]までに終[お]わる。もっとも、問題[もんだい]が起[お]きなければの話[はなし]だが。","ko":"이 일은 다음 주까지 끝난다. 다만 문제가 생기지 않는다면 말이지만."},{"jp":"彼[かれ]の料理[りょうり]はおいしい。もっとも、作[つく]るのに時間[じかん]がかかるが。","ko":"그의 요리는 맛있다. 하기는 만드는 데 시간이 걸리지만."}],"dr":[{"t":"make","q":"日曜日は家にいます。/ 天気がよければ出かけます → もっとも","a":"日曜日は家にいます。もっとも、天気がよければ出かけますが。","hint":"예외 문장 앞에 もっとも, 끝에 が"},{"t":"make","q":"この店は安い。/ 味は普通だ → もっとも","a":"この店は安い。もっとも、味は普通だが。","hint":"もっとも + 보충 + が"},{"t":"fill","q":"私[わたし]は毎日[まいにち]料理[りょうり]をする。（　）、簡単[かんたん]なものばかりだが。","a":"もっとも","opts":["もっとも","ということは","それなら","だって"]}],"src":["https://bunpro.jp/grammar_points/もっとも"],"vf":1,"u":19,"g":1,"gp":"gg_N2_08"},{"id":"g2_043","t":"～かいもなく","ko":"~한 보람도 없이","cat":"역접","conn":[{"w":"동사 た형","f":"頑張った + かいもなく"},{"w":"명사","f":"努力の + かいもなく"}],"rule":["1. 동사를 た형으로 바꾼다(1그룹 頑張る: 어미 る → った, 頑張った).","2. 그 뒤에 かいもなく를 붙인다(頑張ったかいもなく).","3. 명사는 の를 넣어 연결한다(努力のかいもなく).","4. 뒤에는 기대와 달리 좋지 않게 끝난 결과를 쓴다."],"why":"かい(甲斐, 보람) + も + ない의 연용형 なく로 이루어져 '보람도 없이'라는 뜻이 된다.","nu":"노력·기대를 했지만 결과가 헛되이 끝났다는 실망을 나타낸다. 약간 딱딱한 표현으로 글이나 격식 있는 말에서 쓴다. 뒤에는 이미 일어난 결과(失敗した, 負けた, 亡くなった 등)가 온다. 반대 뜻은 ～かいがあって.","cmp":[{"g":"～かいがあって","d":"노력이 보상받아 좋은 결과가 나왔을 때."},{"g":"～のに","d":"일반적인 역접. かいもなく는 '들인 노력·기대가 헛되었다'는 뜻에 한정된다."}],"ex":[{"jp":"毎晩[まいばん]遅[おそ]くまで勉強[べんきょう]したかいもなく、試験[しけん]に落[お]ちてしまった。","ko":"매일 밤 늦게까지 공부한 보람도 없이 시험에 떨어지고 말았다."},{"jp":"みんなの応援[おうえん]のかいもなく、チームは負[ま]けた。","ko":"모두의 응원도 보람 없이 팀은 졌다."},{"jp":"急[いそ]いで駅[えき]まで走[はし]ったかいもなく、電車[でんしゃ]は出[で]てしまった。","ko":"서둘러 역까지 달린 보람도 없이 전철은 떠나 버렸다."}],"dr":[{"t":"make","q":"待つ → ～かいもなく","a":"待ったかいもなく","hint":"1그룹 つ → った + かいもなく"},{"t":"make","q":"治療 → ～かいもなく","a":"治療のかいもなく","hint":"명사 + の + かいもなく"},{"t":"fill","q":"何度[なんど]も練習[れんしゅう]した（　）、本番[ほんばん]で失敗[しっぱい]した。","a":"かいもなく","opts":["かいもなく","かいがあって","おかげで","うちに"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/甲斐もなく-かいもなく-kai-mo-naku-meaning/","https://bunpro.jp/grammar_points/540"],"vf":1,"u":20,"g":1,"gp":"gg_N2_08"},{"id":"g2_054","t":"～からといって","ko":"~라고 해서","cat":"역접","conn":[{"w":"동사 보통형","f":"勉強した + からといって"},{"w":"い형용사","f":"安い + からといって"},{"w":"な형용사","f":"好きだ + からといって"},{"w":"명사","f":"日本人だ + からといって"}],"rule":["1. 동사·い형용사는 보통형 그대로 쓴다(安い).","2. な형용사·명사는 だ를 붙인다(日本人だ).","3. 이유의 から를 붙인다(安いから).","4. といって를 붙여 からといって로 만들고, 뒤에 わけではない·とは限らない·てはいけない 같은 부정 표현을 잇는다."],"why":"이유의 から에 と言って(~라고 말하고)가 붙은 형태다.","nu":"'그 이유만으로 당연히 ~라고 할 수는 없다'는 뜻으로 뒤에 반드시 부정이나 금지가 온다. 회화에서는 からって로 줄여 말하기도 한다. 뒤를 긍정으로 끝내면 틀린 문장이 된다.","cmp":[{"g":"～からこそ","d":"그 이유를 강하게 인정한다. からといって는 그 이유만으로는 결론이 성립하지 않는다고 부정한다."}],"ex":[{"jp":"安[やす]いからといって、いい物[もの]だとは限[かぎ]らない。","ko":"싸다고 해서 좋은 물건이라고는 할 수 없다."},{"jp":"日本人[にほんじん]だからといって、敬語[けいご]が上手[じょうず]なわけではない。","ko":"일본인이라고 해서 경어를 잘하는 것은 아니다."},{"jp":"忙[いそが]しいからといって、食事[しょくじ]を抜[ぬ]いてはいけない。","ko":"바쁘다고 해서 식사를 거르면 안 된다."}],"dr":[{"t":"make","q":"高い → ～からといって","a":"高いからといって","hint":"い형용사 보통형 + からといって"},{"t":"make","q":"子供だ → ～からといって","a":"子供だからといって","hint":"명사 + だ + からといって"},{"t":"fill","q":"有名[ゆうめい]な店[みせ]だ（　）、おいしいとは限[かぎ]らない。","a":"からといって","opts":["からといって","からこそ","からには","ことから"]}],"src":["https://bunpro.jp/grammar_points/501"],"vf":1,"u":20,"g":1,"gp":"gg_N2_08"},{"id":"g2_059","t":"～くせに","ko":"~인 주제에, ~면서도","cat":"역접","conn":[{"w":"동사 보통형","f":"知っている + くせに"},{"w":"い형용사","f":"若い + くせに"},{"w":"な형용사","f":"下手な + くせに"},{"w":"명사","f":"学生の + くせに"}],"rule":["1. 동사를 보통형으로 만든다. 知る → 知っている(る를 って로 바꾸고 いる).","2. 그 뒤에 くせに를 붙인다(知っているくせに).","3. な형용사는 な, 명사는 の를 넣고 くせに를 붙인다(下手なくせに, 学生のくせに)."],"why":"くせ(癖, 버릇)에 조사 に가 붙은 형태다.","nu":"앞뒤 주어가 같은 사람이며, 그 사람의 행동을 말하는 사람이 비난·경멸·불만의 감정으로 말한다. 회화체이고 윗사람에게 직접 쓰면 실례다. 자기 자신에 대해서는 보통 쓰지 않는다. 문장 끝에서 '知ってるくせに。'처럼 뒤를 생략하기도 한다.","cmp":[{"g":"～のに","d":"예상과 다른 결과에 대한 의외·유감을 나타내며 비난의 느낌이 약하고 주어가 달라도 된다. くせに는 비난이 강하고 주어가 같아야 한다."}],"ex":[{"jp":"本当[ほんとう]は知[し]っているくせに、教[おし]えてくれない。","ko":"사실은 알고 있으면서 가르쳐 주지 않는다."},{"jp":"彼[かれ]は背[せ]が高[たか]いくせに、バスケが下手[へた]だ。","ko":"그는 키가 큰 주제에 농구를 못한다."},{"jp":"子供[こども]のくせに、生意気[なまいき]なことを言[い]うな。","ko":"애인 주제에 건방진 소리 하지 마."}],"dr":[{"t":"make","q":"知る → ～くせに","a":"知っているくせに","hint":"知っている(상태) + くせに"},{"t":"make","q":"下手だ → ～くせに","a":"下手なくせに","hint":"な형용사는 な + くせに"},{"t":"fill","q":"彼[かれ]は学生[がくせい]の（　）、全然[ぜんぜん]勉強[べんきょう]しない。","a":"くせに","opts":["くせに","ために","ように","おかげで"]}],"src":["https://bunpro.jp/grammar_points/295"],"vf":1,"u":20,"g":1,"gp":"gg_N2_08"},{"id":"g2_075","t":"～つつ","ko":"~하면서 / ~하면서도","cat":"역접","conn":[{"w":"동사 ます형(1그룹)","f":"思い + つつ"},{"w":"동사 ます형(1그룹)","f":"知り + つつ"},{"w":"동사 ます형(2그룹)","f":"考え + つつ"}],"rule":["1. 1그룹 동사 思う는 어미 う를 い로 바꿔 ます형 思い를 만든다.","2. ます형 뒤에 つつ를 붙인다(思いつつ).","3. 역접의 뜻을 분명히 할 때는 つつも로 쓴다(思いつつも)."],"why":"","nu":"두 가지 뜻이 있다. ① 동시 동작 '~하면서'(ながら의 문어적 표현, 앞뒤 주어가 같다). ② 역접 '~하면서도'로, 悪いと知りつつ·思いつつ처럼 생각·인식을 나타내는 동사와 자주 쓴다. 문어적이어서 일상 회화에서는 ながら를 더 많이 쓴다.","cmp":[{"g":"～ながら","d":"ながら는 회화와 글 모두 쓰는 일반적 표현이다. つつ는 같은 뜻의 딱딱한 문어체다."}],"ex":[{"jp":"体[からだ]に悪[わる]いと思[おも]いつつ、毎晩[まいばん]ラーメンを食[た]べてしまう。","ko":"몸에 나쁘다고 생각하면서도 매일 밤 라면을 먹고 만다."},{"jp":"いけないと知[し]りつつも、またうそをついてしまった。","ko":"안 된다는 걸 알면서도 또 거짓말을 해 버렸다."},{"jp":"美[うつく]しい景色[けしき]を楽[たの]しみつつ、山道[やまみち]を歩[ある]いた。","ko":"아름다운 경치를 즐기면서 산길을 걸었다."}],"dr":[{"t":"make","q":"知る → ～つつ","a":"知りつつ","hint":"る를 り로 바꾼 ます형 + つつ"},{"t":"make","q":"考える → ～つつ","a":"考えつつ","hint":"2그룹은 る를 뗀 ます형 + つつ"},{"t":"fill","q":"早[はや]く寝[ね]なければと思[おも]い（　）、ついゲームをしてしまう。","a":"つつ","opts":["つつ","っこない","っぱなし","だらけ"]}],"src":["https://www.mlcjapanese.co.jp/n2_04_24.html"],"vf":1,"u":20,"g":1,"gp":"gg_N2_08"},{"id":"g2_096","t":"～どころか","ko":"~는커녕, ~기는커녕 오히려","cat":"역접","conn":[{"w":"동사 보통형","f":"やむ + どころか"},{"w":"い형용사","f":"安い + どころか"},{"w":"な형용사 어간","f":"暇 + どころか"},{"w":"명사","f":"漢字 + どころか"}],"rule":["1. 예상되는 일을 앞에 둔다. 동사는 사전형 그대로(やむ).","2. 그 뒤에 どころか를 붙여 그 예상을 부정한다(やむどころか).","3. 뒤에 정반대의 사실을 이어 말한다(やむどころか、強くなる). な형용사는 だ를 뗀 어간, 명사는 그대로 붙인다(暇どころか)."],"why":"","nu":"앞의 내용은 물론 아니고 실제로는 그와 정반대라는 강한 놀람·의외를 나타낸다. 또 '쉬운 A도 안 되니 어려운 B는 말할 것도 없다'처럼 정도를 비교할 때는 뒤에 も・さえ + 부정이 온다(漢字どころか、ひらがなも書けない). 한국어 '~는커녕'과 거의 같다.","cmp":[{"g":"～ばかりか","d":"'~뿐만 아니라 ~도'로 같은 방향의 내용을 덧붙인다. ～どころか는 앞의 내용을 부정하고 반대 방향의 사실을 말한다."}],"ex":[{"jp":"雨[あめ]はやむどころか、ますます強[つよ]くなってきた。","ko":"비는 그치기는커녕 점점 더 세졌다."},{"jp":"彼[かれ]は漢字[かんじ]どころか、ひらがなも書[か]けない。","ko":"그는 한자는커녕 히라가나도 못 쓴다."},{"jp":"仕事[しごと]が暇[ひま]どころか、毎日[まいにち]残業[ざんぎょう]している。","ko":"일이 한가하기는커녕 매일 야근하고 있다."}],"dr":[{"t":"make","q":"暇だ → ～どころか","a":"暇どころか","hint":"な형용사: だ를 떼고 どころか"},{"t":"make","q":"やせる → ～どころか","a":"やせるどころか","hint":"동사는 사전형 그대로 + どころか"},{"t":"fill","q":"薬[くすり]を飲[の]んだが、熱[ねつ]は下[さ]がる（　）、もっと上[あ]がってしまった。","a":"どころか","opts":["どころか","ばかりか","とおり","うちに"]}],"src":["https://mlcjapanese.co.jp/n2_04_25.html"],"vf":1,"u":20,"g":1,"gp":"gg_N2_08"},{"id":"g2_099","t":"～としても","ko":"~라고 해도, 설령 ~하더라도","cat":"역접","conn":[{"w":"동사 보통형","f":"降った + としても"},{"w":"い형용사","f":"高い + としても"},{"w":"な형용사","f":"大変だ + としても"},{"w":"명사","f":"冗談だ + としても"}],"rule":["1. 동사를 보통형으로 만든다. 과거라면 降る → 降った(る를 った로).","2. 그 뒤에 としても를 붙인다(降ったとしても).","3. な형용사와 명사는 だ를 남긴 채 붙인다(冗談だとしても)."],"why":"","nu":"'그렇다고 가정해도' 뒤의 결과는 바뀌지 않는다는 역접 가정이다. 앞에 たとえ・仮に가 자주 온다. 실제로 일어난 일보다는 가정한 일에 쓴다. 회화에서도 글에서도 쓴다.","cmp":[{"g":"～ても","d":"실제의 일과 가정 모두에 쓰는 기본 역접 조건이다. ～としても는 '가정하면'이라는 느낌이 더 분명하다."},{"g":"～としたら","d":"가정한 뒤 그에 맞는 결론을 말한다. ～としても는 가정해도 결론이 바뀌지 않음을 말한다."}],"ex":[{"jp":"たとえ雨[あめ]が降[ふ]ったとしても、試合[しあい]は行[おこな]われる。","ko":"설령 비가 오더라도 시합은 열린다."},{"jp":"今[いま]から急[いそ]いだとしても、もう間[ま]に合[あ]わないだろう。","ko":"지금부터 서두른다 해도 이미 늦을 것이다."},{"jp":"冗談[じょうだん]だとしても、そんなことを言[い]ってはいけない。","ko":"농담이라 해도 그런 말을 해서는 안 된다."}],"dr":[{"t":"make","q":"失敗する(과거) → ～としても","a":"失敗したとしても","hint":"する를 した로 바꾼 과거형 + としても"},{"t":"make","q":"高い → ～としても","a":"高いとしても","hint":"い형용사는 그대로 + としても"},{"t":"fill","q":"たとえ反対[はんたい]された（　）、私[わたし]はこの仕事[しごと]を続[つづ]ける。","a":"としても","opts":["としても","としたら","ところ","ばかりに"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%A8%E3%81%97%E3%81%A6%E3%82%82"],"vf":1,"u":21,"g":1,"gp":"gg_N2_08"},{"id":"g2_117","t":"～にもかかわらず","ko":"~인데도 불구하고","cat":"역접","conn":[{"w":"동사 보통형","f":"降っている + にもかかわらず"},{"w":"い형용사","f":"忙しい + にもかかわらず"},{"w":"な형용사","f":"便利である + にもかかわらず"},{"w":"명사","f":"雨 + にもかかわらず / 学生である + にもかかわらず"}],"rule":["1. 1그룹 동사 降る의 어미 る를 って로 바꿔 て형을 만든다(촉음편). 降る → 降って.","2. いる를 붙여 진행형을 만든다. 降って → 降っている.","3. 보통형 뒤에 にもかかわらず를 붙인다. 降っている → 降っているにもかかわらず.","4. な형용사·명사는 である를 넣어 붙이며(便利であるにもかかわらず), 명사는 바로 붙이기도 한다(雨にもかかわらず)."],"why":"","nu":"앞의 사실에서 예상되는 것과 반대되는 결과가 뒤에 온다는 뜻으로, 놀람·의외·불만의 느낌이 담긴다. のに보다 딱딱하여 글이나 격식 있는 말에서 쓴다. 뒤에는 이미 일어난 사실이 오며, 말하는 사람의 의지·명령·의뢰(×雨にもかかわらず行ってください)는 오지 않는다. '~에 관계없이'라는 뜻의 ～にかかわらず와 헷갈리지 않도록 주의한다.","cmp":[{"g":"～にかかわらず","d":"'~에 관계없이'로, 앞에 여러 경우를 포함하는 말(天気・年齢)이 온다. にもかかわらず는 하나의 사실에 대한 역접이다."},{"g":"～のに","d":"뜻은 비슷하지만 회화적이고 불만·아쉬움의 감정이 더 직접적이다."}],"ex":[{"jp":"雨[あめ]が降[ふ]っているにもかかわらず、試合[しあい]は続[つづ]けられた。","ko":"비가 내리고 있는데도 불구하고 경기는 계속되었다."},{"jp":"彼[かれ]は忙[いそが]しいにもかかわらず、毎日[まいにち]運動[うんどう]している。","ko":"그는 바쁜데도 불구하고 매일 운동하고 있다."},{"jp":"休日[きゅうじつ]にもかかわらず、多[おお]くの社員[しゃいん]が出勤[しゅっきん]した。","ko":"휴일인데도 불구하고 많은 사원이 출근했다."}],"dr":[{"t":"make","q":"注意する(た형) → ～にもかかわらず","a":"注意したにもかかわらず","hint":"する를 した로 바꾸고 にもかかわらず"},{"t":"make","q":"高い → ～にもかかわらず","a":"高いにもかかわらず","hint":"い형용사 보통형 + にもかかわらず"},{"t":"fill","q":"何度[なんど]も練習[れんしゅう]した（　）、本番[ほんばん]で失敗[しっぱい]してしまった。","a":"にもかかわらず","opts":["にもかかわらず","にかかわらず","にしたがって","にほかならない"]}],"src":["https://nihongokyoshi-net.com/?p=7493","https://bunpro.jp/grammar_points/570"],"vf":1,"u":21,"g":1,"gp":"gg_N2_08"},{"id":"g2_156","t":"～ものの","ko":"~하기는 했지만, ~이지만","cat":"역접","conn":[{"w":"동사 보통형","f":"買った + ものの"},{"w":"い형용사","f":"安い + ものの"},{"w":"な형용사","f":"便利な / 便利である + ものの"},{"w":"명사","f":"学生である + ものの"}],"rule":["1. 동사를 보통형(주로 た형)으로 만든다. う로 끝나는 1그룹 동사는 う를 った로 바꾼다(買う → 買った).","2. 그 뒤에 ものの를 붙인다(買ったものの).","3. な형용사는 な 또는 である, 명사는 である를 넣어 붙인다(学生であるものの)."],"why":"","nu":"앞의 사실은 인정하지만, 그로부터 기대되는 결과가 이루어지지 않았다는 역접이다. 문어적이고 딱딱하다. 뒤에 명령·의뢰·의지 표현은 오지 않는다. とはいうものの(그렇다고는 해도)의 형태로도 쓴다.","cmp":[{"g":"～のに","d":"のに는 불만·의외의 감정이 강한 회화체이고, ものの는 감정이 적은 문어체 역접이다."}],"ex":[{"jp":"運動[うんどう]の道具[どうぐ]を買[か]ったものの、一度[いちど]も使[つか]っていない。","ko":"운동 기구를 사기는 했지만 한 번도 쓰지 않았다."},{"jp":"この部屋[へや]は駅[えき]から近[ちか]いものの、少[すこ]しうるさい。","ko":"이 방은 역에서 가깝기는 하지만 조금 시끄럽다."},{"jp":"大学[だいがく]を出[で]たものの、まだ仕事[しごと]が見[み]つからない。","ko":"대학을 나오기는 했지만 아직 일자리를 찾지 못했다."}],"dr":[{"t":"make","q":"習う → ～ものの","a":"習ったものの","hint":"う를 った로 바꾼 た형 + ものの"},{"t":"make","q":"学生だ → ～ものの","a":"学生であるものの","hint":"명사는 である + ものの"},{"t":"fill","q":"約束[やくそく]した（　）、どうしても行[い]く気[き]になれない。","a":"ものの","opts":["ものの","ものなら","ものだから","ものがある"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201209.html","https://bunpro.jp/ja/grammar_points/%E3%82%82%E3%81%AE%E3%81%AE"],"vf":1,"u":21,"g":1,"gp":"gg_N2_08"},{"id":"g2_173","t":"～一方(で)","ko":"~하는 한편(으로)","cat":"역접","conn":[{"w":"동사 보통형","f":"増える + 一方で"},{"w":"い형용사","f":"おいしい + 一方で"},{"w":"な형용사","f":"便利な / 便利である + 一方で"},{"w":"명사","f":"学生である + 一方で"}],"rule":["1. な형용사는 어간에 な를 붙인다. 便利 → 便利な(또는 便利である).","2. 그 뒤에 一方で 또는 一方를 붙인다. 便利な一方で.","3. 동사·い형용사는 보통형에 그대로 붙이고, 명사는 である를 넣는다(学生である一方で)."],"why":"","nu":"한 가지 면과 함께 다른 면(대개 대조적인 면)도 있음을 나타낸다. 같은 대상의 두 측면(便利な一方で物価が高い), 또는 서로 다른 두 대상의 대비(兄は~一方、弟は~)에 쓴다. 문장 첫머리의 접속사 '一方、'도 같은 뜻이다. 다소 딱딱한 문어적 표현이다.","cmp":[{"g":"～反面","d":"같은 대상의 정반대 성질을 대비할 때 쓴다. ～一方(で)는 대비 외에 '~하는 한편 ~도 한다'는 병행에도 쓸 수 있다."}],"ex":[{"jp":"都会[とかい]は便利[べんり]な一方[いっぽう]で、物価[ぶっか]が高[たか]い。","ko":"도시는 편리한 한편으로 물가가 비싸다."},{"jp":"兄[あに]はスポーツが得意[とくい]な一方[いっぽう]、弟[おとうと]は本[ほん]を読[よ]むのが好[す]きだ。","ko":"형은 운동을 잘하는 한편, 동생은 책 읽기를 좋아한다."},{"jp":"彼[かれ]は会社[かいしゃ]で働[はたら]く一方[いっぽう]で、夜[よる]は大学[だいがく]に通[かよ]っている。","ko":"그는 회사에서 일하는 한편으로 밤에는 대학에 다니고 있다."}],"dr":[{"t":"make","q":"有名だ → ～一方で","a":"有名な一方で","hint":"な형용사는 だ를 な로 바꿔 + 一方で"},{"t":"make","q":"給料が高い → ～一方で","a":"給料が高い一方で","hint":"い형용사는 그대로 + 一方で"},{"t":"fill","q":"この仕事[しごと]は大変[たいへん]な（　）、やりがいもある。","a":"一方で","opts":["一方で","一方だ","わけだ","くせに"]}],"src":["https://nihongokyoshi-net.com/2019/06/01/jlptn2-grammar-ippode/"],"vf":1,"u":21,"g":1,"gp":"gg_N2_08"},{"id":"g2_181","t":"～反面","ko":"~인 반면, ~하는 한편으로","cat":"역접","conn":[{"w":"동사 보통형","f":"よく働く + 反面"},{"w":"い형용사","f":"速い + 反面"},{"w":"な형용사","f":"便利な / 便利である + 反面"},{"w":"명사 + である","f":"学生である + 反面"}],"rule":["1. な형용사는 끝의 だ를 な로 바꾼다(便利だ → 便利な).","2. 그 뒤에 反面을 붙이고 반대되는 면을 잇는다(便利な反面、高い).","3. い형용사와 동사는 보통형에 그대로 붙인다(速い反面). 명사는 である를 넣는다(学生である反面)."],"why":"反面(はんめん)은 '반대쪽 면'이라는 뜻의 명사로, 한 대상의 두 면을 대비한다.","nu":"같은 하나의 대상(사람·물건·일)이 가진 서로 반대되는 두 성질을 나란히 말한다. 서로 다른 두 대상을 비교할 때는 쓰지 않는다(그때는 ～一方(で) 등). 문어적이고 설명문·논설에 많다.","cmp":[{"g":"～一方(で)","d":"한 대상의 두 면뿐 아니라 서로 다른 두 대상의 대비에도 쓸 수 있다. ～反面은 한 대상의 양면에 주로 쓴다."},{"g":"～のに","d":"기대와 다른 결과에 대한 불만·의외를 나타낸다. ～反面은 감정 없이 두 면을 대비한다."}],"ex":[{"jp":"この車[くるま]は速[はや]い反面[はんめん]、ガソリン代[だい]がかかる。","ko":"이 차는 빠른 반면 기름값이 든다."},{"jp":"都会[とかい]の生活[せいかつ]は便利[べんり]な反面[はんめん]、ストレスも多[おお]い。","ko":"도시 생활은 편리한 반면 스트레스도 많다."},{"jp":"彼[かれ]はよく働[はたら]く反面[はんめん]、休[やす]むのが下手[へた]だ。","ko":"그는 일을 열심히 하는 반면 쉬는 데는 서툴다."}],"dr":[{"t":"make","q":"静かだ → ～反面","a":"静かな反面","hint":"な형용사는 だ를 な로 바꾸고 反面"},{"t":"make","q":"楽しい → ～反面","a":"楽しい反面","hint":"い형용사는 그대로 反面"},{"t":"fill","q":"一人暮[ひとりぐ]らしは自由[じゆう]な（　）、寂[さび]しいこともある。","a":"反面","opts":["反面","上は","以来","次第"]}],"src":["https://bunpro.jp/grammar_points/%E5%8F%8D%E9%9D%A2","https://nihongokyoshi-net.com/?p=7607"],"vf":1,"u":21,"g":1,"gp":"gg_N2_09"},{"id":"g2_085","t":"～てならない","ko":"~해서 견딜 수 없다, 너무 ~하다","cat":"비교·정도","conn":[{"w":"い형용사","f":"寂しい → 寂しくて + ならない"},{"w":"な형용사","f":"心配だ → 心配で + ならない"},{"w":"동사 て형","f":"気になる → 気になって + ならない"},{"w":"동사 たい형","f":"会いたい → 会いたくて + ならない"}],"rule":["1. い형용사는 끝의 い를 くて로 바꾼다. 寂しい → 寂しくて.","2. な형용사는 だ를 で로 바꾼다. 心配だ → 心配で.","3. 동사는 て형으로 만든다. 気になる → 気になって.","4. 그 뒤에 ならない를 붙인다(寂しくてならない)."],"why":"","nu":"저절로 생기는 감정·느낌(寂しい・心配だ・残念だ・不安だ・気になる 등)이 억누를 수 없을 만큼 강하다는 표현이다. 기본적으로 말하는 사람 자신의 감정에 쓰고, 다른 사람의 감정이라면 ～てならないようだ・らしい처럼 덧붙인다. 의지적인 동작(食べる・走る 등)에는 쓰지 않는다. 약간 딱딱한 표현이라 회화에서는 ～てしかたがない・～てたまらない를 더 자주 쓴다.","cmp":[{"g":"～てたまらない","d":"뜻은 거의 같지만 더 회화적이고, 暑い・痛い・おなかがすく 같은 몸의 감각에도 자연스럽게 쓴다. ～てならない는 주로 마음속 감정에 쓴다."}],"ex":[{"jp":"友達[ともだち]が引[ひ]っ越[こ]してしまって、寂[さび]しくてならない。","ko":"친구가 이사 가 버려서 외로워 견딜 수가 없다."},{"jp":"明日[あした]の面接[めんせつ]のことが心配[しんぱい]でならない。","ko":"내일 면접이 걱정되어 견딜 수가 없다."},{"jp":"試験[しけん]の結果[けっか]が気[き]になってならない。","ko":"시험 결과가 너무 신경 쓰인다."}],"dr":[{"t":"make","q":"悔しい → ～てならない","a":"悔しくてならない","hint":"い형용사: い를 くて로 바꾸고 ならない"},{"t":"make","q":"不安だ → ～てならない","a":"不安でならない","hint":"な형용사: だ를 で로 바꾸고 ならない"},{"t":"fill","q":"母[はは]の病気[びょうき]が心配[しんぱい]で（　）。","a":"ならない","opts":["ならない","すぎない","ほかない","かまわない"]}],"src":["https://nihongokyoshi-net.com/2019/02/20/jlptn2-grammar-tenaranai/"],"vf":1,"u":22,"g":1,"gp":"gg_N2_09"},{"id":"g2_123","t":"～に対して","ko":"~에 대해, ~에게; ~인 것에 반해","cat":"비교·정도","conn":[{"w":"명사","f":"質問 + に対して"},{"w":"동사·い형용사 보통형 + の(대비)","f":"高いの + に対して"},{"w":"な형용사·명사 + なの(대비)","f":"静かなの + に対して"},{"w":"명사 수식","f":"先生 + に対する + 態度"}],"rule":["1. 동사 対する의 어미 する를 し로 바꾸고 て를 붙여 対して를 만든다(する → して).","2. 대상을 나타낼 때는 명사 + に対して로 쓴다.","3. 두 가지를 대비할 때는 보통형 + の + に対して로 쓴다. な형용사와 명사는 な + の(静かなのに対して).","4. 명사를 꾸밀 때는 に対する + 명사."],"why":"","nu":"두 가지 뜻이 있다. ① 감정・태도・동작이 향하는 대상(~에게, ~에 대해) ② 앞뒤 두 사실의 대비(A인 것에 반해 B). 한국어 '~에 대해'를 모두 に対して로 옮기면 틀린다. 내용・주제를 말할 때(~에 대해 이야기하다)는 について를 쓴다.","cmp":[{"g":"～について","d":"について는 이야기・생각의 '주제'를 나타낸다. に対して는 태도・행동이 '향하는 상대'를 나타낸다. 先生に対して失礼だ / 先生について話す."}],"ex":[{"jp":"先生[せんせい]の質問[しつもん]に対[たい]して、彼女[かのじょ]はすぐに答[こた]えた。","ko":"선생님의 질문에 대해 그녀는 바로 대답했다."},{"jp":"兄[あに]が背[せ]が高[たか]いのに対[たい]して、弟[おとうと]は低[ひく]い。","ko":"형은 키가 큰 것에 반해 남동생은 작다."},{"jp":"お客様[きゃくさま]に対[たい]する言葉遣[ことばづか]いに気[き]をつけてください。","ko":"손님에 대한 말투에 주의해 주세요."}],"dr":[{"t":"make","q":"親 → ～に対して","a":"親に対して","hint":"명사 + に + 対して(する → して)"},{"t":"make","q":"都会はにぎやかだ → ～のに対して","a":"都会はにぎやかなのに対して","hint":"な형용사는 だ를 な로 바꾸고 の + に対して"},{"t":"fill","q":"目上[めうえ]の人[ひと]に（　）、そんな言[い]い方[かた]をしてはいけない。","a":"対して","opts":["対して","ついて","沿って","限り"]}],"src":["https://www.mlcjapanese.co.jp/n2_04_31.html"],"vf":1,"u":22,"g":1,"gp":"gg_N2_09"},{"id":"g2_142","t":"～はまだしも","ko":"~은 그나마 괜찮지만, ~이라면 몰라도","cat":"비교·정도","conn":[{"w":"명사","f":"一日 + はまだしも"},{"w":"동사 사전형 + の","f":"遅刻するの + はまだしも"}],"rule":["1. 그나마 참을 수 있는 명사 A 뒤에 はまだしも를 붙인다(一日はまだしも).","2. 이어서 받아들일 수 없는 B를 쓴다(一週間は).","3. 끝에 '무리다·곤란하다' 같은 부정적 평가를 둔다(一日はまだしも、一週間は無理だ).","4. 동사는 の를 붙여 명사화한 뒤 はまだしも를 붙인다(遅刻するのはまだしも)."],"why":"まだしも는 '그래도 아직 나은 편'이라는 뜻의 부사로, 문형에서도 A가 B보다 그나마 낫다는 의미를 그대로 나타낸다.","nu":"A도 썩 좋지는 않지만 그나마 허용할 수 있는데, B는 도저히 받아들일 수 없다는 불만·비난을 나타낸다. 뒤에는 부정적인 평가가 온다. ～ならまだしも로도 많이 쓴다. 회화에서 주로 쓴다.","cmp":[{"g":"～はともかく","d":"はともかく는 A를 단순히 제쳐 두는 것이고, はまだしも는 A는 허용 가능, B는 허용 불가라는 대비와 불만이 뚜렷하다."}],"ex":[{"jp":"一日[いちにち]はまだしも、一週間[いっしゅうかん]も待[ま]つのは無理[むり]だ。","ko":"하루라면 몰라도 일주일이나 기다리는 건 무리다."},{"jp":"子供[こども]はまだしも、大人[おとな]がそんなことをするなんて。","ko":"아이라면 몰라도 어른이 그런 짓을 하다니."},{"jp":"遅刻[ちこく]するのはまだしも、連絡[れんらく]もしないのは困[こま]る。","ko":"지각하는 것은 그렇다 쳐도 연락도 안 하는 건 곤란하다."}],"dr":[{"t":"make","q":"雨 / 雪は困る → ～はまだしも","a":"雨はまだしも、雪は困る","hint":"참을 만한 명사 + はまだしも + 곤란한 명사 + は"},{"t":"make","q":"休む / 嘘をつくのは許せない → ～はまだしも","a":"休むのはまだしも、嘘をつくのは許せない","hint":"동사 + の + はまだしも"},{"t":"fill","q":"一回[いっかい]（　）、何回[なんかい]も同[おな]じ間違[まちが]いをするのはよくない。","a":"はまだしも","opts":["はまだしも","はもとより","に加えて","をはじめ"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ならまだしも-nara-madashimo-meaning/"],"vf":1,"u":22,"g":1,"gp":"gg_N2_09"},{"id":"g2_158","t":"～も同然だ","ko":"~나 마찬가지다, 거의 ~이다","cat":"비교·정도","conn":[{"w":"명사","f":"家族 + も同然だ"},{"w":"동사 た형","f":"勝った + も同然だ"},{"w":"동사 ない형","f":"来ていない + も同然だ"}],"rule":["1. 명사에는 그대로 も同然だ를 붙인다. 家族 → 家族も同然だ.","2. 동사는 주로 た형으로 바꿔 붙인다. 勝つ → 勝った(つ를 った로) → 勝ったも同然だ.","3. 명사를 꾸밀 때는 だ를 の로 바꾼다. 家族も同然の友達."],"why":"同然은 '같은 상태'라는 뜻의 한자어다(同 같을 동, 然 그러할 연).","nu":"실제로는 그렇지 않지만 사실상 그렇다고 봐도 될 만큼 가깝다는 주관적 평가다. 회화와 글 모두 쓰인다. 결과가 아직 확정되지 않은 일에 '거의 확실하다'는 뜻으로 자주 쓴다(勝ったも同然だ = 이긴 거나 마찬가지).","cmp":[{"g":"～と同じだ","d":"정말로 같다는 객관적 사실을 말한다. ～も同然だ는 실제로는 다르지만 거의 같다고 보는 평가다."}],"ex":[{"jp":"彼[かれ]とは子[こ]どものころからの友達[ともだち]で、家族[かぞく]も同然[どうぜん]だ。","ko":"그와는 어릴 때부터 친구라서 가족이나 마찬가지다."},{"jp":"ここまで来[き]たら、もう勝[か]ったも同然[どうぜん]だ。","ko":"여기까지 왔으면 이제 이긴 거나 마찬가지다."},{"jp":"一度[いちど]も使[つか]っていないから、このパソコンは新品[しんぴん]も同然[どうぜん]だ。","ko":"한 번도 안 썼으니까 이 컴퓨터는 새것이나 마찬가지다."}],"dr":[{"t":"make","q":"決まる → ～も同然だ","a":"決まったも同然だ","hint":"る를 った로 바꾼 た형 + も同然だ"},{"t":"make","q":"ただ → ～も同然だ","a":"ただも同然だ","hint":"명사에는 그대로 も同然だ"},{"t":"fill","q":"この値段[ねだん]なら、ただ（　）。","a":"も同然だ","opts":["も同然だ","わけがない","ようがない","一方だ"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/も同然だ-mo-douzen-da-meaning","https://jisho.org/word/%E5%90%8C%E7%84%B6"],"vf":1,"u":22,"g":1,"gp":"gg_N2_09"},{"id":"g2_189","t":"～気味","ko":"~기미가 있다, 좀 ~한 느낌","cat":"비교·정도","conn":[{"w":"동사 ます형","f":"太り + 気味"},{"w":"명사","f":"風邪 + 気味"}],"rule":["1. 동사를 ます형으로 만든다. 1그룹 동사 太る는 어미 る를 り로 바꾼다(太る → 太り).","2. ます형 뒤에 気味를 붙인다(太り気味). 읽기는 ぎみ.","3. 명사에는 바로 붙인다(風邪気味). 気味だ, 気味の + 명사, 気味で 꼴로 쓴다."],"why":"","nu":"'조금 그런 경향·느낌이 있다'는 뜻으로, 정도가 약함을 나타낸다. 주로 좋지 않은 상태에 쓴다(風邪気味, 疲れ気味, 遅れ気味). い형용사에 바로 붙이는 것은 일반적이지 않다(×暗い気味). 気味(きみ)가 혼자 쓰일 때의 '느낌, 기분'(気味が悪い)과 구별한다.","cmp":[{"g":"～っぽい","d":"'~같은 성질이 있다'는 회화체(忘れっぽい, 子どもっぽい). ～気味는 일시적인 상태가 조금 그렇다는 뜻이 많다."},{"g":"～がち","d":"'자주 ~하는 경향이 있다'는 빈도. ～気味는 지금 상태가 '조금' 그렇다는 정도."}],"ex":[{"jp":"最近[さいきん]、少[すこ]し太[ふと]り気味[ぎみ]だ。","ko":"요즘 조금 살찐 기미가 있다."},{"jp":"今日[きょう]は風邪[かぜ]気味[ぎみ]なので、早[はや]く帰[かえ]ります。","ko":"오늘은 감기 기운이 있어서 일찍 돌아가겠습니다."},{"jp":"仕事[しごと]が忙[いそが]しくて、疲[つか]れ気味[ぎみ]です。","ko":"일이 바빠서 좀 피곤한 상태입니다."}],"dr":[{"t":"make","q":"疲れる → ～気味","a":"疲れ気味","hint":"る를 뗀 ます형 + 気味"},{"t":"make","q":"遅れる → ～気味","a":"遅れ気味","hint":"る를 뗀 ます형 + 気味"},{"t":"fill","q":"昨日[きのう]から少[すこ]し風邪[かぜ]（　）で、頭[あたま]が痛[いた]い。","a":"気味","opts":["気味","向け","次第","以来"]}],"src":["https://bunpro.jp/grammar_points/ぎみ"],"vf":1,"u":22,"g":1,"gp":"gg_N2_09"},{"id":"g2_047","t":"～かねない","ko":"~할지도 모른다 (나쁜 결과)","cat":"추량·전문","conn":[{"w":"동사 ます형 어간","f":"起こし + かねない"},{"w":"동사(する)","f":"し + かねない"}],"rule":["1. 동사를 ます형 어간으로 바꾼다(1그룹 起こす: 어미 す → し, 起こし).","2. 그 뒤에 かねない를 붙인다(起こしかねない).","3. する는 し + かねない가 된다(しかねない)."],"why":"","nu":"그대로 두면 좋지 않은 일이 일어날 가능성이 있다는 말하는 사람의 걱정·경고를 나타낸다. 좋은 결과에는 쓰지 않는다(×合格しかねない). 형태는 부정이지만 뜻은 '~할 수도 있다'라는 긍정적 가능성이라는 점에 주의한다. 회화와 글 모두에서 쓰며, 비즈니스 등에서 말을 부드럽게 할 때도 쓴다.","cmp":[{"g":"～かもしれない","d":"좋은 일·나쁜 일 모두 쓰는 일반적인 추측."},{"g":"～おそれがある","d":"뉴스·공식 발표에서 쓰는 더 객관적인 경고 표현."}],"ex":[{"jp":"スマホを見[み]ながら歩[ある]くと、事故[じこ]を起[お]こしかねない。","ko":"스마트폰을 보면서 걸으면 사고를 낼 수도 있다."},{"jp":"そんな言[い]い方[かた]をしたら、誤解[ごかい]されかねない。","ko":"그런 식으로 말하면 오해받을 수도 있다."},{"jp":"無理[むり]をすると、病気[びょうき]になりかねないよ。","ko":"무리하면 병이 날 수도 있어."}],"dr":[{"t":"make","q":"失う → ～かねない","a":"失いかねない","hint":"1그룹 う → い + かねない"},{"t":"make","q":"忘れる → ～かねない","a":"忘れかねない","hint":"2그룹: る를 빼고 かねない"},{"t":"fill","q":"このまま雨[あめ]が続[つづ]くと、川[かわ]があふれ（　）。","a":"かねない","opts":["かねない","かねる","がちだ","かけだ"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%8B%E3%81%AD%E3%81%AA%E3%81%84"],"vf":1,"u":23,"g":1,"gp":"gg_N2_09"},{"id":"g2_049","t":"～かのようだ","ko":"마치 ~인 것 같다, ~인 듯이","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"見た + かのようだ"},{"w":"い형용사","f":"暑い + かのようだ"},{"w":"な형용사","f":"本当である + かのようだ"},{"w":"명사","f":"社長である + かのようだ"}],"rule":["1. 동사는 보통형(사전형·た형·ない형) 그대로 쓴다. 見る → 見た(る를 빼고 た).","2. 그 뒤에 かのようだ를 붙인다(見たかのようだ).","3. な형용사·명사는 だ 대신 である를 넣고 かのようだ를 붙인다(社長であるかのようだ).","4. 명사를 꾸밀 때는 かのような, 동사를 꾸밀 때는 かのように로 바꾼다."],"why":"","nu":"실제로는 그렇지 않은데 그런 것처럼 보인다는 비유를 나타내며 まるで와 자주 함께 쓴다. 회화와 글 모두에서 쓴다. 실제로 그럴 가능성이 있다는 추측(～ようだ)과 달리 사실과 다르다는 느낌이 강하다.","cmp":[{"g":"～ようだ","d":"근거를 바탕으로 한 추측('~인 것 같다')에도 쓴다. かのようだ는 사실이 아닌 것을 사실처럼 비유하는 데 쓴다."}],"ex":[{"jp":"彼[かれ]はまるで何[なに]も知[し]らないかのように黙[だま]っていた。","ko":"그는 마치 아무것도 모르는 듯이 입을 다물고 있었다."},{"jp":"四月[しがつ]なのに、まるで夏[なつ]が来[き]たかのような暑[あつ]さだ。","ko":"4월인데 마치 여름이 온 것 같은 더위다."},{"jp":"彼女[かのじょ]は自分[じぶん]が社長[しゃちょう]であるかのように話[はな]す。","ko":"그녀는 자기가 사장인 것처럼 말한다."}],"dr":[{"t":"make","q":"見る(과거) → ～かのようだ","a":"見たかのようだ","hint":"た형으로 바꾼 뒤 かのようだ"},{"t":"make","q":"本物だ(명사) → ～かのようだ","a":"本物であるかのようだ","hint":"명사는 である + かのようだ"},{"t":"fill","q":"彼[かれ]はまるで幽霊[ゆうれい]でも見[み]た（　）顔[かお]をしている。","a":"かのような","opts":["かのような","からには","ばかりに","ついでに"]}],"src":["https://bunpro.jp/grammar_points/682"],"vf":1,"u":23,"g":1,"gp":"gg_N2_09"},{"id":"g2_066","t":"～そうにない","ko":"~할 것 같지 않다","cat":"추량·전문","conn":[{"w":"1그룹 동사","f":"止み + そうにない"},{"w":"2그룹 동사","f":"起き + そうにない"},{"w":"する","f":"し + そうにない"},{"w":"가능동사","f":"できそうにない"}],"rule":["1. 동사를 ます형으로 만든다. 止む → 止み(어미 む를 み로).","2. 그 뒤에 そうにない를 붙인다(止みそうにない).","3. そうもない・そうにもない도 같은 뜻으로 쓴다(止みそうもない)."],"why":"","nu":"현재 상황을 보고 어떤 일이 일어날 가능성이 거의 없다고 판단할 때 쓴다. 동사에만 쓰는 것이 기본이다. い형용사는 おいしそうにない가 아니라 おいしくなさそうだ로 말한다.","cmp":[{"g":"～そうだ(전문)","d":"降るそうだ처럼 사전형에 붙으면 들은 말을 전한다. そうにない는 ます형에 붙는 양태의 부정이다."}],"ex":[{"jp":"この雨[あめ]はなかなか止[や]みそうにない。","ko":"이 비는 좀처럼 그칠 것 같지 않다."},{"jp":"仕事[しごと]が多[おお]すぎて、今日中[きょうじゅう]には終[お]わりそうにない。","ko":"일이 너무 많아서 오늘 안에는 끝날 것 같지 않다."},{"jp":"こんなに難[むずか]しい問題[もんだい]は、私[わたし]には解[と]けそうにない。","ko":"이렇게 어려운 문제는 나는 풀 수 없을 것 같다."}],"dr":[{"t":"make","q":"間に合う → ～そうにない","a":"間に合いそうにない","hint":"う를 い로 바꾼 ます형 + そうにない"},{"t":"make","q":"来る → ～そうにない","a":"来そうにない","hint":"来る의 ます형 来(き) + そうにない"},{"t":"fill","q":"この渋滞[じゅうたい]では、約束[やくそく]の時間[じかん]に着[つ]き（　）。","a":"そうにない","opts":["そうにない","ばかりだ","わけがない","はずがない"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/そうもない-sou-mo-nai-そうにない-sou-ni-nai-meaning/"],"vf":1,"u":23,"g":1,"gp":"gg_N2_09"},{"id":"g2_074","t":"～っこない","ko":"~할 리가 없다, 절대 ~못 한다","cat":"추량·전문","conn":[{"w":"동사 ます형(가능형)","f":"勝て + っこない"},{"w":"동사 ます형","f":"分かり + っこない"},{"w":"동사 ます형(できる)","f":"でき + っこない"}],"rule":["1. 勝つ의 어미 つ를 て로 바꾸고 る를 붙여 가능형 勝てる를 만든다.","2. 가능형 勝てる에서 る를 떼어 ます형 勝て로 만든다.","3. ます형 뒤에 っこない를 붙인다(勝てっこない)."],"why":"","nu":"말하는 사람이 '절대 그럴 리 없다'고 강하게 부정하는 표현으로, 친한 사이의 회화에서만 쓴다. できる·分かる나 동사의 가능형과 자주 함께 쓴다. 격식 있는 자리나 글에서는 わけがない·はずがない를 쓴다.","cmp":[{"g":"～わけがない","d":"わけがない도 '~할 리 없다'이지만 회화와 글 모두 쓴다. っこない는 더 감정적이고 허물없는 회화체다."}],"ex":[{"jp":"あんな強[つよ]いチームに勝[か]てっこない。","ko":"저렇게 강한 팀에게 이길 리가 없다."},{"jp":"こんな難[むずか]しい問題[もんだい]、子[こ]どもに分[わ]かりっこないよ。","ko":"이렇게 어려운 문제, 아이가 알 리가 없어."},{"jp":"一日[いちにち]で全部[ぜんぶ]覚[おぼ]えるなんて、できっこない。","ko":"하루 만에 전부 외우다니 절대 못 해."}],"dr":[{"t":"make","q":"分かる → ～っこない","a":"分かりっこない","hint":"る를 り로 바꾼 ます형 + っこない"},{"t":"make","q":"できる → ～っこない","a":"できっこない","hint":"る를 뗀 ます형 + っこない"},{"t":"fill","q":"こんなに遠[とお]いんだから、歩[ある]いて行[い]け（　）よ。","a":"っこない","opts":["っこない","っぱなし","っぽい","つつ"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/っこない-kkonai-meaning/"],"vf":1,"u":23,"g":1,"gp":"gg_N2_09"},{"id":"g2_078","t":"～っぽい","ko":"~스럽다, ~같은 느낌이다, 잘 ~하다","cat":"추량·전문","conn":[{"w":"명사","f":"子ども + っぽい"},{"w":"동사 ます형","f":"忘れ + っぽい"},{"w":"い형용사 어간","f":"安 + っぽい"},{"w":"색 명사","f":"白 + っぽい"}],"rule":["1. 2그룹 동사 忘れる는 어미 る를 떼어 ます형 忘れ를 만든다.","2. ます형 뒤에 っぽい를 붙인다(忘れっぽい).","3. 명사는 바로 붙인다(子どもっぽい). っぽい는 い형용사처럼 활용한다(忘れっぽくない)."],"why":"","nu":"① 명사·い형용사 어간 + っぽい: 실제로는 아니지만 그런 성질이나 느낌이 있다(子どもっぽい, 安っぽい, 白っぽい). 子どもっぽい·安っぽい처럼 부정적 평가가 되는 일이 많다. ② 동사 ます형 + っぽい: 그렇게 되기 쉬운 성향(忘れっぽい, 怒りっぽい). 회화체다.","cmp":[{"g":"～らしい","d":"男らしい는 '남자로서 그 본질에 걸맞다(남자답다)'는 칭찬이고, 男っぽい는 '남자 같은 느낌이 난다'는 인상이다."}],"ex":[{"jp":"兄[あに]はとても忘[わす]れっぽくて、よく傘[かさ]をなくす。","ko":"형은 건망증이 심해서 자주 우산을 잃어버린다."},{"jp":"彼[かれ]はもう大人[おとな]なのに、考[かんが]え方[かた]が子[こ]どもっぽい。","ko":"그는 이제 어른인데 생각하는 게 어린애 같다."},{"jp":"この服[ふく]は安[やす]っぽく見[み]える。","ko":"이 옷은 싸구려처럼 보인다."}],"dr":[{"t":"make","q":"怒る → ～っぽい","a":"怒りっぽい","hint":"る를 り로 바꾼 ます형 + っぽい"},{"t":"make","q":"大人 → ～っぽい","a":"大人っぽい","hint":"명사 + っぽい"},{"t":"fill","q":"あの人[ひと]は怒[おこ]り（　）から、話[はな]すときは気[き]をつけて。","a":"っぽい","opts":["っぽい","っこない","つつある","だらけ"]}],"src":["https://bunpro.jp/grammar_points/312"],"vf":1,"u":23,"g":1,"gp":"gg_N2_09"},{"id":"g2_126","t":"～に決まっている","ko":"~임에 틀림없다, 당연히 ~이다","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"濡れる + に決まっている"},{"w":"い형용사","f":"高い + に決まっている"},{"w":"な형용사 어간","f":"無理 + に決まっている"},{"w":"명사","f":"うそ + に決まっている"}],"rule":["1. 동사・い형용사는 보통형 그대로 뒤에 に決まっている를 붙인다(濡れる + に決まっている).","2. な형용사와 명사는 だ를 붙이지 않고 어간・명사에 바로 붙인다(無理に決まっている).","3. 決まっている는 決まる의 て형 決まって + いる이고, 과거 일을 추측할 때는 앞을 た형으로 한다(負けたに決まっている)."],"why":"決まる(정해지다)의 상태 표현 決まっている에서 '이미 정해져 있다 = 그럴 것이 뻔하다'라는 뜻이 된다.","nu":"말하는 사람의 강한 확신・단정을 나타내는 회화적 표현이다. 회화에서는 に決まってる로 줄여 말하는 일이 많다. 주관적 확신이므로 논문・공식 문서에는 맞지 않는다. 같은 확신이라도 객관적 근거를 강조할 때는 に違いない를 쓴다.","cmp":[{"g":"～に違いない","d":"に違いない는 근거를 바탕으로 한 확신으로 문어에서도 쓴다. に決まっている는 더 주관적이고 감정적인 회화 표현이다."}],"ex":[{"jp":"傘[かさ]を持[も]たずに出[で]かけたら、濡[ぬ]れるに決[き]まっている。","ko":"우산을 안 가지고 나가면 젖을 게 뻔하다."},{"jp":"こんな店[みせ]のワインは高[たか]いに決[き]まっている。","ko":"이런 가게의 와인은 비쌀 게 틀림없다."},{"jp":"一日[いちにち]で全部[ぜんぶ]読[よ]むなんて無理[むり]に決[き]まっているよ。","ko":"하루 만에 다 읽는다니 무리인 게 당연하지."}],"dr":[{"t":"make","q":"うそだ → ～に決まっている","a":"うそに決まっている","hint":"명사는 だ를 빼고 바로 に決まっている"},{"t":"make","q":"疲れる → ～に決まっている","a":"疲れるに決まっている","hint":"동사는 보통형 그대로 + に決まっている"},{"t":"fill","q":"毎日[まいにち]練習[れんしゅう]している彼[かれ]が勝[か]つ（　）。","a":"に決まっている","opts":["に決まっている","に過ぎない","に応じて","に反して"]}],"src":["https://bunpro.jp/grammar_points/524"],"vf":1,"u":24,"g":1,"gp":"gg_N2_09"},{"id":"g2_146","t":"～まい","ko":"~하지 않겠다 / ~하지 않을 것이다","cat":"추량·전문","conn":[{"w":"1그룹 동사","f":"行く + まい"},{"w":"2그룹 동사","f":"食べる + まい / 食べ + まい"},{"w":"する","f":"するまい / すまい / しまい"},{"w":"来る","f":"来るまい / 来まい(こまい)"}],"rule":["1. 1그룹 동사는 사전형에 그대로 まい를 붙인다(行く → 行くまい).","2. 2그룹 동사는 사전형(食べるまい) 또는 る를 뺀 형태(食べまい)에 붙인다.","3. する는 するまい・すまい・しまい, 来る는 来るまい・来まい(こまい)가 된다."],"why":"","nu":"두 가지 뜻이 있다. ① 화자의 부정 의지: '두 번 다시 ~하지 않겠다'(もう二度と行くまい). ② 부정 추측: '~하지 않을 것이다'(ないだろう의 문어적 표현). 딱딱한 문어체로, 회화에서는 ないつもりだ・ないだろう를 쓴다. ～まいと思う(~하지 않으려고 생각하다)의 형태도 많다.","cmp":[{"g":"～ないだろう","d":"부정 추측의 뜻은 같지만 ないだろう는 회화체이고 まい는 문어체다."}],"ex":[{"jp":"あんな店[みせ]には、もう二度[にど]と行[い]くまい。","ko":"저런 가게에는 이제 두 번 다시 가지 않겠다."},{"jp":"この雨[あめ]はすぐにはやむまい。","ko":"이 비는 금방은 그치지 않을 것이다."},{"jp":"同[おな]じ失敗[しっぱい]はするまいと心[こころ]に決[き]めた。","ko":"같은 실수는 하지 않겠다고 마음먹었다."}],"dr":[{"t":"make","q":"言う → ～まい","a":"言うまい","hint":"1그룹은 사전형 + まい"},{"t":"make","q":"する → ～まい (す형)","a":"すまい","hint":"する는 するまい・すまい・しまい"},{"t":"fill","q":"もう二度[にど]と彼[かれ]には会[あ]う（　）。","a":"まい","opts":["まい","べきだ","ようだ","らしい"]}],"src":["https://bunpro.jp/grammar_points/343"],"vf":1,"u":24,"g":1,"gp":"gg_N2_10"},{"id":"g2_162","t":"～わけがない","ko":"~일 리가 없다","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"勝てる + わけがない"},{"w":"い형용사","f":"まずい + わけがない"},{"w":"な형용사","f":"静かな + わけがない"},{"w":"명사","f":"犯人の / 犯人である + わけがない"}],"rule":["1. 동사는 보통형에 붙인다. 가능형이면 勝つ → 勝てる(つ를 て로 바꾸고 る).","2. 그 뒤에 わけがない를 붙인다. 勝てるわけがない.","3. な형용사는 な, 명사는 の 또는 である를 넣는다. 静かなわけがない, 犯人のわけがない."],"why":"","nu":"근거를 바탕으로 '절대 그럴 리 없다'고 강하게 부정한다. 회화에서는 が를 빼고 わけない라고도 한다. 부분 부정인 ～わけではない(꼭 ~인 것은 아니다)와 헷갈리기 쉬우니 주의.","cmp":[{"g":"～はずがない","d":"대개 바꿔 쓸 수 있다. ～はずがない는 말하는 사람이 스스로 추론한 결론(놀람·믿기지 않음)에 가깝고, ～わけがない는 당연한 사실처럼 단정하는 더 강한 부정이다."},{"g":"～わけではない","d":"'꼭 ~인 것은 아니다'라는 부분 부정이다. ～わけがない는 '~일 리 없다'는 전면 부정."}],"ex":[{"jp":"こんな難[むずか]しい問題[もんだい]、子[こ]どもに解[と]けるわけがない。","ko":"이렇게 어려운 문제를 아이가 풀 수 있을 리가 없다."},{"jp":"あの有名[ゆうめい]な店[みせ]の料理[りょうり]がまずいわけがない。","ko":"그 유명한 가게 요리가 맛없을 리가 없다."},{"jp":"子[こ]どもが五人[ごにん]もいる家[いえ]が静[しず]かなわけがない。","ko":"아이가 다섯이나 있는 집이 조용할 리가 없다."}],"dr":[{"t":"make","q":"できる → ～わけがない","a":"できるわけがない","hint":"보통형(사전형) 그대로 + わけがない"},{"t":"make","q":"暇だ → ～わけがない","a":"暇なわけがない","hint":"な형용사는 だ를 な로 바꿔 + わけがない"},{"t":"fill","q":"毎日[まいにち]練習[れんしゅう]している彼[かれ]が負[ま]ける（　）。","a":"わけがない","opts":["わけがない","わけだ","よりほかない","も同然だ"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%8F%E3%81%91%E3%81%8C%E3%81%AA%E3%81%84"],"vf":1,"u":24,"g":1,"gp":"gg_N2_10"},{"id":"g2_183","t":"～恐れがある","ko":"~할 우려가 있다","cat":"추량·전문","conn":[{"w":"동사 사전형","f":"遅れる + 恐れがある"},{"w":"동사 ない형","f":"間に合わない + 恐れがある"},{"w":"명사 + の","f":"台風の + 恐れがある"}],"rule":["1. 동사는 사전형 그대로 둔다(遅れる).","2. 그 뒤에 恐れ를 붙인다(遅れる恐れ).","3. 조사 が와 ある를 이어 恐れがある로 끝낸다. 명사는 の를 넣는다(台風の恐れがある)."],"why":"恐れ(おそれ)는 恐れる(두려워하다)의 명사형으로, '걱정·우려'라는 뜻이다.","nu":"좋지 않은 일이 일어날 가능성이 있다는 경고를 나타낸다. 좋은 일에는 쓰지 않는다. 뉴스·일기예보·안내문 등 딱딱한 문장에 많이 쓰며, 일상 회화에서는 ～かもしれない가 자연스럽다. 恐れ는 히라가나로 おそれ라고 쓰는 경우도 많다.","cmp":[{"g":"～かもしれない","d":"좋은 일·나쁜 일 모두에 쓰는 일반적인 추측. ～恐れがある는 나쁜 일에만 쓰는 딱딱한 경고 표현."}],"ex":[{"jp":"明日[あした]は大雨[おおあめ]になる恐[おそ]れがあります。","ko":"내일은 큰비가 내릴 우려가 있습니다."},{"jp":"このままでは電車[でんしゃ]に間[ま]に合[あ]わない恐[おそ]れがある。","ko":"이대로는 전철 시간에 늦을 우려가 있다."},{"jp":"今夜[こんや]から台風[たいふう]の恐[おそ]れがあるので、気[き]をつけてください。","ko":"오늘 밤부터 태풍의 우려가 있으니 조심하세요."}],"dr":[{"t":"make","q":"広がる → ～恐れがある","a":"広がる恐れがある","hint":"동사 사전형 + 恐れがある"},{"t":"make","q":"地震 → ～恐れがある","a":"地震の恐れがある","hint":"명사는 の + 恐れがある"},{"t":"fill","q":"この薬[くすり]は飲[の]みすぎると、体[からだ]に悪[わる]い影響[えいきょう]が出[で]る（　）。","a":"恐れがある","opts":["恐れがある","ことにする","つもりだ","ようにする"]}],"src":["https://www.mlcjapanese.co.jp/n2_04_03.html","https://bunpro.jp/grammar_points/恐れがある"],"vf":1,"u":24,"g":1,"gp":"gg_N2_10"},{"id":"g2_052","t":"～からして","ko":"~부터가(벌써), ~로 보아","cat":"강조·한정","conn":[{"w":"명사","f":"名前 + からして"},{"w":"명사","f":"態度 + からして"}],"rule":["1. 명사 뒤에 からして를 바로 붙인다(名前からして).","2. 활용하는 부분은 없다. 뒤에 그로부터 내린 평가나 판단이 온다(名前からして高そうだ)."],"why":"","nu":"① 가장 기본적이거나 사소한 한 가지를 예로 들어 '그것부터가 이러니 나머지는 말할 것도 없다'고 할 때, ② 판단의 근거를 나타낼 때 쓴다. ①은 부정적인 평가에 자주 쓴다. 명사에만 붙는다.","cmp":[{"g":"～からすると","d":"판단의 근거·입장을 중립적으로 말한다. からして는 '그것부터가'라는 강조의 느낌이 더해진다."}],"ex":[{"jp":"この店[みせ]は名前[なまえ]からして高[たか]そうだ。","ko":"이 가게는 이름부터가 비싸 보인다."},{"jp":"この映画[えいが]はタイトルからして怖[こわ]い。","ko":"이 영화는 제목부터가 무섭다."},{"jp":"彼[かれ]の態度[たいど]からして、反省[はんせい]しているとは思[おも]えない。","ko":"그의 태도로 보아 반성하고 있다고는 생각되지 않는다."}],"dr":[{"t":"make","q":"話し方 → ～からして","a":"話し方からして","hint":"명사 + からして"},{"t":"make","q":"顔つき → ～からして","a":"顔つきからして","hint":"명사 뒤에 그대로 からして"},{"t":"fill","q":"あの人[ひと]は服装[ふくそう]（　）、普通[ふつう]の人[ひと]とは違[ちが]う。","a":"からして","opts":["からして","につれて","をめぐって","にかけて"]}],"src":["https://nihongokyoshi-net.com/2019/05/30/jlptn2-grammar-karashite/"],"vf":1,"u":24,"g":1,"gp":"gg_N2_10"},{"id":"g2_061","t":"～ことに","ko":"~하게도 (감정 강조)","cat":"강조·한정","conn":[{"w":"동사 た형(감정)","f":"驚いた + ことに"},{"w":"い형용사(감정)","f":"うれしい + ことに"},{"w":"な형용사(감정)","f":"残念な + ことに"}],"rule":["1. 감정을 나타내는 동사를 た형으로 만든다. 驚く → 驚いた(く를 い로 바꾸고 た).","2. 그 뒤에 ことに를 붙인다(驚いたことに).","3. い형용사는 그대로(うれしいことに), な형용사는 な를 넣어(残念なことに) ことに를 붙인다."],"why":"","nu":"뒤에 오는 사실에 대해 말하는 사람이 먼저 자기 감정(놀람·기쁨·유감 등)을 밝히는 표현이다. 앞에는 驚く・困る・うれしい・残念だ・不思議だ 같은 감정어만 온다. 뒤에는 사실이 오며 명령·의뢰는 오지 않는다. 문어적이다. '~ことに驚いた(~한 것에 놀랐다)'의 조사 に와는 다른 문형이다.","cmp":[{"g":"～ことに + 감정 동사","d":"彼が来たことに驚いた처럼 こと가 목적어이고 に는 감정의 대상을 나타내는 조사다. 문형 ことに는 문장 앞에서 감정을 먼저 말한다."}],"ex":[{"jp":"驚[おどろ]いたことに、彼[かれ]は一人[ひとり]でその山[やま]に登[のぼ]ったそうだ。","ko":"놀랍게도 그는 혼자서 그 산에 올랐다고 한다."},{"jp":"残念[ざんねん]なことに、雨[あめ]で花火大会[はなびたいかい]は中止[ちゅうし]になった。","ko":"유감스럽게도 비 때문에 불꽃놀이 대회는 취소되었다."},{"jp":"うれしいことに、母[はは]の病気[びょうき]がすっかり治[なお]った。","ko":"기쁘게도 어머니의 병이 완전히 나았다."}],"dr":[{"t":"make","q":"困る → ～ことに","a":"困ったことに","hint":"る를 った로 바꾼 た형 + ことに"},{"t":"make","q":"不思議だ → ～ことに","a":"不思議なことに","hint":"な형용사는 な + ことに"},{"t":"fill","q":"ありがたい（　）、たくさんの人[ひと]が手伝[てつだ]ってくれた。","a":"ことに","opts":["ことに","ことから","ことなく","ことだから"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%93%E3%81%A8%E3%81%AB","https://jlptsensei.com/learn-japanese-grammar/ことに-koto-ni-meaning/"],"vf":1,"u":25,"g":1,"gp":"gg_N2_10"},{"id":"g2_073","t":"～だらけ","ko":"~투성이","cat":"강조·한정","conn":[{"w":"명사","f":"泥 + だらけ"},{"w":"명사","f":"間違い + だらけ"},{"w":"명사","f":"ゴミ + だらけ"}],"rule":["1. 명사 뒤에 だらけ를 바로 붙인다(泥 → 泥だらけ).","2. 활용은 명사와 같다: 서술은 泥だらけだ, 수식은 泥だらけの靴, 변화는 泥だらけになる."],"why":"","nu":"좋지 않은 것이 온통 퍼져 있거나 표면을 뒤덮고 있음을 나타내며, 말하는 사람의 불쾌함이나 부정적 평가가 담긴다. 좋은 것에는 보통 쓰지 않는다(꽃이 가득한 것은 花でいっぱい). 회화와 글 모두 쓴다.","cmp":[{"g":"～まみれ","d":"まみれ는 땀·피·기름·흙처럼 액체나 가루가 몸 표면에 들러붙은 상태에만 쓴다. だらけ는 間違いだらけ처럼 수가 많은 것에도 쓴다."}],"ex":[{"jp":"子[こ]どもたちは泥[どろ]だらけになって遊[あそ]んでいる。","ko":"아이들은 진흙투성이가 되어 놀고 있다."},{"jp":"この作文[さくぶん]は間違[まちが]いだらけだ。","ko":"이 작문은 틀린 곳투성이다."},{"jp":"ゴミだらけの部屋[へや]を片付[かたづ]けた。","ko":"쓰레기투성이인 방을 정리했다."}],"dr":[{"t":"make","q":"傷 → ～だらけ","a":"傷だらけ","hint":"명사 + だらけ"},{"t":"make","q":"ほこり → ～だらけの部屋","a":"ほこりだらけの部屋","hint":"명사 + だらけ + の + 명사"},{"t":"fill","q":"雨[あめ]の中[なか]でサッカーをして、服[ふく]が泥[どろ]（　）になった。","a":"だらけ","opts":["だらけ","ぎみ","がち","げ"]}],"src":["https://guidetojapanese.org/learn/grammar/covered"],"vf":1,"u":25,"g":1,"gp":"gg_N2_10"},{"id":"g2_080","t":"～てかなわない","ko":"~해서 견딜 수 없다, 너무 ~하다","cat":"강조·한정","conn":[{"w":"い형용사","f":"うるさくて + かなわない"},{"w":"な형용사","f":"不便で + かなわない"},{"w":"동사 て형","f":"腹が立って + かなわない"}],"rule":["1. い형용사 うるさい는 끝의 い를 く로 바꾼다(うるさく).","2. 그 뒤에 て를 붙여 うるさくて를 만든다.","3. 마지막에 かなわない를 붙인다(うるさくてかなわない). な형용사는 だ를 で로 바꿔 붙인다(不便でかなわない)."],"why":"かなわない는 '당해 내다'라는 뜻의 かなう(敵う)의 부정형이다.","nu":"참을 수 없을 만큼 불쾌하거나 괴롭다는 말하는 사람의 느낌을 나타낸다. 더위·소음·불편함처럼 싫은 것에만 쓰고, 좋은 감정에는 쓰지 않는다. 주로 1인칭의 느낌이며 회화에서 쓴다.","cmp":[{"g":"～てたまらない","d":"てたまらない는 好きでたまらない처럼 좋은 감정에도 쓴다. てかなわない는 불쾌한 것에만 쓴다."}],"ex":[{"jp":"隣[となり]の工事[こうじ]がうるさくてかなわない。","ko":"옆집 공사가 시끄러워서 견딜 수가 없다."},{"jp":"この町[まち]はバスが少[すく]なくて、不便[ふべん]でかなわない。","ko":"이 동네는 버스가 적어서 불편해서 못 견디겠다."},{"jp":"彼[かれ]の自慢話[じまんばなし]を聞[き]くと、腹[はら]が立[た]ってかなわない。","ko":"그의 자랑을 들으면 화가 나서 견딜 수 없다."}],"dr":[{"t":"make","q":"暑い → ～てかなわない","a":"暑くてかなわない","hint":"い를 くて로 바꾸고 + かなわない"},{"t":"make","q":"不便だ → ～てかなわない","a":"不便でかなわない","hint":"な형용사는 だ를 で로 바꾸고 + かなわない"},{"t":"fill","q":"夏[なつ]の東京[とうきょう]は蒸[む]し暑[あつ]くて（　）。","a":"かなわない","opts":["かなわない","ばかりだ","ものだ","ことだ"]}],"src":["https://bunpro.jp/grammar_points/947","https://jlptsensei.com/learn-japanese-grammar/て敵わない-てかなわない-te-kanawanai-meaning/"],"vf":1,"u":25,"g":1,"gp":"gg_N2_10"},{"id":"g2_082","t":"～てこそ","ko":"~해야 비로소","cat":"강조·한정","conn":[{"w":"동사 て형(1그룹)","f":"登って + こそ"},{"w":"동사 て형(2그룹)","f":"続けて + こそ"},{"w":"동사 て형(する)","f":"経験して + こそ"}],"rule":["1. 1그룹 동사 登る는 어미 る를 촉음 っ로 바꾸고 て를 붙여 て형 登って를 만든다.","2. て형 뒤에 こそ를 붙인다(登ってこそ).","3. 뒤에는 그렇게 해야 비로소 얻어지는 긍정적 결과나 가치가 온다."],"why":"동사 て형 뒤에 앞말을 강하게 내세우는 조사 こそ가 붙은 형태다.","nu":"'그 일을 해야만 비로소 참된 결과·가치가 생긴다'고 강조한다. 뒤에는 分かる·意味がある·価値がある 같은 긍정적 평가가 오며, 나쁜 결과에는 쓰지 않는다. 연설이나 격언처럼 다소 딱딱한 표현이다.","cmp":[{"g":"～てはじめて","d":"てはじめて는 그 일을 계기로 처음 무엇이 실현되었다는 사실을 말한다. てこそ는 그 조건이 반드시 필요하다는 말하는 사람의 판단을 강조한다."}],"ex":[{"jp":"自分[じぶん]の足[あし]で登[のぼ]ってこそ、頂上[ちょうじょう]の景色[けしき]が美[うつく]しく感[かん]じられる。","ko":"자기 발로 올라가야 비로소 정상의 경치가 아름답게 느껴진다."},{"jp":"勉強[べんきょう]は毎日[まいにち]続[つづ]けてこそ意味[いみ]がある。","ko":"공부는 매일 계속해야 의미가 있다."},{"jp":"自分[じぶん]で経験[けいけん]してこそ、その大変[たいへん]さが分[わ]かる。","ko":"직접 경험해 봐야 비로소 그 힘듦을 안다."}],"dr":[{"t":"make","q":"努力する → ～てこそ","a":"努力してこそ","hint":"する는 して + こそ"},{"t":"make","q":"続ける → ～てこそ","a":"続けてこそ","hint":"2그룹은 る를 떼고 て + こそ"},{"t":"fill","q":"練習[れんしゅう]を重[かさ]ねて（　）、本番[ほんばん]で力[ちから]が出[だ]せる。","a":"こそ","opts":["こそ","ばかり","まで","しか"]}],"src":["https://bunpro.jp/grammar_points/352"],"vf":1,"u":25,"g":1,"gp":"gg_N2_10"},{"id":"g2_083","t":"～でしょうがない","ko":"~해서 어쩔 수 없다, 너무 ~하다","cat":"강조·한정","conn":[{"w":"な형용사","f":"心配で + しょうがない"},{"w":"い형용사","f":"眠くて + しょうがない"},{"w":"동사 て형","f":"気になって + しょうがない"},{"w":"たい형","f":"会いたくて + しょうがない"}],"rule":["1. な형용사 心配だ는 끝의 だ를 で로 바꾼다(心配で).","2. 그 뒤에 しょうがない를 붙인다(心配でしょうがない).","3. い형용사는 い를 くて로(眠くてしょうがない), 동사는 て형으로(気になってしょうがない) 바꿔 붙인다."],"why":"しょうがない는 しようがない(할 방법이 없다)가 줄어든 말이다.","nu":"감정·감각·욕구가 너무 강해서 스스로 어쩔 수 없다는 뜻이다. 말하는 사람 자신의 느낌에 쓰고, 남의 느낌에는 ～ようだ·～らしい를 붙인다. 회화체이며 조금 격식 있게는 ～てしかたがない라고 한다.","cmp":[{"g":"～てたまらない","d":"뜻은 거의 같다. 둘 다 회화에서 강한 감정·감각을 말할 때 쓴다."},{"g":"～てならない","d":"てならない는 더 문어적이며 気がする·思える처럼 저절로 드는 느낌에 잘 쓴다."}],"ex":[{"jp":"試験[しけん]の結果[けっか]が心配[しんぱい]でしょうがない。","ko":"시험 결과가 걱정돼서 어쩔 수가 없다."},{"jp":"昨日[きのう]あまり寝[ね]ていないので、眠[ねむ]くてしょうがない。","ko":"어제 별로 못 자서 너무 졸리다."},{"jp":"彼女[かのじょ]の言葉[ことば]が気[き]になってしょうがない。","ko":"그녀의 말이 신경 쓰여서 견딜 수 없다."}],"dr":[{"t":"make","q":"退屈だ → ～でしょうがない","a":"退屈でしょうがない","hint":"な형용사는 だ를 で로 바꾸고 + しょうがない"},{"t":"make","q":"痛い → ～てしょうがない","a":"痛くてしょうがない","hint":"い를 くて로 바꾸고 + しょうがない"},{"t":"fill","q":"一人[ひとり]で留学[りゅうがく]している娘[むすめ]のことが心配[しんぱい]で（　）。","a":"しょうがない","opts":["しょうがない","ほかない","わけだ","ことだ"]}],"src":["https://bunpro.jp/grammar_points/432"],"vf":1,"u":25,"g":1,"gp":"gg_N2_10"},{"id":"g2_084","t":"～でたまらない","ko":"~해서 견딜 수 없다, 너무너무 ~하다","cat":"강조·한정","conn":[{"w":"な형용사","f":"好きで + たまらない"},{"w":"い형용사","f":"暑くて + たまらない"},{"w":"たい형","f":"会いたくて + たまらない"},{"w":"동사 て형","f":"気になって + たまらない"}],"rule":["1. な형용사 好きだ는 끝의 だ를 で로 바꾼다(好きで).","2. 그 뒤에 たまらない를 붙인다(好きでたまらない).","3. い형용사는 い를 くて로(暑くてたまらない), 동사는 て형으로(気になってたまらない) 바꿔 붙인다."],"why":"たまらない는 '견디다'라는 뜻의 たまる(堪る)의 부정형이다.","nu":"감정이나 몸의 감각이 견딜 수 없을 만큼 강하다는 뜻으로, 好き·うれしい 같은 좋은 감정에도 寂しい·痛い 같은 괴로운 느낌에도 쓴다. 말하는 사람 자신의 느낌에 쓰고, 남의 느낌에는 ～ようだ·～らしい를 붙인다.","cmp":[{"g":"～てかなわない","d":"てかなわない는 불쾌한 것에만 쓴다. てたまらない는 좋은 감정에도 쓸 수 있다."}],"ex":[{"jp":"この子犬[こいぬ]が好[す]きでたまらない。","ko":"이 강아지가 좋아서 견딜 수가 없다."},{"jp":"今日[きょう]は暑[あつ]くてたまらない。","ko":"오늘은 너무 더워서 못 견디겠다."},{"jp":"国[くに]の家族[かぞく]に会[あ]いたくてたまらない。","ko":"고향의 가족이 보고 싶어서 견딜 수 없다."}],"dr":[{"t":"make","q":"残念だ → ～でたまらない","a":"残念でたまらない","hint":"な형용사는 だ를 で로 바꾸고 + たまらない"},{"t":"make","q":"寂しい → ～てたまらない","a":"寂しくてたまらない","hint":"い를 くて로 바꾸고 + たまらない"},{"t":"fill","q":"合格[ごうかく]の知[し]らせを聞[き]いて、うれしくて（　）。","a":"たまらない","opts":["たまらない","ほかない","わけだ","ことだ"]}],"src":["https://bunpro.jp/grammar_points/411"],"vf":1,"u":25,"g":1,"gp":"gg_N2_10"},{"id":"g2_089","t":"～てまで","ko":"~하면서까지","cat":"강조·한정","conn":[{"w":"동사 て형(1그룹)","f":"並ぶ → 並んで + まで"},{"w":"동사 て형(2그룹)","f":"借りる → 借りて + まで"},{"w":"する","f":"借金する → 借金して + まで"}],"rule":["1. 동사를 て형으로 만든다. 並ぶ → 並んで(ぶ를 んで로).","2. 그 뒤에 まで를 붙인다(並んでまで).","3. 뒤에는 그런 극단적인 수단으로 이루려는 목적이나, 그것에 대한 판단이 온다."],"why":"","nu":"어떤 목적을 위해 보통은 하지 않는 극단적인 수단까지 쓴다는 뜻이다. 뒤에 ～たくない, ～必要はない, ～とは思わない처럼 그런 수단은 지나치다는 부정적 판단이 자주 온다. 남의 행동에 쓰면 놀람이나 비판의 느낌이 생긴다.","cmp":[{"g":"명사 + までして","d":"借金までして처럼 명사에 붙는 형태로 뜻은 같다. ～てまで는 동사 て형에 붙는다."}],"ex":[{"jp":"借金[しゃっきん]してまで車[くるま]を買[か]いたくない。","ko":"빚을 내면서까지 차를 사고 싶지는 않다."},{"jp":"彼[かれ]は徹夜[てつや]してまで準備[じゅんび]を終[お]わらせた。","ko":"그는 밤을 새우면서까지 준비를 끝냈다."},{"jp":"友達[ともだち]に嘘[うそ]をついてまで行[い]きたいとは思[おも]わない。","ko":"친구에게 거짓말을 하면서까지 가고 싶지는 않다."}],"dr":[{"t":"make","q":"並ぶ → ～てまで","a":"並んでまで","hint":"ぶ를 んで로 바꾼 て형 + まで"},{"t":"make","q":"借りる → ～てまで","a":"借りてまで","hint":"2그룹: る를 떼고 て + まで"},{"t":"fill","q":"体[からだ]を壊[こわ]して（　）働[はたら]く必要[ひつよう]はない。","a":"まで","opts":["まで","ほど","こそ","ばかり"]}],"src":["https://www.gyanmirai.com/jlpt/jlpt-n2/grammar-study/temade"],"vf":1,"u":26,"g":1,"gp":"gg_N2_10"},{"id":"g2_109","t":"～にかけては","ko":"~에 있어서는, ~에 관해서라면 (자신 있다)","cat":"강조·한정","conn":[{"w":"명사","f":"料理 + にかけては"},{"w":"명사(능력·분야)","f":"足の速さ + にかけては"}],"rule":["1. 능력이나 분야를 나타내는 명사 뒤에 그대로 にかけては를 붙인다. 料理 → 料理にかけては.","2. 뒤에는 '누구에게도 지지 않는다, 제일이다' 같은 높은 평가가 온다.","3. 강조할 때는 にかけても(~에 있어서도)라고도 한다."],"why":"","nu":"어떤 사람이 특정 분야나 능력에서 뛰어나다는 것을 말할 때 쓰며, 뒤에는 誰にも負けない・一番だ・自信がある 같은 긍정적인 평가가 온다. 장소나 가게의 맛처럼 능력과 관계없는 내용(×この町にかけては、この店のラーメンが一番だ)에는 어울리지 않는다. 부정적인 평가에는 잘 쓰지 않는다. 회화와 글 모두에서 쓴다.","cmp":[{"g":"～に関しては","d":"단순히 '~에 관해서는'이라는 화제 제시로, 뒤에 평가가 오지 않아도 된다."},{"g":"～にとって","d":"'~의 입장에서 보면'이라는 판단 기준이다. にかけては는 뛰어난 분야를 나타낸다."}],"ex":[{"jp":"料理[りょうり]の腕[うで]にかけては、母[はは]はだれにも負[ま]けない。","ko":"요리 솜씨에 있어서는 어머니는 누구에게도 지지 않는다."},{"jp":"足[あし]の速[はや]さにかけては、彼[かれ]がクラスで一番[いちばん]だ。","ko":"발 빠르기에 관해서라면 그가 반에서 제일이다."},{"jp":"パソコンの知識[ちしき]にかけては、自信[じしん]があります。","ko":"컴퓨터 지식에 있어서는 자신이 있습니다."}],"dr":[{"t":"make","q":"歌 → ～にかけては","a":"歌にかけては","hint":"명사 뒤에 그대로 にかけては"},{"t":"make","q":"数学 → ～にかけては","a":"数学にかけては","hint":"분야 명사 + にかけては"},{"t":"fill","q":"ピアノ（　）、彼女[かのじょ]の右[みぎ]に出[で]る人[ひと]はいない。","a":"にかけては","opts":["にかけては","にあたり","にもかかわらず","にわたって"]}],"src":["https://bunpro.jp/grammar_points/579"],"vf":1,"u":26,"g":1,"gp":"gg_N2_10"},{"id":"g2_116","t":"～にほかならない","ko":"바로 ~이다, ~에 다름 아니다","cat":"강조·한정","conn":[{"w":"명사","f":"努力 + にほかならない"},{"w":"명사(の結果)","f":"努力の結果 + にほかならない"},{"w":"이유절 + から","f":"愛している + から + にほかならない"}],"rule":["1. 명사 뒤에 그대로 にほかならない를 붙인다. 努力 → 努力にほかならない.","2. 이유를 강조할 때는 보통형 + から 뒤에 붙인다. 心配しているから → 心配しているからにほかならない.","3. 문장은 'AはBにほかならない(A는 바로 B이다)'의 형태가 된다."],"why":"조사 に + ほか(他, 그 밖) + ならない(なる의 부정)로, '~ 이외의 것이 되지 않는다 → 바로 ~이다'라는 뜻이 된다.","nu":"'다른 것이 아니라 바로 그것이다'라고 단정하는 강한 표현이다. 원인·본질·의미를 말할 때 많이 쓰며, 논문·연설·사설 같은 딱딱한 글에 주로 나온다. 일상 회화에서는 지나치게 딱딱하다. 단순한 사실 확인(×これはペンにほかならない)처럼 굳이 강조할 필요가 없는 내용에는 어울리지 않는다.","cmp":[{"g":"～にすぎない","d":"'~에 지나지 않는다'로 정도가 낮거나 별것 아님을 말한다. にほかならない는 바로 그것이라고 강조한다."},{"g":"～にちがいない","d":"'~임에 틀림없다'라는 확신 있는 추측이다. にほかならない는 추측이 아니라 단정이다."}],"ex":[{"jp":"彼[かれ]の成功[せいこう]は、毎日[まいにち]の努力[どりょく]の結果[けっか]にほかならない。","ko":"그의 성공은 바로 매일의 노력의 결과이다."},{"jp":"親[おや]が厳[きび]しく言[い]うのは、子[こ]どもを心配[しんぱい]しているからにほかならない。","ko":"부모가 엄하게 말하는 것은 바로 아이를 걱정하기 때문이다."},{"jp":"この事故[じこ]の原因[げんいん]は、運転手[うんてんしゅ]の不注意[ふちゅうい]にほかならない。","ko":"이 사고의 원인은 다름 아닌 운전자의 부주의이다."}],"dr":[{"t":"make","q":"愛情 → ～にほかならない","a":"愛情にほかならない","hint":"명사 뒤에 그대로 にほかならない"},{"t":"make","q":"期待しているから → ～にほかならない","a":"期待しているからにほかならない","hint":"보통형 + から + にほかならない"},{"t":"fill","q":"この勝利[しょうり]は、チーム全員[ぜんいん]の協力[きょうりょく]の結果[けっか]（　）。","a":"にほかならない","opts":["にほかならない","にすぎない","にわたって","にともなって"]}],"src":["https://bunpro.jp/grammar_points/538"],"vf":1,"u":26,"g":1,"gp":"gg_N2_11"},{"id":"g2_128","t":"～に過ぎない","ko":"~에 불과하다, ~일 뿐이다","cat":"강조·한정","conn":[{"w":"명사","f":"猫 + に過ぎない"},{"w":"동사 보통형","f":"言った + に過ぎない"}],"rule":["1. 2그룹 동사 過ぎる의 어미 る를 뗀다.","2. 남은 過ぎ 뒤에 부정 ない를 붙여 過ぎない를 만든다(る → ない).","3. 명사 또는 동사 보통형 뒤에 に過ぎない를 붙인다."],"why":"","nu":"'그 이상은 아니다, 대단한 것이 아니다'라고 정도를 낮춰 평가하는 표현이다. 문어적이고 딱딱하며 회화에서는 ただの～だ, ～だけだ가 자연스럽다. 정중형은 に過ぎません. 수량 명사와 함께 '겨우 ~'의 뜻으로도 자주 쓴다(参加者は十人に過ぎない).","cmp":[{"g":"～だけだ","d":"だけだ는 한정만 나타내는 일상 표현이다. に過ぎない는 '하찮다, 별것 아니다'는 평가가 더해진 문어 표현이다."}],"ex":[{"jp":"怖[こわ]い影[かげ]だと思[おも]ったら、小[ちい]さな猫[ねこ]に過[す]ぎなかった。","ko":"무서운 그림자인 줄 알았더니 작은 고양이에 불과했다."},{"jp":"それは噂[うわさ]に過[す]ぎないから、信[しん]じないほうがいい。","ko":"그건 소문에 불과하니까 믿지 않는 게 좋다."},{"jp":"私[わたし]は思[おも]ったことを言[い]ったに過[す]ぎません。","ko":"저는 생각한 것을 말했을 뿐입니다."}],"dr":[{"t":"make","q":"冗談 → ～に過ぎない","a":"冗談に過ぎない","hint":"명사 + に + 過ぎない(過ぎる의 る를 떼고 ない)"},{"t":"make","q":"手伝った → ～に過ぎない","a":"手伝ったに過ぎない","hint":"동사 보통형 그대로 + に過ぎない"},{"t":"fill","q":"この会社[かいしゃ]の社員[しゃいん]は、まだ十人[じゅうにん]（　）。","a":"に過ぎない","opts":["に過ぎない","に決まっている","に沿って","に際して"]}],"src":["https://bunpro.jp/grammar_points/330"],"vf":1,"u":26,"g":1,"gp":"gg_N2_11"},{"id":"g2_130","t":"～に限り","ko":"~에 한하여, ~만","cat":"강조·한정","conn":[{"w":"명사","f":"今日 + に限り"},{"w":"수량 명사","f":"先着十名 + に限り"}],"rule":["1. 1그룹 동사 限る(한정하다)의 어미 る를 り로 바꾼다(연용형).","2. 앞의 명사에 に를 붙여 명사 + に限り로 쓴다."],"why":"","nu":"가게 안내문・공지 등에서 '그 조건에 해당하는 경우에만' 특별한 대우가 있음을 알리는 격식 있는 표현이다. 회화에서는 ～だけ가 자연스럽다. 今日に限って(하필 오늘따라)와는 뜻이 다르니 주의.","cmp":[{"g":"～に限って","d":"に限って는 '하필 그때만(나쁜 일이)' 또는 '~만은 절대(그럴 리 없다)'라는 뜻이다. に限り는 '~에 한해서 (특별 혜택)'이라는 한정이다."}],"ex":[{"jp":"本日[ほんじつ]に限[かぎ]り、全品[ぜんぴん]半額[はんがく]です。","ko":"오늘에 한해 전 상품 반값입니다."},{"jp":"会員[かいいん]に限[かぎ]り、無料[むりょう]で利用[りよう]できます。","ko":"회원에 한해 무료로 이용할 수 있습니다."},{"jp":"先着[せんちゃく]十名様[じゅうめいさま]に限[かぎ]り、プレゼントを差[さ]し上[あ]げます。","ko":"선착순 10분에 한해 선물을 드립니다."}],"dr":[{"t":"make","q":"学生 → ～に限り","a":"学生に限り","hint":"限る의 る를 り로 바꿔 명사 + に 뒤에"},{"t":"make","q":"雨の日 → ～に限り","a":"雨の日に限り","hint":"명사 + に + 限り"},{"t":"fill","q":"このクーポンは、初[はじ]めてのお客様[きゃくさま]（　）ご利用[りよう]いただけます。","a":"に限り","opts":["に限り","に反して","に過ぎず","に沿って"]}],"src":[],"vf":0,"u":26,"g":1,"gp":"gg_N2_11"},{"id":"g2_133","t":"～のみならず～も","ko":"~뿐만 아니라 ~도","cat":"강조·한정","conn":[{"w":"명사","f":"英語 + のみならず"},{"w":"동사 보통형","f":"話せる + のみならず"},{"w":"い형용사","f":"安い + のみならず"},{"w":"な형용사·명사 + である","f":"便利である + のみならず"}],"rule":["1. 앞에 오는 말 뒤에 のみならず를 붙인다. 명사는 바로 붙인다(英語のみならず).","2. 동사・い형용사는 보통형 그대로 붙인다(安いのみならず).","3. な형용사는 である를 넣어 붙인다(便利であるのみならず).","4. 뒤에 오는 말에 も를 붙여 '그것도 또한'임을 나타낸다(数学も)."],"why":"のみ(~만) + ならず(なる의 옛 부정형)로, '~만으로 그치지 않고'라는 뜻이다.","nu":"だけでなく・ばかりでなく의 문어・격식 표현이다. 글・연설・뉴스에서 쓰며 일상 회화에서는 だけじゃなく가 자연스럽다. 뒤에 も・まで 등이 짝으로 자주 온다. な형용사에 바로 붙여 便利のみならず로 쓰는 것은 부자연스럽다.","cmp":[{"g":"～ばかりか","d":"ばかりか는 '그뿐 아니라 (놀랍게도) 더한 것까지'라는 의외・놀람의 느낌이 강하다. のみならず는 범위가 넓어짐을 담담하게 말하는 문어 표현이다."}],"ex":[{"jp":"彼[かれ]は英語[えいご]のみならず、数学[すうがく]も得意[とくい]だ。","ko":"그는 영어뿐만 아니라 수학도 잘한다."},{"jp":"この店[みせ]は安[やす]いのみならず、サービスもいい。","ko":"이 가게는 쌀 뿐만 아니라 서비스도 좋다."},{"jp":"この問題[もんだい]は日本[にほん]のみならず、世界中[せかいじゅう]で注目[ちゅうもく]されている。","ko":"이 문제는 일본뿐만 아니라 전 세계에서 주목받고 있다."}],"dr":[{"t":"make","q":"学生 / 先生 → ～のみならず～も","a":"学生のみならず先生も","hint":"명사 + のみならず, 뒤 명사 + も"},{"t":"make","q":"静かだ → ～のみならず","a":"静かであるのみならず","hint":"な형용사는 である + のみならず"},{"t":"fill","q":"この祭[まつ]りには、地元[じもと]の人[ひと]（　）、外国人[がいこくじん]観光客[かんこうきゃく]も大勢[おおぜい]来[く]る。","a":"のみならず","opts":["のみならず","に限り","に過ぎず","に反して"]}],"src":["https://bunpro.jp/grammar_points/601"],"vf":1,"u":27,"g":1,"gp":"gg_N2_11"},{"id":"g2_137","t":"～ばかりか～も","ko":"~뿐만 아니라 ~도","cat":"강조·한정","conn":[{"w":"동사 보통형","f":"遅れる + ばかりか"},{"w":"い형용사","f":"安い + ばかりか"},{"w":"な형용사","f":"上手な + ばかりか"},{"w":"명사","f":"子ども + ばかりか"}],"rule":["1. 동사・い형용사는 보통형 그대로 뒤에 ばかりか를 붙인다(安いばかりか).","2. な형용사는 な를 넣어 붙이고(上手なばかりか), 명사는 바로 붙인다(子どもばかりか).","3. 뒤 문장의 말에 も(또는 まで・さえ)를 붙여 '그것도 또한'을 나타낸다(味もいい)."],"why":"ばかり(~만) + か로, '~만이겠는가 (그뿐이 아니다)'라는 뜻에서 온 것이다.","nu":"앞의 일만으로도 충분한데 그 위에 더 정도가 심한 일이 더해진다는 놀라움・강조가 있다. 좋은 일, 나쁜 일 모두 쓴다. 뒤에 명령・의뢰・권유・의지 표현은 올 수 없다(× 野菜ばかりか肉も食べなさい). 그럴 때는 だけでなく를 쓴다.","cmp":[{"g":"～だけでなく","d":"だけでなく는 단순 추가로 회화에서 두루 쓰고 뒤에 명령・의뢰도 올 수 있다. ばかりか는 놀라움・강조가 있고 뒤에 명령・의뢰가 올 수 없다."}],"ex":[{"jp":"この店[みせ]は安[やす]いばかりか、味[あじ]もいい。","ko":"이 가게는 쌀 뿐만 아니라 맛도 좋다."},{"jp":"彼[かれ]は遅刻[ちこく]したばかりか、宿題[しゅくだい]も忘[わす]れてきた。","ko":"그는 지각했을 뿐만 아니라 숙제도 잊고 왔다."},{"jp":"このゲームは子[こ]どもばかりか、大人[おとな]にも人気[にんき]がある。","ko":"이 게임은 아이들뿐만 아니라 어른들에게도 인기가 있다."}],"dr":[{"t":"make","q":"きれいだ → ～ばかりか","a":"きれいなばかりか","hint":"な형용사는 だ를 な로 바꾸고 ばかりか"},{"t":"make","q":"雨が降った → ～ばかりか","a":"雨が降ったばかりか","hint":"동사 보통형(た형) 그대로 + ばかりか"},{"t":"fill","q":"彼女[かのじょ]は英語[えいご]（　）、フランス語[ご]も話[はな]せる。","a":"ばかりか","opts":["ばかりか","ばかりだ","に過ぎず","の上では"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ばかりか-bakari-ka-meaning","https://bunpro.jp/grammar_points/255"],"vf":1,"u":27,"g":1,"gp":"gg_N2_11"},{"id":"g2_141","t":"～はともかく","ko":"~은 어쨌든, ~은 제쳐 두고","cat":"강조·한정","conn":[{"w":"명사","f":"味 + はともかく"},{"w":"의문사절","f":"できるかどうか + はともかく"}],"rule":["1. 제쳐 둘 명사 A 뒤에 はともかく를 붙인다(味はともかく).","2. 이어서 정말 말하고 싶은 명사 B를 は로 제시한다(値段は).","3. B에 대한 평가를 말한다(味はともかく、値段は安い)."],"why":"","nu":"A는 지금 문제 삼지 않고, 그보다 B가 중요하다(B에 대해서 말하겠다)는 뜻이다. A가 좋은지 나쁜지는 판단을 보류한다. 회화와 문장 모두에 쓴다. ～はともかくとして로도 쓴다. A와 B는 같은 종류의 화제(맛과 가격 등)가 온다.","cmp":[{"g":"～はもとより","d":"はもとより는 A는 당연하고 B도 그렇다는 '추가'이고, はともかく는 A는 제쳐 두고 B를 말하는 '보류·초점 이동'이다."}],"ex":[{"jp":"この店[みせ]は味[あじ]はともかく、値段[ねだん]は安[やす]い。","ko":"이 가게는 맛은 어쨌든 가격은 싸다."},{"jp":"結果[けっか]はともかく、最後[さいご]まで頑張[がんば]ったことが大切[たいせつ]だ。","ko":"결과는 제쳐 두고, 끝까지 열심히 한 것이 중요하다."},{"jp":"できるかどうかはともかく、一度[いちど]やってみよう。","ko":"할 수 있을지 없을지는 차치하고 한번 해 보자."}],"dr":[{"t":"make","q":"デザイン / 機能はいい → ～はともかく","a":"デザインはともかく、機能はいい","hint":"제쳐 둘 명사 + はともかく + 초점 명사 + は"},{"t":"make","q":"見た目 / 味はおいしい → ～はともかく","a":"見た目はともかく、味はおいしい","hint":"명사 + はともかく, 뒤 명사 + は"},{"t":"fill","q":"値段[ねだん]（　）、品質[ひんしつ]はとてもいい。","a":"はともかく","opts":["はともかく","に比べて","によって","にとって"]}],"src":["https://nihongokyoshi-net.com/2019/02/22/jlptn2-grammar-tomokakutoshite/"],"vf":1,"u":27,"g":1,"gp":"gg_N2_11"},{"id":"g2_143","t":"～はもとより","ko":"~은 물론이고","cat":"강조·한정","conn":[{"w":"명사","f":"大人 + はもとより"}],"rule":["1. 당연한 명사 A 뒤에 はもとより를 붙인다(大人はもとより).","2. 이어서 추가하는 명사 B 뒤에 も를 붙인다(子供も).","3. 끝에 둘 다 해당하는 내용을 쓴다(大人はもとより、子供も楽しめる)."],"why":"もとより(元より)는 '원래부터, 물론'이라는 뜻의 부사다.","nu":"A는 말할 필요도 없이 당연하고, B까지도 그렇다는 뜻이다. はもちろん과 같은 의미지만 더 딱딱하고 격식 있는 표현으로 문장·연설·안내문에 많이 쓴다. B 뒤에는 보통 も나 まで가 온다. 일상 회화에서는 はもちろん이 자연스럽다.","cmp":[{"g":"～はもちろん","d":"의미는 거의 같지만 はもちろん은 회화·문장 모두에 쓰고, はもとより는 격식 있는 문어체다."}],"ex":[{"jp":"この公園[こうえん]は大人[おとな]はもとより、子供[こども]も楽[たの]しめる。","ko":"이 공원은 어른은 물론이고 아이도 즐길 수 있다."},{"jp":"彼女[かのじょ]は英語[えいご]はもとより、中国語[ちゅうごくご]も話[はな]せる。","ko":"그녀는 영어는 물론이고 중국어도 할 줄 안다."},{"jp":"この店[みせ]は味[あじ]はもとより、サービスもすばらしい。","ko":"이 가게는 맛은 물론이고 서비스도 훌륭하다."}],"dr":[{"t":"make","q":"平日 / 週末も混む → ～はもとより","a":"平日はもとより、週末も混む","hint":"당연한 명사 + はもとより + 추가 명사 + も"},{"t":"make","q":"日本 / 海外でも人気だ → ～はもとより","a":"日本はもとより、海外でも人気だ","hint":"명사 + はもとより, 뒤에 も"},{"t":"fill","q":"この歌[うた]は若者[わかもの]（　）、お年寄[としよ]りにも人気[にんき]がある。","a":"はもとより","opts":["はもとより","はともかく","はまだしも","にかわって"]}],"src":["https://bunpro.jp/grammar_points/611"],"vf":1,"u":27,"g":1,"gp":"gg_N2_11"},{"id":"g2_147","t":"～てまで・～までして","ko":"~하면서까지","cat":"강조·한정","conn":[{"w":"동사 て형","f":"並んで + まで"},{"w":"명사","f":"借金 + までして"}],"rule":["1. 동사를 て형으로 만든다. 1그룹 ぶ로 끝나는 동사는 ぶ를 んで로 바꾼다(並ぶ → 並んで).","2. 그 뒤에 まで를 붙인다(並んでまで).","3. 명사는 までして를 붙인다(借金までして)."],"why":"","nu":"목적을 위해 보통은 하지 않는 극단적인 수단까지 쓴다는 뜻이다. 뒤에 '~하고 싶지 않다', '~할 필요는 없다'처럼 부정이나 비난이 오는 경우가 많다. 긍정문에서는 그만큼 열의가 크다는 느낌을 준다. 단순히 시간·장소의 '~까지'(9時まで)와는 다르다.","cmp":[{"g":"～てでも","d":"てでも는 '어떤 수단을 써서라도 하겠다'는 강한 의지이고, てまで는 그 수단이 지나치다는 평가가 담기는 경우가 많다."}],"ex":[{"jp":"一時間[いちじかん]も並[なら]んでまで食[た]べたいとは思[おも]わない。","ko":"한 시간이나 줄 서면서까지 먹고 싶지는 않다."},{"jp":"友達[ともだち]をだましてまでお金[かね]がほしいのか。","ko":"친구를 속이면서까지 돈이 갖고 싶은 거야?"},{"jp":"彼[かれ]は借金[しゃっきん]までして車[くるま]を買[か]った。","ko":"그는 빚까지 내서 차를 샀다."}],"dr":[{"t":"make","q":"休む → ～てまで","a":"休んでまで","hint":"む를 んで로 바꾼 て형 + まで"},{"t":"make","q":"うそ → ～までして","a":"うそまでして","hint":"명사 + までして"},{"t":"fill","q":"体[からだ]を壊[こわ]して（　）働[はたら]く必要[ひつよう]はない。","a":"まで","opts":["まで","から","ばかり","だけ"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/てまで-te-made-meaning/"],"vf":1,"u":27,"g":1,"gp":"gg_N2_11"},{"id":"g2_164","t":"～わけではない","ko":"(꼭) ~인 것은 아니다","cat":"강조·한정","conn":[{"w":"동사 보통형","f":"走る + わけではない"},{"w":"い형용사","f":"高い + わけではない"},{"w":"な형용사","f":"嫌いな + わけではない"},{"w":"명사","f":"学生という + わけではない"}],"rule":["1. 동사·い형용사는 보통형 그대로 둔다. 毎日走る.","2. 그 뒤에 わけではない를 붙인다. 毎日走るわけではない.","3. な형용사는 な를 넣는다(嫌いなわけではない). 명사는 という를 넣어 말하는 경우가 많다(学生というわけではない)."],"why":"","nu":"전부 부정이 아니라 '꼭 그런 것은 아니다'라는 부분 부정·완곡한 부정이다. 毎日・いつも・全部・必ずしも와 함께 잘 쓴다. 회화에서는 わけじゃない라고 한다. '~일 리가 없다'인 ～わけがない와 헷갈리지 않도록 주의.","cmp":[{"g":"～わけがない","d":"'~일 리가 없다'는 강한 전면 부정이다. ～わけではない는 일부만 부정한다."}],"ex":[{"jp":"毎日[まいにち]走[はし]るわけではないが、週[しゅう]に三回[さんかい]は走[はし]っている。","ko":"매일 달리는 건 아니지만 일주일에 세 번은 달리고 있다."},{"jp":"肉[にく]が嫌[きら]いなわけではないが、あまり食[た]べない。","ko":"고기를 싫어하는 건 아니지만 별로 먹지 않는다."},{"jp":"高[たか]ければいいというわけではない。","ko":"비싸면 좋다는 것은 아니다."}],"dr":[{"t":"make","q":"全部わかる → ～わけではない","a":"全部わかるわけではない","hint":"보통형 그대로 + わけではない"},{"t":"make","q":"暇だ → ～わけではない","a":"暇なわけではない","hint":"な형용사는 だ를 な로 바꿔 + わけではない"},{"t":"fill","q":"日本人[にほんじん]がみんな納豆[なっとう]を好[す]きな（　）。","a":"わけではない","opts":["わけではない","わけだ","よりほかない","一方だ"]}],"src":["https://www.mlcjapanese.co.jp/n3_04_12.html"],"vf":1,"u":28,"g":1,"gp":"gg_N2_11"},{"id":"g2_001","t":"A あるいは B","ko":"A 또는 B, 혹은","cat":"부사·접속사","conn":[{"w":"명사","f":"黒 + あるいは + 青"},{"w":"명사구","f":"郵便 + あるいは + メール"},{"w":"문장","f":"電車で行く(か)、あるいは バスで行く(か)"}],"rule":["1. 고를 수 있는 두 항목 A와 B를 같은 형태(명사끼리, 문장끼리)로 맞춘다.","2. A와 B 사이에 あるいは를 넣는다(黒あるいは青).","3. 문장끼리 이을 때는 A 뒤에 쉼표(、)를 찍고 あるいは를 쓰며, 'Aか、あるいはBか'처럼 か와 함께 쓰기도 한다."],"why":"","nu":"선택지를 나열하는 딱딱한 말로, 안내문·서류·뉴스 등 문어나 격식 있는 자리에서 주로 쓴다. 일상 회화에서는 か나 それか가 자연스럽다. 'あるいは～かもしれない'처럼 '어쩌면'이라는 부사 뜻도 있으니 문맥으로 구별한다.","cmp":[{"g":"または","d":"둘 다 격식 있는 '또는'으로 거의 바꿔 쓸 수 있다. あるいは에는 '어쩌면'이라는 부사 용법도 있다."}],"ex":[{"jp":"黒[くろ]あるいは青[あお]のペンで書[か]いてください。","ko":"검은색 또는 파란색 펜으로 써 주세요."},{"jp":"申込書[もうしこみしょ]は郵便[ゆうびん]、あるいはメールで送[おく]ってください。","ko":"신청서는 우편 또는 메일로 보내 주세요."},{"jp":"電車[でんしゃ]で行[い]くか、あるいはバスで行[い]くか、まだ決[き]めていない。","ko":"전철로 갈지 혹은 버스로 갈지 아직 정하지 않았다."}],"dr":[{"t":"make","q":"黒 / 青 → あるいは로 연결","a":"黒あるいは青","hint":"두 명사 사이에 あるいは"},{"t":"make","q":"郵便 / メール → あるいは로 연결","a":"郵便あるいはメール","hint":"두 명사 사이에 あるいは"},{"t":"fill","q":"名前[なまえ]はボールペン（　）サインペンで書[か]いてください。","a":"あるいは","opts":["あるいは","しかし","だから","ところで"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%82%E3%82%8B%E3%81%84%E3%81%AF","https://jlptsensei.com/learn-japanese-grammar/あるいは-aruiwa-meaning/"],"vf":1,"u":28,"g":1,"gp":"gg_N2_11"},{"id":"g2_002","t":"A。おまけに B。","ko":"게다가, 설상가상으로","cat":"부사·접속사","conn":[{"w":"문장 + 문장","f":"道に迷った。 + おまけに + 雨が降ってきた。"},{"w":"문장 + 문장","f":"狭い。 + おまけに + 遠い。"}],"rule":["1. 먼저 상황 A를 한 문장으로 말한다(道に迷った。).","2. 다음 문장 맨 앞에 おまけに를 놓는다.","3. 그 뒤에 A와 같은 방향(나쁜 일에는 나쁜 일, 좋은 일에는 좋은 일)의 내용 B를 덧붙인다."],"why":"","nu":"주로 회화체로, 안 좋은 일이 겹칠 때 '설상가상으로'라는 느낌으로 자주 쓰지만 좋은 일을 덧붙일 때도 쓴다. B에는 も·まで가 자주 함께 온다(雨まで降ってきた). 논문·공식 문서에는 その上나 さらに가 어울린다.","cmp":[{"g":"その上","d":"その上는 회화와 문어 모두에서 중립적으로 쓴다. おまけに는 더 구어적이고 '거기다 이것까지'라는 감정이 실린다."}],"ex":[{"jp":"道[みち]に迷[まよ]った。おまけに雨[あめ]まで降[ふ]ってきた。","ko":"길을 잃었다. 설상가상으로 비까지 내리기 시작했다."},{"jp":"この部屋[へや]は狭[せま]い。おまけに駅[えき]からも遠[とお]い。","ko":"이 방은 좁다. 게다가 역에서도 멀다."},{"jp":"あの店[みせ]は安[やす]くておいしい。おまけに店員[てんいん]も親切[しんせつ]だ。","ko":"그 가게는 싸고 맛있다. 게다가 점원도 친절하다."}],"dr":[{"t":"make","q":"狭い。/ 遠い。→ おまけに로 연결","a":"狭い。おまけに遠い。","hint":"두 번째 문장 앞에 おまけに"},{"t":"make","q":"道に迷った。/ 雨まで降ってきた。→ おまけに로 연결","a":"道に迷った。おまけに雨まで降ってきた。","hint":"두 번째 문장 앞에 おまけに"},{"t":"fill","q":"財布[さいふ]を落[お]とした。（　）、携帯[けいたい]もなくした。","a":"おまけに","opts":["おまけに","ところで","すなわち","それとも"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%8A%E3%81%BE%E3%81%91%E3%81%AB","https://jlptsensei.com/learn-japanese-grammar/おまけに-omake-ni-meaning/"],"vf":1,"u":28,"g":1,"gp":"gg_N2_11"},{"id":"g2_003","t":"A。さて B。","ko":"자, 그럼 / 그런데(화제 전환)","cat":"부사·접속사","conn":[{"w":"문장 + 문장","f":"仕事が終わった。 + さて + 帰ろうか。"},{"w":"인사·서론 + 본론","f":"こんにちは。 + さて + 今日は～についてお話しします。"}],"rule":["1. 앞 이야기나 일 A를 일단 마무리한다(仕事が終わった。).","2. 다음 문장 맨 앞에 さて를 놓는다.","3. 그 뒤에 새로운 화제나 다음 행동 B를 말한다(帰ろうか)."],"why":"","nu":"앞의 일을 정리하고 다음으로 넘어갈 때 쓴다. 연설·편지에서 인사 뒤 본론에 들어갈 때, 혼잣말로 다음 행동을 시작할 때(さて、何をしようかな) 자주 쓴다. 격식 있는 자리와 회화 모두 쓸 수 있다.","cmp":[{"g":"ところで","d":"ところで는 대화 중 갑자기 관계없는 다른 화제로 바꿀 때 쓴다. さて는 앞 내용을 매듭짓고 본론·다음 단계로 넘어가는 느낌이다."}],"ex":[{"jp":"今日[きょう]の仕事[しごと]は終[お]わった。さて、帰[かえ]ろうか。","ko":"오늘 일은 끝났다. 자, 그럼 돌아갈까."},{"jp":"皆[みな]さん、こんにちは。さて、今日[きょう]は新[あたら]しい計画[けいかく]についてお話[はな]しします。","ko":"여러분 안녕하세요. 그럼 오늘은 새 계획에 대해 말씀드리겠습니다."},{"jp":"ご飯[はん]も食[た]べたし、さて、何[なに]をしようかな。","ko":"밥도 먹었고, 자 그럼 뭘 할까."}],"dr":[{"t":"make","q":"仕事が終わった。/ 帰ろうか。→ さて로 연결","a":"仕事が終わった。さて、帰ろうか。","hint":"다음 행동 문장 앞에 さて"},{"t":"make","q":"皆さん、こんにちは。/ 本題に入りましょう。→ さて로 연결","a":"皆さん、こんにちは。さて、本題に入りましょう。","hint":"인사 뒤 본론 앞에 さて"},{"t":"fill","q":"準備[じゅんび]はできた。（　）、出発[しゅっぱつ]しよう。","a":"さて","opts":["さて","しかし","すなわち","おまけに"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%95%E3%81%A6","https://jlptsensei.com/learn-japanese-grammar/さて-sate-meaning"],"vf":1,"u":28,"g":1,"gp":"gg_N2_11"},{"id":"g2_004","t":"A。しかも B。","ko":"게다가, 더욱이","cat":"부사·접속사","conn":[{"w":"문장 + 문장","f":"安い。 + しかも + おいしい。"},{"w":"て형 + しかも","f":"近くて、 + しかも + 静かだ"}],"rule":["1. 먼저 A의 내용을 말한다(この店の料理は安い。).","2. 다음 문장 맨 앞에 しかも를 놓는다. 한 문장 안에서는 'Aて(で)、しかもB'로 잇는다.","3. 그 뒤에 A에 더해지는 같은 방향의 내용 B를 말한다(しかも、おいしい)."],"why":"","nu":"A만으로도 충분한데 B까지 더해진다는 놀라움·강조의 느낌이 있다. 좋은 일·나쁜 일 모두에 쓰며 회화와 문어 모두 쓸 수 있다. B 뒤에 명령·권유를 두기보다는 사실을 덧붙이는 데 쓴다.","cmp":[{"g":"それに","d":"それに는 회화에서 항목을 하나 더 덧붙이는 말로 중립적이다. しかも는 덧붙이는 내용이 더 눈에 띈다는 강조가 있다."}],"ex":[{"jp":"この店[みせ]の料理[りょうり]は安[やす]い。しかも、おいしい。","ko":"이 가게 요리는 싸다. 게다가 맛있다."},{"jp":"彼[かれ]は頭[あたま]がいい。しかも、スポーツも得意[とくい]だ。","ko":"그는 머리가 좋다. 더욱이 스포츠도 잘한다."},{"jp":"駅[えき]から近[ちか]くて、しかも静[しず]かな部屋[へや]を探[さが]している。","ko":"역에서 가깝고 게다가 조용한 방을 찾고 있다."}],"dr":[{"t":"make","q":"安い。/ おいしい。→ しかも로 연결","a":"安い。しかも、おいしい。","hint":"두 번째 문장 앞에 しかも"},{"t":"make","q":"近い / 静かな部屋 → 한 문장으로","a":"近くて、しかも静かな部屋","hint":"い형용사 い→くて, 그 뒤에 しかも"},{"t":"fill","q":"このホテルは広[ひろ]い。（　）、値段[ねだん]も安[やす]い。","a":"しかも","opts":["しかも","それでも","ところで","あるいは"]}],"src":["https://bunpro.jp/grammar_points/しかも","https://jlptsensei.com/learn-japanese-grammar/しかも-shikamo-meaning/"],"vf":1,"u":28,"g":1,"gp":"gg_N2_12"},{"id":"g2_006","t":"A すなわち B","ko":"즉, 다시 말해","cat":"부사·접속사","conn":[{"w":"명사 + 명사","f":"母の兄、 + すなわち + おじ"},{"w":"명사 + 명사","f":"来週の月曜日、 + すなわち + 五日"}],"rule":["1. 먼저 A를 말한다(母の兄).","2. A 뒤에 쉼표를 찍고 すなわち를 놓는다.","3. 그 뒤에 A와 같은 것을 다른 말로 바꾼 B를 놓는다(すなわち、おじ). A와 B는 같은 대상을 가리킨다."],"why":"","nu":"A와 B가 같은 것임을 밝히며 바꿔 말하는 딱딱한 문어체 표현이다. 논문·설명문·뉴스에서 주로 쓰고, 일상 회화에서는 つまり가 자연스럽다.","cmp":[{"g":"つまり","d":"つまり는 회화에서도 흔히 쓰며 앞 내용을 요약·결론짓는 데도 쓴다. すなわち는 문어적이고 A=B의 바꿔 말하기에 주로 쓴다."}],"ex":[{"jp":"彼[かれ]は母[はは]の兄[あに]、すなわち私[わたし]のおじだ。","ko":"그는 어머니의 오빠, 즉 나의 외삼촌이다."},{"jp":"来週[らいしゅう]の月曜日[げつようび]、すなわち五日[いつか]に会議[かいぎ]があります。","ko":"다음 주 월요일, 즉 5일에 회의가 있습니다."},{"jp":"日本[にほん]の首都[しゅと]、すなわち東京[とうきょう]には人[ひと]が集[あつ]まる。","ko":"일본의 수도, 즉 도쿄에는 사람이 모인다."}],"dr":[{"t":"make","q":"母の兄 / 私のおじ → すなわち로 연결","a":"母の兄、すなわち私のおじ","hint":"A 뒤 쉼표 + すなわち + 바꿔 말한 B"},{"t":"make","q":"日本の首都 / 東京 → すなわち로 연결","a":"日本の首都、すなわち東京","hint":"A 뒤 쉼표 + すなわち + B"},{"t":"fill","q":"父[ちち]の父[ちち]、（　）祖父[そふ]は今年[ことし]九十歳[きゅうじっさい]だ。","a":"すなわち","opts":["すなわち","しかし","それでも","さて"]}],"src":["https://bunpro.jp/grammar_points/即ち"],"vf":1,"u":29,"g":1,"gp":"gg_N2_12"},{"id":"g2_008","t":"A。そういえば B。","ko":"그러고 보니, 그 말을 들으니 생각났는데","cat":"부사·접속사","conn":[{"w":"문장 + 문장","f":"雨だね。 + そういえば + 傘を忘れてきた。"},{"w":"문장 맨 앞","f":"そういえば + 宿題、もう出した？"}],"rule":["1. 무언가를 떠올리게 한 계기 A(상대의 말, 눈앞의 상황)가 먼저 있다(雨だね。).","2. 다음 문장 맨 앞에 そういえば를 놓는다.","3. 그 뒤에 A를 계기로 문득 생각난 일 B를 말한다(傘を会社に忘れてきた)."],"why":"そう(그렇게)에 言う의 가정형 言えば가 붙은 형태로, '그렇게 말하니'라는 뜻에서 '그러고 보니'가 되었다.","nu":"회화체 표현이다. 앞 말이나 눈앞의 상황에서 연상되어 떠오른 일을 꺼낼 때 쓰며, 앞 이야기와 전혀 관계없는 화제로 바꿀 때는 쓰지 않는다. 논문·공식 문서에는 쓰지 않는다.","cmp":[{"g":"ところで","d":"ところで는 앞 이야기와 관계없이 의도적으로 화제를 바꾼다. そういえば는 앞 이야기나 상황에서 연상되어 생각난 일을 꺼낸다."}],"ex":[{"jp":"雨[あめ]だね。そういえば、傘[かさ]を会社[かいしゃ]に忘[わす]れてきた。","ko":"비 오네. 그러고 보니 우산을 회사에 두고 왔다."},{"jp":"「来週[らいしゅう]は連休[れんきゅう]だね。」「そういえば、田中[たなか]さんは旅行[りょこう]に行[い]くって言[い]ってたよ。」","ko":"\"다음 주는 연휴네.\" \"그러고 보니 다나카 씨는 여행 간다고 했어.\""},{"jp":"そういえば、昨日[きのう]の宿題[しゅくだい]、もう出[だ]した？","ko":"그러고 보니 어제 숙제 벌써 냈어?"}],"dr":[{"t":"make","q":"雨だね。/ 傘を忘れてきた。→ そういえば로 연결","a":"雨だね。そういえば、傘を忘れてきた。","hint":"생각난 일 앞에 そういえば"},{"t":"make","q":"連休だね。/ 田中さんは旅行に行くって。→ そういえば로 연결","a":"連休だね。そういえば、田中さんは旅行に行くって。","hint":"연상된 일 앞에 そういえば"},{"t":"fill","q":"このケーキ、おいしいね。（　）、駅前[えきまえ]に新[あたら]しいケーキ屋[や]ができたよ。","a":"そういえば","opts":["そういえば","したがって","それでも","すると"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9D%E3%81%86%E3%81%84%E3%81%88%E3%81%B0"],"vf":1,"u":29,"g":1,"gp":"gg_N2_12"},{"id":"g2_015","t":"それはそうと","ko":"그건 그렇고","cat":"부사·접속사","conn":[{"w":"문장 A 다음 (문장 첫머리)","f":"暑いね。+ それはそうと + 宿題は？"}],"rule":["1. 지금까지의 화제 A를 일단 끝낸다.","2. 새 문장 맨 앞에 それはそうと를 놓는다.","3. B에는 A와 직접 관계없는 새 화제가 온다."],"why":"","nu":"앞 화제를 인정하고 넘어가며 화제를 바꾸는 말로, 주로 회화에서 쓴다. 갑자기 생각난 일이나 원래 하고 싶던 말을 꺼낼 때 잘 쓴다. 비슷한 말로 ところで가 있으며, 격식 있는 글에서는 ところで가 더 무난하다.","cmp":[{"g":"ところで","d":"ところで는 화제 전환의 가장 일반적인 말로 회화·글 모두 쓴다. それはそうと는 앞 화제를 받아 두고 넘어가는 느낌이 있는 회화적 표현이다."}],"ex":[{"jp":"今日[きょう]は暑[あつ]いね。それはそうと、宿題[しゅくだい]はもう終[お]わった？","ko":"오늘은 덥네. 그건 그렇고, 숙제는 벌써 끝났어?"},{"jp":"旅行[りょこう]、楽[たの]しかったよ。それはそうと、この前[まえ]貸[か]した本[ほん]、読[よ]んだ？","ko":"여행 즐거웠어. 그건 그렇고, 요전에 빌려준 책 읽었어?"},{"jp":"それはそうと、来週[らいしゅう]の会議[かいぎ]は何時[なんじ]からでしたっけ。","ko":"그건 그렇고, 다음 주 회의는 몇 시부터였죠?"}],"dr":[{"t":"make","q":"いい天気だね。/ 田中さんは元気？→ それはそうと","a":"いい天気だね。それはそうと、田中さんは元気？","hint":"새 화제 문장 앞에 それはそうと"},{"t":"make","q":"この店、おいしいね。/ 明日の予定は？→ それはそうと","a":"この店、おいしいね。それはそうと、明日の予定は？","hint":"관계없는 화제로 넘어갈 때 문장 첫머리에"},{"t":"fill","q":"昨日[きのう]の試合[しあい]はすごかったね。（　）、来月[らいげつ]の旅行[りょこう]、どこに行[い]く？","a":"それはそうと","opts":["それはそうと","それなのに","だから","ただし"]}],"src":[],"vf":0,"u":29,"g":1,"gp":"gg_N2_12"},{"id":"g2_020","t":"ちなみに","ko":"덧붙여 말하면, 참고로","cat":"부사·접속사","conn":[{"w":"문장 A 다음 (문장 첫머리)","f":"店は九時まで。+ ちなみに + 日曜は休み。"}],"rule":["1. 앞 문장 A에서 주된 내용을 말한다.","2. 다음 문장 맨 앞에 ちなみに를 놓는다(뒤에 、를 찍는 경우가 많다).","3. B에는 A와 관련된, 꼭 필요하지는 않은 참고 정보가 온다."],"why":"","nu":"회화·글 모두 쓰며, 격식 있는 자리에서도 쓸 수 있다. B는 A와 관련된 정보여야 하므로, 전혀 다른 화제로 넘어갈 때는 ところで를 쓴다. 회화에서 '참고로 말하자면'처럼 가볍게 정보를 덧붙일 때 자주 쓴다.","cmp":[{"g":"ところで","d":"ところで는 화제를 바꾼다. ちなみに는 같은 화제 안에서 참고 정보를 덧붙인다."},{"g":"なお","d":"なお는 안내문·공문 같은 딱딱한 글에서 보충 사항을 덧붙일 때 쓴다."}],"ex":[{"jp":"この店[みせ]は夜[よる]九時[くじ]までです。ちなみに、日曜日[にちようび]は休[やす]みです。","ko":"이 가게는 밤 9시까지입니다. 참고로 일요일은 휴무입니다."},{"jp":"このケーキは私[わたし]が作[つく]りました。ちなみに、砂糖[さとう]はあまり使[つか]っていません。","ko":"이 케이크는 제가 만들었습니다. 덧붙이자면 설탕은 별로 쓰지 않았어요."},{"jp":"来週[らいしゅう]、京都[きょうと]に行[い]きます。ちなみに、京都[きょうと]は初[はじ]めてです。","ko":"다음 주에 교토에 갑니다. 참고로 교토는 처음이에요."}],"dr":[{"t":"make","q":"このシャツは千円です。/ 色は三つあります。→ ちなみに","a":"このシャツは千円です。ちなみに、色は三つあります。","hint":"참고 정보 문장 앞에 ちなみに"},{"t":"make","q":"私は大阪出身です。/ 兄は東京に住んでいます。→ ちなみに","a":"私は大阪出身です。ちなみに、兄は東京に住んでいます。","hint":"관련된 덤 정보를 뒤에 붙인다"},{"t":"fill","q":"この映画[えいが]、すごく面白[おもしろ]かったよ。（　）、監督[かんとく]は日本人[にほんじん]なんだって。","a":"ちなみに","opts":["ちなみに","それなのに","ただし","だが"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ちなみに-chinamini-meaning"],"vf":1,"u":29,"g":1,"gp":"gg_N2_12"},{"id":"g2_021","t":"ということは","ko":"그렇다는 것은, 즉","cat":"부사·접속사","conn":[{"w":"문장 A 다음 (문장 첫머리)","f":"電気が消えてる。+ ということは + 留守だ。"}],"rule":["1. 앞 문장 A에서 보거나 들은 사실을 말한다.","2. 다음 문장 맨 앞에 ということは를 놓는다.","3. B에는 A로부터 끌어낸 결론·추론이 오고, ～ということだ / ～わけだ / ～ね / ～かな 등으로 맺는 경우가 많다."],"why":"と(인용) + いう(말하다) + こと(것) + は(주제). 'A라고 하는 것은'이라는 뜻에서 A를 근거로 결론을 이끄는 말이 되었다.","nu":"회화에서 상대가 한 말을 받아 그 뜻을 확인할 때 특히 많이 쓴다(「明日は休みです。」「ということは、会議もなしですか。」). 추론이므로 B에 확신이 없으면 ～かもしれない, ～だろう를 쓴다. 명령·의뢰는 B에 잘 오지 않는다.","cmp":[{"g":"つまり","d":"つまり는 A를 다른 말로 바꿔 말하거나 요약한다. ということは는 A를 근거로 새로운 결론을 끌어낸다."},{"g":"それなら","d":"それなら 뒤에는 말하는 사람의 제안·의지가 온다. ということは 뒤에는 추론한 사실이 온다."}],"ex":[{"jp":"部屋[へや]の電気[でんき]が消[き]えている。ということは、もう寝[ね]たのかな。","ko":"방의 불이 꺼져 있다. 그렇다는 건 벌써 잤나?"},{"jp":"「明日[あした]は祝日[しゅくじつ]ですよ。」「ということは、銀行[ぎんこう]は休[やす]みですね。」","ko":"\"내일은 공휴일이에요.\" \"그렇다는 건 은행은 쉬겠네요.\""},{"jp":"道[みち]がすごく混[こ]んでいる。ということは、どこかで事故[じこ]があったのかもしれない。","ko":"길이 엄청 막힌다. 그렇다는 건 어딘가에서 사고가 났을지도 모른다."}],"dr":[{"t":"make","q":"「田中さんは辞めました。」→ ということは + 席が一つ空く","a":"ということは、席が一つ空くんですね。","hint":"상대 말을 받아 결론 앞에 ということは"},{"t":"make","q":"道が濡れている。/ 雨が降った → ということは","a":"道が濡れている。ということは、雨が降ったんだ。","hint":"사실 → ということは → 추론"},{"t":"fill","q":"「今日[きょう]は先生[せんせい]が休[やす]みだって。」「（　）、授業[じゅぎょう]はないの？」","a":"ということは","opts":["ということは","ただし","それなのに","だが"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%84%E3%81%86%E3%81%93%E3%81%A8"],"vf":1,"u":29,"g":1,"gp":"gg_N2_12"},{"id":"g2_023","t":"なお","ko":"덧붙여, 또한","cat":"부사·접속사","conn":[{"w":"문장 A 다음 (문장 첫머리)","f":"会議は十時から。+ なお + 昼食は出ません。"}],"rule":["1. 앞 문장 A에서 주된 안내·내용을 말한다.","2. 다음 문장 맨 앞에 なお를 놓는다(뒤에 、를 찍는다).","3. B에는 A와 관련된 보충 사항·주의 사항이 온다."],"why":"","nu":"안내문·공지·업무 메일·방송 같은 격식 있는 글과 말에서 쓰며, 친구끼리의 회화에는 거의 쓰지 않는다. B는 A의 내용을 제한하지 않고 별도의 정보를 보탠다. '여전히, 더욱'이라는 뜻의 부사 なお(なお一層)와는 다른 쓰임이다.","cmp":[{"g":"ただし","d":"ただし는 A에 조건·예외를 붙여 A를 제한한다. なお는 제한하지 않고 별도 정보를 보탠다."},{"g":"ちなみに","d":"ちなみに는 회화에서도 쓰는 가벼운 참고 정보다."}],"ex":[{"jp":"会議[かいぎ]は十時[じゅうじ]から始[はじ]まります。なお、昼食[ちゅうしょく]は各自[かくじ]でご用意[ようい]ください。","ko":"회의는 10시부터 시작합니다. 또한 점심은 각자 준비해 주십시오."},{"jp":"申[もう]し込[こ]みは今月[こんげつ]末[まつ]までです。なお、詳[くわ]しいことは担当者[たんとうしゃ]にお聞[き]きください。","ko":"신청은 이번 달 말까지입니다. 덧붙여 자세한 것은 담당자에게 문의해 주십시오."},{"jp":"明日[あした]は休館日[きゅうかんび]です。なお、駐車場[ちゅうしゃじょう]は通常[つうじょう]どおり使[つか]えます。","ko":"내일은 휴관일입니다. 또한 주차장은 평소대로 이용할 수 있습니다."}],"dr":[{"t":"make","q":"試験は九時からです。/ 筆記用具を忘れないでください。→ なお","a":"試験は九時からです。なお、筆記用具を忘れないでください。","hint":"보충 사항 문장 앞에 なお"},{"t":"make","q":"説明会は三階で行います。/ 参加は無料です。→ なお","a":"説明会は三階で行います。なお、参加は無料です。","hint":"주된 안내 뒤에 なお + 추가 정보"},{"t":"fill","q":"本日[ほんじつ]の営業[えいぎょう]は午後[ごご]五時[ごじ]までです。（　）、明日[あした]は通常[つうじょう]どおり営業[えいぎょう]いたします。","a":"なお","opts":["なお","だって","それなのに","だが"]}],"src":["https://bunpro.jp/grammar_points/なお2","https://bunpro.jp/grammar_points/なお1"],"vf":1,"u":30,"g":1,"gp":"gg_N2_12"},{"id":"g2_025","t":"要するに","ko":"요컨대, 결국","cat":"부사·접속사","conn":[{"w":"문장 A 다음 (문장 첫머리)","f":"高いし、遠い。+ 要するに + 行かない。"}],"rule":["1. 앞 문장 A에서 여러 사정·설명을 늘어놓는다.","2. 다음 문장 맨 앞에 要するに를 놓는다.","3. B에는 A를 한마디로 정리한 요점·결론이 오고, ～ということだ / ～わけだ로 맺는 경우도 많다."],"why":"","nu":"길게 말한 내용이나 상대의 말을 짧게 정리할 때 쓴다. 회화·글 모두 쓴다. 상대의 긴 말을 「要するに～ってこと？」로 정리하면 말을 끊는 느낌이 들 수 있으니 주의. 정리가 아니라 단순히 다른 말로 바꿔 말할 때는 つまり가 더 넓게 쓰인다.","cmp":[{"g":"つまり","d":"つまり는 바꿔 말하기·요약 모두에 쓰는 일반적인 말이다. 要するに는 여러 내용을 묶어 핵심만 말하는 느낌이 더 강하다."},{"g":"ということは","d":"ということは는 A를 근거로 새로운 결론을 추론한다. 要するに는 A 자체를 요약한다."}],"ex":[{"jp":"値段[ねだん]も高[たか]いし、駅[えき]からも遠[とお]い。要するに、あの店[みせ]にはもう行[い]かない。","ko":"값도 비싸고 역에서도 멀다. 요컨대 그 가게에는 이제 안 간다."},{"jp":"彼[かれ]は理由[りゆう]をいろいろ話[はな]したが、要するに、やりたくないということだ。","ko":"그는 이유를 이것저것 말했지만, 결국 하기 싫다는 것이다."},{"jp":"毎日[まいにち]少[すこ]しずつ練習[れんしゅう]すること。要するに、続[つづ]けることが大切[たいせつ]なんです。","ko":"매일 조금씩 연습할 것. 요컨대 계속하는 것이 중요한 거예요."}],"dr":[{"t":"make","q":"忙しいし、お金もない。/ 旅行は無理だ → 要するに","a":"忙しいし、お金もない。要するに、旅行は無理だ。","hint":"요점 문장 앞에 要するに"},{"t":"make","q":"彼は遅刻も多いし、宿題もしない。/ やる気がない + ということだ → 要するに","a":"彼は遅刻も多いし、宿題もしない。要するに、やる気がないということだ。","hint":"要するに + 요점 + ということだ"},{"t":"fill","q":"あれもダメ、これもダメ。（　）、何[なに]もしたくないんでしょう？","a":"要するに","opts":["要するに","ちなみに","ただし","なお"]}],"src":["https://bunpro.jp/ja/grammar_points/%E8%A6%81%E3%81%99%E3%82%8B%E3%81%AB"],"vf":1,"u":30,"g":1,"gp":"gg_N2_12"},{"id":"g2_029","t":"～をはじめ","ko":"~을 비롯해","cat":"기타","conn":[{"w":"명사","f":"東京 + をはじめ"},{"w":"명사 수식 (～をはじめとする + 명사)","f":"東京 + をはじめとする + 大都市"}],"rule":["1. 명사 뒤에 をはじめ를 바로 붙인다(東京をはじめ).","2. 앞의 명사는 대표적인 한 예이고, 뒤에는 그것을 포함한 같은 부류 전체가 온다(各地, 多くの国 등).","3. 뒤의 명사를 꾸밀 때는 をはじめとする + 명사 형태를 쓴다."],"why":"","nu":"대표적인 것을 먼저 들고 같은 종류의 다른 것들도 있다는 것을 말한다. 뉴스·연설·소개문 등 격식 있는 말과 글에서 많이 쓴다. 뒤에는 いろいろな, 多くの, ～など처럼 여럿을 가리키는 말이 오는 것이 자연스럽다. 앞 명사가 대표 예가 아닌 아무것이나 되면 어색하다.","cmp":[{"g":"～をはじめとして","d":"뜻은 같고, として가 붙어 조금 더 딱딱한 느낌이다."},{"g":"～など","d":"など는 예를 늘어놓을 뿐이고, をはじめ는 그중 대표를 맨 앞에 내세운다."}],"ex":[{"jp":"東京[とうきょう]をはじめ、各地[かくち]で雪[ゆき]が降[ふ]った。","ko":"도쿄를 비롯해 각지에서 눈이 내렸다."},{"jp":"この店[みせ]では、ラーメンをはじめ、いろいろな料理[りょうり]が食[た]べられる。","ko":"이 가게에서는 라멘을 비롯해 여러 가지 요리를 먹을 수 있다."},{"jp":"京都[きょうと]には、金閣寺[きんかくじ]をはじめとする有名[ゆうめい]なお寺[てら]が多[おお]い。","ko":"교토에는 금각사를 비롯한 유명한 절이 많다."}],"dr":[{"t":"make","q":"両親 → ～をはじめ + 家族みんなが喜んだ","a":"両親をはじめ、家族みんなが喜んだ。","hint":"대표 명사 + をはじめ"},{"t":"make","q":"富士山 + 有名な山 → ～をはじめとする","a":"富士山をはじめとする有名な山","hint":"명사를 꾸밀 때는 をはじめとする + 명사"},{"t":"fill","q":"日本[にほん]には、寿司[すし]（　）、おいしい料理[りょうり]がたくさんある。","a":"をはじめ","opts":["をはじめ","につき","にて","のことだから"]}],"src":["https://bunpro.jp/grammar_points/%E3%82%92%E3%81%AF%E3%81%98%E3%82%81","https://nihongokyoshi-net.com/?p=4205"],"vf":1,"u":30,"g":1,"gp":"gg_N2_12"},{"id":"g2_030","t":"～をはじめとして","ko":"~을 비롯하여","cat":"기타","conn":[{"w":"명사","f":"社長 + をはじめとして"},{"w":"명사 수식 (～をはじめとする + 명사)","f":"社長 + をはじめとする + 社員"}],"rule":["1. 명사 뒤에 をはじめ를 붙이고 として를 이어 붙인다(社長をはじめ → 社長をはじめとして).","2. 앞의 명사는 대표·중심이 되는 예이고, 뒤에는 그것을 포함한 무리 전체가 온다.","3. 뒤의 명사를 꾸밀 때는 をはじめとする + 명사로 바꾼다."],"why":"","nu":"をはじめ와 뜻이 같고, として가 붙은 만큼 더 딱딱해서 연설·뉴스·공식 문서에 잘 어울린다. 앞 명사에는 그 무리를 대표하는 사람·사물(社長, 校長先生, 首都 등)이 온다. 뒤에는 全員, 多くの～, さまざまな～처럼 여럿을 나타내는 말이 오는 것이 자연스럽다.","cmp":[{"g":"～をはじめ","d":"뜻은 같지만 をはじめ가 더 짧고 조금 덜 딱딱하다."}],"ex":[{"jp":"社長[しゃちょう]をはじめとして、社員[しゃいん]全員[ぜんいん]がパーティーに参加[さんか]した。","ko":"사장님을 비롯하여 사원 전원이 파티에 참가했다."},{"jp":"この町[まち]には、図書館[としょかん]をはじめとして、便利[べんり]な施設[しせつ]がたくさんある。","ko":"이 동네에는 도서관을 비롯하여 편리한 시설이 많이 있다."},{"jp":"校長[こうちょう]先生[せんせい]をはじめとする先生方[せんせいがた]に、お礼[れい]を申[もう]し上[あ]げます。","ko":"교장 선생님을 비롯한 선생님들께 감사 말씀을 드립니다."}],"dr":[{"t":"make","q":"部長 → ～をはじめとして + 多くの人が反対した","a":"部長をはじめとして、多くの人が反対した。","hint":"명사 + をはじめ + として"},{"t":"make","q":"大阪をはじめとして → 명사 수식형 (大都市)","a":"大阪をはじめとする大都市","hint":"명사를 꾸밀 때는 をはじめとする"},{"t":"fill","q":"アジア（　）、世界[せかい]の多[おお]くの国[くに]から観光客[かんこうきゃく]が来[く]る。","a":"をはじめとして","opts":["をはじめとして","につき","にて","のことだから"]}],"src":["https://bunpro.jp/grammar_points/%E3%82%92%E3%81%AF%E3%81%98%E3%82%81"],"vf":1,"u":30,"g":1,"gp":"gg_N2_12"},{"id":"g2_031","t":"～をはじめとする","ko":"~을 비롯한","cat":"기타","conn":[{"w":"명사","f":"東京 + をはじめとする + 大都市"}],"rule":["1. 대표로 내세울 명사(명사1) 뒤에 조사 を를 붙인다.","2. 그 뒤에 はじめとする를 그대로 붙인다(활용하지 않는 고정 표현).","3. 마지막에 명사1이 속한 더 큰 무리를 나타내는 명사(명사2)를 놓는다(東京をはじめとする大都市)."],"why":"はじめ(始め, 처음)とする(~으로 삼다)가 합쳐져 '~을 처음(대표)으로 삼는'이라는 뜻이 된다.","nu":"명사1은 명사2 무리의 대표적인 예이고, 그 밖에도 같은 종류가 더 있다는 느낌을 준다. 뉴스·안내문 등 딱딱한 말에서 많이 쓴다. 뒤에는 반드시 명사가 와야 하며, 문장을 이어 갈 때는 をはじめ 또는 をはじめとして를 쓴다. 대표가 될 만큼 잘 알려진 것을 명사1에 둔다.","cmp":[{"g":"～をはじめ(として)","d":"뜻은 같지만 뒤에 명사를 꾸미지 않고 문장을 이어 간다(東京をはじめ、各地で…)."},{"g":"～など","d":"여러 예를 나열할 뿐, 하나를 대표로 내세우는 느낌은 없다."}],"ex":[{"jp":"東京[とうきょう]をはじめとする大都市[だいとし]では、家賃[やちん]が高[たか]い。","ko":"도쿄를 비롯한 대도시에서는 집세가 비싸다."},{"jp":"この店[みせ]では、すしをはじめとする日本料理[にほんりょうり]が食[た]べられる。","ko":"이 가게에서는 초밥을 비롯한 일본 요리를 먹을 수 있다."},{"jp":"社長[しゃちょう]をはじめとする社員[しゃいん]全員[ぜんいん]が会議[かいぎ]に出[で]た。","ko":"사장을 비롯한 사원 전원이 회의에 나왔다."}],"dr":[{"t":"make","q":"京都 / 古い町 → ～をはじめとする","a":"京都をはじめとする古い町","hint":"명사1 + を + はじめとする + 명사2"},{"t":"make","q":"サッカー / スポーツ → ～をはじめとする","a":"サッカーをはじめとするスポーツ","hint":"대표 명사 + をはじめとする + 무리 명사"},{"t":"fill","q":"ここには、パンダ（　）めずらしい動物[どうぶつ]がたくさんいる。","a":"をはじめとする","opts":["をはじめとする","にとって","によって","に対して"]}],"src":["https://nihongokyoshi-net.com/?p=4205","https://bunpro.jp/grammar_points/263"],"vf":1,"u":30,"g":1,"gp":"gg_N2_12"},{"id":"g2_032","t":"～をめぐって","ko":"~을 둘러싸고","cat":"기타","conn":[{"w":"명사","f":"土地 + をめぐって"}],"rule":["1. 화제가 되는 명사 뒤에 조사 を를 붙인다.","2. 그 뒤에 동사 めぐる의 て형 めぐって를 붙인다(る → って).","3. 뒤에는 争う・対立する・議論する처럼 여럿이 다투거나 의견을 나누는 동사가 온다(土地をめぐって争う)."],"why":"동사 めぐる(巡る, 둘레를 돌다)의 て형으로, '어떤 것을 중심에 두고 그 둘레에서'라는 뜻에서 왔다.","nu":"한 가지 일을 놓고 여러 사람·집단이 다투거나 의견이 갈리는 상황에 쓴다. 문어체·뉴스체. 단순히 '~에 대해 말하다·쓰다'에는 쓰지 않는다(×日本の文化をめぐってレポートを書く → について). 한국어 '~을 둘러싸고'와 쓰임이 비슷하다. 명사를 꾸밀 때는 をめぐる를 쓴다.","cmp":[{"g":"～について","d":"화제를 나타내는 일반 표현으로 말하다·쓰다·조사하다 등 어떤 동사와도 쓴다. をめぐって는 다툼·논의가 있을 때만 쓴다."}],"ex":[{"jp":"土地[とち]をめぐって、兄弟[きょうだい]が争[あらそ]っている。","ko":"땅을 둘러싸고 형제가 다투고 있다."},{"jp":"新[あたら]しい駅[えき]の場所[ばしょ]をめぐって、住民[じゅうみん]の意見[いけん]が分[わ]かれた。","ko":"새 역의 위치를 둘러싸고 주민의 의견이 갈렸다."},{"jp":"その事件[じけん]をめぐって、国会[こっかい]で議論[ぎろん]が続[つづ]いている。","ko":"그 사건을 둘러싸고 국회에서 논의가 계속되고 있다."}],"dr":[{"t":"make","q":"税金 → ～をめぐって","a":"税金をめぐって","hint":"명사 + を + めぐって"},{"t":"make","q":"めぐる → て형","a":"めぐって","hint":"る로 끝나는 1그룹 동사: る → って"},{"t":"fill","q":"ごみ処理場[しょりじょう]の建設[けんせつ]（　）、市[し]と住民[じゅうみん]が対立[たいりつ]している。","a":"をめぐって","opts":["をめぐって","をもとに","にしては","のおかげで"]}],"src":["https://nihongokyoshi-net.com/2019/05/15/jlptn2-grammar-megutte/","https://bunpro.jp/grammar_points/690"],"vf":1,"u":31,"g":1,"gp":"gg_N2_12"},{"id":"g2_034","t":"～をもとに","ko":"~을 바탕으로","cat":"기타","conn":[{"w":"명사","f":"実話 + をもとに + 作る"}],"rule":["1. 바탕(재료·근거)이 되는 명사 뒤에 조사 を를 붙인다.","2. 그 뒤에 もとに를 붙인다.","3. 뒤에는 作る・書く・決める처럼 무언가를 만들어 내는 동사가 온다(実話をもとに作る). 명사를 꾸밀 때는 をもとにした를 쓴다."],"why":"もと(基·元, 바탕·근본)에 조사 に가 붙은 것으로, もとにする(~을 바탕으로 삼다)의 줄임 형태다.","nu":"이야기·자료·경험 등을 재료로 삼아 새 것을 만들어 낼 때 쓴다. 회화와 글 모두에서 쓰지만 약간 딱딱하다. 단순히 '~에 따라 행동하다'에는 に従って, '~에 근거하여 판단하다'에는 に基づいて가 더 어울린다.","cmp":[{"g":"～に基づいて","d":"규칙·법·사실을 근거로 엄격히 따를 때. をもとに는 재료로 삼아 새로운 것을 만드는 느낌이 강하다."}],"ex":[{"jp":"この映画[えいが]は実話[じつわ]をもとに作[つく]られた。","ko":"이 영화는 실화를 바탕으로 만들어졌다."},{"jp":"アンケートの結果[けっか]をもとに、新[あたら]しい商品[しょうひん]を考[かんが]えた。","ko":"설문 결과를 바탕으로 새 상품을 생각했다."},{"jp":"祖母[そぼ]の話[はなし]をもとにした小説[しょうせつ]を読[よ]んだ。","ko":"할머니의 이야기를 바탕으로 한 소설을 읽었다."}],"dr":[{"t":"make","q":"写真 → ～をもとに絵を描く","a":"写真をもとに絵を描く","hint":"명사 + を + もとに + 동사"},{"t":"make","q":"経験 / 本 → ～をもとにした + 명사","a":"経験をもとにした本","hint":"명사를 꾸밀 때는 をもとにした"},{"t":"fill","q":"この料理[りょうり]は、母[はは]のレシピ（　）作[つく]りました。","a":"をもとに","opts":["をもとに","をめぐって","にとって","のくせに"]}],"src":["https://bunpro.jp/grammar_points/%E3%82%92%E3%82%82%E3%81%A8%E3%81%AB"],"vf":1,"u":31,"g":1,"gp":"gg_N2_13"},{"id":"g2_035","t":"～をもとにして","ko":"~을 바탕으로 해서","cat":"기타","conn":[{"w":"명사","f":"データ + をもとにして + 書く"}],"rule":["1. 바탕이 되는 명사 뒤에 조사 を를 붙인다.","2. もとに 뒤에 する의 て형 して를 붙여 をもとにして로 만든다.","3. 뒤에 만들어 내는 동사를 이어 쓴다(データをもとにして書く)."],"why":"もとにする(~을 바탕으로 삼다)의 て형이다. して를 빼면 をもとに가 된다.","nu":"をもとに와 뜻은 같고 して가 붙어 조금 더 또렷하게 들린다. 자료·의견·원작 등을 재료로 무언가를 만들거나 바꿀 때 쓴다. 명사를 꾸밀 때는 をもとにした를 쓴다(をもとにした映画).","cmp":[{"g":"～をもとに","d":"して를 생략한 형태로 뜻은 같다."},{"g":"～を中心にして","d":"'~을 중심으로'라는 뜻으로 바탕·재료의 뜻은 없다."}],"ex":[{"jp":"調査[ちょうさ]のデータをもとにして、レポートを書[か]いた。","ko":"조사 데이터를 바탕으로 해서 보고서를 썼다."},{"jp":"みんなの意見[いけん]をもとにして、旅行[りょこう]の計画[けいかく]を変[か]えた。","ko":"모두의 의견을 바탕으로 해서 여행 계획을 바꿨다."},{"jp":"このドラマは人気[にんき]のマンガをもとにして作[つく]られている。","ko":"이 드라마는 인기 만화를 바탕으로 해서 만들어졌다."}],"dr":[{"t":"make","q":"資料をもとに → して 추가","a":"資料をもとにして","hint":"もとに 뒤에 する의 て형 して"},{"t":"make","q":"この地図 → ～をもとにして道を探す","a":"この地図をもとにして道を探す","hint":"명사 + を + もとにして + 동사"},{"t":"fill","q":"先生[せんせい]のアドバイス（　）、作文[さくぶん]を書[か]き直[なお]した。","a":"をもとにして","opts":["をもとにして","をはじめ","に反して","のあまり"]}],"src":["https://bunpro.jp/grammar_points/%E3%82%92%E3%82%82%E3%81%A8%E3%81%AB"],"vf":1,"u":31,"g":1,"gp":"gg_N2_13"},{"id":"g2_036","t":"～ことなく","ko":"~하는 일 없이, ~하지 않고","cat":"기타","conn":[{"w":"동사 사전형","f":"休む + ことなく"},{"w":"동사(する)","f":"失敗する + ことなく"}],"rule":["1. 동사를 사전형 그대로 둔다(休む).","2. 그 뒤에 명사 こと를 붙인다.","3. 이어서 ない의 연용형 なく를 붙인다(休むことなく).","4. 뒤에 실제로 한 행동을 쓴다(休むことなく働く)."],"why":"こと(일)에 ない의 연용형 なく가 붙어 '~하는 일이 없이'라는 뜻이 된다.","nu":"문어체로 뉴스·연설·글에서 쓴다. 회화에서는 ～ないで나 ～ずに가 자연스럽다. 보통이라면 할 법한 일(쉬다, 포기하다, 멈추다)을 하지 않고 계속했다는 뜻을 강조하며, 一度も・誰にも 등과 잘 어울린다. ます형 어간이 아니라 사전형에 붙는다는 점에 주의한다.","cmp":[{"g":"～ずに / ～ないで","d":"같은 뜻의 일상 표현. ことなく는 더 딱딱하고 '한 번도 ~하지 않고'라는 강조가 있다."}],"ex":[{"jp":"彼[かれ]は一日[いちにち]も休[やす]むことなく働[はたら]いた。","ko":"그는 하루도 쉬지 않고 일했다."},{"jp":"彼女[かのじょ]は誰[だれ]にも相談[そうだん]することなく、会社[かいしゃ]を辞[や]めた。","ko":"그녀는 누구와도 상담하지 않고 회사를 그만두었다."},{"jp":"あきらめることなく、最後[さいご]まで走[はし]り続[つづ]けた。","ko":"포기하지 않고 마지막까지 계속 달렸다."}],"dr":[{"t":"make","q":"止まる → ～ことなく","a":"止まることなく","hint":"사전형 + こと + なく"},{"t":"make","q":"迷う → ～ことなく","a":"迷うことなく","hint":"사전형 그대로 + ことなく"},{"t":"fill","q":"彼[かれ]は一度[いちど]も失敗[しっぱい]する（　）、試験[しけん]に合格[ごうかく]した。","a":"ことなく","opts":["ことなく","ことには","おかげで","ばかりか"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%93%E3%81%A8%E3%81%AA%E3%81%8F"],"vf":1,"u":31,"g":1,"gp":"gg_N2_13"},{"id":"g2_041","t":"～がい","ko":"~하는 보람","cat":"기타","conn":[{"w":"동사 ます형 어간","f":"やり + がい"},{"w":"동사 ます형 어간","f":"教え + がい"}],"rule":["1. 동사를 ます형 어간으로 바꾼다(1그룹 やる: 어미 る → り, やり).","2. 그 뒤에 がい를 붙여 명사로 만든다(やりがい).","3. 보통 がある・がない를 붙이거나, のある + 명사로 쓴다(やりがいがある, やりがいのある仕事)."],"why":"명사 かい(甲斐, 보람)가 동사 뒤에 붙으면서 연탁되어 がい로 소리 난다.","nu":"그 행동을 한 만큼의 보람·가치가 있다는 뜻이다. 生きがい(삶의 보람), やりがい, 働きがい처럼 굳어진 말이 많다. ～がいがある / ～がいのある 형태로 자주 쓴다. 사전형에 붙이지 않도록 주의한다(×やるがい).","cmp":[{"g":"～かいがあって","d":"이미 한 노력이 결과로 보상받았다는 뜻. ～がい는 그 행동 자체가 가치 있다는 명사를 만든다."}],"ex":[{"jp":"今[いま]の仕事[しごと]はとてもやりがいがある。","ko":"지금 일은 아주 보람이 있다."},{"jp":"熱心[ねっしん]な学生[がくせい]が多[おお]くて、教[おし]えがいがある。","ko":"열심인 학생이 많아서 가르치는 보람이 있다."},{"jp":"祖父[そふ]は孫[まご]の成長[せいちょう]が生[い]きがいだと言[い]う。","ko":"할아버지는 손주의 성장이 삶의 보람이라고 한다."}],"dr":[{"t":"make","q":"働く → ～がい","a":"働きがい","hint":"1그룹 く → き + がい"},{"t":"make","q":"育てる → ～がいがある","a":"育てがいがある","hint":"2그룹: る를 빼고 がい + がある"},{"t":"fill","q":"みんなが喜[よろこ]んでくれるので、料理[りょうり]の作[つく]り（　）がある。","a":"がい","opts":["がい","がち","かけ","ぎみ"]}],"src":["https://bunpro.jp/grammar_points/540"],"vf":1,"u":31,"g":1,"gp":"gg_N2_13"},{"id":"g2_045","t":"～がち","ko":"자주 ~하는 경향이 있다, ~하기 쉽다","cat":"기타","conn":[{"w":"동사 ます형 어간","f":"忘れ + がち"},{"w":"명사","f":"病気 + がち"}],"rule":["1. 동사를 ます형 어간으로 바꾼다(2그룹 忘れる: 어미 る를 뺀다 → 忘れ).","2. 그 뒤에 がち를 붙인다(忘れがち).","3. 명사에는 바로 붙인다(病気がち).","4. がち는 な형용사처럼 쓴다(忘れがちだ, 忘れがちな人)."],"why":"","nu":"그렇게 되기 쉽다, 자주 그렇게 된다는 뜻으로 대개 바람직하지 않은 경향에 쓴다(忘れがち, 遅れがち, 病気がち). 좋은 일에는 잘 쓰지 않는다(×褒められがち). 주로 의도와 상관없이 그렇게 되어 버리는 일에 쓰고, 단순한 습관에는 よく～する를 쓴다.","cmp":[{"g":"～やすい","d":"성질상 그렇게 되기 쉬움(壊れやすい). がち는 실제로 자주 그런 일이 일어난다는 경향을 말한다."},{"g":"～気味","d":"'약간 ~한 기미가 있다'로 현재 상태에 쓴다(風邪気味)."}],"ex":[{"jp":"私[わたし]は傘[かさ]を電車[でんしゃ]に忘[わす]れがちだ。","ko":"나는 우산을 전철에 자주 두고 내린다."},{"jp":"冬[ふゆ]は運動不足[うんどうぶそく]になりがちだ。","ko":"겨울에는 운동이 부족해지기 쉽다."},{"jp":"弟[おとうと]は小[ちい]さいころ病気[びょうき]がちだった。","ko":"남동생은 어렸을 때 자주 아팠다."}],"dr":[{"t":"make","q":"遅れる → ～がち","a":"遅れがち","hint":"2그룹: る를 빼고 がち"},{"t":"make","q":"休む → ～がち","a":"休みがち","hint":"1그룹 む → み + がち"},{"t":"fill","q":"忙[いそが]しいと、食事[しょくじ]が不規則[ふきそく]になり（　）だ。","a":"がち","opts":["がち","かけ","がい","ながら"]}],"src":["https://www.mlcjapanese.co.jp/n2_04_20.html"],"vf":1,"u":31,"g":1,"gp":"gg_N2_13"},{"id":"g2_050","t":"～か～まいか","ko":"~할까 말까","cat":"기타","conn":[{"w":"1그룹 동사","f":"行こう + か + 行く + まいか"},{"w":"2그룹 동사","f":"食べようか + 食べまいか / 食べるまいか"},{"w":"する","f":"しようか + するまいか / すまいか"}],"rule":["1. 앞 동사를 의지형으로 바꾼다. 行く → 行こう(어미 く를 こ로 바꾸고 う).","2. 의지형 뒤에 か를 붙인다(行こうか).","3. 같은 동사를 다시 쓰고 부정 의지의 まい를 붙인다. 1그룹은 사전형 + まい(行くまい).","4. 2그룹은 ない형 어간 + まい(食べまい)나 사전형 + まい(食べるまい), する는 するまい·すまい로 만들고 끝에 か를 붙인다."],"why":"","nu":"할지 말지 망설이는 마음을 나타내며 뒤에 迷う・悩む・決められない 같은 말이 자주 온다. 앞에 의지형 대신 사전형을 쓰는 형태(行くか行くまいか)도 있다. 문어적인 느낌이 있고 회화에서는 行こうかどうか가 더 흔하다. 형용사나 명사에는 쓰지 않는다.","cmp":[{"g":"～かどうか","d":"할지 안 할지·인지 아닌지를 중립적으로 말하며 회화에서도 흔하다. か～まいか는 망설임을 더 문어적으로 강조한다."}],"ex":[{"jp":"パーティーに行[い]こうか行[い]くまいか、まだ迷[まよ]っている。","ko":"파티에 갈까 말까 아직 망설이고 있다."},{"jp":"彼[かれ]に本当[ほんとう]のことを言[い]おうか言[い]うまいか、一晩中[ひとばんじゅう]悩[なや]んだ。","ko":"그에게 사실을 말할까 말까 밤새 고민했다."},{"jp":"留学[りゅうがく]しようかするまいか、なかなか決[き]められない。","ko":"유학을 할까 말까 좀처럼 정하지 못하겠다."}],"dr":[{"t":"make","q":"買う → ～か～まいか","a":"買おうか買うまいか","hint":"의지형(買おう) + か + 사전형 + まいか"},{"t":"make","q":"話す → ～か～まいか","a":"話そうか話すまいか","hint":"す를 そ로 바꿔 う, 뒤는 話す + まいか"},{"t":"fill","q":"その仕事[しごと]を引[ひ]き受[う]けようか引[ひ]き受[う]ける（　）、迷[まよ]っている。","a":"まいか","opts":["まいか","ばかりか","どころか","ものか"]}],"src":["https://www.gyanmirai.com/jlpt/jlpt-n2/grammar-study/youkamaika"],"vf":1,"u":32,"g":1,"gp":"gg_N2_13"},{"id":"g2_053","t":"～からすると","ko":"~로 보아, ~의 입장에서 보면","cat":"기타","conn":[{"w":"명사","f":"空の様子 + からすると"},{"w":"명사(사람)","f":"子供 + からすると"}],"rule":["1. 명사 뒤에 からすると를 붙인다(様子からすると).","2. 활용하는 부분은 없다. からすれば의 형태도 같은 뜻으로 쓴다.","3. 뒤에는 그 근거·입장에서 본 판단이 온다(雨になりそうだ)."],"why":"","nu":"① 판단의 근거(~로 미루어 보아), ② 누군가의 입장·관점(~의 입장에서 보면)을 나타낸다. 뒤에 だろう·ようだ·そうだ 같은 추측이나 평가가 자주 온다.","cmp":[{"g":"～から見ると","d":"관점·근거를 나타내는 거의 같은 뜻의 표현이다. からすると는 사람의 입장에도 자연스럽게 붙는다."}],"ex":[{"jp":"この空[そら]の様子[ようす]からすると、午後[ごご]は雨[あめ]になりそうだ。","ko":"이 하늘 모양으로 보아 오후에는 비가 올 것 같다."},{"jp":"子供[こども]からすると、大人[おとな]の話[はなし]はつまらないものだ。","ko":"아이 입장에서 보면 어른들의 이야기는 지루한 법이다."},{"jp":"彼[かれ]の発音[はつおん]からすると、関西[かんさい]の人[ひと]だろう。","ko":"그의 발음으로 보아 간사이 사람일 것이다."}],"dr":[{"t":"make","q":"親 → ～からすると","a":"親からすると","hint":"명사 + からすると"},{"t":"make","q":"この結果 → ～からすれば","a":"この結果からすれば","hint":"명사 + からすれば"},{"t":"fill","q":"あの表情[ひょうじょう]（　）、彼[かれ]はかなり疲[つか]れているようだ。","a":"からすると","opts":["からすると","にかけて","をこめて","にわたって"]}],"src":["https://bunpro.jp/grammar_points/340"],"vf":1,"u":32,"g":1,"gp":"gg_N2_13"},{"id":"g2_057","t":"～から見ると","ko":"~의 입장에서 보면, ~로 보아","cat":"기타","conn":[{"w":"명사(사람)","f":"子供 + から見ると"},{"w":"명사","f":"この成績 + から見ると"}],"rule":["1. 명사 뒤에 から見ると를 붙인다(子供から見ると).","2. 활용하는 부분은 없다. から見れば・から見て도 같은 뜻으로 쓴다.","3. 뒤에는 그 관점·근거에서 본 판단이 온다."],"why":"","nu":"① 어떤 사람·입장의 관점, ② 판단의 근거를 나타낸다. 뒤에는 평가나 추측이 온다. 문자 그대로 '~에서 봤다'는 행동이 아니라 관점이라는 점에 주의한다.","cmp":[{"g":"～からすると","d":"거의 같은 뜻이다. から見ると는 '보는 시점'이라는 이미지가 더 분명하다."}],"ex":[{"jp":"子供[こども]から見[み]ると、大人[おとな]はとても大[おお]きい。","ko":"아이 입장에서 보면 어른은 무척 크다."},{"jp":"外国人[がいこくじん]から見[み]ると、日本[にほん]の電車[でんしゃ]はとても静[しず]かだそうだ。","ko":"외국인이 보기에 일본 전철은 아주 조용하다고 한다."},{"jp":"この成績[せいせき]から見[み]ると、合格[ごうかく]は難[むずか]しいだろう。","ko":"이 성적으로 보아 합격은 어려울 것이다."}],"dr":[{"t":"make","q":"若い人 → ～から見ると","a":"若い人から見ると","hint":"명사 + から見ると"},{"t":"make","q":"専門家 → ～から見れば","a":"専門家から見れば","hint":"명사 + から見れば"},{"t":"fill","q":"親[おや]（　）、子供[こども]はいつまでも子供[こども]だ。","a":"から見ると","opts":["から見ると","に比べて","にかけて","をはじめ"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/から見ると-kara-miru-to-meaning"],"vf":1,"u":32,"g":1,"gp":"gg_N2_13"},{"id":"g2_058","t":"～から言うと","ko":"~(기준)으로 말하자면, ~면에서 보면","cat":"기타","conn":[{"w":"명사","f":"値段 + から言うと"},{"w":"명사","f":"便利さ + から言えば"}],"rule":["1. 판단 기준이 되는 명사 뒤에 から言うと를 붙인다(値段から言うと).","2. 활용하는 부분은 없다. から言えば・から言って도 같은 뜻으로 쓴다.","3. 뒤에는 그 기준으로 본 판단·평가가 온다."],"why":"","nu":"값·질·편리함 같은 '기준'의 면에서 판단할 때 쓴다. 사람 명사에는 붙이지 않으므로 '내 입장에서 말하면'은 私から見ると・私からすると를 쓴다. 비교하는 말(ほうがいい, 一番)과 잘 어울린다.","cmp":[{"g":"～から見ると","d":"사람의 관점에도 쓸 수 있다. から言うと는 기준(값·질 등)에 쓰고 사람에는 쓰지 않는다."}],"ex":[{"jp":"値段[ねだん]から言[い]うと、こちらのほうがお得[とく]だ。","ko":"가격으로 말하자면 이쪽이 더 이득이다."},{"jp":"経験[けいけん]から言[い]うと、彼[かれ]がリーダーに一番[いちばん]向[む]いている。","ko":"경험 면에서 보면 그가 리더에 가장 적합하다."},{"jp":"便利[べんり]さから言[い]えば、駅前[えきまえ]のアパートがいい。","ko":"편리함으로 말하자면 역 앞 아파트가 좋다."}],"dr":[{"t":"make","q":"味 → ～から言うと","a":"味から言うと","hint":"명사 + から言うと"},{"t":"make","q":"広さ → ～から言えば","a":"広さから言えば","hint":"명사 + から言えば"},{"t":"fill","q":"品質[ひんしつ]（　）、この店[みせ]の商品[しょうひん]が一番[いちばん]だ。","a":"から言うと","opts":["から言うと","にかけて","に対して","とともに"]}],"src":["https://nihongokyoshi-net.com/2019/05/27/jlptn2-grammar-karaiuto/"],"vf":1,"u":32,"g":1,"gp":"gg_N2_13"},{"id":"g2_093","t":"～とおり(に)・～どおり(に)","ko":"~대로","cat":"기타","conn":[{"w":"동사 た형","f":"言った + とおりに"},{"w":"동사 사전형","f":"言う + とおりに"},{"w":"명사 + の","f":"地図の + とおりに"},{"w":"명사(직접)","f":"予定 + どおりに"}],"rule":["1. 동사를 た형으로 만든다. 言う → 言った(う를 った로).","2. 그 뒤에 とおりに를 붙인다(言ったとおりに).","3. 명사는 の를 넣어 とおり를 붙이거나(地図のとおりに), 명사에 바로 붙여 と를 탁음 ど로 바꾼 どおり를 쓴다(予定どおりに)."],"why":"","nu":"앞의 말·지시·예상과 똑같은 방식이나 상태임을 나타낸다. 동사를 꾸밀 때는 とおりに, 명사를 꾸밀 때는 とおりの(予想どおりの結果), 문장 끝에서는 とおりだ(思ったとおりだ)가 된다. 명사에 바로 붙일 때는 반드시 どおり로 읽고 쓴다. 한자로 通り라고도 쓴다.","cmp":[{"g":"～ように","d":"先生が言ったように처럼 '~처럼, ~한 바와 같이'로 뜻이 넓다. ～とおりに는 그 내용과 똑같이 따른다는 느낌이 더 강하다."}],"ex":[{"jp":"先生[せんせい]が言[い]ったとおりに、もう一度[いちど]やってみてください。","ko":"선생님이 말씀하신 대로 한 번 더 해 보세요."},{"jp":"地図[ちず]のとおりに歩[ある]いたら、すぐ駅[えき]に着[つ]いた。","ko":"지도대로 걸었더니 금방 역에 도착했다."},{"jp":"工事[こうじ]は予定[よてい]どおりに終[お]わった。","ko":"공사는 예정대로 끝났다."}],"dr":[{"t":"make","q":"聞く → ～とおりに","a":"聞いたとおりに","hint":"く를 いた로 바꾼 た형 + とおりに"},{"t":"make","q":"計画 → ～どおりに","a":"計画どおりに","hint":"명사에 바로 붙이면 どおり"},{"t":"fill","q":"説明書[せつめいしょ]の（　）組[く]み立[た]てたら、うまくできた。","a":"とおりに","opts":["とおりに","ために","うちに","せいで"]}],"src":["https://bunpro.jp/grammar_points/289"],"vf":1,"u":32,"g":1,"gp":"gg_N2_13"},{"id":"g2_097","t":"～どころではない","ko":"~할 상황이 아니다, ~할 때가 아니다","cat":"기타","conn":[{"w":"동사 사전형","f":"遊ぶ + どころではない"},{"w":"명사","f":"旅行 + どころではない"}],"rule":["1. 동사는 사전형을 그대로 쓴다(遊ぶ).","2. 그 뒤에 どころではない를 붙인다(遊ぶどころではない).","3. 명사는 바로 붙인다(旅行どころではない)."],"why":"","nu":"다른 사정(바쁨·병·걱정 등) 때문에 마음이나 시간의 여유가 없어서 그런 일을 할 형편이 아니라는 뜻이다. 앞에는 즐기는 일·평소에 하는 일이 자주 온다. 회화에서는 どころじゃない, 과거는 どころではなかった. 뒤에 다른 말이 이어지는 ～どころか(~는커녕)와 구별할 것.","cmp":[{"g":"～どころか","d":"앞의 내용을 부정하고 뒤에 반대 사실을 잇는 접속 표현이다. ～どころではない는 문장 끝에서 '그럴 형편이 아니다'로 끝난다."}],"ex":[{"jp":"試験[しけん]が近[ちか]くて、遊[あそ]ぶどころではない。","ko":"시험이 가까워서 놀 상황이 아니다."},{"jp":"熱[ねつ]があって、旅行[りょこう]どころではなかった。","ko":"열이 나서 여행할 상황이 아니었다."},{"jp":"隣[となり]の工事[こうじ]がうるさくて、勉強[べんきょう]どころではない。","ko":"옆집 공사가 시끄러워서 공부할 상황이 아니다."}],"dr":[{"t":"make","q":"花見 → ～どころではない","a":"花見どころではない","hint":"명사에 바로 どころではない"},{"t":"make","q":"寝る → ～どころではない","a":"寝るどころではない","hint":"사전형 그대로 + どころではない"},{"t":"fill","q":"引[ひ]っ越[こ]しの準備[じゅんび]で忙[いそが]しくて、パーティー（　）。","a":"どころではない","opts":["どころではない","にすぎない","にほかならない","に限る"]}],"src":["https://bunpro.jp/grammar_points/422"],"vf":1,"u":33,"g":1,"gp":"gg_N2_13"},{"id":"g2_101","t":"～とは限らない","ko":"(반드시) ~라고는 할 수 없다","cat":"기타","conn":[{"w":"동사 보통형","f":"できる + とは限らない"},{"w":"い형용사","f":"おいしい + とは限らない"},{"w":"な형용사","f":"幸せだ + とは限らない"},{"w":"명사","f":"日本人だ + とは限らない"}],"rule":["1. な형용사 어간에 だ를 붙인다. 幸せ → 幸せだ.","2. 그 뒤에 とは를 붙인다(幸せだとは).","3. 마지막에 限らない를 붙인다(幸せだとは限らない). 동사·い형용사는 보통형에 그대로 붙인다(おいしいとは限らない)."],"why":"","nu":"일반적으로 그렇게 생각되는 일에도 예외가 있다는 부분 부정이다. 必ずしも・いつも・誰でも 같은 말과 자주 함께 쓴다. 명사·な형용사 뒤에는 だ를 넣는 것이 기본형이다. '절대 아니다'라는 전면 부정이 아니라 '꼭 그렇지는 않다'는 뜻임에 주의.","cmp":[{"g":"～わけではない","d":"'(특별히) ~라는 것은 아니다'로 상대의 추측이나 자기 말을 부분적으로 부정한다. ～とは限らない는 일반적인 통념에 예외가 있다고 말한다."}],"ex":[{"jp":"高[たか]い料理[りょうり]がおいしいとは限[かぎ]らない。","ko":"비싼 요리가 맛있다고는 할 수 없다."},{"jp":"有名[ゆうめい]な大学[だいがく]を出[で]た人[ひと]が、必[かなら]ずしも仕事[しごと]ができるとは限[かぎ]らない。","ko":"유명한 대학을 나온 사람이 반드시 일을 잘하는 것은 아니다."},{"jp":"お金持[かねも]ちが幸[しあわ]せだとは限[かぎ]らない。","ko":"부자가 꼭 행복한 것은 아니다."}],"dr":[{"t":"make","q":"正しい → ～とは限らない","a":"正しいとは限らない","hint":"い형용사는 그대로 + とは限らない"},{"t":"make","q":"安全だ → ～とは限らない","a":"安全だとは限らない","hint":"な형용사는 だ + とは限らない"},{"t":"fill","q":"先生[せんせい]の言[い]うことがいつも正[ただ]しい（　）。","a":"とは限らない","opts":["とは限らない","ばかりか","どころか","とともに"]}],"src":["https://bunpro.jp/grammar_points/278"],"vf":1,"u":33,"g":1,"gp":"gg_N2_13"},{"id":"g2_102","t":"～ないことはない","ko":"~하지 못할 것은 없다, ~할 수는 있다","cat":"기타","conn":[{"w":"동사 가능형의 ない형","f":"読めない + ことはない"},{"w":"동사 ない형","f":"間に合わない + ことはない"},{"w":"い형용사","f":"寂しくない + ことはない"}],"rule":["1. 동사를 가능형으로 만든다. 読む → 読める(む를 め로 바꾸고 る).","2. 가능형의 る를 ない로 바꾼다(読めない).","3. 그 뒤에 ことはない를 붙인다(読めないことはない). い형용사는 い를 くない로 바꾸어 붙인다(寂しくないことはない)."],"why":"","nu":"부정을 다시 부정해 '전혀 안 되는 것은 아니다'라고 소극적으로 긍정한다. 완전히 자신 있지는 않거나 내키지 않는 느낌이 있고, 뒤에 が・けど로 조건이나 불만이 이어지기 쉽다. ～ないこともない는 더 완곡하다. 사전형 + ことはない(行くことはない = 갈 필요 없다)와는 뜻이 전혀 다르다.","cmp":[{"g":"동사 사전형 + ことはない","d":"'~할 필요는 없다'는 뜻이다(心配することはない). ～ないことはない는 '~할 수는 있다'는 소극적 긍정이다."}],"ex":[{"jp":"少[すこ]し高[たか]いけど、買[か]えないことはない。","ko":"조금 비싸지만 못 살 것은 없다."},{"jp":"急[いそ]げば、間[ま]に合[あ]わないことはないよ。","ko":"서두르면 못 맞출 것도 없어."},{"jp":"一人[ひとり]で住[す]むのは寂[さび]しくないことはないが、もう慣[な]れた。","ko":"혼자 사는 것이 외롭지 않은 것은 아니지만 이제 익숙해졌다."}],"dr":[{"t":"make","q":"食べる → (가능) ～ないことはない","a":"食べられないことはない","hint":"2그룹 가능형 食べられる → る를 ない로 + ことはない"},{"t":"make","q":"作る → (가능) ～ないことはない","a":"作れないことはない","hint":"る를 れ로 바꾼 가능형 作れる → る를 ない로 + ことはない"},{"t":"fill","q":"歩[ある]いて行[い]けない（　）が、バスのほうが楽[らく]だ。","a":"ことはない","opts":["ことはない","ものか","ばかりか","どころか"]}],"src":["https://nihongokyoshi-net.com/2019/05/17/jlptn2-grammar-naikotowanai"],"vf":1,"u":33,"g":1,"gp":"gg_N2_14"},{"id":"g2_111","t":"～にしたら","ko":"~의 입장에서 보면, ~로서는","cat":"기타","conn":[{"w":"명사(사람)","f":"子ども + にしたら"},{"w":"명사(조직·동물)","f":"会社 + にしたら"}],"rule":["1. 사람이나 조직을 나타내는 명사 뒤에 그대로 にしたら를 붙인다. 子ども → 子どもにしたら.","2. 같은 뜻으로 にすれば, にしてみれば도 쓴다.","3. 뒤에는 だろう・かもしれない・と思う 같은 추측 표현이 자주 온다."],"why":"조사 に + する의 たら형 したら로 이루어져 '~의 입장이 된다면'이라는 뜻이 된다.","nu":"다른 사람(혹은 동물·조직)의 입장에 서서 그 사람의 기분이나 생각을 짐작해 말하는 표현이다. 그래서 문장 끝은 추측(だろう, かもしれない)이 되는 경우가 많다. 주로 제3자에게 쓰며, 사물이나 일반적인 평가 기준을 말할 때는 ～にとって를 쓰는 것이 자연스럽다. 회화체에 가깝다.","cmp":[{"g":"～にとって","d":"'~에게 있어'라는 평가의 기준이다(健康にとって大切だ). 사람 아닌 것에도 쓰고, 뒤에 大切だ・難しい 같은 판단이 온다."},{"g":"～にしてみれば","d":"뜻은 거의 같고 '그 사람 입장이 되어 보면'이라는 느낌이 조금 더 강하다."}],"ex":[{"jp":"親[おや]は喜[よろこ]んでいるが、子[こ]どもにしたら美術館[びじゅつかん]はつまらないだろう。","ko":"부모는 좋아하지만 아이 입장에서 보면 미술관은 지루하겠지."},{"jp":"急[きゅう]に予定[よてい]を変[か]えられて、彼[かれ]にしたら迷惑[めいわく]だったかもしれない。","ko":"갑자기 일정이 바뀌어서 그의 입장에서는 폐가 되었을지도 모른다."},{"jp":"店[みせ]にしたら、雨[あめ]の日[ひ]は客[きゃく]が少[すく]なくて困[こま]るだろう。","ko":"가게 입장에서는 비 오는 날은 손님이 적어서 곤란할 것이다."}],"dr":[{"t":"make","q":"母 → ～にしたら","a":"母にしたら","hint":"사람 명사 + にしたら"},{"t":"make","q":"学生 → ～にしたら","a":"学生にしたら","hint":"사람 명사 + にしたら"},{"t":"fill","q":"毎日[まいにち]残業[ざんぎょう]させられる社員[しゃいん]（　）、つらいだろう。","a":"にしたら","opts":["にしたら","にかけては","において","にしたがって"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AB%E3%81%97%E3%81%9F%E3%82%89"],"vf":1,"u":33,"g":1,"gp":"gg_N2_14"},{"id":"g2_121","t":"～に反して","ko":"~에 반하여, ~와 달리","cat":"기타","conn":[{"w":"명사","f":"予想 + に反して"},{"w":"명사 수식","f":"予想 + に反する/に反した + 結果"}],"rule":["1. 동사 反する(반하다)의 어미 する를 し로 바꾼다.","2. し 뒤에 て를 붙여 反して를 만든다(する → して).","3. 앞의 명사에 조사 に를 붙여 명사 + に反して 형태로 쓴다. 명사를 꾸밀 때는 に反する/に反した + 명사."],"why":"","nu":"주로 予想・期待・予報 같은 '예상' 명사에 붙어 결과가 예상과 반대였음을 말하고, 規則・法律・意志 같은 명사에 붙어 그것을 거슬러 행동함을 나타낸다. 문어적이고 딱딱한 표현이다. 회화에서는 '予想と違って'가 더 자연스럽다.","cmp":[{"g":"～に対して","d":"に対して는 동작의 대상이나 두 가지의 대비를 나타낸다. に反して는 예상·규칙과 '반대로 됨, 거스름'을 나타낸다."}],"ex":[{"jp":"予想[よそう]に反[はん]して、試合[しあい]は弱[よわ]いチームが勝[か]った。","ko":"예상과 달리 시합은 약한 팀이 이겼다."},{"jp":"天気予報[てんきよほう]に反[はん]して、午後[ごご]から雨[あめ]が降[ふ]りだした。","ko":"일기예보와 달리 오후부터 비가 내리기 시작했다."},{"jp":"規則[きそく]に反[はん]する行為[こうい]は許[ゆる]されない。","ko":"규칙에 반하는 행위는 허용되지 않는다."}],"dr":[{"t":"make","q":"期待 → ～に反して","a":"期待に反して","hint":"명사 + に + 反して(する → して)"},{"t":"make","q":"法律 + 行為 → ～に反する + 명사","a":"法律に反する行為","hint":"명사를 꾸밀 때는 に反する + 명사"},{"t":"fill","q":"大方[おおかた]の予想[よそう]に（　）、新人[しんじん]が優勝[ゆうしょう]した。","a":"反して","opts":["反して","沿って","基づいて","応じて"]}],"src":["https://nihongokyoshi-net.com/2018/09/22/jlptn3-grammar-hanshite/","https://bunpro.jp/grammar_points/543"],"vf":1,"u":33,"g":1,"gp":"gg_N2_14"},{"id":"g2_122","t":"～に基づいて","ko":"~에 근거하여, ~을 바탕으로","cat":"기타","conn":[{"w":"명사","f":"データ + に基づいて"},{"w":"명사 수식","f":"事実 + に基づく/に基づいた + 話"}],"rule":["1. 1그룹 동사 基づく(근거하다)의 어미 く를 い로 바꾼다(イ음편).","2. 그 뒤에 て를 붙여 基づいて를 만든다(く → いて).","3. 앞의 명사에 に를 붙여 명사 + に基づいて로 쓴다. 명사를 꾸밀 때는 に基づく/に基づいた + 명사."],"why":"","nu":"자료・사실・법률・경험 등을 근거나 기준으로 삼아 무언가를 한다는 뜻이다. 문어적이며 보고서・뉴스에서 많이 쓴다. 더 딱딱한 문장에서는 て 대신 に基づき를 쓴다. 기준이 되는 것이 구체적인 근거일 때 쓰며, 단순한 '~에 따라 변한다'는 に応じて를 쓴다.","cmp":[{"g":"～をもとに","d":"をもとに는 소재・힌트로 삼아 새로 만든다는 느낌이고, に基づいて는 근거・기준에서 벗어나지 않는다는 느낌이 강하다."}],"ex":[{"jp":"調査[ちょうさ]のデータに基[もと]づいて、計画[けいかく]を立[た]てた。","ko":"조사 데이터를 바탕으로 계획을 세웠다."},{"jp":"この映画[えいが]は事実[じじつ]に基[もと]づいて作[つく]られた。","ko":"이 영화는 사실에 근거하여 만들어졌다."},{"jp":"法律[ほうりつ]に基[もと]づく手続[てつづ]きが必要[ひつよう]だ。","ko":"법률에 근거한 절차가 필요하다."}],"dr":[{"t":"make","q":"経験 → ～に基づいて","a":"経験に基づいて","hint":"基づく의 く를 いて로 바꿔 명사 + に 뒤에"},{"t":"make","q":"事実 + 話 → ～に基づいた + 명사","a":"事実に基づいた話","hint":"명사 수식은 に基づいた + 명사"},{"t":"fill","q":"アンケートの結果[けっか]に（　）、新[あたら]しい商品[しょうひん]を開発[かいはつ]した。","a":"基づいて","opts":["基づいて","反して","際して","過ぎず"]}],"src":["https://nihongokyoshi-net.com/2018/07/02/jlptn2-grammar-motoduite/"],"vf":1,"u":34,"g":1,"gp":"gg_N2_14"},{"id":"g2_124","t":"～に応えて","ko":"~에 부응하여, ~에 응하여","cat":"기타","conn":[{"w":"명사","f":"期待 + に応えて"},{"w":"명사 수식","f":"要望 + に応える/に応えた + 商品"}],"rule":["1. 2그룹 동사 応える(부응하다)의 어미 る를 뗀다.","2. 남은 応え 뒤에 て를 붙여 応えて를 만든다(る → て).","3. 앞의 명사에 に를 붙여 명사 + に応えて로 쓴다. 명사를 꾸밀 때는 に応える/に応えた + 명사."],"why":"","nu":"期待・要望・声援・声 같이 '상대가 바라는 것' 명사에 붙어 그 바람을 이루어 주려고 행동함을 나타낸다. 주로 긍정적인 결과와 함께 쓰며 다소 격식 있는 표현이다. 질문에 '대답하다'의 答える와 한자가 다르니 주의.","cmp":[{"g":"～に応じて","d":"に応じて는 상황・조건의 변화에 '맞춰' 바꾼다는 뜻이다. に応えて는 기대・요구를 '채워 준다'는 뜻이다."}],"ex":[{"jp":"ファンの声援[せいえん]に応[こた]えて、選手[せんしゅ]は手[て]を振[ふ]った。","ko":"팬들의 성원에 응하여 선수는 손을 흔들었다."},{"jp":"お客様[きゃくさま]の要望[ようぼう]に応[こた]えて、営業時間[えいぎょうじかん]を延[の]ばした。","ko":"손님들의 요망에 부응하여 영업시간을 늘렸다."},{"jp":"親[おや]の期待[きたい]に応[こた]えたいと思[おも]っている。","ko":"부모님의 기대에 부응하고 싶다고 생각한다."}],"dr":[{"t":"make","q":"声援 → ～に応えて","a":"声援に応えて","hint":"応える의 る를 떼고 て, 명사 + に 뒤에"},{"t":"make","q":"要望 + 商品 → ～に応えた + 명사","a":"要望に応えた商品","hint":"명사 수식은 に応えた + 명사"},{"t":"fill","q":"市民[しみん]の要望[ようぼう]に（　）、駅前[えきまえ]に図書館[としょかん]が作[つく]られた。","a":"応えて","opts":["応えて","反して","際して","過ぎない"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AB%E5%BF%9C%E3%81%88%E3%81%A6"],"vf":1,"u":34,"g":1,"gp":"gg_N2_14"},{"id":"g2_125","t":"～に応じて","ko":"~에 따라, ~에 맞춰","cat":"기타","conn":[{"w":"명사","f":"量 + に応じて"},{"w":"명사 수식","f":"能力 + に応じた + 仕事"}],"rule":["1. 2그룹 동사 応じる(응하다)의 어미 る를 뗀다.","2. 남은 応じ 뒤에 て를 붙여 応じて를 만든다(る → て).","3. 앞의 명사에 に를 붙여 명사 + に応じて로 쓴다. 명사를 꾸밀 때는 に応じた + 명사."],"why":"","nu":"앞의 명사(양・정도・상황・요구 등)가 달라지면 그에 맞춰 뒤의 일도 달라진다는 뜻이다. 年齢・季節・能力・必要 같은 변하는 기준과 잘 어울린다. 격식체·문어체에서도 회화에서도 쓴다. 딱딱한 문장에서는 に応じ도 쓴다.","cmp":[{"g":"～によって","d":"によって는 '~에 따라 다르다'처럼 차이를 말할 때 널리 쓴다. に応じて는 기준에 '맞추어 조정한다'는 의도가 강하다."}],"ex":[{"jp":"仕事[しごと]の量[りょう]に応[おう]じて、給料[きゅうりょう]が変[か]わる。","ko":"일의 양에 따라 급여가 바뀐다."},{"jp":"季節[きせつ]に応[おう]じて、メニューを変[か]えている。","ko":"계절에 맞춰 메뉴를 바꾸고 있다."},{"jp":"レベルに応[おう]じたクラスを選[えら]んでください。","ko":"레벨에 맞는 반을 골라 주세요."}],"dr":[{"t":"make","q":"年齢 → ～に応じて","a":"年齢に応じて","hint":"応じる의 る를 떼고 て, 명사 + に 뒤에"},{"t":"make","q":"能力 + 仕事 → ～に応じた + 명사","a":"能力に応じた仕事","hint":"명사 수식은 に応じた + 명사"},{"t":"fill","q":"参加者[さんかしゃ]の人数[にんずう]に（　）、部屋[へや]の大[おお]きさを決[き]める。","a":"応じて","opts":["応じて","反して","過ぎず","際して"]}],"src":["https://nihongokyoshi-net.com/2019/04/29/jlptn2-grammar-oujite/","https://bunpro.jp/grammar_points/%E3%81%AB%E5%BF%9C%E3%81%88%E3%81%A6"],"vf":1,"u":34,"g":1,"gp":"gg_N2_14"},{"id":"g2_127","t":"～に沿って","ko":"~을 따라; ~에 맞춰","cat":"기타","conn":[{"w":"명사","f":"川 + に沿って"},{"w":"명사 수식","f":"方針 + に沿った + 計画"}],"rule":["1. 1그룹 동사 沿う(따르다)의 어미 う를 っ로 바꾼다(촉음편).","2. 그 뒤에 て를 붙여 沿って를 만든다(う → って).","3. 앞의 명사에 に를 붙여 명사 + に沿って로 쓴다. 명사를 꾸밀 때는 に沿った + 명사."],"why":"","nu":"두 가지로 쓴다. ① 川・道・線路 같은 길고 이어진 것을 따라 이동하거나 늘어섬 ② 方針・計画・希望・マニュアル 같은 기준에 어긋나지 않게 맞춤. ②는 격식 있는 표현이며 딱딱한 문장에서는 に沿い도 쓴다.","cmp":[{"g":"～に基づいて","d":"に基づいて는 근거(데이터・사실)를 바탕으로 삼는다. に沿って는 정해진 방향・방침에서 벗어나지 않게 따른다."}],"ex":[{"jp":"川[かわ]に沿[そ]って歩[ある]いていくと、橋[はし]が見[み]えてきます。","ko":"강을 따라 걸어가면 다리가 보입니다."},{"jp":"会社[かいしゃ]の方針[ほうしん]に沿[そ]って、計画[けいかく]を変更[へんこう]した。","ko":"회사 방침에 맞춰 계획을 변경했다."},{"jp":"お客様[きゃくさま]の希望[きぼう]に沿[そ]ったプランを考[かんが]えます。","ko":"손님의 희망에 맞는 플랜을 생각하겠습니다."}],"dr":[{"t":"make","q":"線路 → ～に沿って","a":"線路に沿って","hint":"沿う의 う를 って로 바꿔 명사 + に 뒤에"},{"t":"make","q":"マニュアル + 説明 → ～に沿った + 명사","a":"マニュアルに沿った説明","hint":"명사 수식은 に沿った + 명사"},{"t":"fill","q":"道[みち]に（　）、桜[さくら]の木[き]が並[なら]んでいる。","a":"沿って","opts":["沿って","反して","際して","限り"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AB%E6%B2%BF%E3%81%A3%E3%81%A6"],"vf":1,"u":34,"g":1,"gp":"gg_N2_14"},{"id":"g2_129","t":"～に関わって","ko":"~에 관여하여, ~에 관계되어","cat":"기타","conn":[{"w":"명사","f":"計画 + に関わって"},{"w":"명사 수식","f":"命 + に関わる + 問題"}],"rule":["1. 1그룹 동사 関わる(관계되다)의 어미 る를 っ로 바꾼다(촉음편).","2. 그 뒤에 て를 붙여 関わって를 만든다(る → って).","3. 앞의 명사에 に를 붙여 명사 + に関わって로 쓴다. 명사를 꾸밀 때는 に関わる + 명사."],"why":"","nu":"어떤 일・활동에 직접 관여하거나, 어떤 일이 중요한 것과 관계됨을 나타낸다. に関わる + 명사 형태로 命・名誉・将来처럼 중대한 것에 '영향을 미치는'의 뜻으로 많이 쓴다. 단순히 '~에 대해 말하다'처럼 주제만 말할 때는 について가 자연스럽다.","cmp":[{"g":"～に関して","d":"に関して는 '~에 관해서'처럼 화제・주제를 나타낸다. に関わる/に関わって는 실제로 관여하거나 중대한 영향을 주고받는 관계를 나타낸다."}],"ex":[{"jp":"彼[かれ]は長[なが]い間[あいだ]、町[まち]の祭[まつ]りの準備[じゅんび]に関[かか]わってきた。","ko":"그는 오랫동안 마을 축제 준비에 관여해 왔다."},{"jp":"このプロジェクトに関[かか]わっている人[ひと]は、全員[ぜんいん]会議[かいぎ]に出[で]てください。","ko":"이 프로젝트에 관여하고 있는 사람은 전원 회의에 나와 주세요."},{"jp":"命[いのち]に関[かか]わる病気[びょうき]ではないので、安心[あんしん]してください。","ko":"생명에 관계되는 병은 아니니 안심하세요."}],"dr":[{"t":"make","q":"教育 → ～に関わって","a":"教育に関わって","hint":"関わる의 る를 って로 바꿔 명사 + に 뒤에"},{"t":"make","q":"将来 + 問題 → ～に関わる + 명사","a":"将来に関わる問題","hint":"명사 수식은 に関わる + 명사"},{"t":"fill","q":"これは会社[かいしゃ]の信用[しんよう]に（　）重大[じゅうだい]な問題[もんだい]だ。","a":"関わる","opts":["関わる","過ぎない","限り","際して"]}],"src":["https://nihongokyoshi-net.com/2019/06/05/jlptn1-grammar-nikakawaru"],"vf":1,"u":34,"g":1,"gp":"gg_N2_14"},{"id":"g2_135","t":"～の上では","ko":"~상으로는","cat":"기타","conn":[{"w":"명사","f":"暦 + の上では"},{"w":"명사","f":"数字 + の上では"}],"rule":["1. 활용은 없다. 명사 뒤에 の上では를 붙인다(暦の上では).","2. 그 뒤에 그 기준에서 본 판단을 쓰고, 흔히 が・けれど로 실제 상황과 대비한다(暦の上では春だが、まだ寒い)."],"why":"","nu":"暦・数字・計算・データ・法律・書類처럼 '형식상의 기준'을 나타내는 명사에 붙어, 그 기준으로 보면 그렇다는 뜻이다. 실제와는 다르다는 대비가 뒤따르는 경우가 많다. 다소 문어적이다. 上는 うえ로 읽는다. 한자어 명사 + 上(じょう)(法律上, 計算上)도 비슷한 뜻이다.","cmp":[{"g":"～上(じょう)","d":"法律上・計算上처럼 한자어 명사에 직접 붙는 짧은 문어 표현이다. の上では는 '~으로는 그렇지만 (실제는)'이라는 대비가 더 잘 드러난다."}],"ex":[{"jp":"暦[こよみ]の上[うえ]では春[はる]だが、まだ雪[ゆき]が降[ふ]っている。","ko":"달력상으로는 봄이지만 아직 눈이 내리고 있다."},{"jp":"数字[すうじ]の上[うえ]では景気[けいき]は良[よ]くなっているが、生活[せいかつ]は楽[らく]にならない。","ko":"수치상으로는 경기가 좋아지고 있지만 생활은 편해지지 않는다."},{"jp":"計算[けいさん]の上[うえ]では、明日[あした]までに終[お]わるはずだ。","ko":"계산상으로는 내일까지 끝날 것이다."}],"dr":[{"t":"make","q":"データ → ～の上では","a":"データの上では","hint":"명사 + の上では"},{"t":"make","q":"書類 → ～の上では","a":"書類の上では","hint":"명사 + の上では"},{"t":"fill","q":"暦[こよみ]の（　）もう秋[あき]なのに、毎日[まいにち]暑[あつ]い。","a":"上では","opts":["上では","下で","ばかりか","のみならず"]}],"src":["https://nihongokyoshi-net.com/2019/05/30/jlptn0-grammar-jouno/"],"vf":1,"u":35,"g":1,"gp":"gg_N2_14"},{"id":"g2_136","t":"～の下で","ko":"~의 아래에서, ~하에서","cat":"기타","conn":[{"w":"명사","f":"先生 + の下で"},{"w":"명사","f":"条件 + の下で"}],"rule":["1. 활용은 없다. 명사 뒤에 の를 붙이고 下で를 붙인다(先生の下で).","2. 이 문형에서 下는 もと로 읽는다(のもとで).","3. 명사를 꾸밀 때는 の下での + 명사(先生の下での修業)."],"why":"","nu":"사람(先生・監督・両親)의 지도・보호・영향 아래에서, 또는 조건・상황(条件・約束・ルール) 아래에서 무언가를 한다는 뜻이다. 글에서는 もと를 ひらがな나 下・元로 쓴다. 물리적인 '아래'(机の下で)는 した로 읽는 별개의 표현이니 구별해야 한다.","cmp":[{"g":"～によって","d":"によって는 수단・원인・행위자를 나타낸다. の下で는 지도・영향・조건이라는 '테두리 안에서'를 나타낸다."}],"ex":[{"jp":"有名[ゆうめい]な先生[せんせい]の下[もと]で、絵[え]を学[まな]んでいる。","ko":"유명한 선생님 밑에서 그림을 배우고 있다."},{"jp":"新[あたら]しい監督[かんとく]の下[もと]で、チームは強[つよ]くなった。","ko":"새 감독 아래에서 팀은 강해졌다."},{"jp":"厳[きび]しい条件[じょうけん]の下[もと]で、実験[じっけん]が行[おこな]われた。","ko":"엄격한 조건하에서 실험이 실시되었다."}],"dr":[{"t":"make","q":"両親の愛 → ～の下で","a":"両親の愛の下で","hint":"명사 + の + 下(もと)で"},{"t":"make","q":"新しい社長 → ～の下で","a":"新しい社長の下で","hint":"명사 + の + 下(もと)で"},{"t":"fill","q":"彼[かれ]は祖父[そふ]の（　）、料理[りょうり]の修業[しゅぎょう]をした。","a":"下で","opts":["下で","上では","ばかりか","のみならず"]}],"src":["https://bunpro.jp/grammar_points/686"],"vf":1,"u":35,"g":1,"gp":"gg_N2_14"},{"id":"g2_140","t":"～ば～というものでもない","ko":"~하면 ~하다는 것은 아니다, ~한다고 꼭 ~인 것은 아니다","cat":"기타","conn":[{"w":"동사 ば형","f":"練習すれば + 上手になる + というものでもない"},{"w":"い형용사 ければ","f":"高ければ + いい + というものでもない"},{"w":"な형용사·명사 なら","f":"有名なら + いい + というものでもない"}],"rule":["1. 조건 부분을 ば형으로 만든다. い형용사는 い를 ければ로 바꾼다(高い → 高ければ).","2. 그 뒤에 기대되는 결과를 보통형으로 쓴다(高ければいい).","3. 맨 끝에 というものでもない를 붙인다(高ければいいというものでもない)."],"why":"","nu":"'A이면 당연히 B'라는 일반적인 생각을 '꼭 그렇지만은 않다'고 부분적으로 부정한다. 완전 부정이 아니라 예외가 있다는 뜻이다. '~ばいいというものでもない'처럼 ば～いい 형태가 특히 많이 쓰인다. というものではない로도 쓴다. 의견·주장을 말하는 약간 딱딱한 표현이다.","cmp":[{"g":"～とは限らない","d":"とは限らない는 단순히 '반드시 그런 것은 아니다'라는 가능성 표현이고, というものでもない는 상대나 세상의 생각을 비판하는 주장의 느낌이 더 강하다."}],"ex":[{"jp":"高[たか]ければいいというものでもない。","ko":"비싸면 좋다는 것도 아니다."},{"jp":"たくさん練習[れんしゅう]すれば上手[じょうず]になるというものでもない。","ko":"많이 연습한다고 꼭 잘하게 되는 것은 아니다."},{"jp":"薬[くすり]は多[おお]く飲[の]めば早[はや]く治[なお]るというものでもない。","ko":"약은 많이 먹는다고 빨리 낫는 것도 아니다."}],"dr":[{"t":"make","q":"安い → ～ば売れるというものでもない","a":"安ければ売れるというものでもない","hint":"い를 ければ로 + 결과 + というものでもない"},{"t":"make","q":"勉強する → ～ば合格するというものでもない","a":"勉強すれば合格するというものでもない","hint":"する를 すれば로 + 결과 + というものでもない"},{"t":"fill","q":"お金[かね]があれば幸[しあわ]せだ（　）。","a":"というものでもない","opts":["というものでもない","にすぎない","に違いない","ばかりだ"]}],"src":["https://bunpro.jp/grammar_points/509"],"vf":1,"u":35,"g":1,"gp":"gg_N2_14"},{"id":"g2_144","t":"～は抜きにして","ko":"~은 빼고, ~은 제쳐 두고","cat":"기타","conn":[{"w":"명사","f":"冗談 + は抜きにして"}],"rule":["1. 빼고 싶은 명사 뒤에 조사 は를 붙인다(冗談は).","2. 그 뒤에 抜きにして를 붙인다(冗談は抜きにして).","3. 뒤에 본래 하려는 일을 이어 쓴다(冗談は抜きにして、本題に入ろう)."],"why":"","nu":"보통 해야 할 것·있는 것을 생략하고 넘어가자는 뜻이다. 堅苦しい挨拶は抜きにして(딱딱한 인사는 생략하고)처럼 관용적으로 많이 쓴다. ～を抜きにして(は)～ない 형태는 'A 없이는 B할 수 없다'라는 뜻이 된다. 抜きで, 抜きに로 줄여 쓰기도 한다.","cmp":[{"g":"～はともかく","d":"はともかく는 A를 일단 판단 보류하고 B에 초점을 두는 것이고, は抜きにして는 A를 아예 빼고(생략하고) 진행하는 것이다."}],"ex":[{"jp":"冗談[じょうだん]は抜[ぬ]きにして、本題[ほんだい]に入[はい]りましょう。","ko":"농담은 빼고 본론으로 들어갑시다."},{"jp":"堅苦[かたくる]しい挨拶[あいさつ]は抜[ぬ]きにして、さっそく始[はじ]めよう。","ko":"딱딱한 인사는 생략하고 바로 시작하자."},{"jp":"お世辞[せじ]は抜[ぬ]きにして、正直[しょうじき]な意見[いけん]を聞[き]かせてください。","ko":"인사치레는 빼고 솔직한 의견을 들려주세요."}],"dr":[{"t":"make","q":"挨拶 → ～は抜きにして","a":"挨拶は抜きにして","hint":"명사 + は + 抜きにして"},{"t":"make","q":"仕事の話 → ～は抜きにして","a":"仕事の話は抜きにして","hint":"명사 + は + 抜きにして"},{"t":"fill","q":"今日[きょう]は仕事[しごと]の話[はなし]（　）、楽[たの]しく飲[の]みましょう。","a":"は抜きにして","opts":["は抜きにして","にとって","について","に加えて"]}],"src":["https://aiueo.cc/pages/en/grammar/web/453.php"],"vf":1,"u":35,"g":1,"gp":"gg_N2_14"},{"id":"g2_148","t":"～ままに","ko":"~하는 대로, ~에 맡겨","cat":"기타","conn":[{"w":"동사 사전형","f":"気の向く + ままに"},{"w":"동사 수동형","f":"言われる + ままに"},{"w":"명사","f":"心の + ままに"}],"rule":["1. 동사를 사전형으로 둔다(向く).","2. 그 뒤에 ままに를 붙인다(気の向くままに).","3. 명사는 の를 넣어 붙인다(心のままに)."],"why":"","nu":"자기 마음이나 남의 말, 흐름에 그대로 따라 행동한다는 뜻이다. 気の向くままに, 足の向くままに, 思いつくままに, 言われるままに 같은 관용적 표현이 많다. 문어적이다. 상태를 그대로 유지하는 '~たまま(窓を開けたまま)'와는 뜻이 다르므로 주의.","cmp":[{"g":"～たまま","d":"たまま는 어떤 상태가 그대로 계속됨(신발을 신은 채)을 나타내고, ままに는 마음·지시에 따라 행동함을 나타낸다."}],"ex":[{"jp":"休[やす]みの日[ひ]は気[き]の向[む]くままに町[まち]を歩[ある]く。","ko":"쉬는 날에는 마음 가는 대로 동네를 걷는다."},{"jp":"店員[てんいん]に言[い]われるままに、高[たか]い服[ふく]を買[か]ってしまった。","ko":"점원이 하라는 대로 비싼 옷을 사 버렸다."},{"jp":"思[おも]いつくままに日記[にっき]を書[か]いた。","ko":"떠오르는 대로 일기를 썼다."}],"dr":[{"t":"make","q":"思いつく → ～ままに","a":"思いつくままに","hint":"사전형 + ままに"},{"t":"make","q":"心 → ～ままに","a":"心のままに","hint":"명사 + の + ままに"},{"t":"fill","q":"足[あし]の向[む]く（　）、旅[たび]を続[つづ]けた。","a":"ままに","opts":["ままに","うちに","ように","ほどに"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ままに-mama-ni-meaning/"],"vf":1,"u":35,"g":1,"gp":"gg_N2_15"},{"id":"g2_149","t":"～もかまわず","ko":"~도 개의치 않고, ~도 아랑곳하지 않고","cat":"기타","conn":[{"w":"명사","f":"人目 + もかまわず"},{"w":"동사 보통형 + の","f":"ぬれるの + もかまわず"}],"rule":["1. 동사는 보통형 뒤에 の를 붙여 명사로 만든다(ぬれる → ぬれるの).","2. 그 뒤에 も를 붙인다(ぬれるのも).","3. 끝에 かまわず를 붙인다(ぬれるのもかまわず).","4. 명사는 바로 もかまわず를 붙인다(人目もかまわず)."],"why":"かまう(신경 쓰다)의 부정형 かまわない의 문어적 형태 かまわず(신경 쓰지 않고)에 조사 も가 붙은 것이다.","nu":"보통이라면 신경 쓸 일(남의 눈, 비, 시간 등)을 전혀 신경 쓰지 않고 행동한다는 뜻이다. 남의 행동을 비난하는 느낌으로 쓰일 때가 많다. 人目もかまわず(남의 눈도 아랑곳하지 않고)가 대표적이다. 동사에 직접 붙이지 않고 반드시 の를 넣는다.","cmp":[{"g":"～にもかかわらず","d":"にもかかわらず는 '~인데도'라는 역접이고, もかまわず는 '~을 신경 쓰지 않고'라는 행동 태도를 나타낸다."}],"ex":[{"jp":"彼女[かのじょ]は人目[ひとめ]もかまわず大声[おおごえ]で泣[な]いた。","ko":"그녀는 남의 눈도 아랑곳하지 않고 큰 소리로 울었다."},{"jp":"子供[こども]たちは雨[あめ]にぬれるのもかまわず遊[あそ]んでいる。","ko":"아이들은 비에 젖는 것도 개의치 않고 놀고 있다."},{"jp":"彼[かれ]は夜中[よなか]なのもかまわず友達[ともだち]に電話[でんわ]した。","ko":"그는 한밤중인 것도 개의치 않고 친구에게 전화했다."}],"dr":[{"t":"make","q":"服が汚れる → ～もかまわず","a":"服が汚れるのもかまわず","hint":"보통형 + の + もかまわず"},{"t":"make","q":"周り → ～もかまわず","a":"周りもかまわず","hint":"명사 + もかまわず"},{"t":"fill","q":"彼[かれ]は周[まわ]りの迷惑[めいわく]（　）、電車[でんしゃ]の中[なか]で電話[でんわ]をしている。","a":"もかまわず","opts":["もかまわず","をはじめ","に加えて","にこたえて"]}],"src":["https://bunpro.jp/grammar_points/344"],"vf":1,"u":36,"g":1,"gp":"gg_N2_15"},{"id":"g2_157","t":"～も～ば～も～","ko":"~도 ~하고 ~도 ~하다","cat":"기타","conn":[{"w":"동사 ば형","f":"ピアノも弾けば + ギターも弾く"},{"w":"い형용사 ければ","f":"値段も安ければ + 味もいい"},{"w":"な형용사 なら","f":"料理も上手なら + 歌もうまい"}],"rule":["1. 1그룹 동사는 어미 う단을 え단으로 바꾸고 ば를 붙인다. 弾く → 弾け → 弾けば.","2. 2그룹 동사는 る를 빼고 れば(食べる → 食べれば), する → すれば, 来る → 来れば.","3. い형용사는 い를 빼고 ければ(安い → 安ければ), な형용사는 なら를 붙인다(上手なら).","4. 'A도 ~ば B도 ~' 순서로 놓는다: ピアノも弾けばギターも弾く."],"why":"","nu":"같은 대상에 대해 같은 방향의 사항(둘 다 좋은 점, 또는 둘 다 나쁜 점)을 겹쳐 말할 때 주로 쓴다. 여기의 ば는 조건 '~하면'이 아니라 나열의 뜻이므로 '~하면'으로 번역하지 않도록 주의. いい時もあれば悪い時もある처럼 대조되는 것을 나란히 놓아 '~할 때도 있고 ~할 때도 있다'는 뜻으로도 쓴다. 주로 글이나 격식 있는 말에서 쓴다.","cmp":[{"g":"～も～し～も～","d":"彼は頭もいいし、顔もいい처럼 같은 나열이지만 し 쪽이 더 일상적이고 형태 제약이 적다. ～も～ば～も～는 조금 더 정돈된 느낌이다."}],"ex":[{"jp":"彼[かれ]は勉強[べんきょう]もできればスポーツもできる。","ko":"그는 공부도 잘하고 운동도 잘한다."},{"jp":"この店[みせ]は値段[ねだん]も安[やす]ければ味[あじ]もいい。","ko":"이 가게는 가격도 싸고 맛도 좋다."},{"jp":"人生[じんせい]にはいい時[とき]もあれば悪[わる]い時[とき]もある。","ko":"인생에는 좋을 때도 있고 나쁠 때도 있다."}],"dr":[{"t":"make","q":"歌も歌う / ダンスも踊る → ～も～ば～も～","a":"歌も歌えばダンスも踊る","hint":"歌う의 う를 え로 바꿔 歌え + ば"},{"t":"make","q":"部屋も広い / 駅も近い → ～も～ば～も～","a":"部屋も広ければ駅も近い","hint":"い형용사는 い를 빼고 ければ"},{"t":"fill","q":"彼女[かのじょ]は英語[えいご]も話[はな]せ（　）中国語[ちゅうごくご]も話[はな]せる。","a":"ば","opts":["ば","て","たら","ながら"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%82-%E3%81%B0-%E3%82%82","https://dojglite.github.io/main/grammar/dojg_pages/advancedもVばもV.html"],"vf":1,"u":36,"g":1,"gp":"gg_N2_15"},{"id":"g2_159","t":"～やら～やら","ko":"~랑 ~랑, ~하기도 하고 ~하기도 하고","cat":"기타","conn":[{"w":"명사","f":"宿題 + やら"},{"w":"동사 사전형","f":"泣く + やら"},{"w":"い형용사","f":"うれしい + やら"}],"rule":["1. 활용 없이 명사·동사 사전형·い형용사 뒤에 やら를 붙인다.","2. 예를 두 개 이상 들어 'A やら B やら'로 반복한다. 宿題やら掃除やら.","3. 뒤에는 그 결과 '정신없다, 큰일이다' 같은 내용이 자주 온다."],"why":"","nu":"여러 가지 중 몇 가지를 예로 드는 표현으로, 일이 많아 정신없거나 감정이 뒤섞인 상황에 잘 쓴다(うれしいやら恥ずかしいやら = 기쁘기도 하고 부끄럽기도 하고). 단순히 담담하게 나열할 때보다 '이것저것 많아서 힘들다'는 기분이 담기는 경우가 많다.","cmp":[{"g":"～とか～とか","d":"가장 일상적인 회화체 나열로 감정색이 약하다. ～やら～やら는 어수선함이나 복잡한 기분이 담기기 쉽다."}],"ex":[{"jp":"宿題[しゅくだい]やら掃除[そうじ]やらで、週末[しゅうまつ]はとても忙[いそが]しかった。","ko":"숙제랑 청소랑 해서 주말은 무척 바빴다."},{"jp":"試合[しあい]に勝[か]って、みんな泣[な]くやら叫[さけ]ぶやら大騒[おおさわ]ぎだった。","ko":"시합에 이겨서 다들 울고 소리 지르고 난리였다."},{"jp":"みんなの前[まえ]でほめられて、うれしいやら恥[は]ずかしいやら。","ko":"모두 앞에서 칭찬을 받아서 기쁘기도 하고 부끄럽기도 하고."}],"dr":[{"t":"make","q":"洗濯 / 料理 → ～やら～やら","a":"洗濯やら料理やら","hint":"명사 뒤에 그대로 やら를 두 번"},{"t":"make","q":"痛い / かゆい → ～やら～やら","a":"痛いやらかゆいやら","hint":"い형용사 뒤에 그대로 やら"},{"t":"fill","q":"引[ひ]っ越[こ]しの準備[じゅんび]（　）仕事[しごと]（　）で、休[やす]む暇[ひま]がない。","a":"やら","opts":["やら","さえ","こそ","ほど"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%84%E3%82%89-%E3%82%84%E3%82%89"],"vf":1,"u":36,"g":1,"gp":"gg_N2_15"},{"id":"g2_167","t":"～を～として","ko":"~을 ~로 삼아, ~을 ~로서","cat":"기타","conn":[{"w":"명사1 を 명사2","f":"箱を + いす + として"},{"w":"명사1 を 명사2(명사 수식)","f":"子どもを + 対象 + とした + 本"}],"rule":["1. 대상이 되는 명사1 뒤에 を를 붙인다. 箱を.","2. 역할·자격·목적이 되는 명사2를 놓는다. 箱をいす.","3. 그 뒤에 として를 붙인다. 箱をいすとして(使う).","4. 명사를 꾸밀 때는 とした를 쓴다. 子どもを対象とした本."],"why":"","nu":"'A를 B라는 역할·자격·목적으로 삼아' 다음 동작을 한다는 뜻이다. 문어적이며 회화에서는 'AをBにして'도 많이 쓴다. 명사2에는 目的・目標・中心・対象・代表 같은 말이 자주 온다.","cmp":[{"g":"～として","d":"'~로서'로 앞 명사 하나의 자격만 말한다(教師として働く). ～を～として는 'A를 B로' 삼는다는 두 명사의 관계를 말한다."}],"ex":[{"jp":"古[ふる]い箱[はこ]をいすとして使[つか]っている。","ko":"낡은 상자를 의자로 쓰고 있다."},{"jp":"クラスの代表[だいひょう]として田中[たなか]さんを選[えら]んだ。","ko":"반 대표로 다나카 씨를 뽑았다."},{"jp":"この会[かい]は、留学生[りゅうがくせい]の生活[せいかつ]を助[たす]けることを目的[もくてき]として作[つく]られた。","ko":"이 모임은 유학생의 생활을 돕는 것을 목적으로 만들어졌다."}],"dr":[{"t":"make","q":"合格 / 目標 → ～を～として","a":"合格を目標として","hint":"명사1 + を + 명사2 + として"},{"t":"make","q":"子ども / 対象 / 本 → ～を～とした～","a":"子どもを対象とした本","hint":"명사를 꾸밀 때는 とした"},{"t":"fill","q":"彼[かれ]は趣味[しゅみ]の写真[しゃしん]を仕事[しごと]（　）生活[せいかつ]している。","a":"として","opts":["として","にとって","について","によって"]}],"src":[],"vf":0,"u":36,"g":1,"gp":"gg_N2_15"},{"id":"g2_168","t":"～を中心に","ko":"~을 중심으로","cat":"기타","conn":[{"w":"명사","f":"駅 + を中心に"},{"w":"명사(명사 수식)","f":"若者 + を中心とした + ファン"}],"rule":["1. 명사 뒤에 조사 を를 붙인다. 駅を.","2. 그 뒤에 中心に를 붙인다. 駅を中心に.","3. を中心にして, を中心として로도 쓰고, 명사를 꾸밀 때는 を中心とした / を中心にした를 쓴다."],"why":"中心(중심) + に의 구성이다.","nu":"장소·사람·화제 등에서 그것이 중심·핵심이 되어 주변으로 퍼지거나 모인다는 뜻이다. 若者を中心に人気がある(젊은이들 사이를 중심으로 인기)처럼 '주로 ~ 사이에서'의 뜻으로도 많이 쓴다.","cmp":[{"g":"～をはじめ","d":"대표적인 예를 하나 들고 다른 것도 포함한다. ～を中心に는 그것이 핵심·중심이라는 점을 말한다."}],"ex":[{"jp":"駅[えき]を中心[ちゅうしん]に、店[みせ]や家[いえ]が広[ひろ]がっている。","ko":"역을 중심으로 가게와 집들이 퍼져 있다."},{"jp":"このゲームは若者[わかもの]を中心[ちゅうしん]に人気[にんき]がある。","ko":"이 게임은 젊은이들을 중심으로 인기가 있다."},{"jp":"今日[きょう]は文法[ぶんぽう]を中心[ちゅうしん]とした授業[じゅぎょう]をします。","ko":"오늘은 문법을 중심으로 한 수업을 하겠습니다."}],"dr":[{"t":"make","q":"東京 → ～を中心に","a":"東京を中心に","hint":"명사 + を + 中心に"},{"t":"make","q":"会話 / 授業 → ～を中心とした～","a":"会話を中心とした授業","hint":"명사를 꾸밀 때는 を中心とした"},{"t":"fill","q":"台風[たいふう]は九州[きゅうしゅう]（　）大[おお]きな被害[ひがい]を出[だ]した。","a":"を中心に","opts":["を中心に","を問わず","をこめて","をきっかけに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%92%E4%B8%AD%E5%BF%83%E3%81%AB"],"vf":1,"u":36,"g":1,"gp":"gg_N2_15"},{"id":"g2_169","t":"～を問わず","ko":"~을 불문하고, ~에 관계없이","cat":"기타","conn":[{"w":"명사","f":"年齢 + を問わず"},{"w":"대립하는 명사 쌍","f":"男女 / 昼夜 + を問わず"},{"w":"有無","f":"経験の有無 + を問わず"}],"rule":["1. 명사 뒤에 조사 を를 붙인다. 年齢を.","2. 問う의 어미 う를 わ로 바꿔 ない형 어간 問わ를 만든다(1그룹, う로 끝나는 동사는 わ).","3. 부정의 ず를 붙인다. 問わず → 年齢を問わず."],"why":"問う(묻다)의 ない형 어간 問わ + 부정 ず로, '~을 묻지 않고'라는 구성이다.","nu":"나이·성별·경험·날씨처럼 차이가 있을 수 있는 것을 따지지 않는다는 뜻으로, 모집 공고·안내문 등 딱딱한 글에 자주 나온다. 男女・昼夜・内外처럼 대립하는 말의 쌍이나 有無, 의문사가 든 표현과 잘 어울린다. 회화에서는 ～に関係なく가 더 자연스럽다.","cmp":[{"g":"～にかかわらず","d":"뜻은 비슷하며 명사 외에 行く行かない처럼 동사의 긍정·부정 쌍에도 붙는다. ～を問わず는 기본적으로 명사에 붙는다."}],"ex":[{"jp":"このゲームは年齢[ねんれい]を問[と]わず、だれでも楽[たの]しめる。","ko":"이 게임은 나이를 불문하고 누구나 즐길 수 있다."},{"jp":"このアルバイトは経験[けいけん]を問[と]わず応募[おうぼ]できます。","ko":"이 아르바이트는 경험에 관계없이 지원할 수 있습니다."},{"jp":"駅前[えきまえ]のコンビニは昼夜[ちゅうや]を問[と]わず客[きゃく]が多[おお]い。","ko":"역 앞 편의점은 밤낮을 가리지 않고 손님이 많다."}],"dr":[{"t":"make","q":"男女 → ～を問わず","a":"男女を問わず","hint":"명사 + を + 問わず(問う의 う를 わ로 + ず)"},{"t":"make","q":"国籍 → ～を問わず","a":"国籍を問わず","hint":"명사 + を + 問わず"},{"t":"fill","q":"この店[みせ]の料理[りょうり]は季節[きせつ]（　）同[おな]じ値段[ねだん]です。","a":"を問わず","opts":["を問わず","をきっかけに","を中心に","を頼りに"]}],"src":["https://www.bunpro.jp/grammar_points/519"],"vf":1,"u":37,"g":1,"gp":"gg_N2_15"},{"id":"g2_170","t":"～を込めて","ko":"~을 담아","cat":"기타","conn":[{"w":"명사(마음·감정)","f":"心 + を込めて"},{"w":"명사 수식","f":"愛 + を込めた + 手紙"}],"rule":["1. 마음·감정을 나타내는 명사 뒤에 を를 붙인다. 心を.","2. 込める(2그룹)의 る를 빼고 て를 붙여 て형 込めて를 만든다.","3. 뒤에 동작을 이어 말한다. 心を込めて作る. 명사를 꾸밀 때는 を込めた + 명사."],"why":"込める(담다, 채워 넣다)의 て형이다.","nu":"心・愛・感謝・願い・祈り처럼 마음이나 감정을 나타내는 명사와 함께 쓰여, 그 마음을 담아 어떤 행동을 한다는 뜻이다. 뒤에는 作る・書く・歌う・贈る 같은 동작이 온다. '心を込めて'는 '정성껏'으로 옮기면 자연스럽다.","cmp":[],"ex":[{"jp":"母[はは]のために心[こころ]を込[こ]めて料理[りょうり]を作[つく]った。","ko":"어머니를 위해 정성껏 요리를 만들었다."},{"jp":"感謝[かんしゃ]の気持[きも]ちを込[こ]めて、先生[せんせい]に手紙[てがみ]を書[か]いた。","ko":"감사의 마음을 담아 선생님께 편지를 썼다."},{"jp":"これは平和[へいわ]への願[ねが]いを込[こ]めた歌[うた]です。","ko":"이것은 평화에 대한 바람을 담은 노래입니다."}],"dr":[{"t":"make","q":"愛 → ～を込めて","a":"愛を込めて","hint":"명사 + を + 込めて(込める의 る를 て로)"},{"t":"make","q":"祈り / 歌 → ～を込めた～","a":"祈りを込めた歌","hint":"명사를 꾸밀 때는 を込めた"},{"t":"fill","q":"お世話[せわ]になった人[ひと]に、感謝[かんしゃ]（　）花[はな]を贈[おく]った。","a":"を込めて","opts":["を込めて","を問わず","を通じて","を中心に"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/を込めて-をこめて-o-komete-meaning/"],"vf":1,"u":37,"g":1,"gp":"gg_N2_15"},{"id":"g2_171","t":"～を通じて","ko":"~을 통해서, ~ 내내","cat":"기타","conn":[{"w":"명사(매개·수단)","f":"友人 + を通じて"},{"w":"명사(기간)","f":"一年 + を通じて"}],"rule":["1. 명사 뒤에 조사 を를 붙인다. 友人を.","2. 通じる(2그룹)의 る를 빼고 て를 붙여 て형 通じて를 만든다.","3. 명사를 꾸밀 때는 を通じた + 명사(インターネットを通じた販売)."],"why":"通じる(통하다)의 て형이다.","nu":"두 가지 뜻이 있다. ① 사람·매체를 매개로 해서(友人を通じて知り合う, インターネットを通じて). ② 기간 전체에 걸쳐 내내(一年を通じて暖かい). ②의 뜻일 때는 一年・四季・生涯 같은 기간을 나타내는 말이 온다.","cmp":[{"g":"～を通して","d":"거의 같은 뜻으로 바꿔 쓸 수 있는 경우가 많다."}],"ex":[{"jp":"友人[ゆうじん]を通[つう]じて、今[いま]の妻[つま]と知[し]り合[あ]った。","ko":"친구를 통해서 지금의 아내와 알게 되었다."},{"jp":"インターネットを通[つう]じて、世界中[せかいじゅう]の人[ひと]と話[はな]せる。","ko":"인터넷을 통해 전 세계 사람과 이야기할 수 있다."},{"jp":"この島[しま]は一年[いちねん]を通[つう]じて暖[あたた]かい。","ko":"이 섬은 일 년 내내 따뜻하다."}],"dr":[{"t":"make","q":"テレビ → ～を通じて","a":"テレビを通じて","hint":"명사 + を + 通じて(通じる의 る를 て로)"},{"t":"make","q":"四季 → ～を通じて","a":"四季を通じて","hint":"기간 명사 + を通じて = 내내"},{"t":"fill","q":"留学[りゅうがく]（　）、世界中[せかいじゅう]に友達[ともだち]ができた。","a":"を通じて","opts":["を通じて","を問わず","をこめて","わけにはいかない"]}],"src":["https://bunpro.jp/grammar_points/%E3%82%92%E9%80%9A%E3%81%98%E3%81%A6-%E3%82%92%E9%80%9A%E3%81%97%E3%81%A6"],"vf":1,"u":37,"g":1,"gp":"gg_N2_15"},{"id":"g2_172","t":"～を頼りに","ko":"~에 의지해서, ~을 의지삼아","cat":"기타","conn":[{"w":"명사","f":"地図 + を頼りに"},{"w":"명사","f":"月の光 + を頼りに"}],"rule":["1. 의지하는 대상 명사 뒤에 조사 を를 붙인다. 地図を.","2. 그 뒤에 頼りに를 붙인다. 地図を頼りに.","3. を頼りにして로도 쓴다. 뒤에는 探す・歩く・読む 같은 동작이 온다."],"why":"頼り(의지할 것, 頼る의 명사형) + に의 구성이다.","nu":"그것만을 실마리나 수단으로 삼아 어떤 일을 한다는 뜻이다. 사람에게도 쓸 수 있다. 문장 끝에서 'Nを頼りにしている'라고 하면 '~을 믿고 의지하고 있다'는 뜻이 된다(君を頼りにしているよ).","cmp":[{"g":"～をもとに","d":"재료·근거로 삼아 무언가를 만든다(事実をもとに書く). ～を頼りに는 그것에 의지해 행동한다."}],"ex":[{"jp":"地図[ちず]を頼[たよ]りに、友達[ともだち]の家[いえ]を探[さが]した。","ko":"지도에 의지해서 친구 집을 찾았다."},{"jp":"月[つき]の光[ひかり]を頼[たよ]りに、暗[くら]い道[みち]を歩[ある]いた。","ko":"달빛에 의지해서 어두운 길을 걸었다."},{"jp":"辞書[じしょ]を頼[たよ]りに、日本語[にほんご]の小説[しょうせつ]を読[よ]んだ。","ko":"사전에 의지해서 일본어 소설을 읽었다."}],"dr":[{"t":"make","q":"記憶 → ～を頼りに","a":"記憶を頼りに","hint":"명사 + を + 頼りに"},{"t":"make","q":"ナビ / 運転する → ～を頼りに～","a":"ナビを頼りに運転する","hint":"명사 + を頼りに + 동작"},{"t":"fill","q":"古[ふる]い写真[しゃしん]（　）、昔[むかし]住[す]んでいた家[いえ]を訪[たず]ねた。","a":"を頼りに","opts":["を頼りに","を問わず","をこめて","を中心に"]}],"src":["https://nihongokyoshi-net.com/2019/06/06/jlptn2-grammar-tayorini/?amp=1"],"vf":1,"u":37,"g":1,"gp":"gg_N2_15"},{"id":"g2_176","t":"～上に","ko":"~한 데다가, ~일 뿐만 아니라","cat":"기타","conn":[{"w":"동사 보통형","f":"雨が降った + 上に"},{"w":"い형용사","f":"安い + 上に"},{"w":"な형용사","f":"便利な + 上に"},{"w":"명사","f":"学生の / 学生である + 上に"}],"rule":["1. い형용사는 그대로 上に를 붙인다(安い上に).","2. 그 뒤에 같은 방향의 정보를 하나 더 잇는다(安い上に、おいしい).","3. な형용사는 な를 넣고(便利な上に), 명사는 の나 である를 넣는다(学生の上に)."],"why":"","nu":"좋은 것에 좋은 것, 나쁜 것에 나쁜 것처럼 같은 방향의 사실을 덧붙인다. 앞뒤가 반대 방향(좋음 + 나쁨)이면 쓰지 않는다. 뒤 문장에 명령·의뢰·권유는 오지 않는다. 뒤 문장에 も가 자주 함께 온다. 문어적이고 약간 딱딱한 표현이다.","cmp":[{"g":"～し","d":"이유를 나열하는 회화체 표현으로 가볍다. ～上に는 '거기에 더해'라는 첨가를 분명히 한다."},{"g":"～ばかりか","d":"'~뿐만 아니라 (놀랍게도) ~까지'라는 의외성이 더 강하다."}],"ex":[{"jp":"この店[みせ]は安[やす]い上[うえ]に、料理[りょうり]もおいしい。","ko":"이 가게는 싸고 게다가 요리도 맛있다."},{"jp":"道[みち]に迷[まよ]った上[うえ]に、雨[あめ]まで降[ふ]ってきた。","ko":"길을 잃은 데다가 비까지 내리기 시작했다."},{"jp":"この部屋[へや]は静[しず]かな上[うえ]に、駅[えき]にも近[ちか]い。","ko":"이 방은 조용한 데다가 역에서도 가깝다."}],"dr":[{"t":"make","q":"便利だ → ～上に","a":"便利な上に","hint":"な형용사는 だ를 な로 바꾸고 上に"},{"t":"make","q":"寝坊する(과거) → ～上に","a":"寝坊した上に","hint":"する를 した로 바꾼 た형 + 上に"},{"t":"fill","q":"彼女[かのじょ]は頭[あたま]がいい（　）、性格[せいかく]もいい。","a":"上に","opts":["上に","くせに","反面","わりに"]}],"src":["https://nihongokyoshi-net.com/2019/02/25/jlptn3-grammar-ueni/"],"vf":1,"u":37,"g":1,"gp":"gg_N2_15"}];
